  0% { opacity: 0; transform: scale(0.2); }
  22% { opacity: 0.42; }
  100% { opacity: 0; transform: scale(1.35); }
}
@media (prefers-reduced-motion: reduce) {
  .weather-drop, .weather-ripple { animation: none; display: none; }
