/* ---------------------------------------------------------------- 背景 */
.bg-img {
  position: absolute;
  inset: 0;
  background: center / cover no-repeat;
  opacity: 0;
  transition: opacity 0.6s ease;
  image-rendering: auto;
}
.scene-art { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.bg-img.show { opacity: 1; }
.bg-img.fast { transition-duration: 0.2s; } /* 画面の切り替え（マップ・店など）は素早く＝前の場面の絵が残って見えない */
.bg-img.black { background-color: #07050b; } /* 場面転換の暗転 */
/* 夜の色調補正（昼の絵しかない屋外・窓のある場所）: 暗く・青く・街の灯りは残す */
.bg-img[data-tint="night"] { filter: brightness(0.7) saturate(0.7) contrast(1.05); box-shadow: inset 0 0 0 2000px rgba(12, 14, 48, 0.5); }
.bg-img[data-tint="dim"] { filter: brightness(0.45) blur(2px); }

/* ---------------------------------------------------------------- ボタン */
.btn {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-width: 180px;
  padding: 12px 20px;
  border: 1px solid var(--panel-edge);
  border-radius: 6px;
  background: linear-gradient(180deg, rgba(40, 30, 58, 0.92), rgba(20, 15, 32, 0.92));
  color: var(--text);
  font-size: 18px;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: transform 0.14s var(--ease-out), border-color 0.2s, box-shadow 0.2s, background 0.2s;
  text-align: left;
}
.btn:hover:not(:disabled), .btn:focus-visible {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(232, 194, 122, 0.3), 0 6px 22px rgba(240, 166, 74, 0.18);
  transform: translateY(-1px);
  outline: none;
}
.btn:active:not(:disabled) { transform: translateY(1px) scale(0.99); }
.btn:disabled { opacity: 0.42; cursor: not-allowed; }
.btn.primary {
  border-color: var(--gold);
  background: linear-gradient(180deg, #caa15d, #9c7437);
  color: #1b1208;
  font-weight: 700;
}
.btn.primary:hover:not(:disabled) { background: linear-gradient(180deg, #e2bb74, #b08440); }
.btn.ghost { background: transparent; }
.btn.small { min-width: 0; padding: 7px 14px; font-size: 15px; }
.btn-desc { font-size: 15px; color: var(--text-dim); letter-spacing: 0; line-height: 1.4; }
.btn.primary .btn-desc { color: rgba(27, 18, 8, 0.75); }

/* ---------------------------------------------------------------- パネル */
.panel {
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  border-radius: 10px;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(6px);
}

/* ---------------------------------------------------------------- 煙ワイプ */
#wipe i {
  position: absolute;
  width: 900px;
  height: 900px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(246, 242, 250, 1) 0%, rgba(236, 230, 244, 0.96) 45%, rgba(230, 222, 240, 0) 70%);
  filter: blur(18px);
  opacity: 0;
  transform: scale(0.2);
  transition: transform 0.62s var(--ease-snap), opacity 0.5s ease;
}
#wipe i:nth-child(1) { left: -300px; top: -200px; }
#wipe i:nth-child(2) { left: 250px; top: -350px; transition-delay: 0.04s; }
#wipe i:nth-child(3) { left: 650px; top: -150px; transition-delay: 0.08s; }
#wipe i:nth-child(4) { left: -100px; top: 150px; transition-delay: 0.06s; }
#wipe i:nth-child(5) { left: 500px; top: 180px; transition-delay: 0.1s; }
#wipe.cover { pointer-events: auto; }
#wipe.cover i { opacity: 1; transform: scale(1.5); }
#wipe.cover.clear i { opacity: 0; transform: scale(2.4) translateY(-120px); transition-duration: 0.7s; }
/* 煙のにじみのワイプ（TMG60）。丸の重なり（i）は使わない */
#wipe.smoke i { display: none; }
.wipe-smoke { position: absolute; inset: 0; background: #efeaf4; }
#wipe[data-color="dark"] .wipe-smoke { background: radial-gradient(ellipse at 50% 60%, #1a1424 0%, #0a0710 70%); }
.wipe-haze { position: absolute; left: -4%; right: -4%; top: 125%; height: 50%; background: center / 100% 100% no-repeat; opacity: 0; mix-blend-mode: screen; pointer-events: none; }
#wipe:not([data-color="dark"]) .wipe-haze { mix-blend-mode: normal; }
#stage[data-wide] :is(.wipe-smoke) { inset: 0 calc(-1 * var(--stage-gutter)); }
#wipe[data-color="dark"] i { background: radial-gradient(circle, #0a0710 0%, rgba(10, 7, 16, 0.96) 45%, rgba(10, 7, 16, 0) 70%); }
#wipe::after {
  content: "";
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 0;
  transition: opacity 0.45s ease;
}
#wipe.black { pointer-events: auto; }
#wipe.black::after { opacity: 1; }

/* ---------------------------------------------------------------- トースト・バナー */
#toasts { display: flex; flex-direction: column; align-items: center; padding-top: 138px; gap: 8px; }
.toast {
  position: relative;
  padding: 10px 22px;
  border-radius: 999px;
  background: rgba(12, 9, 20, 0.92);
  border: 1px solid var(--panel-edge);
  font-size: 16px;
  opacity: 0;
  transform: translateY(-8px);
  transition: opacity 0.3s, transform 0.3s var(--ease-out);
  max-width: min(900px, calc(100% - 24px));
  overflow-wrap: anywhere;
  text-align: center;
}
.toast.show { opacity: 1; transform: none; }
.toast.warn { border-color: var(--danger); color: #ffd6d6; }
.toast.good { border-color: var(--good); }
.toast.charm-bonus { border-color: var(--stat-charm); color: var(--stat-charm); }
.toast.insight-hint { border-color: var(--stat-insight); color: var(--stat-insight); }
.toast.charm-bonus, .toast.insight-hint { display: flex; align-items: center; gap: 6px; }
.toast-badge { display: inline-grid; place-items: center; width: 18px; height: 18px; border: 1px solid currentColor; border-radius: 3px; font-size: 12px; font-weight: 800; }

/* 報酬カード（旧版の Persona 風カード）。ステ色は旧版の --stat-* と同じ */
#banners {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  padding: 150px 34px 0 0;
}
.gain-card {
  --gc: var(--gold);
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 270px;
  padding: 12px 24px 12px 16px;
  overflow: hidden;
  color: var(--text);
  font-family: var(--font);
  letter-spacing: 0.04em;
  background: linear-gradient(135deg, color-mix(in srgb, var(--gc) 18%, #140b1e) 0%, #0a0612 100%);
  border: 1px solid var(--gc);
  border-left-width: 6px;
  border-radius: 4px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.7), 0 0 24px color-mix(in srgb, var(--gc) 28%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  opacity: 0;
  transform: translateX(120%) rotate(-2deg);
}
.gain-card.show { animation: gain-in 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.2) forwards; }
.gain-card.out { animation: gain-out 0.42s cubic-bezier(0.4, 0, 0.7, 0.2) forwards; opacity: 1; transform: none; }
.gain-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 30%, color-mix(in srgb, var(--gc) 22%, transparent) 50%, transparent 70%);
  transform: translateX(-100%);
  animation: gain-shine 1.6s ease-out 0.25s;
  pointer-events: none;
}
@keyframes gain-in {
  0% { transform: translateX(120%) rotate(-2deg); opacity: 0; }
  60% { transform: translateX(-6%) rotate(-1deg); opacity: 1; }
  100% { transform: none; opacity: 1; }
}
@keyframes gain-out { to { transform: translateX(140%) rotate(2deg); opacity: 0; } }
@keyframes gain-shine { to { transform: translateX(100%); } }
/* 作業台では右側が操作パネル＝カードが操作を隠さないよう、左の一台の側から出す */
body[data-screen="bench"] #banners { align-items: flex-start; padding: 120px 0 0 24px; }
body[data-screen="bench"] .gain-card { transform: translateX(-120%) rotate(2deg); }
body[data-screen="bench"] .gain-card.show { animation-name: gain-in-l; }
body[data-screen="bench"] .gain-card.out { animation-name: gain-out-l; }
@keyframes gain-in-l {
  0% { transform: translateX(-120%) rotate(2deg); opacity: 0; }
  60% { transform: translateX(6%) rotate(1deg); opacity: 1; }
  100% { transform: none; opacity: 1; }
}
@keyframes gain-out-l { to { transform: translateX(-140%) rotate(-2deg); opacity: 0; } }
.gc-badge {
  flex: none;
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  font-family: var(--font);
  font-weight: 800;
  font-size: 22px;
  line-height: 1;
  color: #1a1018;
  background: linear-gradient(135deg, var(--gc), color-mix(in srgb, var(--gc) 55%, #201408));
  box-shadow: inset 0 -2px 4px rgba(0, 0, 0, 0.3), 0 0 14px color-mix(in srgb, var(--gc) 60%, transparent);
}
.gc-badge.face { object-fit: cover; image-rendering: pixelated; background: #1a1422; border: 2px solid var(--gc); padding: 0; }
.gc-meta { display: flex; flex-direction: column; gap: 2px; }
.gc-top { font-family: var(--font); font-size: 14px; letter-spacing: 0.04em; color: var(--gc); }
.gc-main { font-size: 21px; font-weight: 700; text-shadow: 0 1px 6px rgba(0, 0, 0, 0.8); }
.gain-card.affinity .gc-main { padding: 1px 6px; border-radius: 4px; color: #fff; background: rgba(26, 14, 30, .9); text-shadow: none; }
.gc-sub { font-size: 13px; letter-spacing: .02em; color: var(--text-dim); }
.gc-evolution { font-size: 20px; line-height: 1.5; color: var(--gold-hi); }
.gc-fx { margin-top: 3px; padding: 2px 8px; font-size: 14px; font-weight: 700; color: #1a1018; background: var(--gc); border-radius: 3px; align-self: flex-start; }
.gain-card.st-technique { --gc: var(--stat-technique); }
.gain-card.st-sense { --gc: var(--stat-sense); }
.gain-card.st-guts { --gc: var(--stat-guts); }
.gain-card.st-charm { --gc: var(--stat-charm); }
.gain-card.st-insight { --gc: var(--stat-insight); }
.gain-card.affinity { --gc: #f48fb1; }
.gain-card.affinity.bond { --gc: #ffd080; }
.gain-card.affinity.bond .gc-hearts i::after { color: #ffd080; text-shadow: 0 0 6px rgba(255, 208, 128, 0.45); }
.gain-card.stamina { --gc: #a6e69b; }
.gc-meter { width: 220px; height: 8px; margin-top: 7px; overflow: hidden; border-radius: 5px; background: rgba(255, 255, 255, 0.12); }
.gc-meter i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #6fcf8f, #c9f07a); transition: width 1s var(--ease-out); }
@media (prefers-reduced-motion: reduce) { .gc-meter i { transition: none; } }
.gain-card.affinity .gc-badge:not(.face) { color: #fff; }
.gc-hearts { display: flex; gap: 3px; margin-top: 3px; }
.gc-hearts i { position: relative; width: 14px; height: 14px; }
.gc-hearts i::before, .gc-hearts i::after { content: "♥"; position: absolute; inset: 0; font-size: 13px; line-height: 14px; text-align: center; font-style: normal; }
.gc-hearts i::before { color: rgba(255, 255, 255, 0.22); }
.gc-hearts i::after {
  color: #ff6b8d;
  text-shadow: 0 0 6px rgba(255, 107, 141, 0.75);
  clip-path: inset(calc(100% - var(--fill, 0%)) 0 0 0);
  transition: clip-path 0.9s cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* ---------------------------------------------------------------- モーダル */
/* ワイドステージ（#2861）では黒帯側へ出した HUD も覆う（モーダル中に端の MENU を押させない）。広がらない画面では inset: 0 */
.modal-backdrop { position: absolute; inset: 0 calc(-1 * var(--stage-gutter, 0px)); background: rgba(0, 0, 0, 0.6); backdrop-filter: blur(3px); }
/* 閉じた画面の写し（MENU の閉じ・#2688 A13）。#modal の一つ下に重ね、操作は受けない */
.modal-ghost { position: absolute; inset: 0; z-index: 89; pointer-events: none; }
.modal-ghost-box { position: absolute; box-sizing: border-box; pointer-events: none; }
.modal-box {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  min-width: 460px;
  max-width: 820px;
  max-height: 620px;
  overflow: auto;
  padding: 28px 32px;
  background: var(--panel);
  border: 1px solid var(--gold);
  border-radius: 12px;
  animation: pop-in 0.3s var(--ease-out);
}
.modal-box h3 { margin: 0 0 14px; font-family: var(--font); font-size: 24px; color: var(--gold-hi); letter-spacing: 0.06em; }
.modal-body { font-size: 17px; line-height: 1.8; color: var(--text); }
.modal-actions { display: flex; gap: 12px; justify-content: center; margin-top: 22px; flex-wrap: wrap; }
@keyframes pop-in { from { opacity: 0; transform: translate(-50%, -46%) scale(0.96); } }

/* ---------------------------------------------------------------- 演出パーツ */
.countdown {
  position: absolute;
  left: 50%;
  top: 44%;
  transform: translate(-50%, -50%);
  font-family: var(--font);
  font-size: 150px;
  font-weight: 800;
  color: #fff;
  text-shadow: 0 0 30px rgba(255, 220, 150, 0.8), 0 0 80px rgba(240, 166, 74, 0.6);
  z-index: 5;
}
.countdown.pop { animation: cd-pop 0.5s var(--ease-out); }
.countdown.go { color: var(--gold-hi); font-size: 120px; }
@keyframes cd-pop { from { transform: translate(-50%, -50%) scale(1.8); opacity: 0; } }

.stamp {
  position: absolute;
  transform: translate(-50%, -50%) rotate(-6deg);
  font-family: var(--font);
  font-weight: 700;
  font-size: 44px;
  letter-spacing: 0.06em;
  color: #fff;
  -webkit-text-stroke: 2px rgba(0, 0, 0, 0.55);
  text-shadow: 0 0 18px rgba(255, 255, 255, 0.55);
  animation: stamp-in 1.1s var(--ease-out) forwards;
  white-space: nowrap;
  z-index: 6;
}
.stamp.perfect, .stamp.just { color: var(--neon-amber); text-shadow: 0 0 24px rgba(255, 194, 74, 0.95), 0 0 60px rgba(255, 120, 40, 0.6); font-size: 54px; }
.stamp.good { color: var(--neon-cyan); text-shadow: 0 0 20px rgba(56, 240, 255, 0.8); }
.stamp.miss { color: #c8c8d0; text-shadow: none; font-size: 38px; }
.stamp.rough { color: #e8b07d; text-shadow: 0 0 16px rgba(232, 176, 125, .45); font-size: 38px; }
.stamp.bad { color: var(--danger); text-shadow: 0 0 20px rgba(255, 60, 60, 0.7); }
@keyframes stamp-in {
  0% { opacity: 0; transform: translate(-50%, -50%) rotate(-6deg) scale(2.2); }
  18% { opacity: 1; transform: translate(-50%, -50%) rotate(-6deg) scale(0.94); }
  28% { transform: translate(-50%, -50%) rotate(-6deg) scale(1); }
  80% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -64%) rotate(-6deg) scale(1); }
}

.flash { position: absolute; inset: 0; background: #fff; animation: flash 0.26s ease-out forwards; }
.flash.gold { background: radial-gradient(circle, rgba(255, 226, 150, 0.95), rgba(255, 160, 60, 0.4)); }
.flash.red { background: rgba(255, 40, 40, 0.5); }
@keyframes flash { from { opacity: 0.9; } to { opacity: 0; } }

#stage.shake { animation: shake 0.38s linear; }
@media (prefers-reduced-motion: reduce) {
  .flash, #stage.shake { animation: none !important; }
  .flash { display: none; }
}
/* 拡縮の transform と独立した translate プロパティで揺らす */
@keyframes shake {
  10%, 90% { translate: -2px 1px; }
  20%, 80% { translate: 4px -2px; }
  30%, 50%, 70% { translate: -6px 2px; }
  40%, 60% { translate: 6px -1px; }
}
@media (prefers-reduced-motion: reduce) {
  .flash { animation: none; opacity: 0; }
  #stage.shake { animation: none; }
}

.chapter-title-shield { position: absolute; inset: 0; pointer-events: auto; }
.chapter-card {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: radial-gradient(ellipse at center, rgba(20, 14, 30, 0.9), #06040a 70%);
  opacity: 0;
  transition: opacity 0.9s ease;
  pointer-events: auto;
}
.chapter-card.show { opacity: 1; }
.chapter-card.out { opacity: 0; }
.cc-no { font-family: var(--font); font-size: 24px; letter-spacing: 0.5em; color: var(--text-dim); }
.cc-name {
  font-family: var(--font);
  font-size: 96px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: #fff;
  text-shadow: 0 0 40px rgba(255, 230, 200, 0.4);
  animation: cc-rise 2.4s var(--ease-out);
}
.cc-read { font-size: 16px; letter-spacing: 0.4em; color: var(--gold); }
.cc-sub { margin-top: 18px; font-size: 18px; letter-spacing: 0.3em; color: var(--text-dim); }
@keyframes cc-rise { from { opacity: 0; filter: blur(14px); letter-spacing: 0.5em; } }
.cc-copy { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.chapter-card.illustrated { background: #0b0812; overflow: hidden; }
.chapter-card .cc-copy[hidden] { display: none; }
.chapter-card.static-title .cc-name { animation: none; }
.chapter-card .cc-art { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }

/* 標準の場面転換「一筆」（core/transitions.js・#2688 F1）。完全に覆った状態で画像のデコードを待つ。 */
.scene-curtain { position: absolute; inset: 0; overflow: hidden; z-index: 100; pointer-events: auto; }
/* 動きを減らす設定: 帯を描かず、夜の紫の面だけをフェードで重ねる */
.scene-curtain.veil { background: #34246a; opacity: 0; }
/* 標準の切り替え「煙のにじみ」（core/transitions.js smokeCurtain・TMG44）。幕は透明で、前の背景（#bg）をマスクでほどく。
   境目と一緒に昇る薄い煙だけを、幕の中に描く（白い煙の絵を画面の明るさで重ねる） */
.scene-curtain.smoke { background: transparent; }
.smoke-haze { position: absolute; left: -4%; right: -4%; top: 125%; height: 50%; background: center / 100% 100% no-repeat; opacity: 0; mix-blend-mode: screen; pointer-events: none; }
#stage[data-wide] .scene-curtain.smoke { inset: 0 calc(-1 * var(--stage-gutter)); }
@media (prefers-reduced-motion: reduce) { .chapter-card { transition: none; } .cc-name { animation: none; } }

/* 敗北→GAME OVER の入り（core/transitions.js defeatFade・#2688 A19）。中心から色が抜けて灰色になる */
.tr-defeat { position: absolute; inset: 0; overflow: hidden; z-index: 100; pointer-events: auto; }
.tr-defeat-gray { position: absolute; inset: 0; clip-path: circle(0% at 50% 55%); backdrop-filter: grayscale(1) brightness(.62); -webkit-backdrop-filter: grayscale(1) brightness(.62); background: #0b081433; }
/* 照明が落ちる（TMG59）: 外側の客席から暗くなり、真ん中の台だけが少し残る */
.tr-defeat-dim { position: absolute; inset: 0; opacity: 0; background: radial-gradient(ellipse 58% 62% at 50% 52%, #05040a26 0%, #05040a99 55%, #05040af2 100%); }
/* 再挑戦（TMG59）: 暗転のあと、戻った場面が灰色で現れて煙のにじみで色が戻る */
.tr-retry { position: absolute; inset: 0; overflow: hidden; z-index: 100; pointer-events: auto; }
.tr-retry-veil { position: absolute; inset: 0; background: #07060c; }
.tr-retry > .tr-retry-gray { position: absolute; inset: 0; background-size: cover; background-position: center; background-color: #07060c; }
/* 場面の意味ごとの型（core/transitions.js・CI102）。紫と淡いラベンダーの図形だけで描く */
.tr-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible; }
.tr-scale { transform-box: fill-box; transform-origin: center; }
.tr-dawn { position: absolute; inset: 0; overflow: hidden; z-index: 100; pointer-events: auto; }
/* 夜明け（core/transitions.js nightToMorning・TMG47）。眠る前の部屋の絵（写し）が暗く沈み、窓から朝の絵が広がる。
   写しは #bg の .bg-img と同じ大きさ（.tr-dawn はワイドでは左右の余白まで広がる）。--dawn-at は光の出どころ（自室は窓） */
.tr-dawn > .tr-dawn-pic { position: absolute; inset: 0; }
.tr-dawn-pic.blank { background: #070912; }
.tr-dawn-pic.day.masked {
  -webkit-mask: radial-gradient(circle at var(--dawn-at, 50% 22%), #000 0 30%, transparent 60%) var(--dawn-at, 50% 22%) / 0% 0% no-repeat;
  mask: radial-gradient(circle at var(--dawn-at, 50% 22%), #000 0 30%, transparent 60%) var(--dawn-at, 50% 22%) / 0% 0% no-repeat;
}
.tr-dawn-grade { position: absolute; inset: 0; background: radial-gradient(90% 85% at var(--dawn-at, 50% 22%), #0b0f3a99, #05061cf2 70%); opacity: 0; pointer-events: none; }
.tr-dawn.sick .tr-dawn-grade { background: radial-gradient(90% 85% at var(--dawn-at, 50% 22%), #3a0b2a99, #12050ff2 70%); }
.tr-dawn-sun { position: absolute; inset: 0; background: radial-gradient(24% 36% at var(--dawn-at, 50% 22%), #fff3cfe6, #ffd58a4d 45%, transparent 72%); mix-blend-mode: screen; opacity: 0; pointer-events: none; }
/* 自室の窓から左下へ落ちる光の筋（右端が窓の中心） */
.tr-dawn-beam { position: absolute; right: 39%; top: 23.8%; width: 50%; height: 14.2%; transform-origin: 100% 50%; rotate: -15deg; background: linear-gradient(to left, #fff1c873, #ffe2a726 60%, transparent); filter: blur(19px); mix-blend-mode: screen; opacity: 0; pointer-events: none; }
.tr-dawn-beam.b2 { rotate: -31deg; height: 16%; top: 22.9%; }
.tr-dawn-cool { position: absolute; inset: 0; background: #5b7fb5; mix-blend-mode: soft-light; opacity: 0; pointer-events: none; }
/* 自室の窓ガラスの雨 */
.tr-dawn-rainpane { position: absolute; inset: 0; clip-path: polygon(52.6% 16.6%, 69.2% 16.6%, 69.2% 45.6%, 52.6% 45.6%); background: repeating-linear-gradient(104deg, transparent 0 9.6px, #dfe9ff73 9.6px 11px, transparent 11px 19.2px); background-size: 77px 115px; opacity: 0; pointer-events: none; }
/* 日付の題字（左下）。DAY と数字は明朝、数字は下から送られる */
.tr-dawn-card { position: absolute; left: 80px; bottom: 82px; display: grid; justify-items: start; gap: 9px; font-family: var(--font); color: #fff; text-shadow: 0 3px 18px #05061ccc; }
.tr-dawn-card::before { content: ""; position: absolute; inset: -90px -150px -110px -110px; background: radial-gradient(closest-side, #05061cb8, #05061c00); z-index: -1; }
#stage[data-wide] .tr-dawn-card { left: calc(80px + var(--stage-gutter)); }
.tr-dawn-day { display: flex; align-items: flex-end; gap: 20px; line-height: 1; font-family: "Suien Name", var(--font); font-weight: 700; }
.tr-dawn-day small { font-size: 33px; letter-spacing: 0.5em; padding-bottom: 28px; }
.tr-dawn-day > .tr-flip { font-size: 180px; min-width: 100px; }
.tr-dawn-rule { display: block; width: 512px; height: 1px; background: linear-gradient(to right, #fff, #ffffff00); transform-origin: 0 50%; }
.tr-dawn-sub { display: flex; align-items: baseline; gap: 0.1em; font-size: 26px; font-weight: 700; letter-spacing: 0.14em; white-space: nowrap; }
.tr-dawn-sub > .tr-flip { font-family: "Suien Name", var(--font); font-size: 38px; letter-spacing: 0.04em; color: #ffe2a7; padding: 0 0.15em; }
.tr-dawn-wx { margin-left: 1.4em; letter-spacing: 0.3em; color: #ffe2a7; }
.tr-dawn-forecast { font-size: 20px; color: #f1e7d6; }
.tr-flip { display: inline-grid; overflow: hidden; }
.tr-flip > i { grid-area: 1 / 1; font-style: normal; }
/* 波: 時間が過ぎる（つなぎの一行・#2688 F3 の時間経過の型）。一行は波の上を左から滑ってくる */
.tr-wave { position: absolute; inset: 0; overflow: hidden; z-index: 100; pointer-events: auto; }
.tr-wave.veil { background: #34246a; opacity: 0; }
.tr-wave-line { position: absolute; left: 0; right: 0; top: 320px; text-align: center; font-family: var(--font); font-size: 30px; font-weight: 700; letter-spacing: 0.14em; color: #fff; text-shadow: 0 2px 0 #34246a, 0 0 24px #1a1238; }
/* ワイドステージ（#2861）: 画面全体を覆う転換（翌朝・波・敗北）は左右の余白まで覆う。
   端へ出した HUD（日付の札・LIME・MENU）が紫の面の外に覗かないように。中身は中央寄せなので位置は変わらない。 */
#stage[data-wide] :is(.tr-dawn, .tr-wave, .tr-defeat, .tr-retry) { inset: 0 calc(-1 * var(--stage-gutter)); }

/* マップ→場所の「移動」の型（core/transition-moves.js・CI103） */
.scene-curtain.move { background: transparent; }
/* 地図の絵そのものを動かす移動（zoom・lights・TMG46）。光は左右の余白まで届かせる */
#stage[data-wide] .scene-curtain.move.on-bg { inset: 0 calc(-1 * var(--stage-gutter)); }
.tr-zoom-glow { position: absolute; inset: -35% -22%; background: radial-gradient(closest-side, #fff8ea 0%, #fff8eaf7 42%, #fff8ea00 100%); opacity: 0; pointer-events: none; }
/* 帰宅の部屋の灯り（家の背景の照明の位置。次の背景の中に一時的に置く） */
.tr-lamp { position: absolute; inset: 0; background: radial-gradient(22% 22% at 94% 50%, #ffcf8a66, transparent 70%), radial-gradient(18% 19% at 24% 54%, #ffcf8a4d, transparent 70%); mix-blend-mode: screen; opacity: 0; pointer-events: none; }
.tr-move-field { position: absolute; inset: 0; }
.tr-move-label { position: absolute; left: 72px; top: 64px; display: flex; flex-direction: column; gap: 2px; font-family: var(--font); color: #fff; text-shadow: 0 3px 0 #150f26; }
.tr-move-label small { font-size: 18px; font-weight: 700; letter-spacing: 0.3em; color: #dcd1f4; }
.tr-move-label b { font-size: 64px; font-weight: 900; letter-spacing: 0.06em; line-height: 1.1; }
.tr-move-label.at-door { left: auto; right: 0; width: 470px; top: 56px; align-items: center; text-align: center; }
.tr-move-label.at-door b { font-size: 44px; }
.tr-foot { filter: drop-shadow(0 0 2px #150f26) drop-shadow(0 0 6px #6b4fb0); }
.tr-noren-back { position: absolute; inset: 0; background: #150f26; }
.tr-noren-panel { position: absolute; top: -2%; width: calc(25% - 6px); margin-left: 3px; height: 104%; background: linear-gradient(#2a1d57, #3d2a78); border-bottom: 10px solid #6b4fb0; transform-origin: top center; box-shadow: inset 0 18px 0 #241845; }
.tr-noren-crest { position: absolute; left: 50%; top: 46%; transform: translate(-50%, -50%); display: flex; flex-direction: column; align-items: center; gap: 12px; font-family: var(--font); pointer-events: none; }
.tr-noren-crest b { width: 190px; height: 190px; border-radius: 50%; border: 8px solid #dcd1f4; display: flex; align-items: center; justify-content: center; font-size: 104px; font-weight: 900; color: #dcd1f4; }
.tr-noren-crest small { font-size: 30px; font-weight: 900; letter-spacing: 0.2em; padding-left: 0.2em; color: #dcd1f4; }
.tr-walkdoor-leaf { transform-box: fill-box; transform-origin: left center; }
.tr-walkdoor-flood { position: absolute; inset: 0; background: radial-gradient(circle, #fffaf0, #fff1d2 60%, #f3d9a8); }

/* 朝の日付カード（TMG60）: 就寝→翌朝の日付の題字（.tr-dawn-card）と同じ組み方。暗い帯はやめ、左下に題字だけ */
.day-card { position: absolute; left: 80px; bottom: 82px; display: grid; justify-items: start; gap: 9px; font-family: var(--font); color: #fff; text-shadow: 0 3px 18px #05061ccc;
  opacity: 0; transform: translateY(14px); transition: transform .42s cubic-bezier(.16,1,.3,1), opacity .38s ease; pointer-events: auto; }
.day-card::before { content: ""; position: absolute; inset: -90px -150px -110px -110px; background: radial-gradient(closest-side, #05061cb8, #05061c00); z-index: -1; }
.day-card.show { opacity: 1; transform: none; }
.day-card.out { opacity: 0; transform: translateY(-12px); transition-timing-function: cubic-bezier(.55,0,.85,.35), ease; }
#stage[data-wide] .day-card { left: calc(80px + var(--stage-gutter)); }
.dc-title { display: flex; align-items: flex-end; gap: 20px; line-height: 1; font-family: "Suien Name", var(--font); font-weight: 700; }
.dc-title small { font-size: 33px; letter-spacing: 0.5em; padding-bottom: 22px; }
.dc-title b { font-size: 160px; font-weight: 700; }
.dc-title b.word { font-size: 84px; letter-spacing: 0.06em; }
.dc-rule { display: block; width: 512px; height: 1px; background: linear-gradient(to right, #fff, #ffffff00); transform-origin: 0 50%; transform: scaleX(0); transition: transform .64s .12s cubic-bezier(.16,1,.3,1); }
.day-card.show .dc-rule { transform: scaleX(1); }
.dc-sub { display: flex; align-items: baseline; gap: 0.6em; font-size: 26px; font-weight: 700; letter-spacing: 0.14em; white-space: nowrap; color: #fff; }
small.dc-sub { font-size: 20px; color: #f1e7d6; }

/* 「ROUND 1」の帯（TMG59）: 登場カットインと同じ生成りの帯（-3度）を大きく。右から入って左へ抜ける */
.round-cut { position: absolute; inset: 0; pointer-events: none; background: #05040a00; transition: background-color .35s ease; }
.round-cut.show { background: #05040a66; }
.round-cut.out { background: #05040a00; }
.round-cut-band { position: absolute; left: -60px; right: -60px; top: 272px; height: 176px; display: flex; align-items: center; justify-content: center;
  background: #f4ecda; rotate: -3deg; translate: 112% 0; box-shadow: 0 16px 36px #05020a99; transition: translate .4s cubic-bezier(.16,1,.3,1); }
.round-cut.show .round-cut-band { translate: 0 0; }
.round-cut.out .round-cut-band { translate: -112% 0; transition: translate .34s cubic-bezier(.55,0,.85,.35); }
/* ワイドステージ: 帯は画面の両端まで（文字は中央のまま） */
#stage[data-wide] .round-cut-band { left: calc(-60px - var(--stage-gutter)); right: calc(-60px - var(--stage-gutter)); }
.round-cut-band b { font-family: "Suien Name", var(--font); font-size: 128px; line-height: 1; font-weight: 700; letter-spacing: 0.12em; padding-left: 0.12em; color: #1a0f24; }
.round-cut-band small { position: absolute; left: 30%; bottom: 100%; background: #2a1638; color: #f4ecda; font-size: 24px; line-height: 1.5; letter-spacing: 0.24em; font-weight: 700; padding: 5px 18px; white-space: nowrap; }

/* ---------------------------------------------------------------- 起動 */
#boot {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 22px;
  background: #07050c;
  transition: opacity 0.6s ease;
}
#boot.done { opacity: 0; pointer-events: none; }
.boot-brand { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.boot-logo { font-family: var(--font); font-size: 64px; font-weight: 500; letter-spacing: 0.2em; color: #efe9f4; opacity: 0.85; }
.boot-subtitle { font-size: 20px; font-weight: 500; letter-spacing: 0.3em; color: var(--text-dim); }
.boot-bar { width: 360px; height: 3px; background: rgba(255, 255, 255, 0.12); border-radius: 2px; overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 0; background: var(--gold); transition: width 0.2s; }
.boot-msg { max-width: 900px; font-size: 15px; color: var(--text-dim); letter-spacing: 0.04em; text-align: center; line-height: 1.8; }
.boot-retry[hidden] { display: none; }

/* 遊んでいる途中に新しい版が公開されたときの知らせ（index.html の起動スクリプトが出す） */
#update-note {
  position: fixed;
  top: max(10px, env(safe-area-inset-top));
  left: 50%;
  z-index: 998;
  display: flex;
  max-width: calc(100vw - 32px);
  transform: translateX(-50%);
  border: 1px solid var(--gold);
  border-radius: 8px;
  background: rgba(7, 5, 12, 0.94);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.5);
}
#update-note button { min-height: 44px; border: 0; background: none; color: var(--text); font: inherit; font-size: 14px; cursor: pointer; }
#update-note .update-go { padding: 8px 14px; color: var(--gold-hi); letter-spacing: 0.04em; text-align: left; }
#update-note .update-close { min-width: 44px; border-left: 1px solid rgba(255, 255, 255, 0.15); color: var(--text-dim); font-size: 18px; }

#rotate-hint {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: none;
  place-items: center;
  background: #07050c;
  color: var(--text);
  font-size: 18px;
  text-align: center;
  padding: 16px;
}
/* 縦画面は廃止（#2826）。タッチ端末を縦に持ったら、タイトルを含む全画面を回転案内だけで覆う。 */
@media (orientation: portrait) and (hover: none) and (pointer: coarse) {
  #rotate-hint { display: grid; }
}

/* 選択済みで次の画面を待っている画面は触れない */
.done, .done * { pointer-events: none !important; }

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

/* ---------------------------------------------------------------- セーブ／ロード（オート＋手動1枠） */
.saveload-modal { box-sizing: border-box; width: 1200px; max-width: calc(100% - 64px); max-height: 660px; padding: 32px 38px; }
.saveload-modal h3 { font-size: 32px; }
.ss-note { margin: -4px 0 22px; font-size: 24px; line-height: 1.5; color: var(--text-dim); }
.ss-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; }
.save-slot {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 18px;
  width: 100%;
  min-height: 390px;
  padding: 24px;
  text-align: left;
  font-family: var(--font);
  color: var(--text);
  background: linear-gradient(90deg, rgba(232, 194, 122, 0.14), rgba(255, 255, 255, 0.03) 70%);
  border: 1px solid rgba(232, 194, 122, 0.45);
  border-left: 4px solid var(--gold);
  border-radius: 6px;
  cursor: pointer;
  transition: filter 0.15s, transform 0.1s;
}
.save-slot:hover:not(:disabled) { filter: brightness(1.15); }
.save-slot:active:not(:disabled) { transform: scale(0.99); }
.save-slot.off { opacity: 0.72; cursor: default; }
.save-slot.auto { border-left-color: #7fb8d4; border-color: rgba(127, 184, 212, 0.45); background: linear-gradient(90deg, rgba(127, 184, 212, 0.16), rgba(255, 255, 255, 0.03) 70%); }
.save-slot.blank { background: rgba(255, 255, 255, 0.02); border-style: dashed; border-left-style: solid; }
.ss-label { flex: none; display: flex; align-items: baseline; gap: 14px; font-size: 30px; font-weight: 700; letter-spacing: 0.05em; color: var(--gold-hi); }
.ss-label small { font-size: 24px; font-weight: 700; letter-spacing: .02em; color: var(--gold); }
.save-slot.auto .ss-label { color: #a9d6ec; }
.save-slot.auto .ss-label small { color: #7fb8d4; }
.ss-info { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; justify-content: space-evenly; gap: 18px; }
.ss-info b { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 12px; font-size: 28px; line-height: 1.35; }
.ss-info em { font-style: normal; }
.ss-chapter { font-size: 24px; letter-spacing: .02em; color: var(--gold-hi); }
.ss-phase { padding: 2px 8px; font-size: 24px; color: var(--text-dim); border: 1px solid var(--panel-edge); border-radius: 3px; }
.ss-info small { font-size: 24px; line-height: 1.35; color: var(--text-dim); }
.ss-info.empty { color: var(--text-dim); letter-spacing: 0.2em; }
.ss-stats { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; }
.ss-stat { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.ss-stat small { font-size: 24px; font-weight: 700; line-height: 1.1; letter-spacing: 0; white-space: nowrap; color: var(--text-dim); }
.ss-stat i { display: block; height: 7px; border-radius: 4px; background: var(--panel-edge); overflow: hidden; }
.ss-stat i::after { content: ""; display: block; width: var(--v); height: 100%; background: linear-gradient(90deg, var(--gold), var(--gold-hi)); }
.save-slot.auto .ss-stat i::after { background: linear-gradient(90deg, #7fb8d4, #a9d6ec); }
.ss-faces { flex: none; display: flex; flex-wrap: wrap; justify-content: flex-start; align-content: center; gap: 8px; min-height: 42px; }
.ss-face { width: 40px; height: 40px; object-fit: cover; image-rendering: pixelated; background: var(--panel); border: 1px solid var(--panel-edge); border-radius: 4px; }
.ss-more { align-self: center; font-size: 17px; color: var(--text-dim); }
.saveload-modal .modal-actions { margin-top: 22px; }
.saveload-modal .modal-actions .btn { min-height: 52px; min-width: 180px; font-size: 19px; }

/* 動きを減らす・揺れ／閃光を減らす（#2688 F11）。会話の送り印の上下を止め、場面の演出の全面の閃光を出さない。 */
@media (prefers-reduced-motion: reduce) { .vn-next.show { animation: none !important; } }
body.reduce-shake .mo-tarot-flash, body.reduce-shake .mo-pk-flash, body.reduce-shake .mo-ck-flash,
body.reduce-shake .ci-flash, body.reduce-shake .win-flash, body.reduce-shake .camel-flash, body.reduce-shake .dr-flash,
body.reduce-shake .axe-declare-flash { display: none !important; }

/* ===== css/axe-throw.css ===== */
/* @import: venue-host.css */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
.venue-host { display: flex; align-items: center; gap: 18px; min-height: 112px; padding: 8px 18px 0 8px; border: 1px solid #99816188; border-radius: 9px; background: linear-gradient(110deg, #493526dd, #18171ddb); text-align: left; color: #f4ead6; }
.venue-host-portrait { position: relative; flex: 0 0 110px; height: 112px; overflow: hidden; }
.venue-host-portrait img { position: absolute; left: 50%; width: 260px; height: auto; max-width: none; }
.venue-host-copy { min-width: 0; padding: 6px 0 12px; }
.venue-host-copy small { display: block; font-size: 12px; color: #c8b28f; }
.venue-host-copy strong { display: block; margin: 4px 0 6px; font-size: 20px; }
.venue-host-copy p { margin: 0; font-size: 17px; line-height: 1.55; overflow-wrap: anywhere; }
.sub-menu.axe-bar-menu { width: 880px; max-height: 94%; padding: 24px 32px; overflow-y: auto; touch-action: pan-y !important; }
.axe-bar-menu .sub-title { font-size: 30px; }
.axe-bar-menu .venue-host { margin: 10px auto; max-width: 660px; }
.axe-bar-menu .sub-lead { margin: 8px 0 14px; }
.axe-bar-menu .axe-bar-lesson { margin: 0 auto 12px; border-color: #b99b69; color: #ffe1a7; }
/* レッスンとマイ斧（VOL07）を1行に並べ、メニューの高さを増やさない。 */
.axe-bar-menu .axe-bar-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin: 0 0 12px; }
.axe-bar-menu .axe-bar-tools > * { margin: 0; }
.axe-bar-menu .sub-choices { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.axe-bar-menu .big-choice { padding: 14px 18px; }
.axe-bar-menu .axe-bar-records { margin-top: 12px; padding-top: 10px; border-top: 1px solid #99816166; font-size: 14px; line-height: 1.6; }
.axe-bar-menu .axe-bar-records p { margin: 6px 0 0; }
.axe-bar-menu .sub-back { margin-top: 14px; }
.trpg-campaign .venue-host { flex-shrink: 0; min-height: 96px; background: linear-gradient(110deg, #2e4a40, #182b2d); }
.trpg-campaign .venue-host-portrait { height: 96px; }
.trpg-campaign .venue-host-copy p { font-size: 16px; }
.trpg-root.trpg-campaign { overflow-y: auto; }
.trpg-campaign .trpg-campaign-books { flex: none; overflow-y: visible; }
.trpg-campaign .trpg-club-proposal { margin: 0 auto; padding: 18px 30px; }
.trpg-campaign .trpg-club-proposal p { margin: 8px 0; font-size: 17px; }
.trpg-day-trial { padding: 14px 20px; border: 1px solid #829e87; border-radius: 9px; background: #213d37; }
.trpg-day-trial h2 { margin: 0 0 7px; font-size: 22px; }
.trpg-day-trial p { margin: 5px 0 10px; font-size: 15px; }
.trpg-trial-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.trpg-trial-score { display: flex; align-items: center; gap: 20px; margin: 14px 0; font-size: 30px; color: #ffe6a3; }
.trpg-trial-die { font-size: 48px; line-height: 1; }
.axe-bar-menu .axe-bar-divisions { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 6px 8px; margin: 10px auto 0; max-width: 760px; font-size: 13px; line-height: 1.4; }
.axe-bar-menu .axe-bar-divisions .btn { min-height: 32px; padding: 4px 12px; }
.axe-bar-menu .axe-bar-divisions .btn[aria-pressed="true"] { border-color: #e8b772; background: rgba(204,150,77,.22); color: #ffe3b5; }
.axe-bar-menu .axe-bar-division-label { color: #ffe1a7; font-size: 13px; font-weight: 700; }
.axe-bar-menu .axe-bar-division-note { flex-basis: 100%; color: #d5cbb8; font-size: 12px; text-align: center; }
.axe-bar-menu .axe-bar-records { margin-top: 8px; padding-top: 8px; }
.axe-bar-menu .axe-bar-career { color: #ffe1a7; }
html:root[data-ui-theme="paper"] .axe-bar-menu .axe-bar-divisions .btn[aria-pressed="true"] { color: #fff; background: var(--lavender); border-color: var(--lavender); }
html:root[data-ui-theme="paper"] .axe-bar-menu .axe-bar-division-label { color: var(--lavender); }
html:root[data-ui-theme="paper"] .axe-bar-menu .axe-bar-division-note { color: var(--paper-muted); }
html:root[data-ui-theme="paper"] .axe-bar-menu .axe-bar-career { color: var(--lavender); }
/* #2834 本編の斧投げBarメニュー: スマホ横持ち（0.47〜0.54倍）でも読める大きさ。文字は 24px 以上、押す部品は 82px 以上。
   店名は見出しにあるので案内役の札の店名は外し、読み上げにも二重に出さない。 */
.sub-menu.axe-bar-menu { width: 1040px; max-height: 96%; padding: 20px 32px; }
.axe-bar-menu .sub-title { font-size: 34px; }
.axe-bar-menu .venue-host { min-height: 0; margin: 8px auto; max-width: none; }
.axe-bar-menu .venue-host-copy small { display: none; }
.axe-bar-menu .venue-host-copy strong { margin: 0 0 4px; font-size: 26px; }
.axe-bar-menu .venue-host-copy p { font-size: 24px; line-height: 1.45; }
.axe-bar-menu .sub-lead { margin: 6px 0 12px; font-size: 24px; line-height: 1.45; }
.axe-bar-menu .axe-bar-tools .btn { min-height: 82px; padding: 8px 22px; font-size: 24px; }
.axe-bar-menu .big-choice { min-height: 82px; padding: 12px 20px; }
.axe-bar-menu .big-choice b { font-size: 28px; }
.axe-bar-menu .big-choice small { font-size: 24px; }
.axe-bar-menu .axe-bar-divisions { gap: 8px 12px; max-width: none; font-size: 24px; }
.axe-bar-menu .axe-bar-divisions .btn { min-width: 120px; min-height: 82px; padding: 6px 18px; font-size: 26px; }
.axe-bar-menu :is(.axe-bar-division-label, .axe-bar-division-note) { font-size: 24px; }
.axe-bar-menu .axe-bar-records { font-size: 24px; line-height: 1.45; }
.axe-bar-menu .sub-back { min-height: 82px; padding: 8px 26px; font-size: 24px; }
.axe-bar-menu .axe-bar-tools p.gear-offer { font-size: 24px; }
/* 上の大きさにすると中身がステージの高さ（720px）を越え、最後にあった「← マップに戻る」は PC でもスクロールしないと見えなかった。
   戻るボタンは見出しの行の右に置き（ボドゲカフェの「閉じる」と同じく上の列）、レッスンとマイ斧は最初の意図どおり1行に収める。
   押す部品はすべて最初の画面に出し、記録・部門の説明の文だけが下へ続く（play_spots・venue_hours の検査）。 */
body:not(:root) .axe-bar-menu .sub-title { display: flex; align-items: center; min-height: 82px; }
body:not(:root) .axe-bar-menu .sub-back { position: absolute; top: 20px; right: 32px; margin: 0; }
body:not(:root) .axe-bar-menu .axe-bar-tools { flex-wrap: nowrap; column-gap: 10px; }
body:not(:root) .axe-bar-menu .axe-bar-tools > .axe-bar-lesson { flex: none; }
body:not(:root) .axe-bar-menu .axe-bar-tools > .gear-offer { flex: 0 1 auto; min-width: 0; } /* 幅が足りない時はマイ斧の札の中で折り返す */

#axe-app { position: absolute; inset: 0; container-type: size; } /* 試遊ページでは #stage（1280×720）の中に置く（#3076） */

/* Practice entrance. Its dedicated stylesheet can refine these shared defaults. */
.axe-intro { --axe-bg: url("../img/backgrounds/bg_axe_lounge_night.webp"); min-height: 100%; display: flex; flex-direction: column; justify-content: center; align-items: flex-start; padding: clamp(20px,7vw,100px); gap: 16px; background: linear-gradient(90deg,rgba(10,7,13,.92),rgba(10,7,13,.54)),var(--axe-bg) center/cover; }
.axe-intro h1 { margin: 0; color: var(--gold-hi); font-size: clamp(34px,7vw,72px); letter-spacing: .08em; }
.axe-intro h2, .axe-intro p { margin: 0; }
.axe-intro ol { padding-left: 24px; line-height: 1.9; }
.axe-eyebrow, .axe-back { color: var(--gold); }
.axe-back { padding: 12px 0; }
.axe-pickers { display: flex; flex-wrap: wrap; gap: 10px; }
.axe-menu-help { color: var(--text-dim); font-size: 14px; max-width: 650px; }
.axe-versus-menu { display: grid; gap: 8px; padding-top: 12px; border-top: 1px solid #665768; }
.axe-versus-menu > p { font-size: 14px; color: var(--gold-hi); }

/* The lane stays visually quiet so the wood, moving sights and impact lead. */
.axe-game {
  --axe-size: 1; --axe-amber: #edb76d; --axe-line: rgba(224,183,126,.22); --axe-muted: #aaa69d;
  position: absolute; inset: 0; z-index: 70; display: grid; grid-template-rows: auto minmax(0,1fr);
  padding: clamp(16px,2.6vw,34px); gap: 16px; color: #f4eee3; font-size: 16px; pointer-events: auto;
  background: linear-gradient(90deg,rgba(10,13,14,.93),rgba(11,13,14,.79)),var(--axe-bg,url("../img/backgrounds/bg_axe_lounge_night.webp")) center/cover;
}
.axe-game::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at 29% 42%,rgba(219,155,71,.12),transparent 55%); }
.axe-game > * { position: relative; min-width: 0; }
.axe-header { display: flex; align-items: center; gap: 12px; }
.axe-header h1 { margin: 0; font-size: clamp(21px,2.6vw,32px); font-weight: 900; letter-spacing: .14em; line-height: 1.3; }
.axe-header p { margin: 7px 0 0; color: var(--axe-muted); font-size: 12px; letter-spacing: .02em; }
.axe-round { order: 2; margin-left: 0; padding: 9px 14px; border-left: 1px solid var(--axe-line); color: var(--axe-amber); font-size: 15px; white-space: nowrap; font-variant-numeric: tabular-nums; }
.axe-header > div:first-child { order: 0; }
.axe-header .axe-rules-button { order: 3; }
.axe-header .axe-close { order: 4; }
.axe-total { order: 1; display: flex; align-items: baseline; gap: 6px; margin-left: auto; padding: 2px 16px; border-inline: 1px solid var(--axe-line); font-variant-numeric: tabular-nums; white-space: nowrap; }
.axe-total small { align-self: center; color: #c6bca8; font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.axe-total strong { color: #f5d6a6; font-size: 32px; font-weight: 900; line-height: 1.45; }
.axe-total > span { color: #bdb9ac; font-size: 13px; }
.axe-body { display: grid; grid-template-columns: minmax(0,1fr) minmax(330px,36%); gap: clamp(14px,2vw,28px); min-height: 0; }
.axe-board-pane { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; overflow: hidden; border: 1px solid var(--axe-line); border-radius: 18px; background: radial-gradient(ellipse at 50% 40%,rgba(152,106,57,.12),rgba(8,11,11,.55) 68%); box-shadow: inset 0 1px rgba(255,255,255,.025),0 14px 40px rgba(0,0,0,.15); }
.axe-target { display: block; width: 100%; flex: 1 1 0; min-height: 0; overflow: hidden; touch-action: none !important; }
.axe-target image, .axe-target circle, .axe-target path, .axe-target g { pointer-events: none; }
.axe-target { cursor: crosshair; outline: none; }
.axe-target:focus-visible { outline-offset: -5px; border-radius: 12px; }
.axe-aim-guides { pointer-events: none; }
.axe-fixed-aim { opacity: .8; }
.axe-legend { order: -1; align-self: center; margin: 12px 8px 0; padding: 5px 12px; color: #d2c6b2; font-size: 12px; font-weight: 700; letter-spacing: .02em; text-align: center; border: 1px solid rgba(224,183,126,.16); border-radius: 100px; background: rgba(10,13,14,.75); }

.axe-panel { display: flex; flex-direction: column; justify-content: center; min-width: 0; min-height: 0; padding: clamp(16px,2vw,25px); gap: 10px; border: 1px solid var(--axe-line); border-radius: 18px; background: linear-gradient(155deg,rgba(31,34,32,.94),rgba(15,19,19,.97)); box-shadow: inset 0 1px rgba(255,255,255,.045),0 16px 40px rgba(0,0,0,.2); }
.axe-panel > * { flex-shrink: 0; min-width: 0; }
.axe-scores { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap: 5px; }
.axe-scores > span { display: flex; align-items: center; justify-content: center; gap: 7px; padding: 7px 2px; border: 1px solid rgba(255,255,255,.075); border-radius: 5px; background: rgba(0,0,0,.19); font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.axe-game[data-mode="practice"] .axe-scores { grid-template-columns: repeat(3,minmax(0,1fr)); }
.axe-scores i { color: #858b88; font-size: 12px; font-weight: 700; font-style: normal; }
.axe-scores strong { color: #7e8582; font-size: 15px; font-weight: 700; }
.axe-scores [data-current="true"] { border-color: #bd9256; background: rgba(194,143,73,.1); }
.axe-scores [data-current="true"] i { color: #f4d8aa; }
.axe-scores [data-filled="true"] strong { color: #f1ddbb; }
.axe-scores [data-outcome="bull"] strong, .axe-scores [data-outcome="killshot"] strong { color: #f8c16e; }
.axe-scores [data-outcome="drop"] strong, .axe-scores [data-outcome="miss"] strong, .axe-scores [data-outcome="killshot-miss"] strong { color: #bda296; }
.axe-note { display: flex; align-items: center; min-height: 2.5em; margin: 0; color: #f6e3c4; font-size: 17px; font-weight: 700; line-height: 1.45; }
.axe-live-score { display: grid; grid-template-columns: minmax(0,1fr) auto; align-items: center; column-gap: 12px; padding: 8px 12px; border: 1px solid rgba(222,183,126,.2); border-radius: 8px; background: rgba(218,172,101,.06); }
.axe-live-label { grid-column: 1; color: #e7d5b5; font-size: 13px; font-weight: 700; }
.axe-live-score strong { grid-column: 2; grid-row: 1/3; color: #f4d29d; font-size: 30px; font-weight: 900; line-height: 1.45; font-variant-numeric: tabular-nums; white-space: nowrap; }
.axe-live-reason { grid-column: 1; color: #aaa99d; font-size: 12px; font-weight: 700; line-height: 1.5; }
.axe-game[data-preview-outcome="killshot"] .axe-live-score strong { color: #a8dcf0; }
.axe-game:is([data-preview-outcome="drop"],[data-preview-outcome="miss"],[data-preview-outcome="killshot-miss"]) .axe-live-score strong { color: #d8a78e; }
.axe-game:is([data-phase="choice"],[data-phase="horizontal"],[data-phase="vertical"],[data-phase="power"]) .axe-note { display: none; }
.axe-steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 5px; }
.axe-steps li { padding: 9px 8px; border: 1px solid rgba(255,255,255,.1); border-radius: 7px; background: rgba(0,0,0,.15); font-size: 12px; }
.axe-steps span, .axe-steps strong { display: block; white-space: nowrap; }
.axe-steps span { margin-bottom: 4px; color: var(--axe-muted); font-size: 12px; font-weight: 700; }
.axe-steps strong { font-weight: 700; font-variant-numeric: tabular-nums; }
.axe-steps [data-state="live"] { border-color: #dca45c; background: rgba(217,161,82,.14); box-shadow: inset 0 2px #dca45c; }
.axe-steps [data-state="live"] span { color: #f3ca8b; }
.axe-steps [data-state="locked"] strong { color: #a8ccb6; }
.axe-steps [data-state="waiting"] strong { color: #7e8782; }
.axe-timing > span { display: block; margin-bottom: 8px; color: #d3d2c7; font-size: 12px; line-height: 1.4; }
.axe-gauge { position: relative; height: 28px; border: 1px solid rgba(211,170,132,.35); border-radius: 5px; background: #563534; }
.axe-stick { position: absolute; top: 0; bottom: 0; left: var(--from); width: var(--size); background: #9c784b; border-inline: 1px solid #dcba7c; }
.axe-sweet { position: absolute; top: 0; bottom: 0; left: var(--from); width: var(--size); background: #8db98c; border-inline: 2px solid #ddf0c2; }
.axe-needle { position: absolute; left: 0; top: -5px; bottom: -5px; width: 3px; transform: translateX(-50%); border-radius: 2px; background: #fff8e8; box-shadow: 0 0 9px rgba(255,244,194,.6); }
.axe-timing[data-active="false"] { opacity: .42; }
.axe-feedback { margin: 0; color: #b2c9b5; font-size: 12px; font-weight: 700; line-height: 1.5; }
.axe-steadiness { margin: 0; color: #a9c1c5; font-size: 12px; font-weight: 700; line-height: 1.5; }
.axe-stability-meter { height: 3px; overflow: hidden; border-radius: 4px; background: rgba(255,255,255,.09); }
.axe-stability-meter i { display: block; width: 100%; height: 100%; transform: scaleX(var(--axe-steady,1)); transform-origin: left center; border-radius: inherit; background: #aebfa9; transition: transform .15s linear,background-color .2s; }
.axe-stability-meter[data-focused="true"] i { background: #bce7d0; box-shadow: 0 0 8px #bce7d0; }
.axe-game[data-focused="true"] .axe-board-pane { border-color: rgba(172,218,192,.5); }

.axe-button { min-height: 48px; padding: 11px 16px; border: 1px solid rgba(215,191,151,.34); border-radius: 8px; background: #252b28; color: #e5e6dc; font: inherit; font-size: 14px; line-height: 1.3; cursor: pointer; transition: background-color .16s,border-color .16s,transform .16s; }
.axe-button:hover:not(:disabled) { background: #343c34; border-color: #d7bb87; }
.axe-button:active:not(:disabled) { transform: translateY(1px); }
.axe-button:disabled { opacity: .45; cursor: default; }
.axe-button:focus-visible, .axe-target:focus-visible { outline: 3px solid #f8e3a7; outline-offset: 3px; }
.axe-target:focus-visible { outline-offset: -4px; }
.axe-primary { min-height: 56px; border-color: #ecc385; background: linear-gradient(115deg,#efc280,#d8a05a); color: #201a11; font-size: 17px; font-weight: 900; box-shadow: 0 5px 18px rgba(0,0,0,.18),inset 0 1px rgba(255,255,255,.3); }
.axe-primary:hover:not(:disabled) { background: linear-gradient(115deg,#f9d49c,#edb56a); border-color: #ffe0ad; }
.axe-primary:disabled { opacity: .6; }
.axe-header .axe-button { min-height: 44px; padding: 9px 13px; font-size: 12px; background: rgba(14,18,17,.5); }
.axe-close { color: #b8b8ad; }
.axe-button[aria-pressed="true"] { border-color: #e8b772; background: rgba(204,150,77,.2); color: #ffe3b5; box-shadow: inset 0 0 0 1px rgba(232,183,114,.2); }
.axe-calls { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 6px; }
.axe-calls .axe-button { min-height: 44px; padding: 7px 6px; font-size: 12px; }
.axe-calls .axe-button[data-closed="true"] { border-style: dashed; }
.axe-calls .axe-button:first-child { grid-row: span 2; }
.axe-call-status { margin: 0; color: #9fc5d2; font-size: 12px; font-weight: 700; line-height: 1.5; }
.axe-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.axe-controls .axe-button { min-height: 44px; padding: 8px 5px; font-size: 12px; }
.axe-keyhint { margin: 0; color: #92988f; font-size: 12px; font-weight: 700; text-align: center; letter-spacing: .02em; }
.axe-keyhint kbd { margin-inline: 2px; padding: 1px 5px; border: 1px solid #54594f; border-radius: 3px; font: inherit; color: #cccab8; }

.axe-result-card { padding: 20px 12px; border: 1px solid rgba(233,184,111,.23); border-radius: 11px; background: radial-gradient(ellipse at 50% 30%,rgba(229,173,88,.1),transparent 80%); text-align: center; animation: axe-score-arrive .32s ease-out both; }
.axe-result-label { display: block; color: #e7c795; font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.axe-result-value { display: block; margin: 7px 0; color: #f9dfb3; font-size: clamp(60px,7vw,86px); font-weight: 900; line-height: 1.25; font-variant-numeric: tabular-nums; text-shadow: 0 3px 20px rgba(235,173,78,.15); }
.axe-result-value small { margin-left: 4px; font-size: .25em; }
.axe-result-tip { display: block; margin: 0; color: #bab9a9; font-size: 12px; line-height: 1.6; }
.axe-game[data-outcome="killshot"] .axe-result-card { border-color: #7caeb9; background: radial-gradient(ellipse at 50% 20%,rgba(99,170,194,.18),transparent 85%); }
.axe-game[data-outcome="killshot"] .axe-result-label { display: block; color: #b3e4f4; }
.axe-game[data-outcome="miss"] .axe-result-value, .axe-game[data-outcome="drop"] .axe-result-value, .axe-game[data-outcome="killshot-miss"] .axe-result-value { color: #c9b9a4; }
/* Bullseye and killshot: a stamp-like pop plus a warm glow; reduced-motion keeps only the static glow. */
.axe-game[data-phase="result"][data-special="true"] .axe-result-card { box-shadow: 0 0 34px rgba(255,205,120,.35); }
.axe-game[data-phase="result"][data-special="true"] .axe-result-label { color: #ffe7a6; letter-spacing: .3em; }
.axe-game[data-phase="result"][data-special="true"] .axe-result-value { width: fit-content; transform-origin: left center; color: #fff1c8; text-shadow: 0 0 22px rgba(255,214,130,.85), 0 3px 20px rgba(235,173,78,.3); animation: axe-stamp .42s cubic-bezier(.2,.8,.2,1) both; }
@keyframes axe-stamp { 0% { transform: scale(.6); opacity: 0; } 55% { transform: scale(1.18); opacity: 1; } 100% { transform: scale(1); opacity: 1; } }
.axe-game:is([data-phase="result"],[data-phase="summary"]) :is(.axe-steps,.axe-timing,.axe-feedback,.axe-steadiness,.axe-stability-meter,.axe-call-status,.axe-note) { display: none; }
.axe-game[data-phase="summary"] .axe-match-records { grid-template-columns: 1fr 1fr; gap: 12px; }
.axe-game[data-phase="choice"] :is(.axe-steps,.axe-feedback,.axe-timing) { display: none; }
.axe-game:is([data-phase="horizontal"],[data-phase="vertical"],[data-phase="power"]) .axe-call-status { display: none; }
.axe-game .axe-announcement { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; pointer-events: none; }
.axe-game [hidden] { display: none !important; }

.axe-companion { display: flex; align-items: center; gap: 12px; min-height: 72px; padding: 9px 16px; border-top: 1px solid var(--axe-line); background: rgba(10,14,13,.8); }
.axe-portrait-frame { position: relative; width: 52px; height: 54px; overflow: hidden; flex-shrink: 0; border-radius: 50%; border: 1px solid rgba(215,180,119,.35); background: #292c26; }
.axe-portrait-frame .axe-portrait { position: absolute; width: 122px; max-width: none; height: auto; left: 50%; top: -5px; transform: translateX(-50%); }
.axe-companion > div:last-child { min-width: 0; }
.axe-companion strong { display: block; color: #d4b67d; font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.axe-comment { margin: 3px 0 0; color: #e2ddcf; font-size: 13px; line-height: 1.55; }
.axe-match-score { padding: 9px 10px; border: 1px solid var(--axe-line); border-radius: 7px; background: rgba(0,0,0,.16); color: #efd4a3; font-size: 15px; font-weight: 700; text-align: center; font-variant-numeric: tabular-nums; }
.axe-match-records { display: grid; gap: 12px; font-size: 12px; }
.axe-match-records strong { color: #e4c391; }
.axe-match-records p { margin: 5px 0 0; line-height: 1.6; overflow-wrap: anywhere; }
.axe-game:is([data-mode="league"],[data-mode="versus"]) .axe-panel { gap: 7px; }
.axe-game:is([data-mode="league"],[data-mode="versus"]) .axe-note { min-height: 1.5em; }
.axe-game[data-mode="versus"] .axe-panel { gap: 4px; }
.axe-in-stage { padding: 22px; gap: 13px; }
.axe-in-stage .axe-body { grid-template-columns: minmax(0,1fr) 408px; }
.axe-in-stage .axe-panel { padding: 20px; gap: 10px; }

.axe-rules { position: absolute; inset: 0; z-index: 90; display: grid; place-items: center; padding: clamp(12px,3vw,36px); background: rgba(8,12,12,.96); color: #eee8db; }
.axe-rules-card { width: min(760px,100%); max-height: 100%; min-height: 0; padding: 24px; display: grid; grid-template-rows: auto minmax(0,1fr); gap: 16px; border: 1px solid #b9955f; border-radius: 14px; background: #1c2320; font-size: 17px; }
.axe-rules-card > header { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.axe-rules h2 { margin: 0; font-size: 23px; color: #f5d4a0; }
.axe-rules h3 { margin: 0 0 8px; font-size: 17px; color: #e2bf87; }
.axe-rules-scroll { min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding-right: 12px; touch-action: pan-y !important; }
.axe-rules-scroll:focus-visible { outline: 2px solid var(--gold); outline-offset: -2px; }
.axe-rules section + section { margin-top: 24px; }
.axe-rules ul { margin: 0; padding-left: 1.3em; line-height: 1.8; }
.axe-rules li + li { margin-top: 8px; }
.axe-coach { position: absolute; inset: 0; z-index: 90; display: flex; align-items: flex-end; justify-content: center; padding: clamp(14px,3vw,32px); background: linear-gradient(180deg,rgba(5,9,8,.35),rgba(5,9,8,.83)); }
.axe-coach-card { display: grid; grid-template-rows: auto minmax(0,1fr) auto; width: min(760px,100%); max-height: 100%; min-height: 0; gap: 16px; padding: 22px; border: 1px solid #b99760; border-radius: 16px; background: linear-gradient(145deg,#26312b,#151e19); box-shadow: 0 18px 70px rgba(0,0,0,.5),inset 0 1px rgba(255,255,255,.06); }
.axe-coach-header { display: flex; align-items: center; gap: 13px; min-width: 0; }
.axe-coach-portrait-frame { position: relative; flex: 0 0 62px; width: 62px; height: 62px; overflow: hidden; border: 1px solid #9c8158; border-radius: 50%; background: #3c4132; }
.axe-coach-portrait { --portrait-width: 260px; position: absolute; left: 50%; top: calc(5px - var(--head-ratio) * var(--portrait-width)); width: var(--portrait-width); max-width: none; height: auto; transform: translateX(calc(-1 * var(--portrait-ax))); }
.axe-coach-identity { min-width: 0; }
.axe-coach-identity small, .axe-coach-identity strong { display: block; }
.axe-coach-identity small { margin-bottom: 3px; color: #baa783; font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.axe-coach-identity strong { color: #f2dbb1; font-size: 18px; }
.axe-coach-progress { margin-left: auto; color: #b6b7a4; font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.axe-coach-scroll { min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding-right: 5px; touch-action: pan-y !important; }
.axe-coach-title { margin: 0 0 9px; color: #f4e4c8; font-size: 23px; line-height: 1.5; }
.axe-coach-line { margin: 0; color: #e0e0d1; font-size: 16px; line-height: 1.9; white-space: pre-line; }
.axe-coach-actions { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 10px; padding-top: 13px; border-top: 1px solid var(--axe-line); }
.axe-coach-actions .axe-button { min-height: 48px; }
.axe-coach-skip { color: #b9bcae; font-size: 12px; }
.axe-coach-diagram { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 15px; }
.axe-coach-diagram > section { display: flex; align-items: center; gap: 12px; padding: 13px; border: 1px solid rgba(232,190,127,.22); border-radius: 9px; background: rgba(0,0,0,.15); }
.axe-coach-diagram .axe-coach-score-kill { border-color: rgba(130,190,219,.3); }
.axe-coach-target-icon { flex: 0 0 66px; width: 66px; height: 66px; }
.axe-coach-diagram strong { color: #f2d4a7; font-size: 14px; }
.axe-coach-score-kill strong { color: #b6e0ee; }
.axe-coach-diagram p { margin: 4px 0; color: #e4e2d2; font-size: 13px; line-height: 1.6; }
.axe-coach-diagram small { display: block; color: #aeb6a8; font-size: 12px; font-weight: 700; line-height: 1.5; }
.axe-game[data-paused="true"] *, .axe-game[data-paused="true"] *::before, .axe-game[data-paused="true"] *::after { animation-play-state: paused !important; }
@keyframes axe-score-arrive { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

@container (min-width: 900px) {
  .axe-intro { position: relative; padding-right: 390px; }
  .axe-versus-menu { position: absolute; right: clamp(20px,5vw,80px); top: 50%; transform: translateY(-50%); width: 280px; padding: 18px; border: 1px solid #665768; border-radius: 10px; background: #201728; }
  .axe-versus-menu > p { line-height: 1.6; }
}
@container (max-width: 650px) and (min-height: 501px) {
  .axe-intro { padding: 16px; gap: 10px; }
  .axe-intro h1 { font-size: 32px; } .axe-intro h2 { display: none; }
  .axe-intro p { font-size: 15px; } .axe-intro ol { font-size: 14px; line-height: 1.6; margin: 8px 0; }
  .axe-intro .axe-button { min-height: 48px; } .axe-intro .axe-back { padding: 6px 0; }
  .axe-menu-help { font-size: 12px; }
  .axe-game { padding: max(10px,env(safe-area-inset-top)) 10px max(10px,env(safe-area-inset-bottom)); gap: 9px; grid-template-rows: auto minmax(0,1fr); font-size: 14px; }
  .axe-header { display: grid; grid-template-columns: minmax(0,1fr) auto auto; column-gap: 6px; row-gap: 2px; }
  .axe-header > div:first-child { grid-column: 1; grid-row: 1; }
  .axe-header .axe-total { grid-column: 2/-1; grid-row: 1; justify-self: end; gap: 5px; margin-left: 0; padding: 0; border: 0; }
  .axe-header .axe-total small { font-size: 12px; font-weight: 700; letter-spacing: 0; }
  .axe-header .axe-total strong { font-size: 26px; }
  .axe-header .axe-total > span { font-size: 12px; font-weight: 700; }
  .axe-header .axe-round { grid-column: 1; grid-row: 2; }
  .axe-header .axe-rules-button { grid-column: 2; grid-row: 2; }
  .axe-header .axe-close { grid-column: 3; grid-row: 2; }
  .axe-header h1 { font-size: 19px; letter-spacing: .075em; }
  .axe-header p { display: none; }
  .axe-round { padding: 6px; font-size: 12px; border-left: 0; }
  .axe-header .axe-button { padding: 7px 9px; font-size: 12px; font-weight: 700; }
  .axe-body { grid-template-columns: 1fr; grid-template-rows: minmax(0,1fr) auto; gap: 9px; }
  .axe-board-pane { border-radius: 13px; }
  .axe-legend { margin-top: 7px; padding: 3px 9px; font-size: 12px; font-weight: 700; }
  .axe-companion { min-height: 60px; padding: 6px 11px; gap: 9px; }
  .axe-portrait-frame { width: 42px; height: 44px; }
