}
/* Companion icon: each expression's face center sits in the middle of the circle. */
.axe-portrait-frame .axe-portrait { width: 450% !important; left: 50%; top: 50%; transform: translate(calc(var(--focus-x, .5) * -100%), calc(var(--focus-y, .28) * -100%)); }
/* Secondary readouts kept for screen readers only; the board, gauge and result card show the same thing. */
.axe-game .axe-quiet { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important; overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }

/* 本編の案内役と無料レッスンも、明るい紙の上で読める墨色に。 */
html:root[data-ui-theme="paper"] .axe-bar-menu .venue-host { color: var(--paper-ink); background: var(--lavender-soft); border-color: var(--paper-line); }
html:root[data-ui-theme="paper"] .axe-bar-menu .venue-host-copy small { color: var(--paper-muted); }
html:root[data-ui-theme="paper"] .axe-bar-menu .venue-host-copy strong { color: var(--lavender); }
html:root[data-ui-theme="paper"] .axe-bar-menu .axe-bar-lesson { color: var(--lavender); border-color: var(--lavender-line); }


/* WATL 2026 lounge rules: league scoreboard, painted target, calls on the board, halves and sudden death. */
.axe-game { grid-template-rows: auto minmax(0,1fr); }
.axe-division { order: 1; align-self: center; padding: 4px 9px; border: 1px solid #c4a766; border-radius: 4px; color: #f1dbb0; font-size: 12px; font-weight: 900; letter-spacing: .02em; white-space: nowrap; background: #141a18cc; }
.axe-scoreboard { display: grid; gap: 4px; padding: 6px 10px; border: 1px solid var(--axe-line); border-radius: 8px; background: #0e1413e6; font-variant-numeric: tabular-nums; }
.axe-score-row { display: grid; grid-template-columns: auto minmax(0,1fr) auto auto; align-items: center; gap: 8px; }
.axe-score-row[data-active="true"] .axe-score-name { color: #f3ca8b; }
.axe-score-name { min-width: 3.5em; color: #b7b1a3; font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.axe-score-tiles { display: flex; gap: 3px; min-width: 0; }
.axe-tile { position: relative; display: grid; grid-template-rows: auto auto; justify-items: center; flex: 1 1 0; min-width: 0; padding: 3px 0 2px; border: 1px solid rgba(255,255,255,.08); border-radius: 4px; background: rgba(0,0,0,.25); line-height: 1.1; }
.axe-tile[data-half="1"]:first-of-type, .axe-tile[data-half="1"] + .axe-tile[data-half="1"] { margin-left: 0; }
.axe-tile[data-half="0"] + .axe-tile[data-half="1"] { margin-left: 10px; }
.axe-tile[data-half="0"] + .axe-tile[data-half="1"]::before { content: ""; position: absolute; left: -7px; top: 10%; height: 80%; border-left: 2px dashed #8a7a5a; }
.axe-tile i { color: #7f8681; font-size: 12px; font-style: normal; font-weight: 700; }
.axe-tile strong { color: #6f7672; font-size: 15px; font-weight: 800; }
.axe-tile em { position: absolute; right: 2px; top: 0; color: #e4c28a; font-size: 12px; font-style: normal; font-weight: 900; line-height: 1; }
.axe-tile[data-filled="true"] strong { color: #f1ddbb; }
.axe-tile[data-current="true"] { border-color: #d9a45c; background: rgba(217,161,82,.16); box-shadow: inset 0 2px #d9a45c; }
.axe-tile[data-current="true"] i { color: #f4d8aa; }
.axe-tile[data-outcome="bull"] strong, .axe-tile[data-outcome="killshot"] strong { color: #ffc46e; }
.axe-tile[data-outcome="killshot"] em { color: #9cecff; }
.axe-tile:is([data-outcome="drop"],[data-outcome="miss"],[data-outcome="killshot-miss"]) strong { color: #bda296; }
.axe-tile-sd { border-color: #4f8aa8; background: rgba(42,110,150,.2); }
.axe-tile-sd i { color: #9cd8ee; }
.axe-score-calls { display: inline-flex; gap: 2px; min-width: 2.6em; }
.axe-score-calls i { display: inline-grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; background: #2f7fc1; border: 1px solid #c23b2a; color: #fff; font-size: 12px; font-style: normal; font-weight: 900; }
.axe-score-total { min-width: 2em; color: #fff1ce; font-size: 18px; font-weight: 900; text-align: right; }
.axe-scores { display: none; }
.axe-markings { pointer-events: none; }
.axe-plank { transition: transform .35s ease; transform-origin: 330px 245px; }
.axe-target[data-half="1"] .axe-plank { transform: scaleX(-1); }
.axe-game[data-reduced-motion="true"] .axe-plank { transition: none; }
.axe-target [data-killshot][data-callable="true"] { pointer-events: auto; cursor: pointer; }
.axe-target [data-killshot][data-callable="true"] circle { pointer-events: auto; }
.axe-target[aria-disabled="false"] [data-killshot][data-callable="true"]:hover circle:first-child { stroke: #fff5b1; }
.axe-cuts { pointer-events: none; }
.axe-sd-badge { letter-spacing: .25em; paint-order: stroke; stroke: #0a1218; stroke-width: 4px; }
.axe-game[data-sudden-death="true"] .axe-board-pane { border-color: #4f8aa8; box-shadow: inset 0 0 0 1px #4f8aa855, 0 0 30px #2a6e9633; }
.axe-game[data-sudden-death="true"] .axe-total strong { color: #9cecff; }
.axe-calls { grid-template-columns: repeat(3,minmax(0,1fr)); grid-template-areas: "ul n ur" "ll n lr"; }
.axe-calls .axe-button:first-child { grid-area: n; }
.axe-calls [data-call="upper-left"] { grid-area: ul; } .axe-calls [data-call="upper-right"] { grid-area: ur; }
.axe-calls [data-call="lower-left"] { grid-area: ll; } .axe-calls [data-call="lower-right"] { grid-area: lr; }
.axe-calls [data-call]:not([data-call="normal"]) { color: #bfe3f5; }
.axe-calls [data-call]:not([data-call="normal"])[aria-pressed="true"] { border-color: #6fc4ea; background: rgba(47,127,193,.3); color: #e8f7ff; }
.axe-declare[data-kind="half"] { border-color: #e0b36c; background: rgba(34,24,10,.86); }
.axe-declare[data-kind="half"] strong { color: #ffd89a; font-size: 1.4rem; letter-spacing: .25em; }
.axe-declare[data-kind="half"] span { color: #f6e2bf; }
.axe-series-line { grid-column: 1/-1; }
.axe-result-tip { font-variant-numeric: tabular-nums; }
@container (max-width: 650px) and (min-height: 501px) {
  .axe-game { grid-template-rows: auto minmax(0,1fr); gap: 7px; }
  .axe-header .axe-division { grid-column: 1; grid-row: 2; justify-self: start; padding: 2px 6px; font-size: 12px; }
  .axe-header:has(.axe-division) .axe-round { grid-column: 1; grid-row: 2; justify-self: end; margin-right: 6px; }
  .axe-scoreboard { padding: 4px 6px; gap: 2px; }
  .axe-score-row { gap: 5px; }
  .axe-score-name { min-width: 0; font-size: 12px; }
  .axe-score-tiles { gap: 2px; }
  .axe-tile { padding: 2px 0 1px; }
  .axe-tile strong { font-size: 12px; } .axe-tile em { right: 0; top: 0; }
  .axe-tile[data-half="0"] + .axe-tile[data-half="1"] { margin-left: 6px; }
  .axe-tile[data-half="0"] + .axe-tile[data-half="1"]::before { left: -5px; }
  .axe-score-calls { min-width: 0; } .axe-score-calls i { width: 15px; height: 15px; }
  .axe-score-total { font-size: 15px; }
  .axe-calls .axe-button { min-height: 40px; }
}
@container (max-height: 500px) {
  .axe-game { grid-template-rows: auto minmax(0,1fr); gap: 5px; }
  .axe-division { padding: 2px 6px; }
  .axe-scoreboard { padding: 3px 8px; gap: 1px; }
  .axe-score-row { gap: 6px; }
  .axe-score-name { min-width: 0; }
  .axe-tile { grid-template-rows: auto; grid-auto-flow: column; gap: 3px; padding: 1px 2px; }
  .axe-tile strong { font-size: 12px; } .axe-tile em { position: static; }
  .axe-tile[data-half="0"] + .axe-tile[data-half="1"] { margin-left: 6px; }
  .axe-tile[data-half="0"] + .axe-tile[data-half="1"]::before { left: -5px; }
  .axe-score-calls i { width: 15px; height: 15px; }
  .axe-score-total { font-size: 14px; }
  .axe-calls .axe-button { min-height: 32px; }
}
/* Versus summary on a phone: the scoreboard already shows every throw, so the chips and the comment give way to the board. */
@container (max-width: 650px) and (min-height: 501px) {
  .axe-game[data-mode="versus"][data-phase="summary"] :is(.axe-challenges, .axe-companion) { display: none; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-result-value { font-size: 44px; margin: 0; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-result-card { padding: 8px 10px; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-match-records { gap: 4px; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-match-records p { line-height: 1.4; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-rank { margin: 0; }
  .axe-game[data-mode="versus"] .axe-panel { gap: 5px; }
}
@container (max-height: 500px) {
  .axe-game[data-mode="versus"][data-phase="summary"] :is(.axe-challenges, .axe-companion) { display: none; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-result-value { font-size: 40px; }
  .axe-game[data-mode="versus"][data-phase="summary"] .axe-rank span { display: none; }
}

/* AXR07: the target and the axe read at a glance. Presentation only. */
.axe-zone-halo { stroke: #fff2b0; stroke-width: 3; pointer-events: none; }
.axe-zone-halo[data-kind="kill"] { stroke: #b6f0ff; }
.axe-zone-halo[data-kind="ring"] { stroke-width: 2.5; stroke-dasharray: 10 6; }
.axe-ghost { pointer-events: none; }
.axe-contact-shadow { pointer-events: none; }
.axe-gauge-label { pointer-events: none; letter-spacing: .02em; }
.axe-zoom { position: absolute; bottom: 12px; z-index: 3; display: grid; justify-items: center; gap: 4px; width: clamp(108px, 27%, 176px); margin: 0; pointer-events: none;
  animation: axe-zoom-in .26s cubic-bezier(.2,.8,.2,1) .18s both; }
.axe-zoom[data-side="left"] { left: 12px; }
.axe-zoom[data-side="right"] { right: 12px; }
.axe-zoom-view { display: block; width: 100%; aspect-ratio: 1; border: 3px solid #f6e3bd; border-radius: 50%; background: #2a1b10; box-shadow: 0 6px 22px rgba(0,0,0,.55), inset 0 0 0 2px rgba(0,0,0,.4); }
.axe-zoom[data-scored="false"] .axe-zoom-view { border-color: #e7a08d; }
.axe-zoom figcaption { display: grid; justify-items: center; padding: 3px 10px; border-radius: 8px; background: rgba(14,10,8,.86); color: #f6e7c8; line-height: 1.3; text-align: center; }
.axe-zoom figcaption strong { font-size: 20px; font-weight: 900; color: #ffe3a6; }
.axe-zoom[data-scored="false"] figcaption strong { color: #f0b3a1; }
.axe-zoom figcaption span { font-size: 12px; font-weight: 700; }
@keyframes axe-zoom-in { from { opacity: 0; transform: scale(.6); } to { opacity: 1; transform: scale(1); } }
.axe-game[data-reduced-motion="true"] .axe-zoom { animation: none; }
@container (max-width: 650px) and (min-height: 501px) {
  .axe-zoom { width: clamp(92px, 30%, 128px); bottom: 8px; }
  .axe-zoom figcaption strong { font-size: 16px; }
}
@container (max-height: 500px) {
  .axe-zoom { width: clamp(84px, 24%, 112px); bottom: 6px; }
  .axe-zoom figcaption { padding: 1px 6px; }
  .axe-zoom figcaption strong { font-size: 14px; }
}

/* #2718 斧投げ専用テーマ「レーン」: 黒板の面・木の枠・チョークの文字・安全オレンジ。
   どのUIテーマ設定でも同じ見た目にし、日常の紙×ラベンダーは使わない（入った瞬間に別の遊びだと分かるように）。
   寸法・当たり判定と、意味の色（赤のブル・青のキルショット・緑の適正帯・赤茶の落下）は変えない。 */
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup, .axe-intro) {
  --lane-board: #17201e; --lane-board-2: #1f2b28; --lane-board-3: #2a3935;
  --lane-wood: #8a5a32; --lane-wood-dark: #2e1c10;
  --lane-chalk: #f4f0e6; --lane-chalk-dim: #bcc5bd; --lane-chalk-faint: #8e9b94; --lane-line: #f4f0e62b;
  --lane-orange: #ff8c3a; --lane-orange-hi: #ffad66; --lane-orange-deep: #b4500f; --lane-orange-ink: #2a1205;
  --lane-slate: linear-gradient(180deg, #ffffff09, transparent 40%), radial-gradient(ellipse at 20% 0%, #ffffff0c, transparent 60%), #17211e;
  --lane-frame: inset 0 0 0 2px var(--lane-wood), inset 0 0 0 3px #0000008c;
  --lane-tape: repeating-linear-gradient(-45deg, var(--lane-orange) 0 10px, #1a120c 10px 20px);
}
.axe-game { --axe-amber: var(--lane-orange-hi); --axe-line: var(--lane-line); --axe-muted: var(--lane-chalk-dim);
  color: var(--lane-chalk); background: linear-gradient(90deg, #0a1211d4 36%, #0a1110f2 80%), var(--axe-bg) center / cover; }
.axe-game::before { background: radial-gradient(ellipse at 30% 46%, #ff8c3a17, transparent 56%); }
.axe-game::after { content: ""; position: absolute; inset: 0 0 auto; height: 5px; background: var(--lane-tape); pointer-events: none; }

/* 看板（上の帯）と各投の黒板。枠は内側の影で描き、寸法は変えない。 */
.axe-game :is(.axe-header, .axe-scoreboard, .axe-panel) { border: 1px solid var(--lane-wood-dark); background: var(--lane-slate);
  box-shadow: var(--lane-frame), 0 12px 30px #00000080; }
.axe-game .axe-header { padding: 5px 8px 5px 14px; border-radius: 10px; }
.axe-game .axe-scoreboard, .axe-game .axe-panel { border-radius: 10px; }
.axe-game .axe-header h1 { color: var(--lane-chalk); font-style: italic; letter-spacing: .1em; text-shadow: 2px 2px 0 var(--lane-orange-deep); }
.axe-game .axe-header p { color: var(--lane-chalk-dim); }
.axe-game .axe-round { color: var(--lane-orange-hi); border-left-color: var(--lane-line); }
.axe-game .axe-division { border-color: var(--lane-orange); background: #0000004d; color: var(--lane-orange-hi); }
.axe-game .axe-total { border-color: var(--lane-line); border-left-color: var(--lane-orange); background: #0a100fe6; box-shadow: inset 0 2px 6px #0009, 0 0 calc(var(--score-glow,0) * 30px) #ff8c3a59; }
.axe-game .axe-total small, .axe-game .axe-total > span { color: var(--lane-chalk-dim); }
.axe-game .axe-total strong { color: var(--lane-chalk); }
.axe-game .axe-score-name { color: var(--lane-chalk-dim); }
.axe-game .axe-score-row[data-active="true"] .axe-score-name { color: var(--lane-orange-hi); }
.axe-game .axe-score-total { color: var(--lane-chalk); }
.axe-game .axe-tile { border-color: var(--lane-line); background: #0000002e; }
.axe-game .axe-tile i { color: var(--lane-chalk-faint); }
.axe-game .axe-tile strong { color: #6e7b75; }
.axe-game .axe-tile[data-filled="true"] strong { color: var(--lane-chalk); }
.axe-game .axe-tile:is([data-outcome="bull"],[data-outcome="killshot"]) strong { color: #ffc46e; }
.axe-game .axe-tile:is([data-outcome="drop"],[data-outcome="miss"],[data-outcome="killshot-miss"]) strong { color: #c9a493; }
.axe-game .axe-tile[data-current="true"] { border-color: var(--lane-orange); background: #ff8c3a26; box-shadow: inset 0 3px var(--lane-orange); }
.axe-game .axe-tile[data-current="true"] i { color: var(--lane-orange-hi); }
.axe-game .axe-tile-sd { border-color: #4f8aa8; background: #2a6e9633; }
.axe-game .axe-tile[data-half="0"] + .axe-tile[data-half="1"]::before { border-left-color: var(--lane-chalk-faint); }
.axe-game .axe-legend { border-color: var(--lane-line); background: #0b1211e0; color: var(--lane-chalk-dim); }

/* 操作欄の中身 */
.axe-game .axe-challenges li { border-color: var(--lane-line); background: #00000033; color: var(--lane-chalk-dim); }
.axe-game .axe-challenges i { color: var(--lane-orange-hi); }
.axe-game .axe-challenges small { color: var(--lane-chalk-faint); }
.axe-game .axe-challenges [data-state="done"] { border-color: #8fd3a0; background: #4c966038; color: #dff5e2; }
.axe-game .axe-challenges [data-state="done"] i { color: #9be7ad; }
.axe-game .axe-companion { border-top-color: var(--lane-line); background: #0000004d; }
.axe-game .axe-companion strong { color: var(--lane-orange-hi); }
.axe-game .axe-comment, .axe-game .axe-note { color: var(--lane-chalk); }
.axe-game .axe-portrait-frame { border-color: var(--lane-orange); background: #2a3532; }
.axe-game .axe-steps li { border-color: var(--lane-line); background: #0000002e; }
.axe-game .axe-steps span { color: var(--lane-chalk-dim); }
.axe-game .axe-steps [data-state="live"] { border-color: var(--lane-orange); background: #ff8c3a26; box-shadow: inset 0 2px var(--lane-orange); }
.axe-game .axe-steps [data-state="live"] span { color: var(--lane-orange-hi); }
.axe-game .axe-steps [data-state="locked"] strong { color: var(--lane-chalk); }
.axe-game .axe-steps [data-state="waiting"] strong { color: var(--lane-chalk-faint); }
.axe-game .axe-live-score { border-bottom-color: var(--lane-line); }
.axe-game .axe-live-label { color: var(--lane-chalk-dim); }
.axe-game .axe-live-score strong { color: var(--lane-orange-hi); }
.axe-game .axe-gauge { border-color: #f4f0e64d; }
.axe-game .axe-timing > span:not(.axe-power-readout), .axe-game .axe-keyhint { color: var(--lane-chalk-faint); }
.axe-game .axe-keyhint kbd { border-color: var(--lane-line); color: var(--lane-chalk-dim); }
.axe-game .axe-stability-meter { background: #f4f0e61a; }
.axe-game .axe-result-card { border-left: 3px solid var(--lane-orange); background: linear-gradient(90deg, #ff8c3a14, transparent 70%); }
.axe-game .axe-result-label { color: var(--lane-orange-hi); }
.axe-game .axe-result-value { color: #fff7e8; text-shadow: 3px 3px 0 #00000059; }
.axe-game .axe-result-tip { color: var(--lane-chalk-dim); }
.axe-game .axe-rank small, .axe-game .axe-rank span { color: var(--lane-chalk-dim); }
.axe-game .axe-match-score { border-color: var(--lane-line); background: #00000033; color: var(--lane-chalk); }
.axe-game .axe-match-records strong { color: var(--lane-orange-hi); }
.axe-game .axe-zoom-view { border-color: var(--lane-chalk); }
.axe-game .axe-zoom figcaption { border: 1px solid var(--lane-line); background: #0b1211e6; color: var(--lane-chalk); }
.axe-game .axe-zoom figcaption strong { color: var(--lane-orange-hi); }

/* ボタン: 黒板の札。押した札と決定ボタンは安全オレンジ。青の宣言と緑の「いま放す」は既存の意味色が勝つ
   （決定ボタンの指定は .axe-primary 単独にして、適正帯の緑 .axe-game[data-phase="power"]:has(...) .axe-primary より弱く保つ。ホバー中も緑）。 */
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-button { border-color: #f4f0e642; background: var(--lane-board-2); color: var(--lane-chalk); box-shadow: inset 0 -2px #00000066; }
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-button:hover:not(:disabled) { border-color: var(--lane-orange); background: var(--lane-board-3); }
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-button[aria-pressed="true"] { border-color: var(--lane-orange-hi); background: var(--lane-orange); color: var(--lane-orange-ink); font-weight: 900; box-shadow: inset 0 -3px var(--lane-orange-deep); }
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-primary { border-color: #ffd3aa; background: linear-gradient(180deg, var(--lane-orange-hi), var(--lane-orange) 60%, #f27a24);
  color: var(--lane-orange-ink); letter-spacing: .08em; box-shadow: 0 3px 0 var(--lane-orange-deep), 0 8px 18px #00000073, inset 0 1px #ffffff66; }
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-primary:hover:not(:disabled) { border-color: #ffe4c8; background: linear-gradient(180deg, #ffc690, var(--lane-orange-hi) 60%, var(--lane-orange)); }
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-primary:active:not(:disabled) { transform: translateY(2px); box-shadow: 0 1px 0 var(--lane-orange-deep), 0 4px 10px #00000073; }
:is(.axe-game, .axe-rules, .axe-coach, .axe-setup) .axe-button:focus-visible { outline-color: #fff2c2; }
.axe-game .axe-close, .axe-coach .axe-coach-skip { color: var(--lane-chalk-dim); }

/* ルール・レッスン: 同じ黒板と木の枠。上にレーンのテープ。 */
.axe-rules { background: #08100ef2; color: var(--lane-chalk); }
.axe-coach { background: linear-gradient(180deg, #060b0a4d, #060b0ad1); }
:is(.axe-rules-card, .axe-coach-card) { position: relative; border: 1px solid var(--lane-wood-dark); background: var(--lane-slate); box-shadow: var(--lane-frame), 0 20px 64px #000000b3; }
:is(.axe-rules-card, .axe-coach-card)::before { content: ""; position: absolute; left: 3px; right: 3px; top: 3px; height: 5px; border-radius: 8px 8px 0 0; background: var(--lane-tape); pointer-events: none; }
.axe-rules h2, .axe-coach .axe-coach-title, .axe-coach .axe-coach-identity strong { color: var(--lane-chalk); }
.axe-rules h3, .axe-coach .axe-coach-identity small { color: var(--lane-orange-hi); }
.axe-rules li::marker { color: var(--lane-orange); }
.axe-coach .axe-coach-line { color: #ebe7dc; }
.axe-coach .axe-coach-progress { color: var(--lane-chalk-dim); }
.axe-coach .axe-coach-portrait-frame { border-color: var(--lane-orange); background: #2a3532; }
.axe-coach .axe-coach-actions { border-top-color: var(--lane-line); }
:is(.axe-rules, .axe-coach) .axe-coach-diagram > section { border-color: var(--lane-line); background: #00000033; }
:is(.axe-rules, .axe-coach) .axe-coach-diagram strong { color: var(--lane-orange-hi); }
:is(.axe-rules, .axe-coach) .axe-coach-score-kill { border-color: #82bedb4d; }
:is(.axe-rules, .axe-coach) .axe-coach-score-kill strong { color: #b6e0ee; }
:is(.axe-rules, .axe-coach) .axe-coach-diagram p { color: var(--lane-chalk); }
:is(.axe-rules, .axe-coach) .axe-coach-diagram small { color: var(--lane-chalk-dim); }

/* #2718 UI方針（ミニゲーム共通・オーナー指示）: 文字を詰めない／遊び方・操作は「？」から開く／基本画面は必要なUIだけ。
   画面から外すだけで、読み上げ用の文字は残す（.axe-quiet と同じ隠し方）。中身はすべて「？」のルールに書いてある。 */
.axe-game .axe-legend { display: none; }
.axe-game :is(.axe-header p, .axe-steps, .axe-power-readout) { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.axe-game:not([data-phase="horizontal"]) .axe-gauge-label[data-gauge="horizontal"],
.axe-game:not([data-phase="vertical"]) .axe-gauge-label[data-gauge="vertical"] { display: none; }
.axe-help { position: relative; }
/* 「？」と「✕」は見た目を文字ほどの小さな丸にし、押せる範囲（ボタンの箱）は透明なまま広く取る（#2729 オーナー指摘「？ボタンが大きい」）。
   ほかのミニゲーム（#2991）と同じ大きさ: 丸は「？」の文字（実寸 11.5px 以上）＋11px、押せる箱は実寸 40px 以上（本編の #stage では --k で割り戻す）。
   丸は ::before で描く。箱は上下の負の余白で看板の高さを押し広げない。 */
/* 看板は押せる箱が丸ごと収まる高さを保つ（箱が看板の外へはみ出さない）。 */
.axe-game .axe-header { --help-font: max(20px, calc(11.5px / var(--k, 1))); --help-size: calc(var(--help-font) + 11px); --help-hit: max(44px, calc(40px / var(--k, 1)));
  min-height: calc(var(--help-hit) + 2px); }
.axe-game .axe-header .axe-help { position: relative; display: grid; place-items: center; width: var(--help-hit); min-width: var(--help-hit); height: var(--help-hit); min-height: var(--help-hit);
  margin-block: calc((var(--help-size) - var(--help-hit)) / 2); padding: 0; border: 0; border-radius: 50%; background: transparent; box-shadow: none; font-size: var(--help-font); font-weight: 900; line-height: 1; }
.axe-game .axe-header .axe-help::before { content: ""; position: absolute; left: 50%; top: 50%; width: var(--help-size); height: var(--help-size); transform: translate(-50%, -50%);
  box-sizing: border-box; border: 1.5px solid #f4f0e66b; border-radius: 50%; background: var(--lane-board-2); box-shadow: inset 0 -2px #00000066; pointer-events: none; }
.axe-game .axe-header .axe-help > span { position: relative; }
.axe-game .axe-header .axe-help:hover:not(:disabled) { border: 0; background: transparent; }
.axe-game .axe-header .axe-help:hover:not(:disabled)::before { border-color: var(--lane-orange); background: var(--lane-board-3); }
.axe-game .axe-header .axe-help:focus-visible { outline: none; }
.axe-game .axe-header .axe-help:focus-visible::before { outline: 3px solid #fff2c2; outline-offset: 2px; }

/* 入った瞬間の幕（#2718）: 黒板の幕に斜めの一閃、題字を押してから上下へ割れる。約1秒。
   入力は素通し（pointer-events: none）で、説明やレッスンで時計が止まっても幕だけは最後まで進む。 */
.axe-game .axe-cutin { position: absolute; inset: 0; z-index: 120; overflow: hidden; pointer-events: none; contain: layout paint; container-type: size;
  animation: axe-cutin-life 1s linear both; }
.axe-cutin :is(.axe-cutin-top, .axe-cutin-bottom) { position: absolute; inset: 0;
  background: repeating-linear-gradient(-45deg, #ffffff06 0 2px, transparent 2px 16px), radial-gradient(ellipse at 50% 50%, #263634, #0e1614 72%); }
.axe-cutin .axe-cutin-top { clip-path: polygon(0 0, 100% 0, 100% 40%, 0 60%); animation: axe-cutin-top .38s cubic-bezier(.55,0,.85,.35) .62s both; }
.axe-cutin .axe-cutin-bottom { clip-path: polygon(0 60%, 100% 40%, 100% 100%, 0 100%); animation: axe-cutin-bottom .38s cubic-bezier(.55,0,.85,.35) .62s both; }
.axe-cutin .axe-cutin-slash { position: absolute; inset: 0; background: linear-gradient(90deg, #ffe0bd, var(--lane-orange) 45%, #ff6a1a);
  clip-path: polygon(0 58.5%, 100% 38.5%, 100% 41.5%, 0 61.5%); animation: axe-cutin-slash .2s cubic-bezier(.2,.8,.2,1) .04s both, axe-cutin-fade .12s ease-in .62s forwards; }
.axe-cutin .axe-cutin-card { position: absolute; left: 50%; top: 50%; display: flex; flex-direction: column; align-items: center; gap: 1.2cqh; translate: -50% -50%; white-space: nowrap;
  animation: axe-cutin-stamp .26s cubic-bezier(.2,.9,.3,1.3) .12s both, axe-cutin-fade .14s ease-in .56s forwards; }
.axe-cutin [data-text]::before { content: attr(data-text); }
.axe-cutin .axe-cutin-tag { padding: 3px 12px; background: var(--lane-orange); color: var(--lane-orange-ink); font-size: clamp(14px, 1.6cqw, 18px); font-weight: 900; letter-spacing: .32em; transform: skewX(-12deg); }
.axe-cutin .axe-cutin-title { color: var(--lane-chalk); font-size: clamp(40px, 11cqw, 112px); font-weight: 900; font-style: italic; line-height: 1.05; letter-spacing: .05em;
  text-shadow: .05em .05em 0 var(--lane-orange-deep), 0 0 .4em #000000d9; }
.axe-cutin .axe-cutin-label { padding: 4px 16px; border-top: 2px solid var(--lane-orange); background: #000000a6; color: var(--lane-chalk); font-size: clamp(14px, 2.1cqw, 22px); font-weight: 700; letter-spacing: .12em; }
@keyframes axe-cutin-life { 0%, 99.9% { visibility: visible; } 100% { visibility: hidden; } }
@keyframes axe-cutin-top { to { transform: translate(-4%, -64%); } }
@keyframes axe-cutin-bottom { to { transform: translate(4%, 64%); } }
@keyframes axe-cutin-slash { from { clip-path: polygon(0 58.5%, 0 58.5%, 0 61.5%, 0 61.5%); } }
@keyframes axe-cutin-stamp { from { opacity: 0; scale: 1.4; } to { opacity: 1; scale: 1; } }
@keyframes axe-cutin-fade { to { opacity: 0; } }
.axe-game[data-paused="true"] :is(.axe-cutin, .axe-cutin *), .axe-game[data-paused="true"] .axe-cutin [data-text]::before { animation-play-state: running !important; }
.axe-game[data-reduced-motion="true"] .axe-cutin { display: none !important; }
@media (prefers-reduced-motion: reduce) { .axe-game .axe-cutin { display: none !important; } }

/* 狭い画面: 看板の余白だけ詰め、文字と操作の大きさは従来のまま。
   PC表示の最も狭い幅（651〜760px）は対戦の「あなた 1 / 10 投 · 前半」と合計点で看板が溢れていた（#2718 以前から）ので、回数を2行まで折り返し、余白を詰める。 */
@container (min-width: 651px) and (max-width: 760px) and (min-height: 501px) {
  .axe-game .axe-header { padding-inline: 8px 4px; gap: 8px; }
  .axe-game .axe-round { max-width: 7.5em; padding-inline: 8px; white-space: normal; line-height: 1.35; text-align: center; }
  .axe-game .axe-total { padding-inline: 10px; }
}
@container (max-width: 650px) and (min-height: 501px) {
  .axe-game .axe-header { padding: 4px 6px 4px 10px; }
}
@container (max-height: 500px) {
  .axe-game .axe-header { padding: 3px 6px 3px 10px; }
}

/* #2834 スマホ横持ちで読める斧投げ（#2729 M-1）。
   残り回数は青いバッジ1つ（斧のマーク＋数）。宣言の残りの文・各投の番号・「各投」は画面から外し、読み上げとルール（？）に残す。 */
.axe-score-calls { display: inline-flex; align-items: center; justify-content: center; gap: 3px; min-width: 0; padding: 2px 9px 2px 6px; border: 1px solid #c23b2a; border-radius: 999px;
  background: #2f7fc1; color: #fff; font-size: 15px; font-weight: 900; line-height: 1.2; font-variant-numeric: tabular-nums; white-space: nowrap; }
.axe-score-calls .axe-mark { width: 1.05em; height: 1.05em; flex: none; }
.axe-score-calls[data-remaining="0"] { opacity: .45; }
.axe-tile:not(.axe-tile-sd) i { display: none; }
/* 「各投」を読み上げだけにした行は、名前の列を詰めて投ごとの点数を広く取る。 */
.axe-score-row:has(> .axe-score-name.axe-quiet) { grid-template-columns: minmax(0,1fr) auto auto; }
.axe-tile:not(.axe-tile-sd) { grid-template-rows: auto; }
.axe-game .axe-call-status[data-kind="remaining"] { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.axe-steps span b { font-weight: 900; }

/* 本編の #stage（1280×720 を縮めて表示）の中だけ: 文字はステージ上 24px 以上、押す部品は 82px 以上。
   iPhone 横持ち（0.54倍）でも Safari のバーあり（0.47倍）でも、実寸で文字 11px・押す部品 38px を下回らない。 */
.axe-in-stage { --axe-tap: 82px; --axe-text: 24px; padding: 18px 22px; gap: 10px; font-size: var(--axe-text); }
.axe-in-stage .axe-button { min-height: var(--axe-tap); font-size: var(--axe-text); font-weight: 700; }
.axe-in-stage .axe-header { gap: 14px; min-height: max(64px, calc(var(--help-hit) + 2px)); }
.axe-in-stage .axe-header h1 { font-size: 32px; }
/* 「？」「✕」の大きさは上の共通の指定（iPhone 横の 0.54倍で丸はステージ上 32px・押せる箱は 74px＝実寸 40px）。押せる箱が広いぶん、2つの丸の間を詰める。 */
.axe-game.axe-in-stage .axe-header .axe-close { margin-left: -14px; }
.axe-in-stage .axe-division { padding: 4px 12px; font-size: var(--axe-text); }
.axe-in-stage .axe-total { gap: 8px; }
.axe-in-stage .axe-total small, .axe-in-stage .axe-total > span { font-size: var(--axe-text); }
/* 合計点の数字: 行の高さを 1.2 にすると書体の字の高さ（約1.46）より低く、字が「合計点」の枠の下へ約3px出ていた。
   行の高さを書体どおり（normal）にして枠の中に収める（枠は12px高くなるが、上の帯（92px）の中に収まる）。 */
.axe-in-stage .axe-total strong { font-size: 48px; line-height: normal; }
.axe-in-stage .axe-round { padding: 8px 14px; font-size: 26px; font-weight: 700; }
.axe-in-stage .axe-heat { font-size: var(--axe-text); }
.axe-in-stage .axe-scoreboard { padding: 6px 10px; gap: 4px; }
.axe-in-stage .axe-score-row { gap: 10px; }
.axe-in-stage .axe-score-name { font-size: var(--axe-text); }
.axe-in-stage .axe-score-tiles { gap: 5px; }
.axe-in-stage .axe-tile { padding: 2px 0; }
.axe-in-stage .axe-tile strong { font-size: 26px; line-height: 1.25; }
.axe-in-stage .axe-tile i { font-size: var(--axe-text); }
.axe-in-stage .axe-tile em { right: 5px; top: 50%; transform: translateY(-50%); font-size: var(--axe-text); }
.axe-in-stage .axe-score-calls { padding: 3px 12px 3px 9px; gap: 5px; font-size: var(--axe-text); }
.axe-in-stage .axe-score-total { min-width: 2.2em; font-size: 30px; }
.axe-in-stage .axe-body, .axe-in-stage.axe-game .axe-body { grid-template-columns: minmax(0,1fr) 430px; gap: 18px; }
.axe-in-stage .axe-panel, .axe-in-stage.axe-game .axe-panel { padding: 14px 16px; gap: 10px; overflow-y: auto; overscroll-behavior: contain; }
.axe-in-stage .axe-challenges { gap: 6px; }
.axe-in-stage .axe-challenges li, .axe-in-stage .axe-challenges small { font-size: var(--axe-text); }
.axe-in-stage .axe-challenges li { padding: 3px 12px; }
.axe-in-stage .axe-companion { gap: 12px; padding: 8px 10px; }
.axe-in-stage .axe-companion strong { font-size: var(--axe-text); }
.axe-in-stage .axe-panel .axe-comment { margin-top: 2px; font-size: var(--axe-text); line-height: 1.45; }
.axe-in-stage .axe-panel .axe-portrait-frame { width: 64px; height: 66px; }
.axe-in-stage .axe-call-status { font-size: var(--axe-text); line-height: 1.4; }
.axe-in-stage .axe-calls { gap: 8px; }
.axe-in-stage .axe-calls .axe-button { min-height: var(--axe-tap); padding: 6px; font-size: var(--axe-text); }
.axe-in-stage .axe-note { font-size: var(--axe-text); }
.axe-in-stage .axe-live-score { padding-block: 2px 6px; }
.axe-in-stage .axe-live-label { font-size: var(--axe-text); }
.axe-in-stage .axe-live-score strong { font-size: 40px; }
/* 工程チップ ↔ ↕ ↻: 今の工程だけ金色。確定した値はチップの下に出す。 */
.axe-game.axe-in-stage .axe-steps { position: static !important; width: auto !important; height: auto !important; margin: 0 !important; overflow: visible !important;
  clip-path: none !important; white-space: normal !important; gap: 8px; }
.axe-in-stage .axe-steps li { display: grid; justify-items: center; gap: 2px; padding: 4px 4px 6px; text-align: center; }
.axe-in-stage .axe-steps span { margin: 0; font-size: 36px; line-height: 1.1; }
.axe-in-stage .axe-steps strong { font-size: var(--axe-text); line-height: 1.3; letter-spacing: 0; }
.axe-game.axe-in-stage .axe-steps [data-state="live"] { border-color: #ffc46e; background: #ffc46e2e; box-shadow: inset 0 3px #ffc46e; }
.axe-game.axe-in-stage .axe-steps [data-state="live"] span, .axe-game.axe-in-stage .axe-steps [data-state="live"] strong { color: #ffd58f; }
/* 回転ゲージ: 見出しの文はチップ ↻ と同じなので読み上げだけ。説明の文（補正・腕の疲れ・キー操作）は「？」へ。 */
.axe-in-stage .axe-timing { padding: 4px 0; }
.axe-in-stage :is(.axe-timing .axe-power-label, .axe-feedback, .axe-steadiness) { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.axe-in-stage .axe-keyhint { display: none !important; }
.axe-in-stage .axe-gauge { height: 46px; }
.axe-in-stage .axe-sweet::after { font-size: var(--axe-text); }
.axe-in-stage .axe-stability-meter { height: 5px; }
.axe-in-stage .axe-primary { font-size: 28px; }
.axe-in-stage .axe-controls { gap: 8px; }
.axe-in-stage .axe-controls .axe-button { min-height: var(--axe-tap); padding: 6px 8px; font-size: var(--axe-text); line-height: 1.25; }
.axe-in-stage .axe-result-card { padding: 8px 14px; }
.axe-in-stage .axe-result-label, .axe-in-stage .axe-result-tip { font-size: var(--axe-text); line-height: 1.4; }
.axe-in-stage .axe-result-value small { font-size: max(.25em, 24px); }
.axe-in-stage .axe-rank small, .axe-in-stage .axe-rank span { font-size: var(--axe-text); }
.axe-in-stage .axe-match-score, .axe-in-stage .axe-match-records { font-size: var(--axe-text); }
.axe-in-stage .axe-zoom { width: clamp(150px, 30%, 200px); }
.axe-in-stage .axe-zoom figcaption strong { font-size: 30px; }
.axe-in-stage .axe-zoom figcaption span { font-size: var(--axe-text); }
.axe-in-stage .axe-declare strong { font-size: 32px; }
.axe-in-stage .axe-declare span { font-size: 26px; }
/* ルール（？）とマキのレッスンも同じ下限で。 */
.axe-in-stage .axe-rules-card, .axe-in-stage .axe-coach-card { width: min(980px, 100%); font-size: var(--axe-text); }
.axe-in-stage .axe-rules h2 { font-size: 30px; }
.axe-in-stage .axe-rules h3 { font-size: 27px; }
.axe-in-stage .axe-rules ul { line-height: 1.6; }
.axe-in-stage :is(.axe-rules, .axe-coach) .axe-button { min-height: var(--axe-tap); padding-inline: 22px; }
.axe-in-stage :is(.axe-rules, .axe-coach) .axe-coach-diagram :is(strong, p, small) { font-size: var(--axe-text); }
.axe-in-stage :is(.axe-rules, .axe-coach) .axe-coach-target-icon { flex-basis: 150px; width: 150px; height: 150px; }
/* 小さな的の絵: リング1〜4の数字は細すぎて読めないので絵だけにし（横の文に書いてある）、青の7・8は大きく。 */
.axe-in-stage :is(.axe-rules, .axe-coach) .axe-coach-score-normal .axe-coach-target-icon text { display: none; }
.axe-in-stage :is(.axe-rules, .axe-coach) .axe-coach-score-kill .axe-coach-target-icon text { font-size: 26px; }
.axe-in-stage .axe-coach-identity small, .axe-in-stage .axe-coach-progress, .axe-in-stage .axe-coach-line { font-size: var(--axe-text); }
.axe-in-stage .axe-coach-identity strong { font-size: 28px; }
.axe-in-stage .axe-coach-title { font-size: 30px; }
.axe-in-stage .axe-coach-actions .axe-coach-skip { font-size: var(--axe-text); }

/* ワイドステージ（#2861）と結果の詰め（#2729）。
   - 右パネルは下寄せのまま、中身が多い時も上が切れない（溢れたら上から読めてスクロールできる）。
   - 結果（summary）は「終了」「もう一度」を横に並べ、ボタン1段ぶん詰めて一画面に収める。
   - ワイドでは広がった幅を右パネルへ回して文の折り返しを減らし、左右のノッチ（safe-area）にかからないよう内側へ寄せる。 */
.axe-game .axe-panel { justify-content: safe flex-end; }
.axe-in-stage.axe-game[data-phase="summary"] .axe-panel { display: grid; grid-template-columns: 1fr 1fr; align-content: safe end; gap: 6px 8px; padding-block: 10px; }
.axe-in-stage.axe-game[data-phase="summary"] .axe-panel > * { grid-column: 1 / -1; }
#stage[data-wide] .axe-game.axe-in-stage { padding-left: max(22px, var(--stage-safe-l, 0px)); padding-right: max(22px, var(--stage-safe-r, 0px)); }
#stage[data-wide] .axe-in-stage.axe-game .axe-body { grid-template-columns: minmax(0,1fr) min(600px, calc(430px + var(--stage-gutter, 0px))); gap: 24px; }
/* 結果では「RANK」を点数の右に並べ、1段ぶん詰める（16:9 の画面でも「終了」「もう一度」まで一画面に収まる）。 */
.axe-in-stage.axe-game[data-phase="summary"] .axe-result-card { display: grid; grid-template-columns: auto minmax(0,1fr); align-items: center; column-gap: 16px; padding-block: 2px; }
.axe-in-stage.axe-game[data-phase="summary"] .axe-result-card > :not(.axe-result-value, .axe-rank) { grid-column: 1 / -1; }
.axe-in-stage.axe-game[data-phase="summary"] .axe-rank { flex-wrap: wrap; justify-content: flex-start; align-items: baseline; column-gap: 8px; row-gap: 0; margin: 0; }
/* A long sudden-death caption stays on one row so the result and buttons fit below the two-row scoreboard. */
.axe-game[data-mode="versus"][data-phase="summary"] .axe-result-label { font-size: 18px; line-height: 1.2; white-space: nowrap; }
/* 対戦の結果: 投ごとの点の一覧は上の得点表（あなた／ひよりの2段）と同じなので本編では出さない。
   チャレンジの札も畳む（達成数は成績の行「チャレンジ n/3」に残る）。勝敗・コメント・自分の点とランク・ボタンを一画面に。 */
.axe-in-stage.axe-game[data-mode="versus"][data-phase="summary"] :is(.axe-match-records, .axe-challenges) { display: none; }
/* ワイドでは「？」の遊び方を横に広げ、スクロールを減らす。 */
#stage[data-wide] .axe-in-stage .axe-rules-card { width: min(1240px, 100%); }
/* 単独ページ（axe-throw.html・練習用）の結果も本編と同じ詰め方にする。右パネルが下寄せの間は溢れた分が上へ隠れて見えず、
   safe flex-end（上の規則）にしてからは「終了」「もう一度」が画面の下へはみ出していた（1280×720 の対戦の結果・axe_versus の検査）。
   単独ページにも上の得点表と成績の行があるので、対戦の結果の投ごとの一覧とチャレンジの札は本編と同じく畳む。 */
.axe-game:not(.axe-in-stage)[data-phase="summary"] .axe-panel { display: grid; grid-template-columns: 1fr 1fr; align-content: safe end; gap: 6px 8px; padding-block: 10px; }
.axe-game:not(.axe-in-stage)[data-phase="summary"] .axe-panel > * { grid-column: 1 / -1; }
.axe-game:not(.axe-in-stage)[data-phase="summary"] .axe-result-card { display: grid; grid-template-columns: auto minmax(0,1fr); align-items: center; column-gap: 16px; padding-block: 2px; }
.axe-game:not(.axe-in-stage)[data-phase="summary"] .axe-result-card > :not(.axe-result-value, .axe-rank) { grid-column: 1 / -1; }
.axe-game:not(.axe-in-stage)[data-phase="summary"] .axe-rank { flex-wrap: wrap; justify-content: flex-start; align-items: baseline; column-gap: 8px; row-gap: 0; margin: 0; }
.axe-game:not(.axe-in-stage)[data-mode="versus"][data-phase="summary"] :is(.axe-match-records, .axe-challenges) { display: none; }


/* #2729 オーナー指摘（2026-11-08・iPhone 横持ち）:「的をもっと大きく」「投げるボタンは枠の中ではなく独立させて、ここで投げると絵で分かるように」「まだ文字が多い」。
   - 各投の帯（得点表）は看板の行の中（題と合計点のあいだ。JS で .axe-header に入れる）。本体が1段ぶん高くなり、的がその高さを使う。
   - 本体は [的 | 情報の枠] の2列で、的は2段ぶんの高さを使う。投げるボタン（.axe-throw）は情報の枠の下に、枠の外の大きな札として置く。
   - 縦長の画面（スマホ縦）は 的 → 情報 → 投げる の順に縦へ積む。
   - 情報の枠に残すのは、見守りの一言・チャレンジ・工程（↔ ↕ ↻）・今の刃先・回転ゲージ・結果の点と集計。
   - 操作の一言・腕の疲れ・回転の見出しと合図の文は、本編と同じく単体ページでも読み上げだけにする（中身は「？」のルールにある）。
   - ひとりで投げる時の看板の「1 / 3 投」は各投の帯（今の投が光る）と同じなので読み上げだけにする（対戦は手番・サドンデス・第何ゲームかを示すので残す）。 */
.axe-game .axe-header > .axe-scoreboard { order: 1; flex: 1 1 0; min-width: 0; align-self: center; margin: 0 6px; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.axe-game .axe-header > .axe-total { margin-left: 0; }
/* 合計は1か所に: ひとりで投げる時は看板の合計点（帯の右端の合計は読み上げだけ）。対戦は帯の2段の右端にあなた／相手の合計が並ぶので、看板の合計点を読み上げだけにする。 */
.axe-game:not([data-mode="versus"]) .axe-score-total, .axe-game[data-mode="versus"] .axe-header > .axe-total {
  position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.axe-game .axe-body { grid-template-rows: minmax(0,1fr) auto; }
.axe-game .axe-board-pane { grid-column: 1; grid-row: 1 / span 2; }
.axe-game .axe-panel { grid-column: 2; grid-row: 1; }
.axe-game .axe-throw { grid-column: 2; grid-row: 2; display: flex; gap: 10px; min-width: 0; }
.axe-game .axe-throw > .axe-button { flex: 1 1 0; min-width: 0; }
.axe-game .axe-throw-button { display: flex; align-items: center; justify-content: center; gap: .55em; min-height: 64px; padding: 8px 18px; border-width: 2px; border-radius: 14px;
  font-size: 20px; font-weight: 900; letter-spacing: .14em; white-space: nowrap; }
.axe-game .axe-throw-icon { display: inline-grid; flex: none; place-items: center; width: 1.7em; height: 1.7em; border-radius: 50%; background: var(--lane-orange-ink); color: var(--lane-orange-hi);
  box-shadow: inset 0 0 0 2px #ffffff26; }
.axe-game .axe-throw-icon .axe-mark { width: 1.1em; height: 1.1em; }
.axe-game .axe-action-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* 斧のマークは投げる工程（構える〜放す）の間だけ。結果・集計の「次の投へ」「終了」は文字だけ。 */
.axe-game:not(:is([data-phase="choice"],[data-phase="horizontal"],[data-phase="vertical"],[data-phase="power"])) .axe-throw-icon { display: none; }
.axe-game[data-phase="power"]:has(.axe-timing[data-quality="sweet"]) .axe-throw-icon { background: #142711; color: #b8e5aa; }
.axe-game .axe-throw .axe-retry { min-height: 64px; border-radius: 14px; font-weight: 900; }
.axe-game :is(.axe-keyhint, .axe-power-label, .axe-feedback, .axe-steadiness), .axe-game:not([data-mode="versus"]) .axe-header .axe-round {
  position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
@container (max-height: 500px) {
  .axe-game .axe-throw-button, .axe-game .axe-throw .axe-retry { min-height: 52px; font-size: 17px; }
}
@container (max-width: 650px) and (min-height: 501px) {
  .axe-game .axe-header > .axe-scoreboard { grid-column: 1 / -1; grid-row: 3; margin: 4px 0 0; }
  .axe-game .axe-body { grid-template-rows: minmax(0,1fr) auto auto; }
  .axe-game .axe-board-pane { grid-column: 1; grid-row: 1; }
  .axe-game .axe-panel { grid-column: 1; grid-row: 2; }
  .axe-game .axe-throw { grid-column: 1; grid-row: 3; }
  .axe-game .axe-throw-button, .axe-game .axe-throw .axe-retry { min-height: 56px; font-size: 18px; }
}
/* 本編の #stage: 投げる札はステージ上 100px（iPhone 横の 0.54倍で実寸 54px）、文字 32px。
   情報の枠はその上の高さに収める（枠の余白を詰め、1投の結果は点数の横に見出しを並べて1段ぶん詰める）。 */
.axe-in-stage .axe-body, .axe-in-stage.axe-game .axe-body { row-gap: 12px; }
.axe-in-stage .axe-throw { gap: 12px; }
.axe-in-stage .axe-throw-button, .axe-in-stage .axe-throw .axe-retry { min-height: 100px; border-radius: 20px; font-size: 32px; }
.axe-in-stage .axe-throw .axe-retry { font-size: var(--axe-text); }
.axe-in-stage .axe-panel, .axe-in-stage.axe-game .axe-panel { padding: 8px 14px; gap: 6px; }
/* 対戦: 得点表が2段（あなた／ひより）になるぶん、枠の中の重複を外す。合計は得点表の右端、チャレンジは対戦の結果にも出していない。 */
.axe-in-stage.axe-game[data-mode="versus"]:not([data-phase="summary"]) .axe-match-score, .axe-in-stage.axe-game[data-mode="versus"] .axe-challenges {
  position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
/* 16:9 のステージ（ワイドでない 1280 幅）の対戦は、10投×2段の得点表を看板の2段目に折り返す（1段目に並べると各投の枠が細くなりすぎる）。 */
#stage:not([data-wide]) .axe-in-stage.axe-game[data-mode="versus"] .axe-header { flex-wrap: wrap; row-gap: 4px; }
#stage:not([data-wide]) .axe-in-stage.axe-game[data-mode="versus"] .axe-header > .axe-scoreboard { order: 5; flex: 1 0 100%; margin: 0 0 4px; }
#stage:not([data-wide]) .axe-in-stage.axe-game[data-mode="versus"] .axe-header .axe-round { margin-left: auto; }
/* チャレンジの札は投げる前（choice）と結果のまとめだけ。投げた直後の結果は点数と一言に絞る（スマホの単体ページと同じ）。 */
.axe-in-stage.axe-game:not([data-phase="choice"]):not([data-phase="summary"]) .axe-challenges { display: none; }
/* 見守りの一言は名前を文の頭に続けて書き、名前だけの1行を詰める（顔の丸で誰かは分かる）。 */
.axe-in-stage .axe-companion strong { display: inline; margin-right: .5em; }
.axe-in-stage .axe-panel .axe-comment { display: inline; margin: 0; }
.axe-in-stage.axe-game[data-phase="result"] .axe-result-card { display: grid; grid-template-columns: auto minmax(0,1fr); align-items: center; column-gap: 16px; padding-block: 4px; }
.axe-in-stage.axe-game[data-phase="result"] .axe-result-value { grid-column: 1; grid-row: 1; margin: 0; font-size: 56px; line-height: 1.15; }
.axe-in-stage.axe-game[data-phase="result"] .axe-result-label { grid-column: 2; grid-row: 1; }
.axe-in-stage.axe-game[data-phase="result"] .axe-result-tip { grid-column: 1 / -1; }

/* 投げる前（狙いを選ぶ場面）は右パネルの中身が少なく、下寄せにすると上に約140pxの空きが残っていた（2026-11-08 撮影で確認）。
   狙いの札（通常・左上の青…）の段をその高さまで伸ばし、札を大きく押しやすくする。中身が多い場面では伸びる余地がないので変わらない。 */
.axe-game .axe-panel > .axe-calls { flex: 1 1 auto; max-height: 300px; }


/* ===== 的に集中する配置（2026-11-10 オーナー指摘） =====
   「処理が重い」「UI配置が悪く斧や的に集中しづらい」「狙う位置を決める所が常に右にあって没入感がない」への作り直し。
   - 的は画面の中央で、本体の高さいっぱいの正方形。左右の枠（黒板の箱）はやめ、レーンの背景が見える。
   - 狙いの札（通常・四つの青）は的の四隅と下に重ねる。出るのは投げる前だけで、構えたら消える（的の青を直接タップしても宣言できる）。
   - 回転ゲージは的のすぐ右に縦で立つ。針が上がるほど刃先も上へずれるので、的から目を離さずに読める。
   - 左は見守りの一言とチャレンジ（構えてから刺さるまでは消える）。右は今の刃先・結果・操作のボタンだけ。
   - 結果のまとめ（summary）は的の上に重ねた1枚の札。
   - 描画: 動かない的（.axe-target-art）と動く照準・斧（.axe-target）を別の層にし、ぼかし・影の filter を使わない。ゲージの針は transform で動かす。
   寸法の下限（文字はステージ上 24px・押す部品 82px）は従来どおり。 */
.axe-game.axe-in-stage { padding: 18px 14px 14px; background: radial-gradient(ellipse 62% 78% at 50% 56%, #0a121159, #0a1110eb 78%), var(--axe-bg) center / cover; }
.axe-game.axe-in-stage::before { display: none; }
.axe-game.axe-in-stage .axe-body { position: relative; display: flex; align-items: stretch; justify-content: center; gap: 14px; }
.axe-game.axe-in-stage .axe-side { display: flex; flex: 1 1 0; flex-direction: column; justify-content: flex-end; gap: 10px; min-width: 0; min-height: 0; }
.axe-game.axe-in-stage .axe-board-pane { flex: none; height: 100%; aspect-ratio: 1; border: 0; border-radius: 12px; background: #1d130b;
  box-shadow: 0 0 0 3px var(--lane-wood-dark), 0 20px 46px #000000c7; }
.axe-game.axe-in-stage :is(.axe-target-art, .axe-target) { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
.axe-game.axe-in-stage .axe-target-art { pointer-events: none; will-change: transform; }
.axe-game.axe-in-stage .axe-target { will-change: transform; }
.axe-game.axe-in-stage .axe-board-pane::after { content: ""; position: absolute; inset: 0; z-index: 3; background: #050908c7; opacity: 0; pointer-events: none; transition: opacity .25s; }
.axe-game.axe-in-stage[data-phase="summary"] .axe-board-pane::after { opacity: 1; }

/* 狙いの札: 的の上。投げる前だけ（JS が choice 以外で hidden にする）。 */
.axe-game.axe-in-stage .axe-board-pane > .axe-calls { position: absolute; inset: 0; z-index: 2; display: block; max-height: none; pointer-events: none; }
.axe-game.axe-in-stage .axe-board-pane > .axe-calls[hidden] { display: none; }
.axe-game.axe-in-stage .axe-calls .axe-button { position: absolute; width: 148px; min-height: var(--axe-tap); padding: 4px 6px; pointer-events: auto; }
.axe-game.axe-in-stage .axe-calls .axe-button:not([data-call="normal"]):not([aria-pressed="true"]) { color: #dff2ff; }
.axe-game.axe-in-stage .axe-calls .axe-button:disabled { opacity: .5; }
.axe-game.axe-in-stage .axe-calls [data-call="upper-left"] { left: 10px; top: 10px; }
.axe-game.axe-in-stage .axe-calls [data-call="upper-right"] { right: 10px; top: 10px; }
.axe-game.axe-in-stage .axe-calls [data-call="lower-left"] { left: 10px; bottom: 10px; }
.axe-game.axe-in-stage .axe-calls [data-call="lower-right"] { right: 10px; bottom: 10px; }
.axe-game.axe-in-stage .axe-calls [data-call="normal"] { left: 50%; bottom: 10px; width: 132px; margin-left: -66px; }
/* 「宣言中：…」の一言は画面に出さない（2026-11-11 オーナー指示）。選んだ札そのものを目立たせ、宣言した青は輪で囲む。文は読み上げ用に残す。
   サドンデスは札が出ないので、狙う青の一言を的の上に1行で出す。 */
.axe-game.axe-in-stage .axe-board-pane > .axe-call-status[data-kind="called"] { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.axe-game.axe-in-stage .axe-board-pane > .axe-call-status[data-kind="sudden-death"] { position: absolute; left: 50%; top: 44px; z-index: 2; transform: translateX(-50%); margin: 0; padding: 4px 16px;
  border: 1px solid #7fc4ee; border-radius: 999px; background: #0b1211eb; color: #dff2ff; white-space: nowrap; pointer-events: none; }
.axe-game.axe-in-stage:is([data-phase="horizontal"],[data-phase="vertical"],[data-phase="power"],[data-phase="result"],[data-phase="summary"]) .axe-board-pane > .axe-call-status { display: none; }
/* 選んだ札: ひと回り大きく、チェックの印と明るい二重の縁。選んでいない札は少し沈める。 */
.axe-game.axe-in-stage .axe-calls .axe-button { transition: transform .12s ease-out, opacity .12s; }
.axe-game.axe-in-stage .axe-calls .axe-button[aria-pressed="false"]:not(:disabled) { opacity: .82; }
.axe-game.axe-in-stage .axe-calls .axe-button[aria-pressed="true"] { z-index: 1; transform: scale(1.1); font-weight: 900; outline: 2px solid #fff8dc; outline-offset: 2px; }
.axe-game.axe-in-stage .axe-calls .axe-button { border-radius: 9px; }
.axe-game.axe-in-stage .axe-calls .axe-button[aria-pressed="true"]::before { content: "✓"; display: inline-grid; place-items: center; width: 1.25em; height: 1.25em; margin-right: .3em; border-radius: 50%; background: #fff8dc; color: #1a120c; font-size: .8em; font-weight: 900; line-height: 1; vertical-align: .08em; }
.axe-game.axe-in-stage .axe-calls [data-call="upper-left"] { transform-origin: left top; } .axe-game.axe-in-stage .axe-calls [data-call="upper-right"] { transform-origin: right top; }
.axe-game.axe-in-stage .axe-calls [data-call="lower-left"] { transform-origin: left bottom; } .axe-game.axe-in-stage .axe-calls [data-call="lower-right"] { transform-origin: right bottom; }
.axe-game.axe-in-stage .axe-calls [data-call="normal"] { transform-origin: center bottom; }

/* 回転ゲージ: 的の右に縦。場所は常に取っておき（的が左右に動かない）、出ていない間は見えないだけ。 */
.axe-game.axe-in-stage .axe-body > .axe-timing { position: relative; display: block !important; flex: none; width: 60px; margin: 0; padding: 0; transition: opacity .15s; }
.axe-game.axe-in-stage .axe-body > .axe-timing[hidden], .axe-game.axe-in-stage[data-phase="summary"] .axe-body > .axe-timing { visibility: hidden; }
.axe-game.axe-in-stage .axe-timing[data-active="false"] { opacity: .45; }
.axe-game.axe-in-stage .axe-timing .axe-power-readout { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.axe-game.axe-in-stage .axe-gauge { position: absolute; inset: 21.2px 13.2px 20.9px 12.9px; height: auto; border: 0; border-radius: 2px; }
.axe-game.axe-in-stage :is(.axe-stick, .axe-sweet) { left: 0; right: 0; top: auto; bottom: var(--from); width: auto; height: var(--size); border-inline: 0; }
.axe-game.axe-in-stage .axe-stick { border-block: 1px solid #dcba7c; }
.axe-game.axe-in-stage .axe-sweet { border-block: 2px solid #ddf0c2; }
.axe-game.axe-in-stage .axe-sweet::after { writing-mode: vertical-rl; letter-spacing: .1em; }
.axe-game.axe-in-stage .axe-power-fill { left: 0; top: 0; bottom: 0; width: 5px; height: auto; transform: scaleY(0); transform-origin: center bottom; }
.axe-game.axe-in-stage .axe-needle { inset: 0; width: auto; border-radius: 0; background: none; box-shadow: none; transform: translateY(100%); pointer-events: none; will-change: transform; }
.axe-game.axe-in-stage .axe-needle::before { left: -20px; right: auto; top: -7px; box-sizing: border-box; width: 67px; height: 14px; border-style: solid; border-color: transparent; border-width: 0; border-radius: 0;
  background: none; box-shadow: none; border-image: url("../img/ui/axe_throw/gauge-needle.webp") 0 42 0 100 fill / 0 6px 0 14.6px / 4.7px; }
.axe-game.axe-in-stage .axe-needle::after { content: none; }

/* 右: 枠のない操作の列。下から 投げる札 → 構え直す・息を整える → 今の刃先／結果。 */
.axe-game.axe-in-stage .axe-panel { flex: 1 1 0; display: flex; flex-direction: column; justify-content: flex-end; gap: 10px; padding: 0; overflow: visible; border: 0; border-radius: 0; background: none; box-shadow: none; }
.axe-game.axe-in-stage .axe-panel > .axe-throw { display: flex; gap: 10px; min-width: 0; }
.axe-game.axe-in-stage .axe-throw-button { gap: .4em; padding: 8px 10px; font-size: 30px; letter-spacing: .05em; white-space: normal; line-height: 1.2; }
.axe-game.axe-in-stage .axe-action-label { overflow: visible; }
.axe-game.axe-in-stage .axe-controls { grid-template-columns: 1fr; gap: 8px; }

.axe-game.axe-in-stage .axe-live-score { padding: 4px 12px; border: 1px solid var(--lane-line); border-radius: 10px; background: #0b1211d9; }
.axe-game.axe-in-stage .axe-note { margin: 0; padding: 6px 12px; border-radius: 10px; background: #0b1211c7; line-height: 1.4; }
.axe-game.axe-in-stage .axe-note.axe-quiet { padding: 0; }
.axe-game.axe-in-stage .axe-result-card { border-radius: 0 10px 10px 0; background: #0b1211e0; }
.axe-game.axe-in-stage .axe-steps { position: absolute !important; width: 1px !important; height: 1px !important; margin: -1px !important; padding: 0 !important;
  overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }

/* 左: 見守りの一言（顔の丸＋吹き出し）とチャレンジ。 */
