.camel-game.cr-medal-silver .camel-medal[data-rank="2"] span,
.camel-game.cr-medal-bronze .camel-medal[data-rank="3"] span,
.camel-game.cr-medal-plain .camel-medal[data-rank="4"] span { left: 55%; font-size: clamp(11px, 1.1cqw, 14px); }
