  background: radial-gradient(circle at 50% 50%, #d8b35b 0 5px, transparent 6px), linear-gradient(#5a3a7a, #3e2858); box-shadow: inset 0 3px 0 rgba(255, 255, 255, .16), 0 6px 8px rgba(0, 0, 0, .3); }
.tt-prop[data-prop="cushion"] .tt-prop-back::before, .tt-prop[data-prop="cushion"] .tt-prop-back::after { content: ""; position: absolute; top: 12px; width: 10px; height: 14px; border-radius: 50%; background: #d8b35b; }
.tt-prop[data-prop="cushion"] .tt-prop-back::before { left: -6px; } .tt-prop[data-prop="cushion"] .tt-prop-back::after { right: -6px; }
.tt-prop[data-prop="cushion"] .tt-prop-front { display: none; }
/* 爪とぎ */
.tt-prop[data-prop="scratcher"] .tt-prop-back { left: -92px; bottom: 0; width: 184px; height: 28px; border-radius: 4px;
  background: repeating-linear-gradient(90deg, #c08f55 0 6px, #a87a44 6px 9px); box-shadow: 0 5px 6px rgba(0, 0, 0, .3); }
.tt-prop[data-prop="scratcher"] .tt-prop-front { display: none; }
/* 小さなトンネル（中に入るとしっぽだけ出る） */
.tt-prop[data-prop="tunnel"] .tt-prop-back { left: -116px; bottom: 0; width: 70px; height: 108px; border-radius: 50%; background: radial-gradient(ellipse at 55% 50%, #10161a 0 58%, #2f6f73 60%); }
.tt-prop[data-prop="tunnel"] .tt-prop-front { left: -96px; bottom: 0; width: 210px; height: 108px; border-radius: 54px 54px 6px 6px;
  background: repeating-linear-gradient(90deg, #3d8a8e 0 30px, #317276 30px 34px); box-shadow: inset 0 10px 14px rgba(255, 255, 255, .12), 0 8px 10px rgba(0, 0, 0, .3); }
.tt-prop > .tt-prop-tail { display: none; right: -150px; bottom: 6px; width: 70px; height: 22px; z-index: 7; border-radius: 0 14px 14px 0;
  background: repeating-linear-gradient(90deg, #e9a24d 0 12px, #c97a2c 12px 20px); transform-origin: 0 50%; }
.tt-slot.holding .tt-prop > .tt-prop-tail { display: block; animation: tt-tail 1.6s ease-in-out infinite; }
@keyframes tt-tail { 50% { transform: rotate(-16deg); } }
/* 猫ベッド */
.tt-prop[data-prop="bed"] .tt-prop-back { left: -124px; bottom: 18px; width: 248px; height: 84px; border-radius: 50%; background: radial-gradient(ellipse at 50% 42%, #7d5f4a 0 46%, #a8876c 52%, #c9ad8f 70%); }
.tt-prop[data-prop="bed"] .tt-prop-front { left: -130px; bottom: 0; width: 260px; height: 58px; border-radius: 30px 30px 130px 130px / 26px 26px 50px 50px;
  background: radial-gradient(ellipse at 50% 0, rgba(255, 255, 255, .25), transparent 60%), linear-gradient(#c9ad8f, #a8876c); box-shadow: 0 8px 10px rgba(0, 0, 0, .3); }

/* 小物の絵（ART_READY.props に書いた物だけ・#2697 の原画を remake/tools/build_tetsuko_art.py で切り出したもの）:
   奥の層＝小物の全体、手前の層＝口より手前の壁・縁（*_front。箱とベッドだけ）。猫が中にいる時だけ手前の層が猫の上に来る。
   大きさ（--aw・--ah）は書き出した絵の半分（@2x）。CSS で描いた代わりの飾り（房・ふた）は消す */
.tt-prop[data-prop="box"] { --aw: 330px; --ah: 203px; } .tt-prop[data-prop="ball"] { --aw: 58px; --ah: 60px; } .tt-prop[data-prop="cushion"] { --aw: 250px; --ah: 135px; }
.tt-prop[data-prop="scratcher"] { --aw: 230px; --ah: 66px; } .tt-prop[data-prop="tunnel"] { --aw: 300px; --ah: 202px; } .tt-prop[data-prop="bed"] { --aw: 290px; --ah: 202px; }
.tetsuko-time[data-art-props~="box"] .tt-prop[data-prop="box"] > :is(.tt-prop-back, .tt-prop-front) { left: calc(var(--aw) / -2); bottom: 0; width: var(--aw); height: var(--ah); border: 0; border-radius: 0; box-shadow: none; clip-path: none; background: none; }
.tetsuko-time[data-art-props~="box"] .tt-prop[data-prop="box"] > :is(.tt-prop-back, .tt-prop-front)::before, .tetsuko-time[data-art-props~="box"] .tt-prop[data-prop="box"] > :is(.tt-prop-back, .tt-prop-front)::after { display: none; }
.tetsuko-time[data-art-props~="box"] .tt-prop[data-prop="box"] > .tt-prop-back { display: block; background: url("../img/ui/tetsuko/prop_box.webp") center bottom / contain no-repeat; }
.tetsuko-time[data-art-props~="box"] .tt-prop[data-prop="box"] > .tt-prop-front { display: block; background: url("../img/ui/tetsuko/prop_box_front.webp") center bottom / contain no-repeat; }
.tetsuko-time[data-art-props~="ball"] .tt-prop[data-prop="ball"] > :is(.tt-prop-back, .tt-prop-front) { left: calc(var(--aw) / -2); bottom: 0; width: var(--aw); height: var(--ah); border: 0; border-radius: 0; box-shadow: none; clip-path: none; background: none; }
.tetsuko-time[data-art-props~="ball"] .tt-prop[data-prop="ball"] > :is(.tt-prop-back, .tt-prop-front)::before, .tetsuko-time[data-art-props~="ball"] .tt-prop[data-prop="ball"] > :is(.tt-prop-back, .tt-prop-front)::after { display: none; }
.tetsuko-time[data-art-props~="ball"] .tt-prop[data-prop="ball"] > .tt-prop-back { display: block; background: url("../img/ui/tetsuko/prop_ball.webp") center bottom / contain no-repeat; }
.tetsuko-time[data-art-props~="ball"] .tt-prop[data-prop="ball"] > .tt-prop-front { display: none; }
.tetsuko-time[data-art-props~="cushion"] .tt-prop[data-prop="cushion"] > :is(.tt-prop-back, .tt-prop-front) { left: calc(var(--aw) / -2); bottom: 0; width: var(--aw); height: var(--ah); border: 0; border-radius: 0; box-shadow: none; clip-path: none; background: none; }
.tetsuko-time[data-art-props~="cushion"] .tt-prop[data-prop="cushion"] > :is(.tt-prop-back, .tt-prop-front)::before, .tetsuko-time[data-art-props~="cushion"] .tt-prop[data-prop="cushion"] > :is(.tt-prop-back, .tt-prop-front)::after { display: none; }
.tetsuko-time[data-art-props~="cushion"] .tt-prop[data-prop="cushion"] > .tt-prop-back { display: block; background: url("../img/ui/tetsuko/prop_cushion.webp") center bottom / contain no-repeat; }
.tetsuko-time[data-art-props~="cushion"] .tt-prop[data-prop="cushion"] > .tt-prop-front { display: none; }
.tetsuko-time[data-art-props~="scratcher"] .tt-prop[data-prop="scratcher"] > :is(.tt-prop-back, .tt-prop-front) { left: calc(var(--aw) / -2); bottom: 0; width: var(--aw); height: var(--ah); border: 0; border-radius: 0; box-shadow: none; clip-path: none; background: none; }
.tetsuko-time[data-art-props~="scratcher"] .tt-prop[data-prop="scratcher"] > :is(.tt-prop-back, .tt-prop-front)::before, .tetsuko-time[data-art-props~="scratcher"] .tt-prop[data-prop="scratcher"] > :is(.tt-prop-back, .tt-prop-front)::after { display: none; }
.tetsuko-time[data-art-props~="scratcher"] .tt-prop[data-prop="scratcher"] > .tt-prop-back { display: block; background: url("../img/ui/tetsuko/prop_scratcher.webp") center bottom / contain no-repeat; }
.tetsuko-time[data-art-props~="scratcher"] .tt-prop[data-prop="scratcher"] > .tt-prop-front { display: none; }
.tetsuko-time[data-art-props~="tunnel"] .tt-prop[data-prop="tunnel"] > :is(.tt-prop-back, .tt-prop-front) { left: calc(var(--aw) / -2); bottom: 0; width: var(--aw); height: var(--ah); border: 0; border-radius: 0; box-shadow: none; clip-path: none; background: none; }
.tetsuko-time[data-art-props~="tunnel"] .tt-prop[data-prop="tunnel"] > :is(.tt-prop-back, .tt-prop-front)::before, .tetsuko-time[data-art-props~="tunnel"] .tt-prop[data-prop="tunnel"] > :is(.tt-prop-back, .tt-prop-front)::after { display: none; }
.tetsuko-time[data-art-props~="tunnel"] .tt-prop[data-prop="tunnel"] > .tt-prop-back { display: block; background: url("../img/ui/tetsuko/prop_tunnel.webp") center bottom / contain no-repeat; }
.tetsuko-time[data-art-props~="tunnel"] .tt-prop[data-prop="tunnel"] > .tt-prop-front { display: none; }
.tetsuko-time[data-art-props~="bed"] .tt-prop[data-prop="bed"] > :is(.tt-prop-back, .tt-prop-front) { left: calc(var(--aw) / -2); bottom: 0; width: var(--aw); height: var(--ah); border: 0; border-radius: 0; box-shadow: none; clip-path: none; background: none; }
.tetsuko-time[data-art-props~="bed"] .tt-prop[data-prop="bed"] > :is(.tt-prop-back, .tt-prop-front)::before, .tetsuko-time[data-art-props~="bed"] .tt-prop[data-prop="bed"] > :is(.tt-prop-back, .tt-prop-front)::after { display: none; }
.tetsuko-time[data-art-props~="bed"] .tt-prop[data-prop="bed"] > .tt-prop-back { display: block; background: url("../img/ui/tetsuko/prop_bed.webp") center bottom / contain no-repeat; }
