.tetsuko-time[data-art-props~="box"] .tt-item-pic .tt-prop[data-prop="box"] { zoom: 0.27; }
.tetsuko-time[data-art-props~="ball"] .tt-item-pic .tt-prop[data-prop="ball"] { zoom: 0.8; }
