.trpg-root.trpg-cinematic .trpg-heading { gap: 16px; }
.trpg-root.trpg-cinematic .trpg-heading > small { font-size: 12px; font-weight: 700; max-width: 80px; line-height: 1.5; letter-spacing: .02em; color: #e5d4b1; }
.trpg-root.trpg-cinematic .trpg-heading > strong { font-size: 18px; font-weight: 500; letter-spacing: .04em; }
