html:root[data-density="phone"] .trpg-root.trpg-cinematic .trpg-hypothesis-stage .trpg-evidence-fold > summary { font-size: var(--phone-sub); min-height: var(--phone-tap); }

/* ---- キャラクターシート: 3枚を横に詰めず、1人ずつ大きく見せて横に送る ---- */
html:root[data-density="phone"] .trpg-root.trpg-cinematic .trpg-modal.trpg-sheet-stage { width: 1200px; max-height: 690px; padding: 6px 10px; }
html:root[data-density="phone"] .trpg-root.trpg-cinematic .trpg-sheet-grid {
