/* The shelf is the entry point; each illustrated card is an actual playable story. */
.trpg-library-header { position: absolute; top: 27px; left: 42px; right: 42px; display: flex; justify-content: space-between; align-items: flex-start; }
.trpg-library-header .trpg-kicker { font-size: 13px; letter-spacing: .02em; }
.trpg-library-header h1 { font-size: 37px; font-weight: 700; margin: 8px 0 0; line-height: 1.3; }
.trpg-library-meta { display: flex; align-items: center; gap: 20px; color: #acc5be; font-size: 13px; letter-spacing: .02em; padding-top: 5px; }
.trpg-library-intro { position: absolute; left: 43px; top: 109px; color: #b8cdc5; font-size: 18px; margin: 0; }
.trpg-library-books { position: absolute; left: 42px; right: 42px; top: 159px; bottom: 57px; display: grid; grid-template-columns: 1fr 1fr; gap: 25px; }
.trpg-library-book { display: flex; flex-direction: column; min-height: 0; overflow: hidden; border: 1px solid #94b3a567; border-radius: 10px; background: linear-gradient(130deg,#2b4444,#1b3236); box-shadow: 0 14px 28px #0003; }
.trpg-library-book[data-theme="shark"] { --accent: #efb393; background: linear-gradient(130deg,#304353,#192e36); border-color: #98b6cb67; }
.trpg-library-art { height: 201px; flex-shrink: 0; position: relative; overflow: hidden; background: #293d45; }
.trpg-library-art > img { width: 100%; height: 100%; object-fit: cover; object-position: center 42%; display: block; transition: transform .5s; }
.trpg-library-book:hover .trpg-library-art > img { transform: scale(1.035); }
.trpg-library-art::after { content: ''; position: absolute; inset: 0; background: linear-gradient(transparent 60%,#12282b8f); pointer-events: none; }
.trpg-library-number { position: absolute; left: 17px; top: 13px; color: #fff4dd; font-size: 34px; font-weight: 900; text-shadow: 0 1px 8px #000; }
.trpg-library-genre { position: absolute; right: 16px; top: 18px; font-size: 14px; padding: 5px 12px; background: #142c34d9; color: #fbe6bb; border: 1px solid #ddd2b94d; border-radius: 20px; }
.trpg-library-copy { padding: 16px 23px 18px; display: flex; flex-direction: column; flex: 1; min-height: 0; }
.trpg-library-byline { color: #b7cabc; font-size: 12px; letter-spacing: .02em; }
.trpg-library-copy h2 { margin: 5px 0; font-size: 30px; line-height: 1.35; color: #fff2d6; font-weight: 700; }
.trpg-library-copy > p { margin: 3px 0 0; font-size: 17px; color: #cbd7cb; }
.trpg-library-details { display: flex; gap: 18px; font-size: 14px; color: #bed0c8; margin: 12px 0 10px; }
.trpg-library-details > span + span { border-left: 1px solid #8cafa261; padding-left: 18px; }
.trpg-library-cast { display: flex; justify-content: flex-start; gap: 19px; margin-bottom: 14px; }
.trpg-library-cast > div { display: flex; align-items: center; gap: 5px; font-size: 14px; color: #d6e0d3; }
.trpg-library-face { display: block; width: 37px; height: 42px; overflow: hidden; position: relative; border-radius: 5px; background: var(--person-color); }
.trpg-library-face img { position: absolute; width: 140px; height: auto; left: 50%; transform: translateX(-50%); }
.trpg-library-copy > button { margin-top: auto; min-height: 48px; width: 100%; display: flex; align-items: center; justify-content: space-between; font-size: 19px; }
.trpg-library-footer { position: absolute; left: 43px; right: 43px; bottom: 23px; display: flex; justify-content: space-between; gap: 20px; color: #9fbbb1; font-size: 12px; }
@keyframes trpg-rain { to { background-position: 40px 80px; } }
@keyframes trpg-breathe { to { opacity: .5; } }
@media (prefers-reduced-motion: reduce) {
  .trpg-root *, .trpg-root *::before, .trpg-root *::after { animation: none !important; transition: none !important; }
  /* 盛り上がりの知らせは、動かさずに消えるだけの trpg-heat-fade（trpg-stage.css）を残す（#3199）。上の一括停止で消えなくなり、
     animationend が来ないので知らせが卓の上に残り続け、判定の卓や結末に重なって、使い終えた勢いを「次の判定 ＋4」と出し続けていた。 */
  .trpg-root .trpg-heat-pop { animation: trpg-heat-fade 1.5s ease-out both !important; }
  .trpg-root .trpg-heat-pop:not([data-tier="0"]) { animation-duration: 2.2s !important; }
}

/* The campaign shelf is a quiet shop, with tonight's party and lasting book memories. */
.trpg-campaign { display: flex; flex-direction: column; gap: 14px; padding: 26px 40px 18px; background: radial-gradient(ellipse at 8% 0%, #23494388, transparent 60%), #121d20; color: #efe7d6; }
