.trpg-teamwork span { font-size: 13px; margin-right: 5px; white-space: nowrap; }
.trpg-teamwork i { display: block; width: 12px; height: 18px; border: 1px solid #e7ce9f; border-radius: 2px; transform: rotate(9deg); background: linear-gradient(135deg, #f4dfb0, #a88a52); box-shadow: 0 2px 5px #0003; }
.trpg-teamwork i.spent { opacity: .23; background: transparent; }
.trpg-journey { position: absolute; top: 87px; left: 28px; right: 470px; height: 22px; }
