.trpg-journey li.done i { color: #bcd4c4; background: #48675975; }
.trpg-table { left: auto; max-width: 450px; gap: 6px; }
.trpg-table-person { font-size: 12px; font-weight: 700; padding: 3px 6px; }
.trpg-side { gap: 8px; }
.trpg-side > p { font-size: 16px; }
.trpg-side > .trpg-button { min-height: 49px; font-size: 18px; }
[data-phase="explore"] .trpg-side > p { display: none; }
.trpg-investigation { padding: 11px 13px 9px; border: 1px solid #8ea89b5c; background: linear-gradient(120deg, #324e48a6, #1d373a); border-radius: 7px; }
