.trpg-risk { flex-shrink: 0; font-size: 13px; }
.trpg-hypothesis-note { font-size: 13px; padding: 6px 10px; }
.trpg-plan-summary { display: flex; flex-direction: column; gap: 7px; padding: 10px 13px; border: 1px solid #7e9e8b50; border-radius: 7px; background: #304c432f; flex-shrink: 0; }
.trpg-plan-summary > strong { color: var(--accent); font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.trpg-plan-summary > div { display: grid; grid-template-columns: 96px 1fr; align-items: baseline; gap: 7px; }
.trpg-plan-summary small { font-size: 12px; color: #9fb6aa; line-height: 1.5; }
