.trpg-aid { padding: 11px 14px; margin: 11px 0; border: 1px solid #869c7f66; border-radius: 6px; background: #abc2a559; }
.trpg-aid strong { display: block; font-size: 17px; font-weight: 500; }
.trpg-aid small { display: block; font-size: 13px; color: #5c755c; margin-top: 2px; }
.trpg-forecast { padding: 12px 15px 10px; border: 1px solid #8da18a80; border-radius: 7px; background: #f9f5e651; }
.trpg-forecast-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.trpg-forecast-head strong { font-size: 14px; color: #3a5a48; }
.trpg-forecast-head small { font-size: 12px; color: #5b755c; }
.trpg-odds { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; text-align: center; }
.trpg-odds > div { display: flex; flex-direction: column; border-right: 1px solid #92a28766; }
.trpg-odds > div:last-child { border: 0; }
.trpg-odds strong { font-size: 23px; line-height: 1.3; color: #315c45; }
.trpg-odds [data-grade="mixed"] strong { color: #796338; }
.trpg-odds [data-grade="trouble"] strong { color: #936345; }
.trpg-odds span { font-size: 14px; color: #415b49; }
.trpg-odds small { font-size: 12px; color: #6b7d64; }
.trpg-forecast > p { font-size: 12px; text-align: center; color: #63775d; margin: 9px 0 0; line-height: 1.5; }
.trpg-dice-total { margin: 9px 0 12px; }
.trpg-dice-grade { display: table; margin: 6px auto 0; font-size: 17px; padding: 2px 20px; border: 1px solid #6e8d7460; border-radius: 20px; background: #8cae8533; }
.trpg-dice-total[data-grade="mixed"] .trpg-dice-grade { color: #7b6237; background: #cdb17633; border-color: #aa8b4b66; }
.trpg-dice-total[data-grade="trouble"] .trpg-dice-grade { color: #926149; background: #c98f6d22; border-color: #ab7e5c66; }
.trpg-rerolls { gap: 13px; }
.trpg-reroll-choice { flex: 1; padding: 10px 12px; }
.trpg-reroll-choice strong { display: block; font-weight: 500; font-size: 16px; }
.trpg-reroll-choice small { display: block; font-size: 12px; color: #5b735a; margin-top: 3px; }
.trpg-reroll-warning { text-align: center; font-size: 12px; color: #7a6b52; margin: 6px 0 0 !important; }
.trpg-recap-heading { padding-bottom: 10px; margin-bottom: 12px; border-bottom: 1px solid #90a08588; line-height: 1.4; }
.trpg-recap-heading small { font-size: 13px; color: #657959; }
.trpg-recap-heading h3 { margin: 4px 0 6px; font-size: 26px; color: #2c4b3e; line-height: 1.4; }
.trpg-recap-heading p { font-size: 14px; color: #5d7456; margin: 0; }
.trpg-recap-grid { display: grid; grid-template-columns: .9fr 1.1fr; gap: 23px; }
.trpg-recap-grid h3, .trpg-recap-grid + p + h3 { font-size: 17px; color: #486344; margin: 0 0 10px; }
.trpg-recap-hypothesis { font-size: 15px; color: #536b50; }
.trpg-recap-grid .trpg-plan-summary { background: #7d9d7820; border-color: #7b96766b; }
.trpg-recap-grid .trpg-plan-summary > strong { color: #486344; }
.trpg-recap-grid .trpg-plan-summary small { color: #627b59; font-size: 12px; }
.trpg-recap-grid .trpg-plan-summary span { color: #2f4e3e; font-size: 18px; }
.trpg-recap-check { padding: 7px 12px; background: #fffaf04d; border-left: 3px solid #839a74; margin-bottom: 8px; line-height: 1.45; }
.trpg-recap-check strong, .trpg-recap-check span, .trpg-recap-check small { display: block; }
.trpg-recap-check strong { font-size: 16px; color: #34543f; }
.trpg-recap-check span { font-size: 14px; color: #435f47; margin-top: 3px; }
.trpg-recap-check small { font-size: 12px; color: #788362; }
.trpg-recap-rule { font-size: 14px; color: #64795a; padding: 8px 0; }
.trpg-room.interactive .trpg-spot:not(.checked):focus-visible { box-shadow: 0 0 0 6px #f4ddaa44, 0 6px 20px #0006; }

/* #2862 本棚: 文字にしなくてよい所は記号（音・所要時間・結末の数）。PCの寸法は変えない。 */
.trpg-icon { width: 1.1em; height: 1.1em; flex: none; vertical-align: -.18em; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.trpg-library-details > span { display: inline-flex; align-items: center; gap: .3em; }
/* 表紙を読めなかった時、代わりの説明（alt）を表紙の上に文字で重ねない。読み上げには残る。 */
.trpg-library-art > img { color: transparent; }
.trpg-library-meta .trpg-icon-button { display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; padding: 0; }
.trpg-library-meta .trpg-icon-button .trpg-icon { width: 22px; height: 22px; }
/* スマホ横持ち（#2729 優先12）: ステージが縮むぶん（--k）を戻し、文字は実寸12px以上・押せる所は実寸44px。
   パンくず・冊数・前置きの一文・作者・名前の文字は外し（顔は残す。説明は右上の「？」）、3列のまま縦に伸ばしてスクロールで吸収する。 */
@media (orientation: landscape) and (max-width: 1024px) and (max-height: 520px) and (pointer: coarse) and (hover: none) {
  html:root .trpg-root.trpg-library { --lib-small: calc(12px / var(--k, 1)); --lib-body: calc(13px / var(--k, 1)); --lib-title: calc(16px / var(--k, 1)); --lib-target: calc(44px / var(--k, 1)); }
  html:root .trpg-root.trpg-library :is(.trpg-library-header .trpg-kicker, .trpg-library-meta > span, .trpg-library-intro, .trpg-library-byline, .trpg-library-cast > div > span:last-child) { display: none; }
  html:root .trpg-root.trpg-library .trpg-library-header { top: 12px; align-items: center; }
  html:root .trpg-root.trpg-library .trpg-library-header h1 { margin: 0; }
  html:root .trpg-root.trpg-library .trpg-library-meta { gap: calc(10px / var(--k, 1)); padding-top: 0; }
  html:root .trpg-root.trpg-library .trpg-library-meta .trpg-button { min-width: var(--lib-target); min-height: var(--lib-target); padding: 0 calc(10px / var(--k, 1)); font-size: var(--lib-body); }
  html:root .trpg-root.trpg-library .trpg-library-meta :is(.trpg-help-button, .trpg-icon-button) { width: var(--lib-target); height: var(--lib-target); padding: 0; font-size: var(--lib-title); }
  html:root .trpg-root.trpg-library .trpg-library-meta .trpg-icon-button .trpg-icon { width: calc(22px / var(--k, 1)); height: calc(22px / var(--k, 1)); }
  html:root .trpg-root.trpg-library .trpg-library-books { top: calc(24px + var(--lib-target)); bottom: 12px; grid-auto-rows: max-content; align-content: start; overflow-y: auto; }
  html:root .trpg-root.trpg-library .trpg-library-art { height: 92px; }
  html:root .trpg-root.trpg-library .trpg-library-number { font-size: var(--lib-title); }
  html:root .trpg-root.trpg-library .trpg-library-genre { font-size: var(--lib-small); font-weight: 700; }
  html:root .trpg-root.trpg-library .trpg-library-copy h2 { font-size: var(--lib-title); line-height: 1.3; }
  html:root .trpg-root.trpg-library .trpg-library-copy > p { font-size: var(--lib-body); line-height: 1.45; }
  html:root .trpg-root.trpg-library .trpg-library-details { flex-wrap: wrap; row-gap: 4px; font-size: var(--lib-small); font-weight: 700; }
  /* 顔の切り抜きは保ったまま、枠ごと大きくする */
  html:root .trpg-root.trpg-library .trpg-library-face { zoom: calc(.75 / var(--k, 1)); }
  html:root .trpg-root.trpg-library .trpg-library-cast { gap: calc(8px / var(--k, 1)); margin-bottom: calc(8px / var(--k, 1)); }
  html:root .trpg-root.trpg-library .trpg-library-copy > button { min-height: var(--lib-target); font-size: var(--lib-body); }
}

/* ===== css/vn.css ===== */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
/* ============================================================
   会話（VN）レイヤー
   ============================================================ */
#vn { opacity: 0; transition: opacity 0.25s ease; }
#vn.active { opacity: 1; }
/* 会話終了と同時に次画面が見えるため、前の文字と操作欄は残像にしない。 */
#vn:not(.active) :is(.vn-box, .vn-choices, .vn-controls, .vn-log) { visibility: hidden; }
/* 登場変形中は直前の台詞を読み終えた画面を片付け、カットイン後に会話へ戻す。 */
#vn :is(.vn-box, .vn-choices, .vn-controls) { transition: opacity 0.18s ease; }
#vn.intro-morph-dialog-hidden :is(.vn-box, .vn-choices, .vn-controls) {
  opacity: 0;
  pointer-events: none;
}

.vn-loading { position: absolute; left: 50%; top: 42%; transform: translate(-50%, -50%); z-index: 101;
  display: flex; align-items: center; gap: 14px; padding: 16px 24px; border: 1px solid #b59d7166; border-radius: 8px;
  background: #171221f2; color: #e4d4b4; font-size: 18px; pointer-events: none; }
.vn-loading::before { content: ""; width: 22px; height: 22px; border: 2px solid #a58b5233; border-top-color: #dfc58e;
  border-radius: 50%; animation: vn-loading-turn 1s linear infinite; }
@keyframes vn-loading-turn { to { transform: rotate(1turn); } }
@media (prefers-reduced-motion: reduce) { .vn-loading::before { animation: none; } }

.vn-cg {
  position: absolute;
  inset: 0;
  background: center / cover no-repeat #000;
  opacity: 0;
  transition: opacity 0.7s ease;
  z-index: 3;
}
.vn-cg.show { opacity: 1; }
.vn-skip .vn-cg { transition-duration: .14s; }
/* 縦型チェキの余白・落書きも、下の台詞ボックスに隠さず一枚全体を見せる。 */
.vn-cg[data-cg="cg_minto_first_cheki"] {
  background-color: var(--ink);
  background-size: auto calc(100% - 230px);
  background-position: center 18px;
}

/* #1076: つむぎの応募CG。実際の回答(窓辺)の台詞へ合わせて、既存の一枚絵の中の
   窓辺・猫・煙の位置へ短く視線を寄せ、次の行で全景へ戻す（新規素材・別画像は使わない）。 */
.vn-cg[data-cg="cg_ch1_tsumugi_heart_art"] {
  transition: opacity 0.7s ease, background-position .22s ease, background-size .22s ease;
}
.vn-cg[data-cg="cg_ch1_tsumugi_heart_art"].cg-focus-window {
  background-position: 41.7% 72.2%;
  background-size: 200% 200%;
}

/* #1076 DAY3: つむぎの描きかけ下描き（cg_ch1_tsumugi_sketch_wip）。回答した箇所へ一度だけ
   控えめに（150%）視線を寄せ、次の行で全景へ戻す。座標は asset_sources の焦点目安に合わせる。 */
.vn-cg[data-cg="cg_ch1_tsumugi_sketch_wip"] {
  transition: opacity 0.7s ease, background-position .22s ease, background-size .22s ease;
}
/* v3 の抽象スケッチ：(a) 葉の耳の猫の顔（左寄り上）、(b) 未着色の右側と色見本（右寄り）。
   座標は asset_sources の焦点目安に合わせる。150% の控えめな寄せ。 */
.vn-cg[data-cg="cg_ch1_tsumugi_sketch_wip"].cg-focus-sketch-cat {
  background-position: 0% 8%;
  background-size: 150% 150%;
}
.vn-cg[data-cg="cg_ch1_tsumugi_sketch_wip"].cg-focus-sketch-blank {
  background-position: 100% 35%;
  background-size: 150% 150%;
}

/* metadata.effect="smoke": 画面の下からうっすら煙がたなびく */
.vn-effect { position: absolute; inset: 0; pointer-events: none; z-index: 1; }
.vn-effect[data-effect="smoke"]::before,
.vn-effect[data-effect="smoke"]::after {
  content: "";
  position: absolute;
  left: -20%;
  right: -20%;
  bottom: -10%;
  height: 70%;
  background:
    radial-gradient(ellipse 40% 50% at 30% 80%, rgba(240, 236, 248, 0.22), transparent 70%),
    radial-gradient(ellipse 35% 45% at 70% 70%, rgba(240, 236, 248, 0.18), transparent 70%);
  filter: blur(20px);
  animation: smoke-drift 14s ease-in-out infinite alternate;
}
.vn-effect[data-effect="smoke"]::after { animation-duration: 19s; animation-direction: alternate-reverse; opacity: 0.7; }
@keyframes smoke-drift {
  from { transform: translateX(-6%) translateY(0); }
  to { transform: translateX(6%) translateY(-6%); }
}

#vn.sepia .vn-portraits, #vn.sepia .vn-cg { filter: sepia(0.75) contrast(0.95) brightness(0.92); }
body.in-vn #bg { transition: filter 0.4s; }
/* #2447 item10: 寝る前の家シーシャなど metadata.lift_scene_props の場面だけ、卓上・床の台を
   本文ボックスの上辺まで持ち上げ、台の下半分が会話ウィンドウに隠れないよう全体を見せる。
   対象は家の台（data-home-rig）のみで、他の背景・場面は従来どおり机へ接地させる。 */
body.vn-lift-props #bg .scene-prop[data-home-rig] {
  transform: translateY(-78px);
  transform-box: view-box;
  transition: transform 0.25s ease;
}
#vn.sepia ~ #bg, body.in-vn:has(#vn.sepia) #bg { filter: sepia(0.8) brightness(0.9); }
#vn.flashback .vn-portraits, #vn.flashback .vn-cg,
body.in-vn:has(#vn.flashback) #bg { filter: grayscale(1) contrast(.92); }
#vn.flashback::after { content: "回想"; position: absolute; top: 36px; left: 50%; transform: translateX(-50%); padding: 8px 24px; color: #eee; background: #19151bd9; border: 1px solid #aaa; font-size: 24px; letter-spacing: .25em; pointer-events: none; }
/* 修羅場の空気（core/scene-mood.js の "dread"）。会話をまたいで背景の色を落とし、四隅を沈める。立ち絵と台詞欄は変えない */
body[data-scene-mood="dread"] #bg { filter: saturate(.4) brightness(.62) contrast(1.06); transition: filter .5s ease; }
body[data-scene-mood="dread"] #bg::after { content: ""; position: absolute; inset: 0; z-index: 3; pointer-events: none;
  background: radial-gradient(ellipse at 50% 40%, #0b081400 30%, #05030ad1 100%); }

.vn-portraits { position: absolute; inset: 0; z-index: 2; overflow: hidden; pointer-events: none; }
.portrait {
  position: absolute;
  left: 50%;
  width: auto;
  max-width: none;
  transform: translateX(var(--ax, -50%));
  /* 話していない側は落とすが、落としすぎると暖色の背景で茶色く沈む（2026-11-14 オーナー指摘）:
     brightness 0.62 → 0.74、saturate 0.85 → 0.92 に緩めた。話し手との差（1.0）は残る。 */
  filter: brightness(0.74) saturate(0.92);
  transition: filter 0.25s ease, left 0.35s var(--ease-out), opacity 0.3s ease, translate 0.35s var(--ease-out);
  image-rendering: auto;
  -webkit-user-drag: none;
}
.portrait.active { filter: none; translate: 0 -3px; }
.portrait[data-pos="left"] { left: 30%; }
.portrait[data-pos="right"] { left: 70%; }
.portrait.enter { opacity: 0; translate: 0 24px; }
.vn-skip .portrait { transition: none; }

.vn-scent {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(ellipse 30% 40% at 40% 60%, var(--c1), transparent 70%),
    radial-gradient(ellipse 28% 36% at 62% 48%, var(--c2), transparent 70%);
  opacity: 0;
  filter: blur(26px);
  mix-blend-mode: screen;
  animation: scent 4.2s ease-in-out forwards;
}
@keyframes scent {
  0% { opacity: 0; transform: translateY(40px) scale(0.8); }
  30% { opacity: 0.55; }
  100% { opacity: 0; transform: translateY(-80px) scale(1.3); }
}

/* ---------------------------------------------------------------- テキストボックス */
.vn-box {
  position: absolute;
  left: 50%;
  bottom: 22px;
  z-index: 5;
  width: 1120px;
  height: 178px;
  transform: translateX(-50%);
  padding: 30px 60px 20px;
  background:
    linear-gradient(180deg, rgba(14, 10, 24, 0.78), rgba(8, 6, 14, 0.92));
  border: 1px solid rgba(232, 194, 122, 0.45);
  border-radius: 6px;
  box-shadow: 0 -2px 30px rgba(0, 0, 0, 0.45), inset 0 0 0 1px rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(4px);
}
.vn-box::before {
  /* 左上の飾り罫（煙の筋） */
  content: "";
  position: absolute;
  left: 18px;
  top: 14px;
  bottom: 14px;
  width: 3px;
  border-radius: 2px;
  background: linear-gradient(180deg, var(--gold), rgba(232, 194, 122, 0));
  opacity: 0.7;
}
.vn-box.narration .vn-text {
  word-break: normal; /* 行は autoWrap が決める */ color: #e9e2d4; }
.vn-box.thought .vn-text { color: #cfd8f2; }
.vn-name {
  position: absolute;
  left: 44px;
  top: -24px;
  min-width: 150px;
  padding: 6px 28px 7px 22px;
  font-family: var(--font);
  font-weight: 700;
  font-size: 22px;
  letter-spacing: 0.1em;
  color: #1a1206;
  background: linear-gradient(100deg, var(--gold-hi), var(--gold));
  clip-path: polygon(0 0, 100% 0, calc(100% - 14px) 100%, 0 100%);
  opacity: 0;
  transform: translateX(-10px);
  transition: opacity 0.15s, transform 0.2s var(--ease-out);
}
.vn-name.show { opacity: 1; transform: none; }
.vn-text {
  font-family: var(--font);
  font-size: 32px;
  font-weight: 500;
  line-height: 1.48;
  letter-spacing: 0.02em;
  white-space: nowrap;
  word-break: normal;
  overflow-wrap: normal;
  color: var(--text);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
  font-feature-settings: "palt" 0;
  min-height: 96px;
}
/* 枠の高さは固定。本心がある発言は1行ずつ送り、本心の2行分を空ける。 */
.vn-box.has-inner .vn-text { min-height: 48px; }
.vn-inner {
  margin-top: 8px;
  font-size: 24px;
  font-weight: 500;
  line-height: 1.45;
  letter-spacing: 0.02em;
  white-space: nowrap;
  color: #ffb6cc;
  text-shadow: 0 1px 2px #000;
}
.vn-inner[hidden] { display: none; }
.tx-imp { color: var(--gold-hi); font-weight: 700; text-shadow: 0 0 16px rgba(255, 210, 120, 0.6); }
.tx-warn { color: #ff8f8f; font-weight: 700; }
.tx-hint { color: #9fe3ff; }
.tx-red { color: #ff7a7a; }
.tx-blue { color: #8fb8ff; }
.tx-sub { font-size: 0.8em; color: var(--text-dim); }
/* 会話演出（#2828）: 「（」で始まる心の声は薄墨・少し小さく。震え文字は行ごとに小刻みに揺らし、
   設定「揺れ・閃光を減らす」・端末の「動きを減らす」・SKIP中は止める。 */
.tx-voice { color: #9aa0b8; font-size: 0.9em; text-shadow: none; }
.tx-shiver { display: inline-block; animation: tx-shiver 0.08s steps(2) infinite; }
@keyframes tx-shiver { 0% { translate: -1px 0; } 50% { translate: 1px 1px; } 100% { translate: 0 -1px; } }
body:is(.reduce-shake, .vn-skip) .tx-shiver { animation: none; }
@media (prefers-reduced-motion: reduce) { .tx-shiver { animation: none; } }
.vn-next {
  position: absolute;
  right: 34px;
  bottom: 16px;
  font-size: 18px;
  color: var(--gold);
  opacity: 0;
}
.vn-next.show { opacity: 1; animation: bob 1s ease-in-out infinite; }
@keyframes bob { 50% { transform: translateY(4px); } }

.vn-controls {
  position: absolute;
  right: 80px;
  bottom: 206px;
  z-index: 6;
  display: flex;
  gap: 8px;
}
.vn-ctl {
  min-width: 72px;
  min-height: 44px;
  padding: 9px 16px;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.06em;
  color: var(--text);
  background: rgba(10, 8, 16, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 4px;
  cursor: pointer;
}
.vn-ctl:hover, .vn-ctl:focus-visible { color: var(--text); border-color: var(--gold); }
.vn-ctl:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
.vn-ctl.on { color: #1a1206; background: var(--gold); border-color: var(--gold); }

/* ---------------------------------------------------------------- 選択肢 */
.vn-choices {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 262px; /* 大きくした操作ボタンの上に12pxの間隔を取る */
  z-index: 7;
  display: none;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.vn-choices.show { display: flex; }
/* 2択は質問・操作札から少し離して上へ寄せる（3択以上は 262px、2択は 356px）。
   オーナー「2択が上すぎる」「もう少し上」（2026-11-13・YHK14）: #3499 の 386px は高すぎ、3択以上と同じ高さは低すぎたので、#3499 の前の 338px に戻した。
   2026-11-14 オーナー「もう少し上へ」で 338px → 356px に微調整。あわせて出現アニメ（choice-in 0.22s・ずらし45ms）で少し速くした。 */
.vn-choices:has(> .vn-choice:nth-child(2):last-child) { bottom: 356px; }
/* 6択以上は画面上端と操作欄の間でスクロールさせる。短い選択肢の配置は維持する。 */
body:not(:root) .vn-choices:has(> .vn-choice:nth-child(6)) {
  top: 16px;
  left: 50%;
  right: auto;
  width: 760px;
  max-width: 100%;
  transform: translateX(-50%);
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  padding: 2px 12px;
}
body:not(:root) .vn-choices:has(> .vn-choice:nth-child(6)) > .vn-choice {
  flex-shrink: 0;
}
.vn-choice {
  width: 720px;
  padding: 16px 30px;
  font-size: 24px;
  letter-spacing: 0.04em;
  text-align: center;
  /* 選択肢は1行（GUI22）。文言は全角26字まで。はみ出すときは engine.js の fitOneLine が字を縮める */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text);
  background: linear-gradient(100deg, rgba(20, 14, 34, 0.94), rgba(34, 24, 50, 0.94));
  border: 1px solid rgba(232, 194, 122, 0.5);
  clip-path: polygon(16px 0, 100% 0, calc(100% - 16px) 100%, 0 100%);
  cursor: pointer;
  animation: choice-in 0.22s var(--ease-out) backwards;
  transition: background 0.15s, transform 0.15s;
}
.vn-choice:hover, .vn-choice:focus-visible {
  outline: none;
  background: linear-gradient(100deg, #caa15d, #9c7437);
  color: #1a1206;
  transform: scale(1.02);
}
.vn-choice.growth-hint { position: relative; }
.vn-choice.growth-hint::before {
  content: "〰";
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%) rotate(-90deg);
  font-size: 18px;
  color: var(--amber, #e8c27a);
  opacity: .8;
  pointer-events: none;
}
@keyframes choice-in { from { opacity: 0; transform: translateX(-30px); } }

