/* 火種の粒: 盤の絵（hidane_<色>.webp）。読めない時は色と形（白火＝丸、紅火＝炎、蒼火＝しずく、翠火＝角。SBD62） */
.hidane-icon { --hc: #fff1d0; position: relative; flex: none; display: inline-block; width: 20px; height: 20px; vertical-align: middle; border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, #fff, var(--hc) 48%, color-mix(in srgb, var(--hc) 45%, #2a1406)); filter: drop-shadow(0 0 5px var(--hc)); }
.hidane-icon.k-body { --hc: #ef8a5e; border-radius: 50% 50% 50% 50% / 62% 62% 38% 38%; }
.hidane-icon.k-sense { --hc: #58a6ff; border-radius: 4px 50% 50% 50%; }
.hidane-icon.k-wisdom { --hc: #7bd36d; border-radius: 4px; }
.hidane-icon img { display: none; position: absolute; inset: -18%; width: 136%; height: 136%; object-fit: contain; pointer-events: none; }
.hidane-icon.has-img { background: none; border-radius: 0; }
.hidane-icon.has-img img { display: block; }
/* 昇る火の粉（飾り） */
.gfx-embers { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.gfx-embers i { position: absolute; left: var(--x); bottom: -12px; width: var(--s); height: var(--s); border-radius: 50%; opacity: 0;
  background: radial-gradient(circle, #fff6dc, var(--ember, #ffb43c) 55%, transparent 72%); animation: gfx-ember var(--d) linear var(--w) infinite; }
@keyframes gfx-ember { 0% { transform: translate(0, 0) scale(1); opacity: 0; } 12% { opacity: 0.85; } 70% { opacity: 0.5; } 100% { transform: translate(var(--sway), -560px) scale(0.3); opacity: 0; } }
/* 火の粉・光の輪・走る光・飛ぶ火種（一度きり。JS が出して消す） */
.gfx-spark { position: absolute; border-radius: 50%; pointer-events: none; z-index: 6; background: radial-gradient(circle, #fff, var(--c, #ffd38a) 55%, transparent 75%); box-shadow: 0 0 6px var(--c, #ffd38a); }
.gfx-ring { position: absolute; border-radius: 50%; pointer-events: none; z-index: 6; border: 2px solid var(--c, #ffd38a); box-shadow: 0 0 14px var(--c, #ffd38a), inset 0 0 10px var(--c, #ffd38a); }
.gfx-run { stroke-width: 5; stroke-linecap: round; fill: none; pointer-events: none; }
.hidane-icon.gfx-fly { position: absolute; left: 0; top: 0; width: 24px; height: 24px; z-index: 30; pointer-events: none; }

@media (prefers-reduced-motion: reduce) {
