@keyframes gb-wall-breathe { 50% { opacity: 0.65; } }
.gb-node.s-locked .gb-face { opacity: 0.3; }
.gb-node.s-locked.lesson .gb-face { opacity: 0.7; }
.gb-face-icon.silhouette { filter: brightness(0) drop-shadow(0 0 1.5px rgba(244, 210, 122, 0.95)) drop-shadow(0 0 4px rgba(244, 210, 122, 0.35)); }
.gb-node.lesson.s-sealed .gb-face-icon.silhouette, .gb-node.lesson.s-locked .gb-face-icon.silhouette { filter: brightness(0) drop-shadow(0 0 1.5px rgba(244, 210, 122, 0.95)) drop-shadow(0 0 4px rgba(244, 210, 122, 0.35)); }
.gb-art .gb-face-icon.silhouette { filter: brightness(0) opacity(0.9); border-color: rgba(244, 210, 122, 0.5); box-shadow: none; }
.gb-mystery { position: absolute; right: -4px; bottom: -4px; display: grid; place-items: center; width: 17px; height: 17px; border-radius: 50%; font-size: 12px; font-weight: 900; line-height: 1;
  color: #1b1020; background: #f4d27a; box-shadow: 0 0 6px rgba(244, 210, 122, 0.8); pointer-events: none; }
/* 授業の札: 後光 */
.gb-node.lesson .gb-face { width: 48px; height: 43px; }
.gb-node.lesson .gb-face::after { content: ""; position: absolute; inset: -9px; z-index: -2; border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle, rgba(244, 210, 122, 0.42), rgba(244, 210, 122, 0.12) 55%, transparent 72%); animation: gb-aura 3s ease-in-out infinite; }
.gb-node.lesson.s-locked .gb-face::after { background: radial-gradient(circle, rgba(200, 190, 220, 0.16), transparent 70%); animation: none; }
@keyframes gb-aura { 50% { transform: scale(1.12); opacity: 0.75; } }
.gb-node.lesson .gb-face-icon { inset: 4px; width: calc(100% - 8px); height: calc(100% - 8px); }
.gb-node.lesson:not(.s-unlocked):not(.s-pending) .gb-face-icon:not(.silhouette) { filter: none; }
.gb-node.lesson.s-sealed .gb-face-icon:not(.silhouette) { filter: saturate(0.7) brightness(0.8); }
.gboard.has-art .gb-node.lesson .gb-face { width: 56px; height: 56px; }
.gboard.has-art .gb-node.lesson.sig .gb-face { width: 60px; height: 60px; }
.gboard.has-art .gb-node.lesson .gb-face-icon { inset: 11px; width: calc(100% - 22px); height: calc(100% - 22px); clip-path: polygon(24% 3%, 76% 3%, 98% 50%, 76% 97%, 24% 97%, 2% 50%); }
.gboard.has-art .gb-node.lesson:not(.s-unlocked):not(.s-available):not(.s-pending):not(.s-locked) .gb-face { filter: none; }
.gboard.has-art .gb-node.lesson.s-available .gb-face { filter: drop-shadow(0 0 9px var(--neon-gold)) brightness(1.08); }
.gboard.has-art .gb-node.lesson.s-locked .gb-face { background-image: url(../img/ui/growth_board/frame_lesson.webp); opacity: 0.72; filter: saturate(0.35); }
.gboard.has-art .gb-node.lesson.s-locked .gb-face::after { display: none; }
@media (prefers-reduced-motion: reduce) { .gb-wall-art, .gb-node.lesson .gb-face::after { animation: none !important; } }
/* 盤の拡大と移動（SBD77）: .gb-board がのぞき窓（スクロール）、.gb-world が拡大後の大きさ、.gb-stage が元の 760×488 を scale */
.gb-board-wrap { position: relative; width: 760px; height: 488px; }
.gb-board { overflow: auto; scrollbar-width: none; overscroll-behavior: contain; touch-action: pan-x pan-y; cursor: grab; }
.gb-board::-webkit-scrollbar { display: none; }
.gb-board.dragging { cursor: grabbing; user-select: none; }
.gb-board.dragging .gb-node { pointer-events: none; }
.gb-world { position: relative; width: 760px; height: 488px; }
.gb-stage { position: absolute; left: 0; top: 0; width: 760px; height: 488px; transform-origin: 0 0; }
.gb-zoom { position: absolute; right: 10px; top: 10px; display: flex; gap: 6px; z-index: 2; }
.gb-zoom .gb-icon { width: auto; min-width: 30px; height: 30px; padding: 0 9px; border-radius: 15px; font-size: 14px; line-height: 1; background: rgba(10, 6, 16, 0.8); }
.gb-zoom .gb-icon:disabled { opacity: 0.35; cursor: default; }
/* ================= 盤の演出の強化（2026-11-11 SBD104）: 仮置きで火種が飛ぶ・道を光が走る・決定のカットイン・昇る火の粉・近い目的地 =================
   部品は js/daily/growth-fx.js。盤の面・札・台座・結界・顔のデザイン（#2129）は変えず、光を足すだけ */
.gb-fx { position: absolute; inset: 0; pointer-events: none; }
.gb-embers { --ember: var(--board-c); z-index: 1; border-radius: 0 0 14px 14px; mix-blend-mode: screen; }
.gb-embers i { display: none; }
.gb-embers[data-level="1"] i:nth-child(-n+5), .gb-embers[data-level="2"] i:nth-child(-n+9), .gb-embers[data-level="3"] i { display: block; }
.gboard.view-only .gb-embers i:nth-child(n+7) { display: none; }
/* 灯した瞬間: 札が弾んで、光の輪が一度広がる（今までの gb-lit を強めた） */
.gb-node.lit-now .gb-face { animation: gb-lit-strong .55s cubic-bezier(.2, 1.4, .4, 1); }
@keyframes gb-lit-strong { 0% { transform: scale(1.7); box-shadow: 0 0 34px #ffd38a; filter: brightness(2); } 55% { transform: scale(0.92); filter: brightness(1.2); } 100% { transform: none; } }
.gboard.has-art .gb-node.gate.lit-now .gb-gate-gem { animation: gb-gem-set .6s cubic-bezier(.2, 1.5, .4, 1); }
@keyframes gb-gem-set { 0% { transform: scale(2.2) rotate(-25deg); opacity: 0; } 60% { transform: scale(0.9); opacity: 1; } 100% { transform: none; } }
/* 今灯せるマスの上に、小さな火が揺れる（どこを押せばいいかが遠目にも分かる） */
.gboard.can-light .gb-node.stat.s-available::before { content: ""; position: absolute; left: 50%; top: -3px; width: 8px; height: 11px; margin-left: -4px; pointer-events: none;
  border-radius: 50% 50% 50% 50% / 62% 62% 38% 38%; background: radial-gradient(circle at 50% 70%, #fff6dc, #ffb43c 60%, transparent 78%); animation: gb-wick 1.3s ease-in-out infinite; }
@keyframes gb-wick { 0%, 100% { transform: translateY(0) scale(0.85); opacity: 0.65; } 50% { transform: translateY(-3px) scale(1.1); opacity: 1; } }
/* 決定の間は盤を触れない（カットインだけ押して進められる） */
.gboard.committing { pointer-events: none; }
.gboard.committing .gfx-cutin-veil { pointer-events: auto; }
.gfx-cutin-veil { position: absolute; inset: 0; z-index: 45; display: grid; place-items: center; cursor: pointer;
  background: radial-gradient(ellipse 70% 46% at 50% 50%, rgba(6, 3, 12, 0.6), transparent 75%), rgba(6, 3, 12, 0.5); animation: gfx-veil-in .18s ease-out both; }
@keyframes gfx-veil-in { from { opacity: 0; } }
.gfx-cutin { --cc: #ffd38a; position: relative; display: flex; align-items: center; gap: 22px; width: 780px; max-width: calc(100% - 48px); box-sizing: border-box; padding: 20px 34px; overflow: hidden;
  color: #fff6e2; border-top: 2px solid var(--cc); border-bottom: 2px solid var(--cc);
  background: linear-gradient(90deg, rgba(14, 9, 22, 0.6), rgba(14, 9, 22, 0.97) 7%, rgba(14, 9, 22, 0.97) 93%, rgba(14, 9, 22, 0.6));
  box-shadow: 0 0 40px color-mix(in srgb, var(--cc) 35%, transparent); animation: gfx-cutin-in .36s cubic-bezier(.2, 1.2, .3, 1) both; }
.gfx-cutin.b-body { --cc: #ef8a5e; } .gfx-cutin.b-sense { --cc: #58a6ff; } .gfx-cutin.b-wisdom { --cc: #7bd36d; }
.gfx-cutin.t-lesson, .gfx-cutin.t-peak, .gfx-cutin.t-notable { --cc: #f4d27a; }
@keyframes gfx-cutin-in { 0% { transform: scaleY(0.1) translateX(-40px); opacity: 0; } 100% { transform: none; opacity: 1; } }
.gfx-cutin-streak { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(100deg, transparent 30%, color-mix(in srgb, var(--cc) 55%, #fff) 50%, transparent 70%); opacity: 0; animation: gfx-streak .7s ease-out .08s; }
@keyframes gfx-streak { 0% { transform: translateX(-100%); opacity: 0.75; } 100% { transform: translateX(100%); opacity: 0; } }
.gfx-cutin-icon { position: relative; flex: none; display: grid; place-items: center; width: 92px; height: 92px; border-radius: 50%; border: 2px solid var(--cc);
  background: radial-gradient(circle, color-mix(in srgb, var(--cc) 34%, #120c1c), #0a0612 75%); box-shadow: 0 0 22px color-mix(in srgb, var(--cc) 60%, transparent), inset 0 0 16px color-mix(in srgb, var(--cc) 40%, transparent);
  animation: gfx-icon-pop .5s cubic-bezier(.2, 1.6, .4, 1) .1s both; }
@keyframes gfx-icon-pop { 0% { transform: scale(0.2) rotate(-20deg); opacity: 0; } 100% { transform: none; opacity: 1; } }
.gfx-cutin-icon b { font-size: 44px; font-weight: 900; color: color-mix(in srgb, var(--cc) 60%, #fff); text-shadow: 0 0 14px var(--cc); }
.gfx-cutin-icon img { display: none; position: absolute; inset: 14%; width: 72%; height: 72%; object-fit: contain; filter: drop-shadow(0 0 6px var(--cc)); }
.gfx-cutin-icon.has-img img { display: block; }
.gfx-cutin-icon.has-img b { display: none; }
.gfx-cutin.t-lesson .gfx-cutin-icon img { inset: 0; width: 100%; height: 100%; border-radius: 50%; object-fit: cover; object-position: 50% 30%; filter: none; }
.gfx-cutin-text { display: grid; gap: 2px; min-width: 0; text-align: left; }
