/* 近い目的地: 絵・名前・火種の粒と数 */
.gb-goal { grid-template-columns: 34px 1fr auto; align-items: center; }
.gb-goal-icon { position: relative; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; overflow: hidden; background: radial-gradient(circle, #2a1f36, #120c1c 80%); border: 1px solid color-mix(in srgb, var(--c) 60%, transparent); }
