.gb-goal-icon img { position: absolute; inset: 12%; width: 76%; height: 76%; object-fit: contain; }
.gb-goal-icon.k-lesson img { inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: 50% 30%; }
.gb-goal-cost { display: inline-flex; align-items: center; gap: 8px; }
