}
.rule-sheet-eyebrow { margin: 0; font-size: 13px; letter-spacing: .02em; text-align: center; }
.rule-sheet h2 { margin: 4px 0 2px; font-size: 25px; text-align: center; letter-spacing: .2em; }
.rule-sheet-lead { margin: 0 0 14px; font-size: 12px; text-align: center; }
.rule-article { padding: 7px 0; border-top: 1px solid #735d3980; }
.rule-article h3 { margin: 0 0 5px; color: #473616; font-size: 16px; }
.rule-article p { margin: 0; font-size: 15px; line-height: 1.4; }
.rule-sheet-foot { margin: 10px 0 0; text-align: right; font-size: 13px; letter-spacing: .02em; }

/* ===== css/ch2-preview.css ===== */
/* 独立した第2章試遊。地図の絵は共有assets、操作と進行はこのページのメモリのみ。 */
.ch2-city { --ch2-accent: #a9eadc; --ch2-panel: #10242bf2; }
.ch2-city #bg { background: #173139; }
.ch2-city #bg img { object-position: center; }
.ch2-city #hud:empty { display: none; }
.ch2-city #screen { color: #fcf6e9; }
.ch2-city button, .ch2-city a { -webkit-tap-highlight-color: transparent; }
.ch2-city button:focus-visible, .ch2-city a:focus-visible {
  outline: 4px solid #fff3af; outline-offset: 5px;
}
.ch2-city .btn { min-height: 54px; }
.ch2-shell { position: absolute; inset: 0; }
.ch2-entry, .ch2-end, .ch2-error {
  display: flex; align-items: center; padding: 72px;
  background: linear-gradient(90deg, #07161ff5 0%, #07161fde 40%, #07161f3d 77%, #07161f12);
}
.ch2-entry-card, .ch2-end-card, .ch2-error-card { width: 660px; }
.ch2-kicker { margin: 0 0 14px; font-size: 18px; letter-spacing: .17em; color: var(--ch2-accent); }
.ch2-entry h1, .ch2-end h1, .ch2-error h1 {
  margin: 0 0 18px; font-size: 58px; line-height: 1.15; letter-spacing: .045em;
  font-weight: 900; text-shadow: 0 2px 15px #0005;
}
.ch2-entry h1 small { display: block; margin-bottom: 16px; font-size: 24px; letter-spacing: .25em; color: #e6d8b8; }
.ch2-entry-description, .ch2-end-description { margin: 0 0 22px; max-width: 620px; font-size: 23px; line-height: 1.75; }
.ch2-preview-note {
  margin: 0 0 24px; padding: 14px 18px; border-left: 3px solid var(--ch2-accent);
  font-size: 18px; line-height: 1.75; color: #c6d7d7; background: #0a1d277d;
}
.ch2-actions { display: flex; gap: 14px; align-items: center; }
.ch2-actions .btn { min-width: 224px; font-size: 22px; }
.ch2-text-link { padding: 12px 8px; font-size: 18px; color: #d4e5e3; text-decoration: underline; text-underline-offset: 4px; }
.ch2-entry-controls { margin: 22px 0 0; font-size: 17px; color: #b3c5c9; }
.ch2-map { background: linear-gradient(180deg, #07131fad 0, #07131f00 150px, #07131f00 565px, #07131fd9); }
.ch2-map.is-map-missing {
  background: repeating-linear-gradient(0deg, #a9eadc07 0 1px, transparent 1px 60px),
    repeating-linear-gradient(90deg, #a9eadc07 0 1px, transparent 1px 60px), linear-gradient(135deg, #173139, #071b27);
}
.ch2-map-header {
  position: absolute; left: 32px; right: 32px; top: 22px;
  display: flex; justify-content: space-between; align-items: flex-start; gap: 24px;
}
.ch2-map-header .ch2-kicker { margin: 0 0 5px; font-size: 14px; letter-spacing: .12em; }
.ch2-map-header h1 { margin: 0; font-size: 35px; font-weight: 900; text-shadow: 0 3px 8px #000; }
.ch2-map-header p { margin: 7px 0 0; font-size: 17px; color: #e0eceb; text-shadow: 0 2px 6px #000; }
.ch2-time-control { display: flex; gap: 4px; padding: 5px; background: #10242bed; border: 1px solid #b0d2c25e; border-radius: 10px; }
.ch2-time-control button { min-width: 78px; min-height: 48px; border: 0; border-radius: 6px; background: transparent; color: #cce4df; font-size: 20px; cursor: pointer; }
.ch2-time-control button[aria-pressed="true"] { color: #12282d; background: #a9eadc; font-weight: 900; }
.ch2-time-control button:disabled { cursor: default; }
.ch2-map-pins { position: absolute; inset: 0; margin: 0; padding: 0; list-style: none; pointer-events: none; }
.ch2-map-pins button { pointer-events: auto; }
.ch2-map-pins li { position: absolute; transform: translate(-50%, -100%); }
.ch2-pin {
  position: relative; display: grid; grid-template-columns: 30px 1fr; align-items: center; column-gap: 8px;
  width: 176px; min-height: 76px; padding: 11px 13px; border-radius: 7px;
  border: 2px solid #a4d5cb; color: #f5f6e9; background: #10242bf5;
  box-shadow: 0 6px 15px #0008; text-align: left; cursor: pointer; transition: transform .15s, background .15s;
}
.ch2-pin::after {
  position: absolute; left: 50%; bottom: -12px; width: 17px; height: 17px; content: "";
  background: #10242b; border-right: 2px solid #a4d5cb; border-bottom: 2px solid #a4d5cb;
  transform: translateX(-50%) rotate(45deg);
}
.ch2-pin:hover:not(:disabled) { transform: translateY(-5px); background: #163b42; }
.ch2-pin:disabled { cursor: wait; }
.ch2-pin-num {
  grid-row: 1 / 3; display: grid; place-items: center; width: 30px; height: 34px;
  font-size: 20px; font-weight: 900; color: var(--ch2-accent); border-right: 1px solid #acd6c74a;
}
.ch2-pin-title { white-space: nowrap; font-size: 20px; font-weight: 900; letter-spacing: .015em; }
.ch2-pin-caption { font-size: 14px; color: #c7d9d8; }
.ch2-pin.read { border-color: #efd0a0; }
.ch2-pin.read::after { border-color: #efd0a0; }
.ch2-pin.read .ch2-pin-num { color: #efd0a0; }
.ch2-pin.c-station { width: 215px; }
.ch2-pin.c-station .ch2-pin-title { font-size: 18px; }
.ch2-pin.ageha { width: 215px; }
.ch2-pin.ageha .ch2-pin-title { font-size: 18px; }
.ch2-pin.station { width: 205px; border-color: #d8e4e9; background: #152c3bf2; }
.ch2-pin.station::after { background: #152c3b; border-color: #d8e4e9; }
.ch2-pin.station .ch2-pin-num { font-size: 22px; color: #dfebef; }
.ch2-pin.station .ch2-pin-num svg { width: 29px; height: 29px; }
.ch2-map-summary {
  position: absolute; right: 32px; bottom: 78px; width: 274px; padding: 20px;
  border: 1px solid #bedace70; border-radius: 9px; background: var(--ch2-panel); box-shadow: 0 8px 22px #0005;
}
.ch2-map-summary h2 { margin: 0 0 12px; font-size: 20px; letter-spacing: .04em; }
.ch2-map-main .ch2-map-summary { width: 340px; }
.ch2-progress { margin: 0 0 12px; font-size: 33px; font-weight: 900; color: #eed3a4; line-height: 1.4; }
.ch2-progress small { font-size: 17px; color: #c6d7d7; font-weight: 400; margin-left: 7px; }
.ch2-map-summary p { margin: 0; font-size: 17px; line-height: 1.6; color: #c6d7d7; }
.ch2-map-summary .btn { width: 100%; margin-top: 15px; min-width: 0; font-size: 20px; }
.ch2-map-footer {
  position: absolute; bottom: 19px; left: 32px; right: 32px;
  display: flex; align-items: center; justify-content: space-between; gap: 18px;
  font-size: 17px; color: #e0e9e7;
}
.ch2-map-footer p { margin: 0; }
.ch2-map-footer .ch2-text-link { font-size: 16px; padding: 8px; }
.ch2-map-warning {
  position: absolute; left: 32px; top: 125px; max-width: 680px; padding: 12px 16px; border-radius: 7px;
  display: flex; align-items: center; gap: 14px; background: #202c39f5; border: 1px solid #e2c58c;
  color: #f3e1be; font-size: 18px;
}
.ch2-map-warning .btn { min-width: 0; min-height: 43px; padding: 8px 15px; font-size: 17px; }
.ch2-vn-label {
  position: absolute; top: 20px; left: 26px; padding: 9px 15px; border-left: 3px solid var(--ch2-accent);
  background: #07131ed9; color: #e8eee6; font-size: 17px; letter-spacing: .03em;
}
.ch2-stop { display: flex; align-items: center; padding: 64px; background: #07161fc7; }
.ch2-stop-card { max-width: 810px; padding: 38px; border: 1px solid #bedace70; border-radius: 10px; background: var(--ch2-panel); }
.ch2-stop-card h1 { margin: 0 0 20px; font-size: 40px; }
.ch2-stop-card p:not(.ch2-kicker) { font-size: 22px; line-height: 1.7; margin: 0 0 24px; }
.ch2-stop-card .ch2-actions { flex-wrap: wrap; }
.ch2-stop-card .ch2-room-warning { color: #f3d89c; }
.ch2-loading { display: grid; place-content: center; text-align: center; background: #0b202b; }
.ch2-loading h1 { font-size: 35px; margin: 0 0 18px; }
.ch2-loading p { margin: 0; font-size: 22px; color: var(--ch2-accent); }
.ch2-end-badge { display: inline-block; margin: 0 0 20px; padding: 7px 12px; border: 1px solid #acd6c77d; color: var(--ch2-accent); font-size: 18px; letter-spacing: .1em; }
.ch2-end h1 { font-size: 48px; }
.ch2-end-description { font-size: 22px; }
.ch2-end-progress { font-size: 21px; color: #efd0a0; margin: 0 0 18px; }
.ch2-error h1 { font-size: 39px; }
.ch2-error p { font-size: 21px; line-height: 1.6; }
.ch2-live-status { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
@media (prefers-reduced-motion: reduce) { .ch2-pin { transition: none; } }
.ch2-stop-card > .store-logo { margin: 0 auto 8px; }

/* 本編の初日にも、第1章と同じ墨色・真鍮の窓とピンを使う。独立試遊には適用しない。 */
.ch2-main { --ch2-accent: var(--gold); --ch2-panel: #100b18f5; }
.ch2-main .ch2-map-main { background: linear-gradient(0deg, #0c08154d, transparent 45%); }
.ch2-main .ch2-map-main .map-pins { inset: 0; }
.ch2-main .ch2-map-main .map-info { width: 300px; padding: 18px 22px; }
.ch2-main .ch2-map-main .mi-banner { margin-top: 0; }
.ch2-main .ch2-map-main .mi-desc { font-size: 16px; }
.ch2-main .ch2-map-main .mi-foot { margin-bottom: 12px; }
.ch2-main .ch2-map-main .spot-pin .sub-label { max-width: 240px; }
.ch2-main .ch2-route-note { top: auto; left: 18px; bottom: 18px; transform: none; display: grid; gap: 8px; width: 330px; padding: 18px 22px; white-space: normal; }
.ch2-main .ch2-route-note strong { font-size: 18px; color: var(--gold-hi); }
.ch2-main .ch2-route-note span { font-size: 15px; }
.ch2-main .ch2-route-note .btn { min-height: 44px; padding: 9px 16px; }
.ch2-main :is(.ch2-stop, .ch2-end, .ch2-error) { justify-content: center; padding: 64px; background: #0c081580; }
.ch2-main :is(.ch2-stop-card, .ch2-end-card, .ch2-error-card) { width: 760px; max-height: 590px; overflow: auto; padding: 32px 42px; }
.ch2-main .ch2-kicker { color: var(--gold); font-size: 16px; }
.ch2-main .ch2-vn-label { border-color: var(--gold); background: #100b18ed; }
.ch2-main .ch2-preview-note { background: var(--inner-face); border-color: var(--inner-edge); color: var(--text-dim); }
.ch2-main .ch2-stop-card h1, .ch2-main .ch2-end h1 { font-size: 36px; }
.ch2-main .ch2-stop-card p:not(.ch2-kicker), .ch2-main .ch2-end-description { font-size: 20px; }
.ch2-main .ch2-loading { background: #100b18; }
.purikura-photo { position: relative; width: min(460px, 100%); height: 310px; margin: 0 auto; overflow: hidden; border: 10px solid #ffbad9; border-radius: 8px; background: linear-gradient(135deg,#ffd6ea,#fff4c9 55%,#f6c5f5); box-shadow: inset 0 0 0 3px #fff; }
.purikura-people { display: flex; justify-content: center; height: 100%; }
.purikura-person { position: relative; flex: 1; max-width: 70%; overflow: hidden; }
.purikura-person img { position: absolute; width: 330px; max-width: none; left: 50%; top: -30px; transform: translateX(-50%); filter: brightness(1.12) saturate(1.08); }
.purikura-sparkles { position: absolute; inset: 10px 4px auto; color: #fff; font-size: 42px; letter-spacing: 18px; text-shadow: 0 0 8px #ff62bc, 0 0 12px #fff; pointer-events: none; }
.purikura-doodle { position: absolute; bottom: 36px; left: 8px; color: #ff1591; font-size: 30px; font-weight: 900; transform: rotate(-5deg); -webkit-text-stroke: 1px #fff; text-shadow: 2px 2px #fff, -2px -2px #fff; }
.purikura-caption { position: absolute; left: 0; right: 0; bottom: 2px; padding: 4px; color: #782246; background: #fff4facc; text-align: center; font-weight: 700; }
.map .spot-pin[data-test^="pin-ch2_"] .evt-badge { top: 4px; right: 4px; }
.map .spot-pin[data-test^="pin-ch2_"] { min-width: 100px; }

.shop-paper .shop-head h2.shop-brand { display: flex; align-items: center; gap: 12px; }
.trpg-campaign-header .store-logo { display: block; margin-bottom: 6px; }

/* ===== css/ch2-tournament.css ===== */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
/* DAY14の順位と持ち点。ゲーム内1280×720を基準にタッチでも同じ情報を保つ。 */
.ch2-contest { position:absolute; inset:22px 60px; padding:24px 32px; background:rgba(15,22,29,.96); color:#f5f1e8; border:1px solid #b7ac88; border-radius:18px; display:flex; flex-direction:column; gap:12px; font-size:21px; }
.ch2-contest h1,.ch2-contest p { margin:0; }
.ch2-contest-header { display:flex; justify-content:space-between; align-items:center; gap:24px; }
.ch2-contest-header h1 { font-size:34px; }
.ch2-contest-header p { color:#ded0a8; font-size:17px; }
.ch2-contest-description { line-height:1.5; }
.ch2-contest-note { color:#ded0b2; font-size:17px; line-height:1.5; }
.ch2-contest-reason { display:grid; gap:2px; padding:8px 14px; border-left:3px solid #e8c27a; background:#e8c27a14; }
.ch2-contest-reason p { margin:0; font-size:17px; line-height:1.5; color:#f4ede0; }
.ch2-contest-reason p + p { color:#e2c593; }
.ch2-contest-growth { display:flex; align-items:center; gap:20px; }
.ch2-contest-growth .radar { width:220px; height:220px; flex:none; }
.ch2-contest-actions { margin-top:auto; display:flex; gap:16px; }
.ch2-contest .btn { min-height:52px; padding:10px 24px; font-size:21px; }
/* 第4章の古い進み方（版1）の自由行動: 行き先7つが1列に並び、最後の「宿へ戻って、この日を終える」がカードの外へはみ出していた。
   行き先を幅240pxにそろえ、列は横に動かせるようにする（TXW07） */
.ch2-contest-actions:has(> .ch4-destination) { overflow-x: auto; overscroll-behavior-x: contain; padding-bottom: 10px; scroll-snap-type: x proximity; }
.ch2-contest-actions > .ch4-destination { flex: 0 0 240px; scroll-snap-align: start; }
.ch4-destination-purpose { text-wrap: balance; }
.ch2-contest-ranking { list-style:none; margin:0; padding:0; display:grid; gap:6px; }
.ch2-contest-rival { display:grid; grid-template-columns:30px 42px 1fr 100px; align-items:center; gap:12px; padding:3px 14px; background:#263644; border-radius:6px; }
.ch2-contest-avatar { position:relative; display:block; width:36px; height:36px; overflow:hidden; }
.ch2-contest-avatar img { width:36px; height:36px; object-fit:cover; object-position:center top; }
.ch2-contest-rival strong { text-align:right; color:#ffe7a0; }
.ch2-contest-judges { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; }
.ch2-contest-judges>div { padding:10px; border:1px solid #647683; border-radius:8px; display:flex; flex-direction:column; gap:4px; }
.ch2-contest-judges span { color:#ffe7a0; }
.ch2-contest-judges small { font-size:15px; line-height:1.4; }
.ch2-tournament-vn-menu { position:absolute; top:20px; right:26px; pointer-events:auto; }
.ch2-tournament .bench-top>.ch2-tournament-menu { margin-left:8px; min-width:86px; min-height:44px; font-size:18px; }
/* 右上の「外観を選ぶ」（絶対配置）とMENUが重ならないよう、帯の右側にボタン分の余白を取る */
body:not(:root) .bench-top:has(> .ch2-tournament-menu) { padding-right:154px; }
body:not(:root) .bench-top:has(> .ch2-tournament-menu) .bench-progress { padding-right:0; }

/* 投票・結果の画面は第1章と同じ中継グラフィック（部品は tournament.css / tournament-graphics.js）。 */
.ch2-contest:has(> .ch2-contest-board) { display: grid; grid-template-columns: minmax(0, 1fr) 290px; align-content: start; column-gap: 22px; row-gap: 10px; inset: 18px 40px; padding: 20px 28px 18px; overflow: hidden; border-color: #e8c27a66; background: linear-gradient(135deg, #1b1228f7, #0d0a15f8 60%); box-shadow: 0 24px 80px #000c, inset 0 1px 0 #ffe7b322; }
.ch2-contest:has(> .ch2-contest-board)::before { content: ""; position: absolute; inset: 0 0 auto; height: 4px; background: linear-gradient(90deg, #ff8db4, #f6c95e 50%, #5fe2cf); }
.ch2-contest:has(> .ch2-contest-board) > * { grid-column: 1 / -1; }
.ch2-contest:has(> .ch2-contest-board) > .ch2-contest-board { grid-column: 1; }
.ch2-contest:has(> .ch2-contest-board) > .ch2-contest-judges { grid-column: 2; }
.ch2-contest:has(> .ch2-contest-board) .ch2-contest-header { padding-bottom: 8px; border-bottom: 1px solid #e8c27a2e; }
.ch2-contest:has(> .ch2-contest-board) .ch2-contest-header h1 { font-size: 36px; font-style: italic; letter-spacing: .04em; background: linear-gradient(180deg, #fff6dc, #e8c27a); -webkit-background-clip: text; background-clip: text; color: transparent; }
.ch2-contest:has(> .ch2-contest-board) .ch2-contest-description { font-size: 18px; color: #d9d1e2; }
.ch2-contest-reason { position: relative; display: grid; grid-template-columns: auto 1fr; column-gap: 14px; align-items: center; padding: 8px 14px; border: 1px solid #e8c27a44; border-left: 0; border-radius: 6px; background: linear-gradient(90deg, #e8c27a1f, #e8c27a08); }
.ch2-contest-reason-tag { grid-row: 1 / 3; align-self: stretch; display: grid; place-items: center; margin: -8px 0 -8px -14px; padding: 0 14px; border-radius: 6px 0 0 6px; background: #d8304f; color: #fff; font-size: 14px; letter-spacing: .2em; }
.ch2-contest-reason p { grid-column: 2; }
.ch2-contest-board { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.ch2-contest-board .ch2-contest-ranking { gap: 8px; }
.ch2-contest-board .ch2-contest-rival { grid-template-columns: 40px 46px 120px minmax(0, 1fr) 78px; gap: 12px; min-height: 58px; padding: 6px 16px 6px 10px; border: 1px solid #ffffff12; border-radius: 8px; background: linear-gradient(90deg, #ffffff0d, #ffffff04); clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%); }
.ch2-contest-board .ch2-contest-rival.me { border-color: #e8c27a88; background: linear-gradient(90deg, #e8c27a33, #e8c27a0a); box-shadow: inset 4px 0 0 #f6c95e; }
.ch2-contest-board .ch2-contest-rival > span { font-weight: 800; font-size: 19px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ch2-contest-board .ch2-contest-rival.me > span, .ch2-contest-board .ch2-contest-rival.me strong { color: #ffe2a6; }
.ch2-contest-board .ch2-contest-avatar { width: 36px; height: 36px; margin: 0 5px; border-radius: 8px; background: #30283c; transform: scale(1.28); }
.ch2-contest-stack { height: 16px; }
.ch2-contest-board .ch2-contest-rival strong { font-size: 30px; font-weight: 900; font-style: italic; color: #fff; font-variant-numeric: tabular-nums; }
.ch2-contest-board .ch2-contest-rival strong small { margin-left: 3px; font-size: 13px; font-style: normal; color: #b8afc2; }
.ch2-contest-judges.judge-panel { display: flex; flex-direction: column; gap: 8px; }
.ch2-contest-judges.judge-panel > .judge-chip { display: grid; padding: 8px 10px 8px 14px; border: 1px solid color-mix(in srgb, var(--c) 40%, transparent); border-radius: 10px; }
.judge-chip .ch2-contest-avatar.judge-face { grid-row: 1 / 4; align-self: center; width: 36px; height: 36px; margin: 4px; border-radius: 50%; box-shadow: 0 0 0 2px var(--c); transform: scale(1.2); }
.ch2-contest-judges .judge-name { font-size: 16px; }
.ch2-contest-judges .judge-left { font-size: 13px; color: #c8c0d1; }
.ch2-contest:has(> .ch2-contest-board) .ch2-contest-note { font-size: 14px; color: #a9a1b3; }
.ch2-contest:has(> .ch2-contest-board) .ch2-contest-actions { justify-content: flex-end; }

/* ===== css/ch3-wayfinding.css ===== */
/* 東京編の既存場面カードにだけ添える、進行を変更しない行程表示。 */
.ch3-wayfinding { flex:0 1 auto; min-height:0; padding:14px 18px; border:1px solid #aebcd44d; border-radius:12px; background:#1c273b; }
.ch3-wayfinding-title { font-size:17px; color:#d8e4f5; }
.ch3-wayfinding-heading { display:flex; align-items:center; justify-content:space-between; gap:12px; }
.ch3-wayfinding-map { min-height:38px; padding:7px 14px; font-size:16px; }
.ch3-wayfinding-stops { display:flex; flex-wrap:wrap; gap:12px; margin-top:8px; }
.ch3-wayfinding-stop { flex:1 1 280px; min-width:0; display:flex; flex-direction:column; gap:3px; border-left:3px solid #93a6bf; padding-left:12px; overflow-wrap:anywhere; }
.ch3-wayfinding-stop.next { border-left-color:#efd494; }
.ch3-wayfinding-stop small { color:#d8e4f5; font-size:15px; }
.ch3-wayfinding-stop strong { color:#fff6df; font-size:23px; }
.ch3-wayfinding-stop span { color:#edf2f9; font-size:17px; line-height:1.4; }

/* Native dialog keeps keyboard/pointer input inside the map, above the scaled game stage. */
.ch3-map-dialog { width:min(1160px,96vw); max-width:96vw; max-height:94dvh; margin:auto; padding:16px; border:1px solid #c0a972; border-radius:14px; color:#f3ebdc; background:#171b29; font-family:var(--font); }
.ch3-map-dialog[open] { display:flex; flex-direction:column; gap:12px; }
.ch3-map-dialog::backdrop { background:#080a13c9; backdrop-filter:blur(3px); }
/* 縮小stageのChromiumで背景が鏡像反復しないよう、招待窓は暗幕だけを使う。 */
#modal:has(.ch3-party-dialog) .modal-backdrop { backdrop-filter: none; }
.ch3-map-header { display:flex; align-items:center; justify-content:space-between; gap:16px; flex:none; }
.ch3-map-header h2 { margin:0; font-size:24px; color:#f4dfaf; }
.ch3-map-header p { margin:2px 0 0; font-size:13px; color:#bdcbdc; }
.ch3-map-close { min-height:40px; padding:8px 18px; }
.ch3-map-content { display:grid; grid-template-columns:minmax(0,1fr) 200px; align-items:start; gap:14px; min-height:0; }
.ch3-map-canvas { position:relative; justify-self:center; align-self:center; width:min(100%,calc((94dvh - 150px) * 16 / 9)); aspect-ratio:16 / 9; overflow:hidden; border:1px solid #74849a; border-radius:8px; background:#283344; }
.ch3-map-art { display:block; width:100%; height:100%; object-fit:cover; }
.ch3-map-art[hidden] { display:none; }
.ch3-map-markers { position:absolute; inset:0; }
.ch3-map-pin { position:absolute; transform:translate(-50%,-50%); display:grid; place-items:center; width:34px; height:34px; padding:0; border:2px solid #f4d38a; border-radius:50%; background:#222638ef; color:#fff5df; font:700 15px var(--font); cursor:pointer; z-index:2; }
.ch3-map-pin.current { outline:3px solid #ffe9a877; outline-offset:3px; }
.ch3-map-pin.gym { border-color:#91d5de; }
.ch3-map-pin[aria-pressed="true"], .ch3-map-place[aria-pressed="true"] { background:#705b31; }
.ch3-map-pin:focus-visible, .ch3-map-place:focus-visible { outline:3px solid #fff; outline-offset:2px; }
.ch3-map-landmark { position:absolute; transform:translate(-50%,-50%); padding:2px 5px; border-radius:3px; background:#111a29db; color:#edf1ed; font-size:14px; line-height:1.2; white-space:nowrap; pointer-events:none; }
.ch3-map-sidebar { min-width:0; max-height:calc(94dvh - 150px); overflow:auto; overscroll-behavior:contain; padding:1px 4px 3px; }
.ch3-map-details { margin-bottom:10px; padding:10px; border:1px solid #6c7d96; border-radius:7px; background:#222b3c; }
.ch3-map-details h3 { margin:0 0 6px; font-size:18px; overflow-wrap:anywhere; }
.ch3-map-details p { margin:6px 0; font-size:13px; line-height:1.5; }
.ch3-map-gym { width:100%; padding:8px; min-height:44px; font-size:13px; white-space:normal; }
.ch3-map-list { display:flex; flex-direction:column; gap:4px; }
.ch3-map-place { display:flex; align-items:center; gap:7px; width:100%; min-height:36px; padding:5px 7px; border:1px solid #738196; border-radius:5px; background:#232c3b; color:#f8f0e1; font:14px var(--font); text-align:left; cursor:pointer; }
.ch3-map-place-number { flex:none; display:grid; place-items:center; width:23px; height:23px; border-radius:50%; background:#121a28; color:#f9dba1; font-size:12px; }
.ch3-map-place small { margin-left:auto; color:#ffe9ac; }
.ch3-map-note { flex:none; margin:0; font-size:12px; line-height:1.45; color:#c4d2e4; }
.ch3-map-image-error { position:absolute; left:4%; right:4%; bottom:6px; margin:0; padding:8px; background:#111a29ee; border-radius:5px; font-size:13px; text-align:center; z-index:1; }
.ch3-map-image-error[hidden] { display:none; }
@media (max-height:500px) {
  .ch3-map-dialog { padding:10px; }
  .ch3-map-dialog[open] { display:grid; grid-template-columns:minmax(0,1fr) 185px; grid-template-rows:auto minmax(0,1fr) auto; gap:8px; }
  .ch3-map-header { grid-column:2; grid-row:1; flex-direction:column; align-items:stretch; gap:5px; }
  .ch3-map-header h2 { font-size:19px; }
  .ch3-map-header p { font-size:12px; font-weight: 700; }
  .ch3-map-content { display:contents; }
  .ch3-map-canvas { grid-column:1; grid-row:1 / 3; width:min(100%,calc((94dvh - 56px) * 16 / 9)); }
  .ch3-map-sidebar { grid-column:2; grid-row:2; max-height:calc(94dvh - 160px); }
  .ch3-map-close { width:100%; min-width:0; min-height:36px; padding:6px 14px; font-size:14px; align-items:center; }
  .ch3-map-landmark { font-size:12px; font-weight:700; }
  .ch3-map-pin { width:32px; height:32px; font-size:13px; }
  .ch3-map-note { grid-column:1 / -1; grid-row:3; font-size:12px; font-weight: 700; }
}
@media (max-width:540px) and (min-height:501px) {
  .ch3-map-content { grid-template-columns:1fr; }
  .ch3-map-sidebar { max-height:32dvh; }
  .ch3-map-canvas { width:100%; }
}
/* 自由時間の行き先（#1655）。理由と一行動のボタンを地点ごとに並べる。 */
.ch3-map-action { margin-top:8px; padding-top:8px; border-top:1px solid #3d4a60; }
.ch3-map-action .btn { width:100%; margin-top:4px; padding:8px; min-height:44px; font-size:13px; white-space:normal; }
.ch3-map-reason { color:#d8e2f2; }

/* ===== css/store-logos.css ===== */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
/* 採用PNGの表示窓。画像を変形せず、採用部分の縦横比で表示する。 */
.store-logo { position: relative; display: block; flex: none; overflow: hidden; }
.store-logo > img { position: absolute; display: block; max-width: none; max-height: none; pointer-events: none; }
/* 画像が読めなかった時の店名。看板の窓（82×46）に収まるよう小さく折り返し、途中で切らない。 */
.store-logo.missing { display: grid; place-items: center; padding: 0 2px; color: #28251f; font-size: 12px; line-height: 1.15; font-weight: 700; letter-spacing: 0; text-align: center; white-space: normal; overflow-wrap: anywhere; }

.spot-pin.branded .shield { width: 90px; min-width: 90px; padding: 8px 5px 4px; background: #fffaf0; border-color: #d9c7a5; }
.spot-pin.branded .shield::after { background: #fffaf0; border-color: #d9c7a5; }
.spot-pin.branded .shield::before { background-color: #fffaf0; background-image: none; -webkit-mask: none; mask: none; border: 1px solid #d9c7a5; border-radius: 8px; }
/* マップだけ約1割縮小。来店演出のロゴサイズは変えない。 */
.spot-pin.branded .ico { height: 46px; grid-template-columns: minmax(0, 1fr); }
/* 原画の形・透過は保ち、黒に近かった緑の文字を地図上で読み取りやすくする。 */
.spot-pin.branded [data-store-logo="minto"] > img { filter: brightness(2) saturate(1.25); }
.spot-pin.branded.sel .shield { border-color: #ffe9a8; }
/* 白い文字のロゴ（クラブSEAM）は、地図の看板と来店の札を暗くして読めるようにする。 */
.spot-pin.branded:has(.store-logo.on-dark) .shield,
.spot-pin.branded:has(.store-logo.on-dark) .shield::before,
.spot-pin.branded:has(.store-logo.on-dark) .shield::after { background-color: #1f1a29; }
.store-arrival-card:has(.store-logo.on-dark) { background: #1f1a29; }
.spot-pin .pin-owner-face { position: absolute; top: -16px; left: -16px; right: auto; width: 32px; height: 32px; }

.store-arrival { position: absolute; inset: 0; z-index: 999; display: grid; place-items: center; pointer-events: none; }
.store-arrival-card { display: grid; place-items: center; gap: 14px; width: 440px; min-height: 250px; padding: 24px 32px; background: #fffdf7; border: 1px solid #d9c7a5; border-radius: 8px; box-shadow: 0 20px 60px rgba(12, 7, 25, .25); }
.store-arrival-card > small { color: #816f52; font-size: 17px; letter-spacing: .14em; }
/* 地図へ寄る移動（TMG46）: 白い札をやめ、光の中にロゴだけを出す。白い文字のロゴだけは暗いにじみを敷いて読めるようにする */
.store-arrival.bare .store-arrival-card { background: none; border: 0; box-shadow: none; }
.store-arrival.bare .store-arrival-card:has(.store-logo.on-dark) { background: radial-gradient(closest-side, #1f1a29f0 55%, #1f1a2900); }

/* Face positions follow the shield, independently of the caption width. */
.spot-pin .pin-visual { position: relative; }
.spot-pin .pin-visual:has(.pin-person:nth-child(3)) .evt-badge { top: 16px; }
/* 店主とゲストを看板の左上に並べる。クリックは親のピンへ通す。 */
.spot-pin .pin-people { position: absolute; top: -24px; left: -4px; right: auto; display: flex; justify-content: flex-start; gap: 2px; pointer-events: none; }
.spot-pin .pin-person { display: block; flex: 0 0 30px; width: 30px; min-width: 0; height: 30px; border: 2px solid #e2d9c7; border-radius: 50%; object-fit: contain; background: #211c2b; box-shadow: 0 2px 4px #0008; }
.spot-pin .pin-unknown { position: relative; color: #f2e8d1; }
.pin-unknown svg { display: block; width: 100%; height: 100%; fill: #666171; }
.pin-unknown b { position: absolute; inset: 0; display: grid; place-items: center; font: bold 16px/1 var(--font); text-shadow: 0 1px 2px #000; }
/* 駅のピンは札（「駅・一律200円」）の幅まで広げる。スマホ規格（#2917）では札の文字が下限（実寸11px・#2853）まで大きくなり、
   daily.css の固定幅 112px から札がはみ出していた（play_spots の第2章の街の検査）。PC は札が 112px に収まるので今までどおり。 */
body:not(:root) .map .spot-pin.pin-station { width: auto; min-width: 112px; }

/* ===== css/craft.css ===== */
/* body:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds) と同じ詳細度を保つための置き換え。 */
/* ============================================================
   作業台（シーシャ作り）と大会の演出
   大会中（data-mode="tournament"）は黒×ネオンの「スタイリッシュ職人バトル」。
   それ以外（練習・リハーサル・レッスン）は閉店後のtonariの暖色。
   ============================================================ */
@font-face { font-family: "Craft Mincho"; src: url("../fonts/ZenOldMincho-Craft.woff2") format("woff2"); font-weight: 700; font-display: swap; }
.bench {
  position: absolute;
  inset: 0;
  --accent: #d8bb86;
  --accent-2: var(--amber);
  --bench-bg: radial-gradient(ellipse at 15% 30%, #86613715, transparent 55%), linear-gradient(135deg, #17151bf2, #0a090dfc 70%);
  background: var(--bench-bg);
}
.bench[data-mode="tournament"] {
  --accent: #a7ddd7;
  --accent-2: var(--neon-pink);
  --bench-bg: radial-gradient(ellipse at 30% 20%, rgba(56, 240, 255, 0.08), transparent 50%), radial-gradient(ellipse at 80% 90%, rgba(255, 63, 164, 0.08), transparent 50%), rgba(4, 4, 8, 0.9);
}
.bench-top { position: absolute; left: 0; right: 0; top: 0; height: 48px; display: flex; align-items: center; gap: 16px; padding: 0 22px; border-bottom: 1px solid #ffffff0d; }
.bench-mode { width: 420px; font-family: var(--font); font-weight: 700; font-size: 12px; letter-spacing: .02em; color: var(--accent); flex: none; }
.bench-condition { position: relative; color: #e6c984; margin-left: auto; z-index: 7; }
.bench-condition[data-health="green"] { color: #95dbae; }
.bench-condition[data-health="red"] { color: #ef9e98; }
.bench-condition summary, .bench-guide summary { list-style: none; cursor: pointer; display: grid; place-items: center; border-radius: 50%; }
.bench-condition summary::-webkit-details-marker, .bench-guide summary::-webkit-details-marker { display: none; }
.bench-condition summary { width: 34px; height: 34px; background: color-mix(in srgb, currentColor 10%, transparent); }
.bench-condition svg { display: block; width: 27px; height: 27px; }
.bench-condition summary:focus-visible, .bench-guide summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
.bench-condition-tip, .bench-guide-tip { position: absolute; padding: 16px 18px; border: 1px solid #ffffff26; border-radius: 12px; background: #242129; box-shadow: 0 16px 38px #0008; color: #ede6db; text-align: left; }
.bench-condition-tip { width: 270px; bottom: calc(100% + 12px); right: 0; }
.bench-condition-tip b, .bench-guide-tip b { font-size: 15px; }
.bench-condition-tip p, .bench-guide-tip p { margin: 6px 0 0; font-size: 15px; line-height: 1.65; color: #c9c2b9; }
.bench-progress { display: flex; align-items: center; gap: 16px; min-width: 0; flex: 1; }
.bench-progress[hidden] { display: none; }
.bench-progress-count { font-size: 12px; font-weight: 700; color: #d3cec5; font-variant-numeric: tabular-nums; letter-spacing: .02em; white-space: nowrap; }
.bench-progress-track { display: flex; align-items: center; gap: 5px; flex: 1; }
.bench-progress-track span { height: 3px; flex: 1; border-radius: 4px; background: #ffffff19; }
.bench-progress-track span.seen { background: color-mix(in srgb, var(--accent) 45%, transparent); }
.bench-progress-track span.now { height: 5px; background: var(--accent); }
.bench-left { position: absolute; left: 22px; top: 60px; bottom: 22px; width: 420px; display: flex; flex-direction: column; gap: 8px; padding: 7px; border: 1px solid #ba99645c; border-radius: 12px; background: #170e21d9; box-shadow: inset 0 0 0 3px #e7c98e09, 0 8px 26px #0006; }
.bench-worker { flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden; border: 1px solid #ffffff1a; border-radius: 14px; background: #0c0a0e; box-shadow: 0 12px 32px #0004; }
.bench-worker-stage { flex: 1; min-height: 0; position: relative; overflow: hidden; isolation: isolate; background-size: cover; background-position: 35% center; }
.bench-worker-stage::before { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, #17101b55, #110c15bb); }
.worker-actor { position: absolute; height: calc(100% + 250px); width: auto; max-width: none; left: -110px; bottom: -205px; pointer-events: none; }
.worker-counter { position: absolute; inset: 64% 0 0; background-size: cover; background-position: center 70%; box-shadow: 0 -8px 18px #0004; }
.worker-equipment { position: absolute; right: 92px; bottom: 7%; width: 120px; height: 260px; pointer-events: none; }
/* Keep the optional appearance preview above the dialogue at the bottom of the worker window. */
.worker-appearance { position: absolute; right: 8px; top: 8px; width: min(160px, 50%); pointer-events: none; z-index: 2; }
.worker-appearance svg { display: block; width: 100%; height: auto; overflow: visible; }
/* 外観ボタンは .bench-top の右端に流し込む（大会MENU等と並べ、重ねない）。 */
.bench-appearance-button { flex: none; white-space: nowrap; }
.bench-appearance-dialog { position: absolute; z-index: 30; inset: 54px 12px 12px auto; width: min(430px, calc(100% - 24px)); overflow-y: auto; padding: 18px; background: #211b29; border: 1px solid #ab9071; border-radius: 8px; box-shadow: 0 10px 35px #000b; }
.worker-equipment > * { position: absolute; left: 50%; transform: translateX(-50%); }
.worker-vignette { position: absolute; inset: 0; background: linear-gradient(180deg, #05030b33, transparent 30%, transparent 65%, #08060ed9), linear-gradient(90deg, #100c1222, transparent 60%, #100c1255); pointer-events: none; }
.worker-scene-tag { position: absolute; left: 20px; top: 18px; font-size: 14px; letter-spacing: 0.02em; color: #d8cbbb; }
/* 一台の記録（CFX03・js/craft/rig-record.js）: 工程を終えるたびに灯が点き、出来が良いほど明るい。数字は出さない */
.rig-record { position: absolute; left: 16px; top: 44px; display: flex; gap: 6px; z-index: 3; pointer-events: none; }
.rig-lamp { position: relative; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%;
  background: #120c18cc; border: 1px solid #6d5d7a; color: #7f6f8b; font-style: normal; transition: background .3s, border-color .3s, color .3s, box-shadow .3s; }
.rig-lamp b { font-size: 12px; line-height: 1; font-weight: 700; }
.rig-lamp[data-tier="dim"] { background: #2a2230e6; border-color: #8a7a96; color: #b8aac4; }
.rig-lamp[data-tier="good"] { background: #5a3a1ee6; border-color: #e0a060; color: #ffe2bd; box-shadow: 0 0 6px #ff9a3a66; }
.rig-lamp[data-tier="great"] { background: #b8601ce6; border-color: #ffc27a; color: #fff4e0; box-shadow: 0 0 10px #ff9a3acc; }
.rig-lamp[data-tier="brilliant"] { background: radial-gradient(circle at 40% 35%, #fff6cf, #ffc21a 55%, #c97a00); border-color: #fff1b0; color: #4a2600;
  box-shadow: 0 0 6px #fff1b0, 0 0 16px #ffc21acc; animation: rig-lamp-glow 2.4s ease-in-out infinite; }
.rig-lamp.lit { animation: rig-lamp-pop .5s cubic-bezier(.2, 1.6, .4, 1); }
.rig-lamp[data-tier="brilliant"].lit { animation: rig-lamp-pop .5s cubic-bezier(.2, 1.6, .4, 1), rig-lamp-glow 2.4s ease-in-out .5s infinite; }
@keyframes rig-lamp-pop { 0% { transform: scale(.4); } 60% { transform: scale(1.35); } 100% { transform: scale(1); } }
@keyframes rig-lamp-glow { 50% { box-shadow: 0 0 10px #fff1b0, 0 0 26px #ffc21a; } }
/* 灯った分だけ作業風景に満ちる暖かい気配。全工程が輝くと縁がゆっくり脈打つ */
.rig-aura { position: absolute; inset: 0; z-index: 1; pointer-events: none; opacity: var(--rig-aura, 0); transition: opacity 1.2s ease;
  background: radial-gradient(120% 70% at 62% 78%, #ffb04a38, transparent 62%); box-shadow: inset 0 0 40px #ffb04a55; }
.rig-aura[data-full="true"] { animation: rig-aura-breathe 3s ease-in-out infinite; }
@keyframes rig-aura-breathe { 50% { box-shadow: inset 0 0 64px #ffc21a88; } }
@media (prefers-reduced-motion: reduce) {
  .rig-lamp.lit, .rig-lamp[data-tier="brilliant"], .rig-lamp[data-tier="brilliant"].lit, .rig-aura[data-full="true"] { animation: none; }
}
/* ライバルの小窓（CFX04・js/craft/rival-windows.js）: 大会だけ。隣の台の進みを工程の灯で見せる。数字・順位は出さない */
.rival-windows { position: absolute; right: 10px; top: 38%; display: flex; flex-direction: column; gap: 6px; z-index: 3; pointer-events: none; }
.rival-card { position: relative; display: grid; grid-template-columns: 30px auto; grid-template-rows: auto auto; column-gap: 6px; align-items: center;
  padding: 4px 8px 4px 4px; border-radius: 10px; background: #120c18d9; border: 1px solid #6d5d7a99; }
.rival-face { grid-row: 1 / 3; width: 30px; height: 30px; border-radius: 50%; overflow: hidden; background: #2a2230; }
.rival-face img { width: 100%; height: 100%; object-fit: cover; display: block; }
.rival-name { font-size: 12px; line-height: 1.2; color: #e8dcef; font-weight: 700; white-space: nowrap; }
.rival-lamps { display: flex; gap: 3px; }
.rival-lamp { width: 7px; height: 7px; border-radius: 50%; background: #2a2230; border: 1px solid #6d5d7a; transition: background .3s, box-shadow .3s; }
.rival-lamp[data-tier="dim"] { background: #6a5a76; }
.rival-lamp[data-tier="good"] { background: #c98a4a; }
.rival-lamp[data-tier="great"] { background: #ff9a3a; box-shadow: 0 0 4px #ff9a3a; }
.rival-lamp[data-tier="brilliant"] { background: #ffd34a; border-color: #fff1b0; box-shadow: 0 0 6px #ffc21a; }
.rival-card.flash { animation: rival-flash .9s ease-out; }
@keyframes rival-flash { 0% { box-shadow: 0 0 0 0 #ffc21a00; border-color: #fff1b0; } 25% { box-shadow: 0 0 18px 4px #ffc21acc; transform: scale(1.06); }
  100% { box-shadow: 0 0 0 0 #ffc21a00; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .rival-card.flash { animation: none; } }
.bench-worker-name { display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 5px 16px; color: #dfd3c2; border-top: 1px solid #ffffff0d; background: #17151b; }
.bench-worker-name > b { font-size: 14px; letter-spacing: 0.12em; }
.bench-worker-caption { display: none; }
.bench-audience { flex: none; height: 88px; min-height: 0; border: 1px solid #ffffff12; border-radius: 14px; background: #ffffff04; overflow: hidden; }
.audience-people { display: grid; grid-template-columns: 1fr; height: 100%; padding: 4px; }
.audience-person { margin: 0; min-width: 0; text-align: center; }
.audience-face { position: relative; width: 100%; height: 56px; border-radius: 8px; overflow: hidden; background: radial-gradient(ellipse at 50% 85%, #d8bb8614, transparent 75%); }
.audience-face img { position: absolute; max-width: none; height: auto; }
.audience-face img.audience-icon { width: 48px !important; height: 48px; left: calc(50% - 24px) !important; top: 2px !important; object-fit: contain; }
.audience-person figcaption { font-size: 12px; font-weight: 700; line-height: 16px; color: #bdb7ae; white-space: nowrap; }
.audience-person[data-mood="nod"] img { animation: audience-nod 0.55s ease-in-out; }
.audience-single { display: flex; align-items: center; gap: 8px; padding-right: 12px; }
.audience-single .audience-people { grid-template-columns: 1fr; width: 84px; flex: none; padding: 4px; }
.audience-speech { flex: 1; min-width: 0; }
.audience-heading { display: flex; align-items: center; gap: 8px; margin-bottom: 3px; }
.audience-rating { font-size: 20px; line-height: 1; font-weight: 700; color: #d3d9cb; }
.audience-caption { font-size: 12px; font-weight: 700; color: #bdb7ac; letter-spacing: .02em; }
.audience-note { margin: 0; font-size: 13px; color: #d1c7b6; line-height: 1.45; overflow-wrap: anywhere; }
.bench-audience[data-tone="bright"] .audience-rating { color: #efcf8a; }
.bench-audience[data-tone="bright"] .audience-note { font-size: 15px; font-weight: 700; color: #ecd4a1; line-height: 1.45; }
.bench-audience[data-speaker="sui"][data-tone="bright"] .audience-note { font-size: 14px; font-weight: 600; color: #d9e1e7; }
.bench-audience[data-tone="warm"] .audience-note { font-size: 14px; color: #d3dcc6; }
.bench-audience[data-tone="warm"] .audience-rating { color: #b7d2bc; }
.bench-audience[data-tone="quiet"] .audience-note, .bench-audience[data-tone="quiet"] .audience-rating { color: #c4ada6; }
@keyframes audience-nod { 45% { transform: translateY(3px); } }
.bench-right { position: absolute; left: 458px; right: 22px; top: 60px; bottom: 22px; display: flex; flex-direction: column; padding: 16px 22px; border: 1px solid #ba99645c; border-radius: 12px; background: #120c1dea; box-shadow: inset 0 0 0 3px #e7c98e09, 0 8px 26px #0006; }
.bench-head { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid #ffffff10; }
.bench-heading { min-width: 0; }
.bench-title { font-family: var(--font); font-weight: 700; font-size: 34px; line-height: 1.2; letter-spacing: 0.08em; color: #f4eee4; }
.bench-hint { margin-top: 4px; font-size: 14px; color: #c0b8aa; font-style: normal; line-height: 20px; min-height: 20px; }
.bench-guide { position: relative; flex: none; z-index: 8; }
.bench-guide[hidden] { display: none; }
.bench-guide summary { width: 34px; height: 34px; color: #bcb4a8; background: #ffffff08; border: 1px solid #ffffff1a; font-size: 16px; font-weight: 500; }
.bench-guide summary:hover { color: #f4eee4; border-color: var(--accent); }
.bench-guide-tip { top: calc(100% + 12px); right: 0; width: 360px; }
.bench-panel { position: relative; flex: 1; min-height: 0; }
.bench-demo-link { border: 0; padding: 0; background: none; color: var(--accent); font: inherit; text-decoration: underline; cursor: pointer; }
.bench-demo-link:focus-visible, .bench-demo-sheet button:focus-visible { outline: 3px solid #ffe3a7; outline-offset: 3px; }
.bench-demo-sheet { position: absolute; inset: 0; z-index: 40; display: grid; place-items: center; padding: 12px; background: #08060de8; container-type: size; }
.bench-demo-card { display: flex; flex-direction: column; width: min(900px, 100%); max-height: 100%; overflow: auto; padding: 14px; border: 1px solid var(--accent); border-radius: 14px; background: #201b25; box-shadow: 0 18px 48px #000b; }
.bench-demo-head { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
.bench-demo-head h2 { margin: 0; font-size: 20px; color: #f2dfb8; }
.bench-demo-sheet button { min-height: 44px; padding: 8px 18px; border: 1px solid var(--accent); border-radius: 999px; background: #312b35; color: #fff4e0; font: inherit; cursor: pointer; }
/* 映像は16:9のまま、シートの高さから見出し・字幕・状態文・手順・ボタンの分を引いた残りで幅を決める（「作業へ進む」を画面外へ出さない）。 */
.bench-demo-stage { flex: none; align-self: center; width: min(100%, calc((100cqh - 360px) * 16 / 9)); position: relative; aspect-ratio: 16 / 9; background: #000; overflow: hidden; }
.bench-demo-stage video { display: block; width: 100%; height: 100%; object-fit: contain; }
.bench-demo-arrow { position: absolute; font-size: clamp(34px, 5vw, 72px); line-height: 1; color: #ffd94d; text-shadow: 0 2px 8px #000; transform: translate(-50%, -50%); pointer-events: none; animation: bench-demo-bob .9s ease-in-out infinite alternate; }
.bench-demo-arrow[hidden] { display: none; }
@keyframes bench-demo-bob { from { margin-top: -5px; } to { margin-top: 5px; } }
.bench-demo-caption { flex: none; min-height: 3em; margin: 10px 0; color: #f2e9dc; font-size: 17px; line-height: 1.5; }
.bench-demo-status, .bench-demo-instructions { color: inherit; font-size: 16px; line-height: 1.6; }
.bench-demo-status { flex: none; margin: 10px 0; }
.bench-demo-instructions { flex: 0 1 auto; min-height: 0; overflow: auto; margin: 10px 0 14px; padding: 10px 14px; border: 1px solid #a895b6; border-radius: 8px; }
.bench-demo-instructions summary { cursor: pointer; }
.bench-demo-instructions summary:focus-visible { outline: 3px solid #ffe3a7; outline-offset: 3px; }
.bench-demo-instructions ol { margin: 10px 0 0; padding-left: 24px; }
.bench-demo-instructions li + li { margin-top: 6px; }
.bench-demo-stage[hidden], .bench-demo-caption[hidden] { display: none; }
.bench-demo-finish { flex: none; display: block; margin-left: auto; }

/* 制作中の操作ボタンは、道具・表情より目立ちすぎない面と一色の縁で統一。 */
.bench .btn { border-image: none; border: 1px solid #ffffff29; border-radius: 10px; background: #28252d; color: #e7e1d8; box-shadow: none; font-size: 17px; }
.bench .btn.primary, .bench .btn.primary:hover:not(:disabled) { background: var(--accent); border-color: var(--accent); color: #15151a; box-shadow: none; }
.bench .btn.ghost { background: transparent; }
.bench .btn:hover:not(:disabled), .bench .btn:focus-visible { border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 18%, transparent); }
.bench .btn:focus-visible, .bench .opt:focus-visible, .bench .fr-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

/* ---------------------------------------------------------------- 一台（リグ） */
.art { background-repeat: no-repeat; image-rendering: pixelated; }
.art-missing { background: rgba(255, 255, 255, 0.06); border-radius: 8px; }
.rig { position: relative; width: 320px; height: 600px; }
.rig > * { position: absolute; left: 50%; transform: translateX(-50%); }
/* 重なり順: ステム（首に差し込む）→ 水 → ガラス台（ステムの差し込み部分はガラス越しに見える）→ トレイ → ボウル → 葉/アルミ → 炭 → 煙 */
.rig-stem { z-index: 1; }
.rig-water { z-index: 2; border-radius: 0 0 50% 50% / 0 0 38% 38%; overflow: hidden; pointer-events: none; }
.rig-base { z-index: 3; }
.rig-tray { z-index: 4; }
.rig-bowl { z-index: 5; }
/* 贈られた専用ハガル: 染み付いた香りの色が素焼きの縁にうっすら残る */
.rig-bowl.infused .rig-bowl-img { filter: drop-shadow(0 0 5px color-mix(in srgb, var(--infuse, #c9a070) 70%, transparent)); }
/* 配合した葉（詰める前）: 湿った刻み葉の粒感をグラデーションで。色は配合の平均色 */
.rig-leaf {
  z-index: 6;
  border-radius: 50%;
  opacity: 0;
  transition: opacity 0.3s;
  background:
    radial-gradient(circle at 30% 40%, rgba(255, 255, 255, 0.25) 0 1.5px, transparent 2px) 0 0 / 7px 5px,
    radial-gradient(circle at 70% 60%, rgba(0, 0, 0, 0.35) 0 1.5px, transparent 2px) 0 0 / 6px 4px,
    radial-gradient(ellipse at 50% 35%, color-mix(in srgb, var(--leaf, #a44) 85%, #fff), color-mix(in srgb, var(--leaf, #a44) 70%, #200) 75%);
  box-shadow: inset 0 -3px 6px rgba(0, 0, 0, 0.5), 0 0 0 2px rgba(0, 0, 0, 0.25);
}
.rig-leaf.show { opacity: 0.95; }
.rig-foil { z-index: 7; opacity: 0; transition: opacity 0.3s; }
.rig-foil.show { opacity: 1; }
.rig-foil-img { position: absolute; left: 0; top: 0; }
.rig-foil-dots { position: absolute; left: 50%; top: 4%; transform: translateX(-50%); }
.rig-foil-dots i { position: absolute; width: 3px; height: 2px; margin: -1px 0 0 -1.5px; border-radius: 50%; background: #1a1a1a; }
.rig-coals { z-index: 8; width: 0; height: 0; }
.rig-coal { position: absolute; transform: translateX(-50%); filter: drop-shadow(0 0 8px rgba(255, 120, 40, 0.9)); animation: ember 1.6s ease-in-out infinite alternate; }
.rig-water i { position: absolute; bottom: -10px; width: 10px; height: 10px; border-radius: 50%; border: 1.5px solid rgba(255, 255, 255, 0.55); opacity: 0; }
.rig-water.bubbling i { animation: bubble-up 1.2s ease-in infinite; }
.rig-water i:nth-child(1) { left: 40%; animation-delay: 0s; }
.rig-water i:nth-child(2) { left: 55%; animation-delay: 0.3s; }
.rig-water i:nth-child(3) { left: 48%; animation-delay: 0.6s; }
.rig-water i:nth-child(4) { left: 60%; animation-delay: 0.9s; }
@keyframes bubble-up { 0% { opacity: 0; transform: translateY(0) scale(0.6); } 20% { opacity: 1; } 100% { opacity: 0; transform: translateY(-80px) scale(1.2); } }
@keyframes ember { from { filter: drop-shadow(0 0 6px rgba(255, 110, 30, 0.7)) brightness(0.95); } to { filter: drop-shadow(0 0 14px rgba(255, 150, 60, 1)) brightness(1.15); } }
.rig-smoke { position: absolute; z-index: 9; left: 0 !important; right: 0; height: 300px; transform: none !important; pointer-events: none; }
.rig-smoke i {
  position: absolute;
  bottom: 0;
  width: 60px;
  height: 60px;
  margin-left: -30px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--tint, #fff) 35%, #fff) 0%, transparent 70%);
  opacity: 0;
  filter: blur(6px);
  animation: smoke-rise 3.4s ease-out forwards;
}
@keyframes smoke-rise {
  0% { opacity: 0; transform: translate(0, 0) scale(0.4); }
  20% { opacity: 0.55; }
  100% { opacity: 0; transform: translate(var(--drift, 0), -260px) scale(2.6); }
}

/* ---------------------------------------------------------------- 選択肢の工程 */
.opt-grid { display: grid; gap: 14px; }
.opt-grid.cols-2 { grid-template-columns: 1fr 1fr; }
.opt-grid.cols-3 { grid-template-columns: 1fr 1fr 1fr; }
.opt {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 22px;
  text-align: left;
  color: var(--text);
  background: linear-gradient(135deg, #ffffff08, #ffffff03);
  border: 1px solid #ffffff1c;
  border-radius: 12px;
  cursor: pointer;
  transition: border-color 0.2s, transform 0.15s var(--ease-out), background 0.2s;
}
.opt b { font-size: 19px; letter-spacing: 0.04em; }
.opt small { font-size: 14px; color: #c0b8ad; line-height: 1.6; }
.opt:hover:not(:disabled) { border-color: var(--accent); transform: translateY(-2px); background: rgba(255, 255, 255, 0.07); }
.opt.on { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, transparent); box-shadow: inset 3px 0 var(--accent); }
.opt.off, .opt:disabled { opacity: 0.35; cursor: not-allowed; }
.step-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 16px; }

/* 配合: 葉と器、香りの返事を中心に置く。 */
.mix { display: grid; grid-template-columns: 300px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; gap: 18px 24px; height: 100%; }
.mix-side { display: flex; flex-direction: column; align-items: center; gap: 8px; min-width: 0; min-height: 0; overflow-y: auto; }
.mix-side > * { flex: none; max-width: 100%; }
/* 検出した名前は予測の先頭へ。長い予測を開いても、初期位置で見つけられる。 */
.mix-side > .recipe-line { order: -1; }
.mix-side > .recipe-line:empty { display: none; }
.mix-vessel { position: relative; flex: none; width: 300px; height: 332px; overflow: hidden; background: radial-gradient(ellipse at 50% 40%, #d5a26012, transparent 70%); }
.mix-vessel-art { position: absolute; inset: 0; display: flex; align-items: flex-end; justify-content: center; }
.mix-vessel-art > .art { flex: none; }
.mix-clay-leaves { position: absolute; border-radius: 50%; background-size: 280% auto; background-position: center 18%; }
.mix-taste { width: 100%; padding: 8px; text-align: center; }
.mix-taste > b { font-family: "Craft Mincho", var(--font); font-size: 23px; color: #e2c593; letter-spacing: .04em; }
.mix-taste p { margin: 8px 0; min-height: 50px; font-size: 15px; line-height: 1.7; color: #e4ddd2; }
.mix-taste-tags { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
.mix-taste-tags span { padding: 3px 9px; border: 1px solid #c4ab7a44; border-radius: 20px; font-size: 12px; color: #d0bda0; }
.mix-list { min-width: 0; display: flex; flex-direction: column; gap: 10px; overflow-y: auto; padding-right: 5px; }
.mix-list-head { flex: none; display: grid; gap: 6px; }
.mix-list-caption { margin: 8px 0 2px; font-size: 16px; letter-spacing: .08em; color: #d3c2a8; }
.flavor-row { display: flex; align-items: center; gap: 8px; padding: 12px; min-height: 76px; background: linear-gradient(120deg, #a2815520, #ffffff04); border: 1px solid #ae906c38; border-radius: 10px; }
.fr-package { flex: none; grid-area: 1 / 1; width: 54px; height: 64px; display: grid; place-items: center; }
.fr-package .shop-product-art { width: 54px; height: 64px; }
.fr-swatch { flex: none; width: 28px; height: 38px; border-radius: 70% 18% 70% 18%; box-shadow: inset 0 -4px 8px #0006; transform: rotate(-20deg); }
.fr-name { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.fr-name b { font-size: 16px; }
.fr-name small { font-size: 12px; line-height: 1.5; color: var(--text-dim); }
.fr-name .fr-reg { color: var(--accent); }
.fr-name .fr-stock { color: #cfe6b8; }
.fr-name .fr-ratio { color: var(--accent); font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; }
.fr-name .fr-ratio { min-height: 21px; }
.fr-name .fr-ratio:empty { visibility: hidden; }
.fr-btn { flex: none; width: 44px; height: 44px; border-radius: 50%; border: 1px solid #bba17566; background: #08070c80; color: var(--text); font-size: 24px; cursor: pointer; }
.fr-btn:hover { border-color: var(--accent); color: var(--accent); }
.fr-g { flex: none; width: 36px; text-align: center; font-family: var(--font); font-size: 18px; font-variant-numeric: tabular-nums; }
.mix-list:has(.flavor-row:nth-child(3)):not(:has(.flavor-row:nth-child(4))) .flavor-row { min-height: 180px; display: grid; grid-template-columns: 54px minmax(0, 1fr) 54px; grid-template-rows: 1fr 54px; padding: 16px 22px; gap: 12px; }
.mix-list:has(.flavor-row:nth-child(3)):not(:has(.flavor-row:nth-child(4))) .fr-swatch { width: 42px; height: 55px; grid-area: 1 / 1; }
.mix-list:has(.flavor-row:nth-child(3)):not(:has(.flavor-row:nth-child(4))) .fr-name { grid-area: 1 / 2 / 2 / 4; }
.mix-list:has(.flavor-row:nth-child(3)):not(:has(.flavor-row:nth-child(4))) .fr-name b { font-size: 20px; }
.mix-list:has(.flavor-row:nth-child(3)):not(:has(.flavor-row:nth-child(4))) .fr-btn { width: 54px; height: 54px; }
.mix-list:has(.flavor-row:nth-child(3)):not(:has(.flavor-row:nth-child(4))) .fr-g { width: 100%; font-size: 28px; }
.mix-footer { grid-column: 1 / -1; display: grid; grid-template-columns: 180px minmax(260px, 1fr) minmax(240px, 1fr); align-items: center; gap: 12px; padding-top: 14px; border-top: 1px solid #d1b48633; }
.mix-footer > .btn { min-height: 64px; }
.lcd { padding: 2px 0; text-align: left; font-family: var(--font); font-size: 23px; font-variant-numeric: tabular-nums; color: #bbd4b8; }
.lcd:not(.ok) { color: #d2bea0; }
.reg-line { font-size: 12px; color: #ff9b9b; line-height: 1.5; }
.reg-line.ok { color: var(--good); }
.recipe-line { font-size: 13px; color: var(--gold-hi); }
.mix-hint { font-size: 14px; color: #afc7d2; line-height: 1.5; padding: 6px 10px; border-left: 2px solid #afc7d266; background: #afc7d20d; }
.effect-badge { display: inline-grid; place-items: center; flex: none; min-width: 18px; height: 18px; padding: 0 2px; border: 1px solid currentColor; border-radius: 3px; font-size: 12px; font-weight: 800; line-height: 1; color: var(--effect-color); background: #101018dd; }
.effect-sense { --effect-color: var(--stat-sense); }
.effect-technique { --effect-color: var(--stat-technique); }
.effect-insight { --effect-color: var(--stat-insight); }
.effect-guts { --effect-color: var(--stat-guts); }
.effect-charm { --effect-color: var(--stat-charm); }
.effect-line { display: inline-flex; align-items: center; gap: 5px; color: var(--effect-color); font-size: 12px; }
.mix-hint:has(.effect-insight) { display: flex; align-items: center; gap: 5px; border-color: var(--stat-insight); color: var(--stat-insight); }
.craft-sense-band { display: flex; align-items: center; gap: 0; max-width: 100%; padding: 4px; }
.craft-sense-band .effect-badge { margin-right: 5px; }
.craft-sense-band i { display: block; height: 7px; flex: none; }
.craft-sense-base { background: #f8f1d0; }
.craft-sense-extra { background: var(--stat-sense); box-shadow: 0 0 8px var(--stat-sense); }
/* #1081 E02: フレーバーを決めるこの工程でも「フレーバーの持ち」を左の窓で先に見せる。 */
.mix-life-preview { width: 100%; display: grid; justify-items: center; gap: 4px; padding: 6px 4px; border-top: 1px solid #d1b48622; }
.mix-life-preview > b { font-size: 13px; letter-spacing: .02em; color: #d3c2a8; }
.mix-life-preview .leaf-icon { gap: 6px; }
.mix-life-preview .flavor-leaf { width: 24px; height: 24px; }
.mix-life-preview .leaf-skin { width: 24px; height: 24px; }
.mix-life-note { font-size: 12px; line-height: 1.4; min-height: 16px; color: #cfe6b8; text-align: center; }
.mix-temperature-preview { min-width: 0; display: grid; gap: 5px; font-size: 13px; color: var(--text-dim); }
.mix-temperature-legend { display: flex; flex-wrap: wrap; gap: 2px 12px; font-size: 14px; font-variant-numeric: tabular-nums; }
.mix-thermal-scale { position: relative; height: 22px; overflow: hidden; background: #55515d; border: 1px solid #eadbc2; border-radius: 4px; }
.mix-thermal-ideal, .mix-thermal-optimal, .mix-thermal-center { position: absolute; top: 0; height: 100%; }
.mix-thermal-ideal { border-inline: 2px solid #111; background: repeating-linear-gradient(135deg, #fff0 0 4px, #162b2540 4px 6px); }
.mix-thermal-optimal { border: 1px solid #fff; background: linear-gradient(90deg, #f6a4c0, #fae0a5, #b6edd2, #bad3fa, #e7bbf5); }
.mix-thermal-center { width: 2px; background: #171020; box-shadow: 0 0 0 1px #fff; }
.mix-temperature [hidden] { display: none; }
.mix-ideal { color: #74e0b0; }
.mix-optimal { color: #ffe5ff; }
.packing { height: 100%; display: flex; flex-direction: column; gap: 10px; }
.pack-aroma { margin: 0; padding: 7px 14px; border-left: 2px solid #c3a576; background: #d4aa6310; color: #e0c69f; font-size: 15px; line-height: 1.6; }
.pack-vessel { flex: 1; min-height: 300px; display: grid; place-items: center; position: relative; background: radial-gradient(ellipse at 50% 70%, #ab794821, transparent 63%); }
.pack-vessel::before { content: ""; position: absolute; width: 260px; height: 24px; bottom: 0; border-radius: 50%; background: #08040ccc; filter: blur(10px); }
.pack-vessel-art { position: relative; filter: drop-shadow(-6px 9px 9px #0007); }
.pack-vessel-art .art { image-rendering: auto; }
.pack-caption { text-align: center; min-height: 58px; }
.pack-caption b { font-size: 24px; color: #f0d1a0; letter-spacing: .1em; }
.pack-caption p { margin: 3px 0 0; font-size: 16px; line-height: 1.5; }
.pack-choices { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.pack-choice { position: relative; border: 1px solid #90795988; border-radius: 8px; background: #17131ee6; color: #ddcbb2; padding: 10px 12px; cursor: pointer; text-align: center; }
.pack-choice b { display: block; font-size: 20px; }
.pack-choice small { display: block; margin-top: 3px; font-size: 13px; color: #c8bab0; }
.pack-choice[aria-pressed="true"] { border-color: #e5bf80; background: #5f43255c; box-shadow: inset 0 -3px #e5bf80; color: #fff1da; }
.pack-choice[aria-pressed="true"]::before { content: "✓"; position: absolute; top: 5px; right: 9px; color: #f5d9a7; }
.pack-choice:focus-visible { outline: 3px solid #fff1da; outline-offset: 3px; }
.pack-footer { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.pack-footer small { color: #c8bab0; font-size: 14px; }
.pack-footer .pack-confirm { min-width: 240px; min-height: 48px; justify-content: center; font-size: 18px; }

/* ---------------------------------------------------------------- 穴あけ */
.holes { display: flex; gap: 24px; align-items: center; height: 100%; }
.hr-stage { flex: none; }
.foil {
  position: relative;
  border-radius: 50%;
  background: radial-gradient(circle at 70% 28%, #e3dfd6, #9998a0 68%, #55515c);
  box-shadow: -6px 14px 26px #0009;
  cursor: crosshair;
  touch-action: none;
}
.foil .foil-surface { position: absolute; inset: 0; border-radius: 50%; image-rendering: auto; pointer-events: none; }
/* The silver top is above the crimped lower rim of the adopted foil image. */
.foil-target-plane { position: absolute; inset: -3% 0 3%; pointer-events: none; }
.foil-ring { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); border-radius: 50%; border: 1px dashed #29253266; pointer-events: none; }
.foil-ring.cur { border: 1px solid #30263099; box-shadow: 0 0 0 1px #fff5; }
.foil-markers, .foil-holes { position: absolute; inset: 0; pointer-events: none; }
.foil-marker { position: absolute; width: 12px; height: 12px; margin: -6px 0 0 -6px; transform: rotate(45deg); border: 2px solid #504a55; background: #e6e0d578; box-shadow: 0 0 0 1px #fff9; }
.foil-marker.cur, .foil-marker.planned { border-color: #251b29; background: #fff6e3; box-shadow: 0 0 0 1px #fff9, 0 1px 3px #20172577; }
.foil-marker.next { background: #f58055; outline: 2px solid #251b29; outline-offset: 3px; }
.foil-marker.next::after { content: ""; position: absolute; inset: 2px; background: #291c28; }
/* CRN05: 開けた穴は盤の上ではっきり見える大きさに（採点の穴径 HOLE_SIZES は変えない・見た目だけ約1.6倍）。めくれた縁を明るく、外側を暗く縁取る */
.foil-hole { position: absolute; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 43% 55% 40% 52%; background: radial-gradient(ellipse at 62% 28%, #030205 48%, #2a2630 72%, #7b7480); box-shadow: 0 0 0 2px #fbf4e0, 0 0 0 3.5px #2b2433b0, -1px 2px 4px 2px #0000004d; animation: hole-pop .24s var(--ease-out); }
.foil-hole::before { content: ""; position: absolute; inset: -5px; border-radius: 45% 51% 40% 48%; background: linear-gradient(135deg, #20203255, transparent 45%, #fff6dd55 70%, transparent); pointer-events: none; }
.foil-hole::after { content: ""; position: absolute; top: calc(50% - 1px); left: -7px; width: 22px; height: 1px; background: linear-gradient(90deg, transparent, #4e465ccc 30%, transparent 46%, #fff5dacc 70%, transparent); transform: rotate(var(--scratch-angle, -28deg)); pointer-events: none; }
.foil-hole.close, .foil-hole.miss, .foil-hole.rough { border-radius: 24% 52% 32% 60%; }
.foil-hole.close::after, .foil-hole.miss::after, .foil-hole.rough::after { width: 27px; height: 2px; }
/* 穴の出方は transform だけ（filter は毎フレーム描き直しになって重い） */
@keyframes hole-pop { from { transform: scale(2.4); } 60% { transform: scale(.92); } }
.foil-hole.perfect { box-shadow: 0 0 0 2px #fff1c4, 0 0 0 3.5px #8a5a10cc, 0 0 8px 3px #ffc94a99, -1px 2px 4px 2px #0000004d; }
.foil-hole.good { box-shadow: 0 0 0 2px #e8fbff, 0 0 0 3.5px #1f4a5acc, -1px 2px 4px 2px #0000004d; }
/* 一刺しの判定は穴のすぐ外側に、小さく短く出す（CRN05）。右の札の大きな文字は使わない */
.foil-target-plane > .stamp { font-size: 22px; -webkit-text-stroke: 1px #00000099; letter-spacing: .02em; transform: translate(-50%, -50%); animation: hole-callout .75s var(--ease-out) forwards; z-index: 31; }
.foil-target-plane > .stamp.perfect { font-size: 26px; }
.foil-target-plane > .stamp.rough { font-size: 19px; }
@keyframes hole-callout { 0% { opacity: 0; transform: translate(-50%, -50%) scale(1.6); } 20% { opacity: 1; transform: translate(-50%, -50%) scale(1); } 70% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%, -85%); } }
@media (prefers-reduced-motion: reduce) { .foil-target-plane > .stamp { animation: hole-callout-calm .75s linear forwards; } }
@keyframes hole-callout-calm { 0%, 70% { opacity: 1; transform: translate(-50%, -50%); } 100% { opacity: 0; transform: translate(-50%, -50%); } }
.foil-cursor { position: absolute; width: 26px; height: 26px; margin: -13px 0 0 -13px; border-radius: 50%; border: 3px solid #c5fcff; outline: 2px solid #132f40; background: transparent; box-shadow: inset 0 0 0 1px #132f40, 0 0 12px #52d9ed99; pointer-events: none; }
.foil-cursor.technique-visible { box-shadow: inset 0 0 0 1px #132f40, 0 0 12px #52d9ed99, -7px 0 10px var(--stat-technique); }
.foil-cursor::after { content: ""; position: absolute; inset: -7px; border: 2px solid #132f40; clip-path: polygon(40% 0, 60% 0, 60% 40%, 100% 40%, 100% 60%, 60% 60%, 60% 100%, 40% 100%, 40% 60%, 0 60%, 0 40%, 40% 40%); }
/* #2937: 針は目印の近くだけを動く。押している間は沈み込み、アルミが小さくへこむ。押しすぎると色で知らせる。 */
.foil-dents { position: absolute; inset: 0; pointer-events: none; }
.foil-cursor { transition: opacity .12s; }
.foil-cursor.resting { opacity: .4; }
.foil-cursor.pressing { transform: scale(calc(1 - var(--press, 0) * .3)); }
.foil-cursor::before { content: ""; position: absolute; left: 50%; top: 50%; width: 6px; height: 6px; margin: -3px 0 0 -3px; border-radius: 50%; box-shadow: inset 1px -1px 2px #13101a88, 0 0 0 1px #fff7; opacity: 0; }
.foil-cursor.pressing::before { opacity: 1; transform: scale(calc(1 + var(--press, 0) * 2)); }
.foil-cursor[data-depth="wide"] { border-color: #ffd27a; }
.foil-cursor[data-depth="large"] { border-color: #ff9a76; }
.foil-hole.shallow { width: 8px; height: 8px; margin: -4px 0 0 -4px; opacity: .8; box-shadow: 0 0 0 1.5px #e6dfcc, 0 0 0 2.5px #2b2433a0; }
.foil-hole.wide { width: 19px; height: 19px; margin: -9.5px 0 0 -9.5px; }
.foil-hole.large { width: 24px; height: 24px; margin: -12px 0 0 -12px; }
.foil-dent { position: absolute; width: 8px; height: 8px; margin: -4px 0 0 -4px; border-radius: 50%; box-shadow: inset 1px -1px 2px #13101a66, 0 0 0 1px #fff8; animation: foil-dent-fade 1.6s ease-out forwards; }
@keyframes foil-dent-fade { 60% { opacity: .8; } to { opacity: .25; } }
@media (prefers-reduced-motion: reduce) { .foil-dent { animation: none; opacity: .4; } }
.foil-legend { display: flex; justify-content: center; gap: 27px; margin-top: 26px; padding: 6px 8px; color: #e8dac7; font-size: 14px; }
.foil-legend span { display: flex; align-items: center; gap: 12px; }
.foil-legend i { position: relative; display: inline-block; left: auto; top: auto; margin: 0; flex: none; animation: none; }
.foil-legend .foil-cursor { width: 20px; height: 20px; }
.hr-side { flex: 1; display: flex; flex-direction: column; gap: 10px; }
.hr-ring { font-size: 26px; font-weight: 700; color: var(--accent); letter-spacing: 0.06em; }
.hr-role { font-size: 14px; color: var(--text-dim); }
.hr-time { display: flex; align-items: center; gap: 10px; font-size: 14px; letter-spacing: 0.2em; color: var(--text-dim); }
.hr-time-bar { flex: 1; height: 8px; border-radius: 4px; background: rgba(255, 255, 255, 0.1); overflow: hidden; }
.hr-time-bar b { display: block; height: 100%; background: linear-gradient(90deg, var(--accent-2), var(--accent)); }
.hr-score { font-family: var(--font); font-size: 20px; color: #fff; }
.hr-combo { font-size: 22px; font-weight: 800; color: var(--neon-amber); min-height: 30px; text-shadow: 0 0 12px rgba(255, 194, 74, 0.8); }
.hr-feedback { position: relative; height: 50px; flex: none; pointer-events: none; overflow: hidden; }
.hr-feedback .stamp { font-size: 24px; letter-spacing: 0.02em; animation: hole-feedback-in 1.1s var(--ease-out) forwards; }
@keyframes hole-feedback-in { 0% { opacity: 0; transform: translate(-50%, -40%); } 15%, 80% { opacity: 1; transform: translate(-50%, -50%); } 100% { opacity: 0; transform: translate(-50%, -60%); } }
.hr-punch { width: 100%; align-items: center; padding: 18px; font-size: 22px; }
.hr-row { display: flex; gap: 8px; }
.hr-depth-hint { margin: 0; font-size: 22px; line-height: 1.4; color: var(--text); order: 7; }
.hr-plan { color: var(--text); font-size: 14px; line-height: 1.6; min-height: 3.2em; }
.hr-row .btn { flex: 1; }
.hr-row .btn:disabled, .hr-punch:disabled { opacity: 0.45; cursor: default; }

/* 同じアルミと作業パネルで、開始前だけ配置を選ぶ。 */
.ht-preview { width: 430px; height: 430px; cursor: default; touch-action: auto; }
.ht-side { flex: 1; min-width: 0; max-height: 100%; overflow-y: auto; display: flex; flex-direction: column; gap: 14px; scrollbar-width: thin; }
.ht-side > * { flex-shrink: 0; }
.ht-title { font-size: 22px; color: var(--accent); }
.bench .ht-option { width: 100%; min-height: 54px; justify-content: center; font-size: 16px; }
.bench .ht-option[aria-pressed="true"] { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 16%, #28252d); }
.ht-counts { color: var(--accent); font-size: 15px; font-variant-numeric: tabular-nums; }
.ht-description, .ht-note, .ht-help { margin: 0; font-size: 14px; line-height: 1.6; color: var(--text-dim); }
.ht-help summary { cursor: pointer; color: var(--text); }
.ht-help p { margin: 8px 0 0; }
.ht-current { font-size: 14px; color: var(--text-dim); }

/* ---------------------------------------------------------------- 炭焼き：中央を空けた三角配置と、別視点の炭壺 */
.bench[data-step="heat"] .bench-left { width: 310px; }
.bench[data-step="heat"] .bench-right { left: 348px; background: radial-gradient(ellipse at 48% 55%, #58251355, transparent 75%), linear-gradient(135deg, #190e18f2, #140c13f2); }
.bench[data-step="heat"] .bench-title { font-family: "Craft Mincho", var(--font); font-size: 36px; }
.heat { display: grid; grid-template-columns: minmax(0, 1fr) 240px; align-items: start; gap: 18px; min-width: 0; height: 100%; }
.heat:not(.heat-compact) { padding-top: 16px; }
.heat-stage { min-width: 0; }
.stove { position: relative; flex: none; margin: 40px auto 0; }
.stove-img { pointer-events: none; image-rendering: auto; }
.coal { position: absolute; width: 100px; height: 90px; transform: translate(-50%, -100%); padding: 0; border: 0; background: none; cursor: pointer; touch-action: manipulation; transition: opacity .2s; }
.coal-sprite { position: absolute; left: 50%; bottom: 0; transform: translateX(-50%) rotate(var(--coal-angle, 0deg)); transform-origin: center bottom; pointer-events: none; }
.coal-sprite > .art { position: absolute; left: 0; bottom: 0; pointer-events: none; image-rendering: auto; }
.c-red { opacity: var(--red, 0); }
.c-hot { opacity: var(--hot, 0); filter: brightness(1.14) saturate(.9); }
.c-ash { opacity: var(--ash, 0); filter: grayscale(.95) brightness(.8); }
.coal-corners { position: absolute; inset: 0; border: 2px solid #ddd7c077; border-radius: 5px; pointer-events: none; mask-image: linear-gradient(#000 0 15px, transparent 15px calc(100% - 15px), #000 calc(100% - 15px)), linear-gradient(90deg, #000 0 15px, transparent 15px calc(100% - 15px), #000 calc(100% - 15px)); mask-composite: intersect; }
.c-core { position: absolute; left: 50%; top: 44%; width: 32px; height: 32px; margin: -16px; border-radius: 50%; opacity: 0; background: radial-gradient(circle, #fff 0 35%, #fff9d9 55%, #ffe6a600 100%); box-shadow: 0 0 6px 5px #fffde7, 0 0 18px 12px #ffe3aaee, 0 0 34px 18px #ff8a45bb; pointer-events: none; }
.coal.pikan .coal-corners, .coal:focus-visible .coal-corners { border-color: #fff3bf; filter: drop-shadow(0 0 7px #ffb45c); }
.coal.pikan .c-core { opacity: 1; }
.coal.pikan .c-hot { opacity: 1; filter: brightness(2.2) saturate(.75) drop-shadow(0 0 10px #ffe1a0); }
.coal.pikan .coal-corners { animation: heat-ready .35s ease-in-out infinite alternate; }
@keyframes heat-ready { to { opacity: .35; filter: drop-shadow(0 0 12px #ff6b36); } }
.coal.soon .coal-corners { border-color: #e6a160; }
.heat.insight-visible .coal.soon .coal-corners { border-color: var(--stat-insight); box-shadow: 0 0 12px var(--stat-insight); animation: insight-soon .5s ease-in-out infinite alternate; }
.coal .effect-insight { display: none; position: absolute; right: -15px; top: -12px; }
.coal.soon .effect-insight { display: inline-grid; }
@keyframes insight-soon { to { opacity: .55; } }
.coal:focus-visible { outline: 2px solid #fff0bf; outline-offset: 4px; border-radius: 5px; }
.coal.picked { opacity: 0; pointer-events: none; }
.heat-info { position: relative; margin-top: 0; padding: 12px 12px 8px; border: 1.5px solid #e5d598; border-radius: 18px; background: linear-gradient(145deg, #100b0eea, #1b100dec); box-shadow: 0 10px 25px #0005; font-variant-numeric: tabular-nums; }
.heat-carrier-head { display: flex; justify-content: space-between; align-items: start; padding-right: 26px; color: #eee6d7; }
.heat-carrier-head h2 { margin: 0; font-family: "Craft Mincho", var(--font); font-weight: 700; font-size: 27px; line-height: 1.2; }
.heat-carrier-head small { font-size: 12px; letter-spacing: .02em; }
.heat-collected-count { font-size: 23px; letter-spacing: .08em; white-space: nowrap; }
.coal-carrier-view { position: relative; width: 195px; height: 232px; margin: 2px auto 0; pointer-events: none; }
.coal-carrier-art { pointer-events: none; image-rendering: auto; }
.coal-carrier-coals { position: absolute; inset: 0; margin: 0; padding: 0; list-style: none; pointer-events: none; }
.coal-stored { position: absolute; width: 35px; height: 40px; transform: translate(-50%, -100%); animation: coal-stored-in .2s ease-out; }
.coal-stored .coal-sprite { transform-origin: center bottom; }
.coal-stored .c-core { display: none; }
@keyframes coal-stored-in { from { opacity: 0; translate: 0 -7px; } to { opacity: 1; translate: 0 0; } }
.heat-feedback { position: relative; height: 45px; display: flex; align-items: center; justify-content: center; gap: 7px; pointer-events: none; color: #f3d68b; white-space: nowrap; }
.heat-feedback .stamp { position: static; font-size: 16px; letter-spacing: .02em; line-height: 1.2; animation: none; text-shadow: 0 0 4px #000; transform: none; }
.heat-feedback .perfect { color: #ffdf7d; }
.heat-feedback .good { color: #cce1be; }
.heat-feedback .miss { color: #eab6ab; }
.heat-error { font-size: 12px; font-weight: 700; padding-left: 7px; border-left: 1px solid #e4c77d66; }
.heat-bonus { color: #e5cd95; font-size: 12px; font-weight: 700; letter-spacing: .02em; }
.heat-picks { position: absolute; width: 1px; height: 1px; padding: 0; margin: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.heat-compact { grid-template-columns: minmax(0, 1fr) 200px; gap: 12px; height: 355px; }
.heat-compact .stove { margin-top: 35px; }
.heat-compact .coal { width: 84px; height: 72px; }
.heat-compact .heat-info { padding: 10px 10px 6px; }
.heat-compact .heat-carrier-head h2 { font-size: 24px; }
.heat-compact .heat-collected-count { font-size: 20px; }
.heat-compact .coal-carrier-view { width: 164px; height: 195px; }
.heat-compact .heat-feedback { height: 44px; flex-direction: column; gap: 2px; }
.heat-compact .heat-feedback .stamp { font-size: 14px; }
.heat-compact .heat-error { font-size: 14px; line-height: 1.2; padding-left: 0; border-left: 0; }
@media (prefers-reduced-motion: reduce) { .coal, .coal-stored, .coal.pikan .coal-corners { transition: none; animation: none; } .coal.pikan .c-core { opacity: 1; } }

/* キッチンタイマー：液晶と四つのボタンだけをコードで重ねる。 */
.steam-timer { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 22px; height: 100%; padding-bottom: 24px; }
.steam-clock { position: relative; width: 520px; height: 348px; flex: none; }
.steam-clock-skin { position: absolute; inset: 0; pointer-events: none; }
.timer-display { position: absolute; left: 12%; width: 76%; top: 17%; height: 38%; display: grid; place-items: center; color: #192e28; }
.timer-button { position: absolute; top: 75%; transform: translate(-50%, -50%); width: 18%; height: 16%; padding: 0; border: 0; border-radius: 12px; background: transparent; color: #27342e; font-size: 18px; font-weight: 800; letter-spacing: 0.015em; line-height: 1.15; -webkit-text-stroke: 0.25px currentColor; text-shadow: none; mix-blend-mode: multiply; cursor: pointer; }
.timer-button:hover:not(:disabled) { background: #ffffff14; }
.timer-button:active:not(:disabled) { background: #0002; transform: translate(-50%, calc(-50% + 2px)); }
.timer-button:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }
.timer-button:disabled { opacity: 0.4; cursor: default; }
.timer-start { display: flex; flex-direction: column; align-items: center; justify-content: center; width: 29%; font-size: 15px; line-height: 1.2; }
.timer-button[data-test="timer-reset"] { width: 15%; font-size: 14px; }
.timer-advice { margin: 0; color: #c6bbab; font-size: 15px; }
.digital-clock { display: block; }
.digital-clock:not(.timer-display) { position: relative; }
.steam-clock .timer-display { position: absolute; display: grid; place-items: center; }
.timer-display .clock-art { width: 92%; height: 96%; }
.timer-display .segment { stroke: currentColor; stroke-width: 1; stroke-linejoin: bevel; }
.clock-value { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.clock-art { display: block; width: 100%; height: 100%; }
.clock-art svg { display: block; width: 100%; height: 100%; fill: currentColor; }
.clock-art .segment { opacity: 0.1; }
.clock-art .segment.on { opacity: 0.94; }
.clock-art .colon { opacity: 0.85; }

/* ---------------------------------------------------------------- 蒸らし（雑念弾幕） */
.steam { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.steam-play { width: 726px; display: flex; align-items: center; justify-content: space-between; }
.steam .steam-temperature { height: 300px; flex: none; }
.steam-temperature .thermo-tube { width: 32px; }
.steam .dodge-controls { align-self: flex-end; margin-right: 11px; }
.dodge-wave { font-size: 14px; color: #94e6e8; align-self: center; }
.dodge { position: relative; overflow: hidden; border: 2px solid rgba(255, 255, 255, 0.5); background: rgba(0, 0, 0, 0.72); touch-action: none; cursor: none; }
.dodge-mental { --mental-ink: #86d6c5; position: absolute; inset: 0; pointer-events: none; color: var(--mental-ink); }
.dodge-mental svg { display: block; width: 100%; height: 100%; position: absolute; inset: 0; overflow: visible; }
.dodge-beat-line { stroke: var(--mental-ink); stroke-width: 2; opacity: .16; }
.dodge-mental-caption { position: absolute; left: 12px; bottom: 10px; font-size: 12px; letter-spacing: .02em; opacity: .8; }
.dodge-mental[data-level="unsteady"] { --mental-ink: #e4bc77; }
.dodge-mental[data-level="shaken"] { --mental-ink: #ef8795; }
.dodge-mental[data-level="shaken"] .dodge-beat-line { stroke-width: 2.5; opacity: .25; }
.dodge-mental.mental-hit { animation: mental-jolt .45s ease-out; }
@keyframes mental-jolt { 0%, 35% { background: #ed79981c; } 15% { transform: translateX(-4px); } 45% { transform: translateX(4px); } 100% { background: transparent; transform: none; } }
.dodge.warning[data-side="left"] { border-left-color: #ffd45c; box-shadow: inset 22px 0 26px -20px #ffd45c; }
.dodge.warning[data-side="right"] { border-right-color: #ffd45c; box-shadow: inset -22px 0 26px -20px #ffd45c; }
.dodge-heart { position: absolute; left: 0; top: 0; width: 28px; height: 28px; line-height: 28px; text-align: center; font-size: 26px; color: #ff3a6a; text-shadow: 0 0 12px rgba(255, 60, 100, 0.9); pointer-events: none; z-index: 3; }
.dodge-core { position: absolute; left: 11px; top: 11px; width: 6px; height: 6px; border-radius: 50%; background: white; box-shadow: 0 0 5px white; }
.dodge-heart.guts-visible .dodge-core { border: 2px solid var(--stat-guts); box-sizing: content-box; margin: -2px; }
.dodge-heart .effect-guts { position: absolute; left: 24px; top: -13px; }
.dodge-refresh-fx.guts-visible .dr-ring { border-color: var(--stat-guts); box-shadow: 0 0 22px var(--stat-guts), inset 0 0 22px var(--stat-guts); }
.dodge-guts-recovery { position: absolute; left: 12px; top: 12px; z-index: 6; }
.dodge-heart.shield::after { content: ""; position: absolute; inset: -7px; border: 2px solid #abf9ef; border-radius: 50%; box-shadow: 0 0 16px #85e9d8; }
.dodge-heart.hit { animation: heart-hit 0.9s steps(6); }
@keyframes heart-hit { 0%, 100% { opacity: 1; } 50% { opacity: 0.1; } }
.dodge-word { position: absolute; left: 0; top: 0; padding: 2px 8px; font-size: 15px; white-space: nowrap; color: #fff; background: rgba(255, 255, 255, 0.08); border: 1px solid rgba(255, 255, 255, 0.45); border-radius: 3px; pointer-events: none; }
.dodge-object { position: absolute; left: 0; top: 0; width: 22px; height: 22px; pointer-events: none; transition: none; }
.dodge-object.coal { margin: 0; padding: 0; background: linear-gradient(140deg, #ffc467, #ce4d27 45%, #39252b); border: 2px solid #ffbd74; border-radius: 4px; box-shadow: 0 0 10px #ff7148; }
.dodge-object.clock { border: 2px solid #c7d3ed; border-radius: 50%; background: #2a3245; }
.dodge-object.clock::after { content: ""; position: absolute; left: 8px; top: 3px; width: 6px; height: 7px; border-left: 2px solid #edf6ff; border-bottom: 2px solid #edf6ff; }
.dodge-object.spark { background: #f8d485; clip-path: polygon(50% 0, 62% 37%, 100% 50%, 62% 63%, 50% 100%, 38% 63%, 0 50%, 38% 37%); }
.dodge-object.smoke { width: 28px; height: 28px; background: radial-gradient(circle at 35% 35%, #e7e1ff, #8a78b3); border: 2px solid #b7a8d5; border-radius: 45% 60% 40% 60%; opacity: 0.9; }
.dodge-controls { display: flex; width: 620px; justify-content: space-between; align-items: center; gap: 22px; }
.dodge-pad { position: relative; width: 128px; height: 128px; flex: none; border-radius: 50%; border: 2px solid #a4b4b6; background: radial-gradient(circle, #36464b, #0f161b 70%); touch-action: none; cursor: grab; outline-offset: 3px; }
.dodge-pad > span { position: absolute; inset: 0; display: grid; place-items: center; font-size: 100px; color: #72898e; line-height: 1; }
.dodge-knob { position: absolute; left: 39px; top: 39px; width: 46px; height: 46px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #c8dadd, #667e86); border: 2px solid #def5f5; box-shadow: 0 4px 8px #0008; pointer-events: none; }
.dodge-pad.held { border-color: #acfff0; box-shadow: 0 0 14px #acfff044; cursor: grabbing; }
.dodge-actions { display: flex; flex-direction: column; gap: 12px; align-items: center; }
.dodge-refresh { min-height: 70px; min-width: 330px; font-size: 22px; touch-action: none; }
.dodge-refresh:disabled { opacity: 0.4; cursor: default; }
.dodge-actions small { color: var(--text-dim); font-size: 14px; }
.dodge-refresh-fx { position: absolute; inset: 0; pointer-events: none; z-index: 4; overflow: hidden; clip-path: circle(var(--reach) at var(--x) var(--y)); }
.dr-flash { position: absolute; inset: 0; background: radial-gradient(circle at var(--x) var(--y), #d8fff8aa, #7ee9dc44 40%, transparent 80%); animation: refresh-flash 0.8s ease-out forwards; }
.dr-ring { position: absolute; left: var(--x); top: var(--y); width: calc(var(--reach) * 2); height: calc(var(--reach) * 2); margin: calc(var(--reach) * -1); border: 3px solid #c7fff4; border-radius: 50%; box-shadow: 0 0 22px #aaffee, inset 0 0 22px #aaffee; animation: refresh-ring 0.8s ease-out forwards; }
.dr-ring.second { border-color: #e4d3ff; animation-delay: 0.12s; }
.dr-ray { position: absolute; left: var(--x); top: var(--y); width: 80px; height: 3px; background: linear-gradient(90deg, transparent, #fff, #85efde); transform-origin: left center; animation: refresh-ray 0.8s ease-out forwards; }
.dodge-refresh-fx b { position: absolute; left: 50%; top: 50%; color: #e9fffa; font-size: 32px; white-space: nowrap; text-shadow: 0 0 18px #69dabd, 0 2px 3px #000; animation: refresh-title 0.85s ease-out forwards; }
@keyframes refresh-flash { from { opacity: 1; } to { opacity: 0; } }
@keyframes refresh-ring { from { transform: scale(0.08); opacity: 1; } 65% { opacity: .8; } to { transform: scale(1); opacity: 0; } }
@keyframes refresh-ray { from { transform: rotate(var(--angle)) translateX(20px); opacity: 1; } to { transform: rotate(var(--angle)) translateX(300px); opacity: 0; } }
@keyframes refresh-title { 0% { transform: translate(-50%, -40%) scale(0.8); opacity: 0; } 20%, 65% { transform: translate(-50%, -50%); opacity: 1; } 100% { transform: translate(-50%, -70%); opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .dodge-mental.mental-hit { animation: none; }
  .dodge-refresh-fx .dr-ring, .dodge-refresh-fx .dr-ray { display: none; }
  .dodge-refresh-fx b { animation: none; transform: translate(-50%, -50%); }
  .dodge-heart.hit { animation: none; }
}

/* ---------------------------------------------------------------- 吸い出し */
.pull { display: flex; gap: 30px; align-items: center; height: 100%; }
.thermo { position: relative; display: flex; gap: 8px; height: 440px; }
.thermo-tube { position: relative; width: 44px; height: 100%; border-radius: 22px; background: rgba(255, 255, 255, 0.08); border: 2px solid rgba(255, 255, 255, 0.25); overflow: hidden; }
.thermo-zone { position: absolute; left: 0; right: 0; background: rgba(142, 230, 168, 0.35); border-top: 2px solid var(--good); border-bottom: 2px solid var(--good); z-index: 1; }
.thermo-mark { position: absolute; left: -4px; right: -4px; height: 4px; margin-bottom: -2px; background: #fff; box-shadow: 0 0 10px #fff; z-index: 2; transition: bottom 0.4s var(--ease-out); }
.thermo.ok .thermo-tube { box-shadow: 0 0 24px rgba(142, 230, 168, 0.6); }
.thermo-optimal { position: absolute; left: 0; right: 0; min-height: 3px; background: #f0d58b; box-shadow: 0 0 8px #edcf8c55; z-index: 2; }
.thermo.optimal .thermo-tube { box-shadow: 0 0 22px #eacf8580; border-color: #edcf8c; }
.pull-main { flex: 1; display: flex; flex-direction: column; gap: 16px; }
.pull-read { font-size: 20px; color: #fff; min-height: 30px; }
.pull-btns { display: flex; gap: 12px; }
