/* ---------------------------------------------------------------- RESULT 10 COUNT */
.count-screen { position: absolute; inset: 0; background: #000; overflow: hidden; pointer-events: none; }
.rc-title { position: absolute; left: 0; right: 0; top: 40px; text-align: center; font-size: 22px; letter-spacing: 0.8em; color: rgba(255, 255, 255, 0.5); }
.count-screen .rc-title { position: absolute; }
.rc-num { position: absolute; left: 50%; top: 42%; transform: translate(-50%, -50%); font-family: var(--font); font-weight: 800; font-size: 220px; color: #fff; text-shadow: 0 0 40px rgba(255, 255, 255, 0.6); }
.rc-num.pop { animation: rc-pop 0.45s var(--ease-out); }
@keyframes rc-pop { from { transform: translate(-50%, -50%) scale(1.6); opacity: 0.2; } }
.rc-cut { position: absolute; padding: 8px 18px; font-size: 22px; font-weight: 700; color: #000; background: var(--neon-amber); transform: rotate(var(--r)); animation: cut-flash 0.9s ease-out forwards; }
@keyframes cut-flash { 0% { opacity: 0; transform: rotate(var(--r)) scale(1.4); } 20% { opacity: 1; transform: rotate(var(--r)) scale(1); } 100% { opacity: 0; } }
.rc-pray { position: absolute; left: 0; right: 0; bottom: 50px; display: flex; justify-content: center; gap: 26px; }
.rc-card { display: flex; flex-direction: column; align-items: center; gap: 6px; font-size: 14px; color: #bbb; }
.rc-card.me { color: var(--neon-amber); }
.rc-shisha { width: 24px; height: 40px; border-radius: 12px 12px 4px 4px; box-shadow: 0 0 14px currentColor; }
.rc-crt { position: absolute; inset: 0; background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.03) 0 2px, transparent 2px 4px); }
.count-screen.almost { animation: almost 0.5s ease-in-out; }
@keyframes almost { 50% { transform: scaleY(0.2); filter: brightness(2); } }
.count-screen.puchun { animation: puchun 0.6s var(--ease-snap) forwards; }
@keyframes puchun { 0% { transform: none; } 50% { transform: scaleY(0.004) scaleX(1); filter: brightness(4); } 100% { transform: scaleY(0.004) scaleX(0); filter: brightness(4); } }
.count-screen.smoke-white { animation: none; transform: none; background: radial-gradient(circle, #fff 0%, #eee 40%, #bbb 100%); transition: background 0.6s; }
.count-screen.smoke-white > * { opacity: 0; }
.count-screen.crack::after { content: ""; position: absolute; inset: 0; background: linear-gradient(115deg, transparent 48%, rgba(255, 255, 255, 0.9) 49%, transparent 50%), linear-gradient(65deg, transparent 40%, rgba(255, 255, 255, 0.7) 41%, transparent 42%), linear-gradient(160deg, transparent 58%, rgba(255, 255, 255, 0.8) 59%, transparent 60%); }
.count-screen.parin::before { content: ""; position: absolute; inset: 0; background: conic-gradient(from 20deg at 50% 45%, rgba(255, 255, 255, 0.4) 0 2deg, transparent 2deg 30deg, rgba(255, 255, 255, 0.3) 30deg 32deg, transparent 32deg 80deg, rgba(255, 255, 255, 0.4) 80deg 82deg, transparent 82deg 140deg, rgba(255, 255, 255, 0.3) 140deg 142deg, transparent 142deg 220deg, rgba(255, 255, 255, 0.4) 220deg 222deg, transparent 222deg 300deg, rgba(255, 255, 255, 0.3) 300deg 302deg, transparent 302deg); z-index: 3; }
.count-screen.smoke-black::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 50% 60%, rgba(30, 30, 30, 0.95), #000 70%); animation: fade-in 1s ease forwards; z-index: 4; }
@keyframes fade-in { from { opacity: 0; } }
.rc-over { position: absolute; left: 0; right: 0; top: 44%; text-align: center; font-size: 72px; font-weight: 800; color: #ff4a4a; text-shadow: 0 0 30px #f00; z-index: 5; animation: rc-pop 0.5s var(--ease-out); }

