.bench-left .bench-audience { position: relative; height: 112px; margin: 5px 6px 0; border: 1px solid #a98d654a; border-radius: 8px; background: linear-gradient(145deg, #1b1522, #100c18); box-shadow: inset 0 0 0 3px #090710b0, inset 0 0 0 4px #9b806317; }
.bench[data-art-skin] :is(.bench-worker, .bench-audience) { border-image: none; border: 1px solid #a98d654a; box-shadow: inset 0 0 0 2px #08060e99, inset 0 0 0 3px #8c725319, 0 3px 12px #0004; }
