.audience-single .audience-people { width: 82px; display: flex; align-items: center; justify-content: center; padding: 0; }
.audience-single .audience-person { width: 82px; }
.audience-single .audience-face { height: 82px; border-radius: 5px; border: 1px solid #93816e26; background: #0e0b14; }
