.audience-caption { color: #aa9baf; }
.bench-audience[data-voice="inner"] .audience-caption { display: none; }
.audience-note { font-size: 16px; line-height: 1.55; color: #e0d5cc; }
.pull-main { gap: 0; justify-content: stretch; }
.pull-play { display: grid; grid-template-rows: minmax(0, 1fr) 64px 96px; gap: 14px; height: 100%; }
.pull-dial-row { position: relative; min-height: 0; }
.pull-dial { position: absolute; left: calc(50% - 10px); bottom: -2px; width: min(100%, 600px); height: auto; aspect-ratio: 2; transform: translateX(-50%); }
.pull-dial svg { left: 0; top: 0; }
.dial-ring { filter: drop-shadow(0 0 13px #efb07458); }
.dial-gloss { fill: #fff7d413; }
