.pg-just { fill: #fff8e8bc; stroke: #fffced; stroke-width: 1.6; filter: drop-shadow(0 0 8px #ffe7bac4); }
.needle-body { fill: #ffe592; stroke: #c49838; stroke-width: .8; filter: drop-shadow(0 0 4px #ffd869); }
.needle-light { fill: none; stroke: #fff8cf; stroke-width: 1.2; }
.needle-cap { fill: #fff0b6; stroke: #e3b755; filter: drop-shadow(0 0 5px #ffd270); }
