.pull-current-zone[data-zone="up"] { border-color: #ff995f; color: #ffd2ae; }
.pull-zone-label { position: absolute; top: 106px; display: flex; flex-direction: column; font-size: 16px; line-height: 1.5; color: #dda577; }
.pull-zone-label > b { font-size: 24px; letter-spacing: .06em; line-height: 1.4; padding-bottom: 5px; margin-bottom: 6px; border-bottom: 1px solid currentColor; text-shadow: 0 0 10px #a342382e; }
.pull-zone-label.l-down { left: 24px; color: #a6d8ff; }
.pull-zone-label.l-up { right: 24px; color: #ffb48b; }
.pull-zone-label.l-keep { top: 8px; left: calc(50% - 10px); transform: translateX(-50%); align-items: center; color: #efe7dd; font-size: 14px; }
.pull-zone-label.l-keep > b { border: 0; padding: 0; margin: 0; font-size: 20px; }
.pull-zone-label.l-keep > span { padding: 1px 24px; border: 1px solid #d6bf9b36; border-radius: 5px; background: #15101b70; }
.pull-zone-label .pull-tag { font-size: 12px; font-weight: 700; }
:is(.pull, .steam, .steam-timer) > .thermo { position: absolute; left: -128px; top: -48px; height: 360px; z-index: 3; }
:is(.pull, .steam, .steam-timer) > .thermo::after { content: ""; position: absolute; inset: -34px -12px -60px; z-index: -1; border: 1px solid #ae916843; border-radius: 8px; background: linear-gradient(160deg, #100b15ed, #100b15dd); box-shadow: inset 0 0 0 1px #eec6890e, 0 2px 10px #0006; }
.pull > .thermo .thermo-projected-label { display: none; }
.pull > .thermo .thermo-projected { height: 1px; margin-bottom: -.5px; border: 0; background: repeating-linear-gradient(90deg, #fff8 0 3px, transparent 3px 6px); box-shadow: none; }
.pull > .thermo .pull-read { position: absolute; top: calc(100% + 12px); left: -3px; right: -3px; justify-content: center; min-height: 32px; border: 1px solid #c1aa7438; border-radius: 6px; background: #100c17ef; }
.pull > .thermo .pull-state { font-size: 14px; white-space: nowrap; letter-spacing: .02em; }
.pull-summary { display: block; justify-self: start; width: max-content; max-width: 100%; padding: 0; border: 0; background: none; }
.pull-life { position: relative; min-width: 0; min-height: 0; height: 100%; display: flex; align-items: center; gap: 24px; padding: 8px 16px; border: 1px solid #a18a665c; border-radius: 9px; background: #100b18bb; box-shadow: inset 0 1px 2px #fff2; }
.pull-life-label { font-size: 13px; color: #c8bcc0; white-space: nowrap; letter-spacing: .02em; }
.pull-life-leaves { display: flex; align-items: center; flex: none; }
/* E08: 消耗する葉を右端に置き、残りの赤い葉を左に残す。 */
.pull-life-leaves .leaf-icon { flex-direction: row-reverse; }
.pull-tags:empty { display: none; }
.pull-serve-icon svg { display: block; width: 100%; height: 100%; }
/* 状態の読み上げだけ残す。注意書きや別ウインドウは表示しない（TH71）。 */
.pull-draw-status { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bench[data-art-skin] .pull-btns .btn { height: 96px; padding: 14px 20px; border-radius: 14px; font-size: 27px; font-weight: 700; border-width: 2px; }
.pull-btns .btn-label { font-family: "Craft Mincho", var(--font); font-weight: 700; letter-spacing: .035em; }
.bench[data-art-skin] .pull-btns .btn.primary { flex: 1.75; border-color: #eaca88; color: #ffe9c4; background: radial-gradient(ellipse at 50% 0%, #cd8f4930, transparent 75%), linear-gradient(135deg, #3f2b31, #211528 70%, #382132); box-shadow: inset 0 0 0 2px #e3bd6666, inset 0 0 0 5px #62402152, inset 0 0 30px #e5a64b1c, 0 0 8px #f2c57280, 0 0 24px #d9955024; text-shadow: 0 0 9px #ffce8099, 0 1px 2px #573821; }
.bench[data-art-skin] .pull-btns .btn.primary:hover:not(:disabled) { background: radial-gradient(ellipse at 50% 0%, #e1a14b50, transparent 75%), linear-gradient(135deg, #513638, #2d1b30 70%, #482b36); }
.bench[data-art-skin] .pull-btns .btn:disabled { opacity: .65; }
.pull-btn-icon { width: 48px; height: 48px; color: #fff0cd; filter: drop-shadow(0 0 5px #ffd29188); }
.pull-serve-icon { width: 48px; height: 40px; flex: none; }
.bench[data-art-skin] .pull-btns .btn.primary,
.bench[data-art-skin] .pull-btns .btn.primary:hover:not(:disabled) {
  border: 0; background-color: #241622; background-image: var(--craft-inhale-art);
  background-size: var(--craft-inhale-size); background-position: var(--craft-inhale-position); background-repeat: no-repeat;
  box-shadow: 0 0 18px #c48a3730; border-radius: 14px;
}
.bench[data-art-skin] .pull-btns .btn.primary:hover:not(:disabled) { filter: brightness(1.1); }
.bench[data-art-skin] .pull-btns .btn:not(.primary) { background: linear-gradient(145deg, #302432, #1c1523); border-color: #a598a782; box-shadow: inset 0 1px 2px #fff2; }
.bench[data-art-skin] .pull-btns .btn:not(.primary):disabled { opacity: .42; }
.pull-btns { display: grid; grid-template-columns: 1.75fr 1fr; gap: 14px; }
.pull-zone-label { top: 112px; }
.pull-life .pull-tag { font-size: 12px; font-weight: 700; padding: 1px 5px; }
.bench-audience[data-voice="inner"] .audience-note { font-size: 16px; max-width: 232px; word-break: normal; }

/* TH83〜90（2026-10-10）: 温度計の現在地の矢印・白線・危険帯、状態の文字色、右ウインドウの煙。 */
.thermo .thermo-pointer, .thermo.danger .thermo-pointer, .thermo.optimal .thermo-pointer {
  left: calc(var(--thermo-span) - 9px); width: 30px; height: 30px; background: none; clip-path: none;
  filter: drop-shadow(0 0 5px var(--pointer-glow, #ffffffaa)) drop-shadow(0 2px 2px #000d); }
.thermo-pointer svg { display: block; width: 100%; height: 100%; fill: var(--pointer-fill, #fff); }
.thermo { --pointer-fill: #fff; --pointer-glow: #ffffffaa; }
.thermo.cool { --pointer-fill: #fff2c8; --pointer-glow: #ffe2a288; }
.thermo.ok { --pointer-fill: #9effd6; --pointer-glow: #2fe39ccc; }
.thermo.optimal { --pointer-fill: #fff; --pointer-glow: #ffe066; }
.thermo.hot { --pointer-fill: #ffc078; --pointer-glow: #ff7a1acc; }
.thermo.danger { --pointer-fill: #ffd21a; --pointer-glow: #ff2a00; }
/* 現在地の白線と、虹の中央の最適温の白線。黒い縁で背景のどの色の上でも読める。 */
.thermo-mark, .thermo:has(.thermo-housing) .thermo-mark, .thermo:has(.thermo-housing).optimal .thermo-mark {
  left: 0; right: 0; height: 4px; margin-bottom: -2px; z-index: 6; background: #fff; box-shadow: 0 0 0 1.5px #0b0610, 0 0 9px #ffffffcc; }
.thermo-optimal::before { height: 3px; z-index: 2; box-shadow: 0 0 0 1px #0b061099, 0 0 6px #fff; }
.thermo-zone::before, .thermo-zone::after { opacity: 1; }
/* 焦げる帯は黄と黒の警戒ストライプ。越えたら明らかに危ないと分かるよう、境目も赤く太くする。 */
.thermo-danger { overflow: hidden;
  background: linear-gradient(-45deg, #ffcf1a 25%, #17100c 25% 50%, #ffcf1a 50% 75%, #17100c 75%) 0 0 / 12px 12px;
  box-shadow: inset 0 0 7px #ff2a00, inset 0 0 0 1px #ff3a1a99; }
.thermo-danger::after { bottom: 0; height: 3px; background: #ff3418; filter: none; box-shadow: 0 0 6px #ff2a00, 0 0 2px #000; }
.thermo-danger .thermo-icon.flame { width: 15px; height: 15px; padding: 1px; border-radius: 50%; background: #1a0b06; box-shadow: 0 0 0 1px #ffcf1a, 0 0 6px #ff2a00; }
.thermo-danger .thermo-icon.flame svg { fill: #ff5a1f; filter: none; }
.thermo.danger .thermo-danger { animation: hazard-slide .5s linear infinite; }
@keyframes hazard-slide { to { background-position: 12px 0; } }
/* 状態の一語も温度帯の色にする（ぬるい＝クリーム、適温＝ミント、熱い＝橙、焦げる寸前＝警戒色）。 */
.pull-read[data-tone="cool"] .pull-state { color: #fff0bd; text-shadow: 0 0 7px #e6bc6444; }
.pull-read[data-tone="ok"] .pull-state { color: #62f2b4; text-shadow: 0 0 8px #22d08c99; }
.pull-read[data-tone="hot"] .pull-state { color: #ffa652; text-shadow: 0 0 8px #ff6a0099; }
.pull-read[data-tone="danger"] .pull-state { color: #ffd21a; text-shadow: 0 0 6px #ff2a00, 0 0 12px #ff2a00aa; }
.pull-read[data-tone="cold"] .pull-state { color: #fff4d2; text-shadow: 0 0 7px #e6bc6444; }
.pull > .thermo .pull-read[data-tone="cool"] { border-color: #ead39b55; }
.pull > .thermo .pull-read[data-tone="ok"] { border-color: #4fe3a466; }
.pull > .thermo .pull-read[data-tone="optimal"] { border-color: #ffe9a477; box-shadow: 0 0 10px #ffd86a33; }
.pull > .thermo .pull-read[data-tone="hot"] { border-color: #ff9a4a66; }
.pull > .thermo .pull-read:is([data-tone="danger"], [data-tone="cold"]) { border-color: #ff4a2a99; }
/* 右ウインドウの奥に漂う煙。立ちのぼって薄れる2枚を半周期ずらし、途切れずに流れて見せる。 */
.panel-smoke { display: none; position: absolute; inset: 0; z-index: -1; overflow: hidden; border-radius: inherit; pointer-events: none; opacity: 0; transition: opacity 1.2s; }
.bench:is([data-step="pull"], [data-step="serve"], [data-step="care"]) .bench-right { isolation: isolate; }
.bench:is([data-step="pull"], [data-step="serve"], [data-step="care"]) .panel-smoke { display: block; }
/* TH93: 煙は温度が危なくなってきた時だけ。過熱で薄く、焦げる寸前・焦げで濃く速く。適温以下では出さない。 */
.bench[data-thermal-band="fire"] .panel-smoke.ready { opacity: .6; }
.bench:is([data-thermal-band="inferno"], [data-thermal-band="burnt"]) .panel-smoke.ready { opacity: 1; }
.bench:is([data-thermal-band="inferno"], [data-thermal-band="burnt"]) .panel-smoke-wisp::before,
.bench:is([data-thermal-band="inferno"], [data-thermal-band="burnt"]) .panel-smoke-wisp::after { animation-duration: 9s; }
.panel-smoke-wisp { position: absolute; }
.panel-smoke-wisp::before, .panel-smoke-wisp::after { content: ""; position: absolute; inset: 0; background: var(--smoke) center / 100% 100% no-repeat; opacity: 0; animation: panel-smoke-rise 16s linear infinite; }
.panel-smoke-wisp::after { transform: scaleX(-1); animation-name: panel-smoke-rise-flip; animation-delay: -8s; }
.panel-smoke-wisp.w-corner { right: -10px; top: -90px; width: 280px; height: 340px; }
.panel-smoke-wisp.w-left { left: -90px; bottom: 40px; width: 300px; height: 360px; }
.panel-smoke-wisp.w-right { right: -70px; bottom: 90px; width: 260px; height: 320px; }
.panel-smoke-wisp.w-left::before { animation-delay: -5s; }
.panel-smoke-wisp.w-right::before { animation-delay: -11s; }
@keyframes panel-smoke-rise { 0% { opacity: 0; transform: translateY(40px) scale(.94); } 30% { opacity: .62; } 70% { opacity: .5; } 100% { opacity: 0; transform: translateY(-50px) scale(1.1); } }
@keyframes panel-smoke-rise-flip { 0% { opacity: 0; transform: translateY(40px) scaleX(-1) scale(.94); } 30% { opacity: .5; } 70% { opacity: .42; } 100% { opacity: 0; transform: translateY(-50px) scaleX(-1) scale(1.1); } }
/* 見出し横の煙も、細い線から本物の煙の一筋へ。 */
.bench:is([data-step="pull"], [data-step="serve"], [data-step="care"]) .bench-title::after { left: calc(100% + 2px); top: -22px; width: 76px; height: 100px; opacity: .9; filter: none;
  background: var(--smoke-title, none) center / contain no-repeat; animation: title-smoke 6s ease-in-out infinite alternate; transform-origin: 50% 100%;
  visibility: hidden; }
.bench:is([data-step="pull"], [data-step="serve"], [data-step="care"]):is([data-thermal-band="fire"], [data-thermal-band="inferno"], [data-thermal-band="burnt"]) .bench-title::after { visibility: visible; }
@keyframes title-smoke { from { transform: translateY(2px) scaleY(.96); opacity: .75; } to { transform: translateY(-4px) scaleY(1.04) skewX(-4deg); opacity: .95; } }
.pull-btn-icon .hose-core { stroke: #2b1a26; }
@media (prefers-reduced-motion: reduce) {
  .thermo.danger .thermo-danger, .bench .bench-title::after { animation: none; }
  .panel-smoke-wisp::before { animation: none; opacity: .5; }
  .panel-smoke-wisp::after { display: none; }
}
/* TH95: 情報欄は左にフレーバーの持ち、右に吸い出し回数を並べる。 */
.pull-summary { display: flex; gap: 14px; width: auto; justify-self: stretch; }
.pull-summary > .pull-life { flex: none; }
.pull-summary > .pull-count-box { flex: 1; min-width: 0; gap: 18px; }
.pull-count-box .pull-pips { gap: 8px; }
.pull-count-box .pull-pip { width: 18px; height: 18px; }

/* #703: 作業絵は台詞の背後まで。台詞と工程表示を前景に重ねる。 */
.bench-left { gap: 0; }
.bench-left .bench-worker { position: relative; }
.bench-left .bench-worker-name { position: absolute; left: 0; right: 0; bottom: 0; z-index: 1; border: 0; background: linear-gradient(0deg, #110b1ad0, transparent); }
.bench-left:has(.bench-audience) .bench-worker-name { bottom: 128px; }
.bench-left .bench-audience { position: absolute; left: 11px; right: 11px; bottom: 11px; margin: 0; z-index: 2; background: linear-gradient(145deg, #1b1522ee, #100c18ed); }
.bench-left .bench-audience .audience-note { max-height: 100%; overflow-y: auto; }
/* 配合も吸い出しと同じ左位置・同じ縦管。操作欄のfooterには置かない。 */
.mix-temperature-preview { position: absolute; left: -140px; top: -3px; width: 88px; height: 464px; padding: 34px 12px 70px; display: block; z-index: 3; }
.mix-temperature-preview::before { content: ""; position: absolute; inset: 0; z-index: -1; border: 1px solid #ae916843; border-radius: 8px; background: linear-gradient(160deg, #100b15ed, #100b15dd); }
.mix-temperature-preview > b { position: absolute; top: 10px; left: 12px; width: 64px; text-align: center; font-size: 12px; font-weight: 700; }
.mix-temperature-preview > .thermo { height: 100%; }
/* #23-B: 下部の凡例（最大2行）＋ヒント（12px太字で2行=34px）の確保枠は70px。#703 の「吸い出しと同じ縦管(360px)」を保つため、枠全体を10px伸ばす。 */
.mix-temperature-legend { position: absolute; top: calc(100% - 70px); left: 4px; right: 4px; justify-content: center; font-size: 12px; line-height: 1.2; gap: 2px 5px; }
.mix-temperature-preview > small { position: absolute; top: calc(100% - 36px); left: 2px; width: 84px; text-align: center; font-weight: 700; font-size: 12px; }
.mix-temperature[data-selected="false"] .thermo-scale { background: #55515d; }
.thermo[hidden], .mix-temperature-preview[hidden] { display: none; }
.mix-footer { grid-template-columns: 180px minmax(240px, 1fr); }

.bench:is([data-step="pull"], [data-step="care"], [data-step="serve"]) .worker-equipment { right: 104px; bottom: 140px; width: 102px; height: 260px; }
.mix-temperature-preview:has([data-selected="false"]) > small { display: none; }
/* パッキングでも配合と同じ左の温度帯ゲージを出す（横画面）。実温度針はまだ無いので帯のみ。 */
body:not(:root) .bench[data-step="pack"] .packing { position: relative; }
body:not(:root) .bench[data-step="pack"] .bench-panel { overflow: visible; }
body:not(:root) .bench[data-step="pack"] .mix-temperature-preview {
  left: -140px; height: 480px; padding-bottom: 78px; overflow: hidden;
}


/* #2359 CUI08: 入場札と実況を夜紫の面へ。 */
.entrance { background: #150d22e8; }
.ent-cut { border: 1px solid #5a4475; background: #221534 url('../img/ui/craft-night/entry-rival.webp') center / 100% 100% no-repeat; }
.ent-card.me .ent-cut { border-color: #e3bd6e; background: #221534 url('../img/ui/craft-night/entry-me.webp') center / 100% 100% no-repeat; }
.ent-tag { background: #2e1d45; color: #f6f1fa; }
.ent-ring { color: #c9a7e6; }
.ent-name { color: #f6f1fa; text-shadow: 0 2px 8px #150d22; }
.ent-note { color: #c9a7e6; }
.nico { color: #f6f1fa; }
.nico.perfect { color: #e3bd6e; }
/* 心得「残り香」: 斬ったあと3秒だけ、実際にゆっくりになった雑念へ薄い余韻。 */
.dodge.afterglow .dodge-word { text-shadow: 0 0 9px #d9bdf5; }

/* 授業の追加操作も、吸う／提供と同じ行に収める。主操作を次の行へ押し出さない。 */
.bench[data-art-skin] .pull-btns.with-options .btn { font-size:20px;line-height:1.4;padding:3px 8px;white-space:normal;overflow-wrap:anywhere; }
.pull-btns.with-options .pull-btn-icon { width:32px;height:32px; }
.pull-omen { position:absolute;left:15%;right:15%;bottom:4px;text-align:center;font-size:16px;line-height:1.5;min-height:28px;padding:2px 4px;color:var(--gold);pointer-events:none; }
.pull-omen:empty { display:none; }

/* 明るい会場でも、観客の一言の文字と輪郭が背景へ溶けない。 */
.nico { background:#160f21b8;border-radius:6px;padding:2px 8px;-webkit-text-stroke:1px #190e21;paint-order:stroke fill; }

/* #2862 「?」の中の補足（詰め方の一覧など。工程が替わると外れる）。 */
.bench-guide-extra ul { margin: 8px 0 0; padding: 0; list-style: none; display: grid; gap: 4px; }
.bench-guide-extra li { display: flex; flex-wrap: wrap; gap: 4px 10px; font-size: 15px; line-height: 1.5; color: #c9c2b9; }
.bench-guide-extra li b { min-width: 6.5em; }

/* ---------- CRN06: 吸い出しの手応え（押した瞬間・行き先の予告・吸っている間の残り） ---------- */
/* 止めた瞬間、針先が白く光り、止めた帯がふくらむ。芯に止めたら、その帯の芯が強く光る（文字・金色は出さない・TH36） */
.pull-play[data-stopped] .pg-needle { animation: pull-needle-stop .32s ease-out; }
@keyframes pull-needle-stop { 0% { filter: drop-shadow(0 0 0 #fff) brightness(2.2); } 100% { filter: none; } }
.pull-play[data-stopped][data-stop-zone="down"] .z-down .pg-just,
.pull-play[data-stopped][data-stop-zone="keep"] .z-keep .pg-just,
.pull-play[data-stopped][data-stop-zone="up"] .z-up .pg-just { animation: pull-zone-stop .45s ease-out; }
.pull-play[data-stopped="just"][data-stop-zone="down"] .z-down .pg-just,
.pull-play[data-stopped="just"][data-stop-zone="keep"] .z-keep .pg-just,
.pull-play[data-stopped="just"][data-stop-zone="up"] .z-up .pg-just { animation: pull-just-stop .7s ease-out; }
@keyframes pull-zone-stop { 0% { filter: brightness(1.35); } 100% { filter: none; } }
@keyframes pull-just-stop { 0% { filter: brightness(2.1) drop-shadow(0 0 10px #ffffff); } 100% { filter: none; } }
/* 吸っている間の残り時間。半円の外側の弧が、吸い終わりに向けて縮む（下げ吸いは長いので、待つ間に見るものを置く） */
.pull-dial .pg-draw-arc { fill: none; stroke: #f3e6c8; stroke-width: 5; stroke-linecap: round; stroke-dasharray: 1 1; stroke-dashoffset: 0; opacity: 0; transition: opacity .15s; }
.pull-play[data-draw] .pull-dial .pg-draw-arc { opacity: .85; stroke-dashoffset: calc(-1 * var(--draw-progress, 0)); }
.pull-play[data-draw="down"] .pull-dial .pg-draw-arc { stroke: #8fd0ff; }
.pull-play[data-draw="up"] .pull-dial .pg-draw-arc { stroke: #ffb27c; }
/* 止めたらどこへ行くか（温度計の点線と同じ予告を、針のそばにも） */
.pull-current-zone .pull-destination { display: block; min-height: 1.3em; font-size: 14px; font-weight: 700; line-height: 1.3; white-space: nowrap; color: #efe6f7; }
/* 吸っている間・結果の間は文字を消すが、行の高さは残す（札の大きさが変わって上下に跳ねないように） */
.pull-current-zone .pull-destination:empty { visibility: hidden; }
.pull-current-zone .pull-destination[data-tone="optimal"] { color: #ffe7a6; text-shadow: 0 0 8px #ffd46a88; }
.pull-current-zone .pull-destination[data-tone="ok"] { color: #a8f0b4; }
.pull-current-zone .pull-destination[data-tone="hot"] { color: #ffb88a; }
.pull-current-zone .pull-destination[data-tone="danger"] { color: #ff7a6a; }
.pull-current-zone .pull-destination[data-tone="cool"], .pull-current-zone .pull-destination[data-tone="cold"] { color: #a9d6ff; }
.pull-current-zone .pull-destination[data-tone="attack"] { color: #ff8fce; } /* 桜井式の攻めの帯（SKR04） */
/* CRN10: 蒸らしの集中の札 */
html .bench[data-mode] .pull-tag.focus[data-tone="calm"] { color: #d9f6ff; border-color: #8fd0ff99; background: #2a4a6a55; }
html .bench[data-mode] .pull-tag.focus[data-tone="rush"] { color: #ffd2b8; border-color: #ff9a6a99; background: #6a2a2a55; }
@media (prefers-reduced-motion: reduce) {
  .pull-play[data-stopped] .pg-needle, .pull-play[data-stopped] .pg-just { animation: none !important; }
}

/* ---------- CRN09: 取り頃の窓が開く直前の構え（一度だけ瞬く） ---------- */
.coal.ready-cue .coal-corners { animation: coal-ready-cue .3s ease-out 1; }
@keyframes coal-ready-cue { 0% { border-color: #fff3bf; filter: drop-shadow(0 0 5px #ffb45c); } 100% { filter: none; } }
/* 炭焼きの判定文字も、出た瞬間だけ明るく光らせる（大きさと場所は変えない。札の幅に収まったまま） */
.heat-feedback .stamp { animation: heat-stamp-in .22s ease-out !important; }
@keyframes heat-stamp-in { from { filter: brightness(2.2) drop-shadow(0 0 6px #ffd27a); } }
@media (prefers-reduced-motion: reduce) { .coal.ready-cue .coal-corners, .heat-feedback .stamp { animation: none !important; } }

/* ---------- 桜井版（リニューアル前の作業台・CRN16）: 作業台の data-craft-version="sakurai" で、リニューアルの見た目を前に戻す ----------
   穴の大きさと縁（CRN05）・炭の判定文字の光り（CRN09）。吸い出しの光り・行き先・弧、穴のそばの判定、炭の構えは、桜井版では JS が出さない。
   片方の版に決めたら、このまとまりごと消す（リニューアルを残すとき）か、上のリニューアルの規則を前の値へ戻す（桜井版を残すとき）。 */
.bench[data-craft-version="sakurai"] .foil-hole { width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; background: radial-gradient(ellipse at 65% 25%, #060509 45%, #34313a 75%, #89828b); box-shadow: -1px 1px 1px 1px #f6f0debd, 1px -1px 2px 2px #332f386b; animation: hole-pop-classic .2s var(--ease-out); }
.bench[data-craft-version="sakurai"] .foil-hole::after { top: 4px; }
.bench[data-craft-version="sakurai"] :is(.foil-hole.perfect, .foil-hole.good) { box-shadow: -1px 1px 1px 1px #f6f0debd, 1px -1px 2px 2px #332f386b; }
.bench[data-craft-version="sakurai"] .foil-hole.shallow { width: 5px; height: 5px; margin: -2.5px 0 0 -2.5px; opacity: .75; box-shadow: -1px 1px 1px 1px #f6f0debd, 1px -1px 2px 2px #332f386b; }
.bench[data-craft-version="sakurai"] .foil-hole.wide { width: 12px; height: 12px; margin: -6px 0 0 -6px; }
.bench[data-craft-version="sakurai"] .foil-hole.large { width: 15px; height: 15px; margin: -7.5px 0 0 -7.5px; }
@keyframes hole-pop-classic { from { transform: scale(2); } }
.bench[data-craft-version="sakurai"] .heat-feedback .stamp { animation: none !important; }

/* ===== css/craft-rank.css ===== */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
/* 制作画面と表示確認ページで共有するランク表示。 */
.bench-top > .craft-rank {
  position: relative; flex: 0 0 220px; width: 220px; height: 56px; min-width: 0;
  --rank-color: #e3bd6e; --rank-glow: transparent; color: var(--rank-color); isolation: isolate; pointer-events: none; user-select: none;
}
.craft-rank-caption { position: absolute; top: 0; left: 2px; font-size: 12px; font-weight: 700; line-height: 12px; letter-spacing: .02em; color: #c9a7e6; }
.craft-rank-wide, .craft-rank-compact { position: absolute; inset: 12px 0 4px; min-width: 0; }
.craft-rank-compact { display: none; }
.craft-rank-fallback { display: flex; align-items: baseline; gap: 8px; height: 100%; overflow: hidden; }
.craft-rank-grade { font-family: Georgia, serif; font-size: 40px; font-style: italic; font-weight: 700; line-height: 1; white-space: nowrap; letter-spacing: .04em; color: var(--rank-color); text-shadow: 0 1px 0 #302334, 0 0 5px var(--rank-glow); }
.craft-rank-fallback small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; color: #ffe7a2; }
.craft-rank :is(.craft-rank-wide, .craft-rank-compact) > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; object-position: left center; opacity: 0; }
.craft-rank [data-art-ready="true"] > img { opacity: 1; }
.craft-rank [data-art-ready="true"] > .craft-rank-fallback { visibility: hidden; }
.craft-rank[data-grade="unavailable"] .craft-rank-grade { color: #c9a7e6; text-shadow: none; }
.craft-rank-meter { position: absolute; left: 2px; right: 8px; bottom: 0; height: 4px; overflow: hidden; background: #352841; outline: 1px solid #a38baf; border-radius: 2px; }
.craft-rank-meter[hidden] { display: none; }
.craft-rank-meter i { display: block; height: 100%; background: var(--rank-color); }
.craft-rank[data-emphasis="s"] { --rank-color: #ffe09a; --rank-glow: #e3bd6e40; }
.craft-rank[data-emphasis="ss"] { --rank-color: #ffeab5; --rank-glow: #e3bd6e70; }
.craft-rank[data-emphasis="sss"] { --rank-color: #fff3d6; --rank-glow: #e3bd6e99; }
/* A static double edge distinguishes the maximum even without colour or motion. */
.craft-rank[data-maxed="true"] .craft-rank-meter { outline: 3px double var(--rank-color); }
.craft-rank-status { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.craft-rank :is(.craft-rank-wide, .craft-rank-compact) { transform-origin: left center; }
.craft-rank[data-change="enter"] :is(.craft-rank-wide, .craft-rank-compact) { animation: craft-rank-enter .24s ease-out; }
.craft-rank[data-change="up"] :is(.craft-rank-wide, .craft-rank-compact) { animation: craft-rank-up .36s ease-out; }
.craft-rank[data-change="down"] :is(.craft-rank-wide, .craft-rank-compact) { animation: craft-rank-down .15s ease-out; }
@keyframes craft-rank-enter { from { opacity: .8; transform: translateY(3px); } to { opacity: 1; transform: none; } }
@keyframes craft-rank-up { from { transform: scale(.94); } 55% { transform: scale(1.03); } to { transform: none; } }
@keyframes craft-rank-down { from { opacity: .9; } to { opacity: 1; } }
.bench:is([data-help-paused="true"], [data-demo-paused]) .craft-rank * { animation-play-state: paused; }
/* 通常横持ちは固定舞台の倍率を維持し、読めない全文だけ略形に切替える。 */
@media (orientation: landscape) and (max-width: 1024px) and (max-height: 520px) and (pointer: coarse) and (hover: none) {
  body:not(:root) .craft-rank-caption, body:not(:root) .craft-rank-wide { display: none; }
  body:not(:root) .craft-rank-compact { display: block; inset: 0 0 5px; }
  body:not(:root) .craft-rank-compact .craft-rank-grade { font-size: min(56px, calc(28px / var(--k, 1))); }
}
/* 先の番号と済み✓は残す。補助の工程絵だけ省き、現在工程名を守る。 */
@media (prefers-reduced-motion: reduce) { .craft-rank *, .craft-rank[data-change] * { animation: none !important; transition: none !important; } }

/* 本編ではモードと案内を二行で残し、ランクを隣へ併設する。 */
body:not(:root) .bench-top:has(> .craft-rank):has(> .bench-mode) { gap: 12px; }
body:not(:root) .bench-top:has(> .craft-rank) > .bench-mode { width: 160px; letter-spacing: .02em; }
body:not(:root) .bench-top:has(> .craft-rank) > .bench-mode small {
  display: block; margin: 4px 0 0; padding: 0; border: 0; line-height: normal;
}
body:not(:root) .bench-top:has(> .bench-mode) > .craft-rank { flex-basis: 100px; width: 100px; }

/* ランクが変わった瞬間（CSL10）: 舞台の中央に補助名まで読める大きさで出し、帯のランクの位置へ縮めて収める。
   位置と大きさは session.js が --to-x / --to-y / --to-s で渡す。動きを減らす設定・自動操作では出さない。 */
.craft-rank-burst {
  position: absolute; left: 0; top: 0; z-index: 30; width: 420px; height: auto; max-height: 340px; object-fit: contain; pointer-events: none;
  --from-x: 640px; --from-y: 330px; translate: var(--from-x) var(--from-y); transform: translate(-50%, -50%) scale(.6); opacity: 0; filter: drop-shadow(0 10px 30px #000c);
  animation: craft-rank-burst 2.1s cubic-bezier(.2, .8, .2, 1) forwards;
}
body.craft-stage .craft-rank-burst { --from-x: 837px; --from-y: 330px; }
@keyframes craft-rank-burst {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.6); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
  20% { transform: translate(-50%, -50%) scale(1); }
  62% { opacity: 1; translate: var(--from-x) var(--from-y); transform: translate(-50%, -50%) scale(1); }
  100% { opacity: .9; translate: var(--to-x) var(--to-y); transform: translate(-50%, -50%) scale(var(--to-s)); }
}
@media (prefers-reduced-motion: reduce) { .craft-rank-burst { display: none; } }
.craft-rank :is(.craft-rank-wide, .craft-rank-compact) > img { filter: drop-shadow(0 2px 6px #000a); }

/* ===== css/reel.css ===== */
/* ============================================================
   MOKUMOKUパッキー（日常スロット）— マップ左下のミニ筐体
   見た目は旧版 web/css/reel.css を踏襲（ランプ・光条・レバー・溜め・カットイン）
   ============================================================ */
.reel-widget {
  --slot-scale: 1;
  position: absolute;
  left: 16px;
  bottom: 14px;
  width: 136px;
  z-index: 5;
  pointer-events: none; /* 普段は飾り。ランプだけ押せる */
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.55));
  transition: transform 0.25s;
}
.reel-widget.lamp-lit { transform: scale(1.06); }
.reel-widget.gakkun .rw-machine { animation: rw-gakkun 0.4s; }
@keyframes rw-gakkun {
  30% { transform: translateY(3px) rotate(-0.8deg); }
  55% { transform: translateY(-2px) rotate(0.6deg); }
}
/* ランプ・枠・レバー・プレートは共通寸法。拡大時はコマの高さと同じ倍率で描く。 */
.rw-lamp-wrap { position: relative; width: calc(50px * var(--slot-scale)); margin: 0 auto calc(-8px * var(--slot-scale)); z-index: 2; }
.rw-lamp {
  position: relative;
  display: block;
  width: calc(50px * var(--slot-scale));
  height: calc(50px * var(--slot-scale));
  padding: 0;
  overflow: hidden;
  border-radius: 50%;
  border: calc(2px * var(--slot-scale)) solid rgba(244, 210, 122, 0.55);
  background: radial-gradient(circle at 35% 30%, #3a3242, #17131d 70%);
  pointer-events: auto;
  cursor: pointer;
}
/* 小筐体で押せるのはランプだけ。見た目は 50px のまま、押せる範囲を実寸 44px 以上へ広げる（#2840） */
.reel-widget .rw-lamp-wrap { pointer-events: auto; cursor: pointer; }
.reel-widget .rw-lamp-wrap::after {
  content: "";
  position: absolute;
  z-index: -1; /* ランプ本体より下。ランプを直接押したときはボタンが受ける */
  inset: calc((50px * var(--slot-scale) - max(50px * var(--slot-scale), 44px / var(--k, 1))) / 2);
  border-radius: 50%;
}
.rw-face { display: block; width: 100%; height: 100%; object-fit: contain; image-rendering: pixelated; }
.rw-face.txt { display: grid; place-items: center; color: var(--gold); font-weight: 800; font-size: calc(20px * var(--slot-scale, 1)); }
.rw-lamp .rw-face { opacity: 0.5; transition: opacity 0.2s; }
.rw-lamp.lit { border-color: #ffe27a; animation: rw-peka 0.55s infinite alternate, rw-peka-pop 0.5s cubic-bezier(0.2, 2.4, 0.4, 1); }
.rw-lamp.lit .rw-face { opacity: 1; }
.reel-widget.lamp-premium .rw-lamp.lit { animation: rw-peka-rainbow 0.7s infinite; }
@keyframes rw-peka {
  from { box-shadow: 0 0 8px 2px rgba(255, 220, 90, 0.75), 0 0 30px 8px rgba(255, 160, 60, 0.45); background: radial-gradient(circle at 35% 30%, #ffdf7e, #c98a2a 75%); }
  to { box-shadow: 0 0 16px 6px rgba(255, 235, 140, 0.95), 0 0 46px 16px rgba(255, 170, 70, 0.6); background: radial-gradient(circle at 35% 30%, #fff3c0, #e8a93e 75%); }
}
@keyframes rw-peka-rainbow {
  0%, 100% { box-shadow: 0 0 14px 5px rgba(255, 110, 110, 0.9); background: radial-gradient(circle at 35% 30%, #ffd2d2, #d2604f 75%); }
  33% { box-shadow: 0 0 14px 5px rgba(120, 200, 255, 0.9); background: radial-gradient(circle at 35% 30%, #d3ecff, #4f86d2 75%); }
  66% { box-shadow: 0 0 14px 5px rgba(160, 255, 150, 0.9); background: radial-gradient(circle at 35% 30%, #e0ffd8, #58b35a 75%); }
}
@keyframes rw-peka-pop { 0% { transform: scale(0.72); } 55% { transform: scale(1.22); } 100% { transform: scale(1); } }
/* GOGOランプ風の光条 */
.rw-lamp-rays {
  position: absolute;
  inset: calc(-15px * var(--slot-scale));
  border-radius: 50%;
  background: repeating-conic-gradient(rgba(255, 226, 122, 0.9) 0deg 7deg, transparent 7deg 30deg);
  -webkit-mask: radial-gradient(circle, transparent 44%, #000 45%, #000 72%, transparent 73%);
  mask: radial-gradient(circle, transparent 44%, #000 45%, #000 72%, transparent 73%);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s;
}
.reel-widget.lamp-lit .rw-lamp-rays, .rc-machine.lamp-lit .rw-lamp-rays { opacity: 1; animation: rw-rays 1.7s linear infinite; }
.reel-widget.lamp-premium .rw-lamp-rays {
  background: repeating-conic-gradient(rgba(255, 140, 200, 0.9) 0deg 7deg, rgba(120, 205, 255, 0.9) 7deg 14deg, rgba(160, 255, 150, 0.9) 14deg 21deg, transparent 21deg 30deg);
}
@keyframes rw-rays { to { transform: rotate(360deg); } }
/* 天井が近いときのほんのり予熱（数値は出さない・気配だけ） */
.reel-widget.warm .rw-lamp { border-color: rgba(255, 196, 100, 0.85); animation: rw-warm 2.4s ease-in-out infinite; }
@keyframes rw-warm { 50% { box-shadow: 0 0 15px rgba(255, 175, 65, 0.5); } }

.rw-machine {
  position: relative;
  display: flex;
  justify-content: center;
  gap: calc(3px * var(--slot-scale));
  padding: calc(10px * var(--slot-scale)) calc(6px * var(--slot-scale)) calc(6px * var(--slot-scale));
  background: linear-gradient(180deg, #2c2433, #16121c);
  border: calc(2px * var(--slot-scale)) solid rgba(244, 210, 122, 0.5);
  border-radius: calc(10px * var(--slot-scale));
}
.rw-reel, .rc-reel {
  position: relative;
  width: calc(36px * var(--slot-scale));
  height: calc(78px * var(--slot-scale)); /* 3コマ窓 */
  overflow: hidden;
  background: linear-gradient(180deg, #d9d4cc, #fbf8f2 30%, #fbf8f2 70%, #d9d4cc);
  /* 3コマの高さを枠線で削らない。下段も上段と同じ余白を保つ。 */
  border: 0;
  box-shadow: inset 0 0 0 calc(1px * var(--slot-scale)) rgba(255, 255, 255, 0.12);
  border-radius: calc(4px * var(--slot-scale));
}
.rw-reel::after, .rc-reel::after { /* 中段ライン */
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: calc(26px * var(--slot-scale));
  height: calc(26px * var(--slot-scale));
  border-top: calc(1px * var(--slot-scale)) solid rgba(244, 210, 122, 0.25);
  border-bottom: calc(1px * var(--slot-scale)) solid rgba(244, 210, 122, 0.25);
  pointer-events: none;
}
.reel-widget.win-flash .rw-reel::after, .rc-machine.lamp-lit .rc-reel::after { border-color: rgba(255, 232, 140, 0.95); box-shadow: 0 0 10px rgba(255, 212, 90, 0.6); }
.rw-strip { will-change: transform; }
.rw-strip.spinning { animation: rw-spin 0.28s linear infinite; filter: blur(1.2px); }
/* ボーナス中は拡大盤を描画元にする。小筐体自身の回転・着地補間は重ねない。 */
.rw-strip.mirrored { transition: none; }
.rw-strip.mirrored.spinning { animation: none; }
.reel-widget.silent-spin .rw-strip.spinning { animation-duration: 0.55s; filter: blur(0.6px); }
.rw-strip.frozen { animation-play-state: paused; filter: blur(0.8px) brightness(1.4); }
.rw-strip.land { transition: transform 0.12s cubic-bezier(0.2, 1.6, 0.4, 1); }
/* 下向きに回る（実機と同じ）。--loop＝1周ぶんの高さ（JS がコマ数から入れる） */
@keyframes rw-spin { from { transform: translateY(var(--loop)); } to { transform: translateY(0); } }
.rw-cell, .rc-cellr { height: calc(26px * var(--slot-scale)); display: grid; place-items: center; }
.sym {
  /* 等分セルの中心ではなく、絵の輪郭＋4pxの透過余白を中心に置く。 */
  --symbol-size: 22px;
  --art-scale: calc(var(--symbol-size) * var(--slot-scale) / var(--sprite-max));
  display: block;
  width: calc(var(--sprite-width) * var(--art-scale));
  height: calc(var(--sprite-height) * var(--art-scale));
  background-image: url("../img/ui/pakki-slot/symbols.webp");
  background-size: calc(1254 * var(--art-scale)) calc(1254 * var(--art-scale));
  background-position: calc(-1 * var(--sprite-x) * var(--art-scale)) calc(-1 * var(--sprite-y) * var(--art-scale));
  background-repeat: no-repeat;
}
.sym-seven, .sym-bar, .sym-smoke, .sym-pakki {
  background-image: url("../img/ui/pakki-slot/symbols-premium.webp");
}
/* 横長の7とBARも、輪郭＋透過余白の縦横比を保ってコマ内へ置く。 */
.sym-seven { --symbol-size: 28px; --sprite-x: 73; --sprite-y: 241; --sprite-width: 508; --sprite-height: 287; --sprite-max: 508; }
.sym-bar { --symbol-size: 26px; --sprite-x: 677; --sprite-y: 270; --sprite-width: 518; --sprite-height: 245; --sprite-max: 518; }
.sym-bell { --sprite-x: 856; --sprite-y: 51; --sprite-width: 349; --sprite-height: 368; --sprite-max: 368; }
.sym-cherry { --symbol-size: 21px; --sprite-x: 46; --sprite-y: 478; --sprite-width: 375; --sprite-height: 349; --sprite-max: 375; }
.sym-replay { --sprite-x: 484; --sprite-y: 469; --sprite-width: 283; --sprite-height: 361; --sprite-max: 361; }
/* ブランクの炭は小さく薄く。小筐体・拡大盤とも当たり図柄を引き立てる。 */
.sym-smoke { --symbol-size: 17px; --sprite-x: 95; --sprite-y: 787; --sprite-width: 454; --sprite-height: 346; --sprite-max: 454; opacity: 0.54; filter: grayscale(1); }
.sym-pakki { --symbol-size: 23px; --sprite-x: 706; --sprite-y: 729; --sprite-width: 473; --sprite-height: 430; --sprite-max: 473; }
/* 生成した透過ベゼルを、小筐体と拡大盤のどちらにも同じ比率で重ねる。 */
.rw-machine::before {
  content: "";
  position: absolute;
  inset: calc(-2px * var(--slot-scale));
  z-index: 2;
  background: url("../img/ui/pakki-slot/bezel.webp") center / 100% 100% no-repeat;
  pointer-events: none;
}
.reel-widget.flash-blue .rw-machine { animation: rw-flash-blue 0.35s; }
@keyframes rw-flash-blue { 40% { box-shadow: 0 0 18px 6px rgba(80, 170, 255, 0.8) inset, 0 0 14px 4px rgba(80, 170, 255, 0.6); } }
/* レバーアーム（回すたびにカチッと倒れる） */
.rw-lever-arm { position: absolute; right: calc(-10px * var(--slot-scale)); bottom: calc(14px * var(--slot-scale)); width: calc(12px * var(--slot-scale)); height: calc(32px * var(--slot-scale)); transform-origin: 15% 92%; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.5)); }
.rw-lever-arm::before { content: ""; position: absolute; left: calc(3px * var(--slot-scale)); top: calc(7px * var(--slot-scale)); width: calc(4px * var(--slot-scale)); height: calc(24px * var(--slot-scale)); border-radius: calc(2px * var(--slot-scale)); background: linear-gradient(180deg, #969cb0, #4c5060); }
.rw-lever-arm::after { content: ""; position: absolute; left: 0; top: 0; width: calc(12px * var(--slot-scale)); height: calc(12px * var(--slot-scale)); border-radius: 50%; background: radial-gradient(circle at 35% 30%, #ff9d9d, #b02222 72%); box-shadow: inset 0 -2px 3px rgba(0, 0, 0, 0.45); }
.rw-lever-pivot { position: absolute; left: calc(-1px * var(--slot-scale)); bottom: calc(-1px * var(--slot-scale)); width: calc(8px * var(--slot-scale)); height: calc(8px * var(--slot-scale)); border: calc(1px * var(--slot-scale)) solid #b5a578; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #c2bbce, #484050 75%); }
.reel-widget.lever-pull .rw-lever-arm, .rc-machine.lever-pull .rw-lever-arm { animation: rw-lever 0.36s ease-out; }
@keyframes rw-lever { 35% { transform: rotate(44deg); } }
/* 第3リールの溜め（2つ止まって、残り1つ……） */
.reel-widget.tension .rw-machine { border-color: rgba(255, 222, 120, 0.9); animation: rw-tension 0.12s linear infinite; }
@keyframes rw-tension { 25% { transform: translate(0.7px, -0.4px); } 75% { transform: translate(-0.7px, 0.4px); } }
.reel-widget.bonus-pop .rw-machine { animation: rw-bonus-pop 0.6s cubic-bezier(0.2, 2, 0.4, 1); }
@keyframes rw-bonus-pop { 40% { transform: scale(1.09); } }

/* パッキーの吹き出し */
.rw-bubble {
  position: absolute;
  left: 0;
  bottom: calc(100% + 8px);
  width: max-content;
  max-width: 320px;
  padding: 4px 12px;
  /* 文字は 20px。スマホ横持ちで舞台が縮む（--k）ときも実寸 11.5px を下回らない（#2840） */
  font-size: max(20px, 11.5px / var(--k, 1));
  font-weight: 700;
  line-height: 1.45;
  color: #221a2c;
  background: #fff;
  border-radius: 10px;
  opacity: 0;
  transform: scale(0.7);
  transform-origin: 60px 100%;
  transition: opacity 0.18s, transform 0.18s;
}
.rw-bubble::after { content: ""; position: absolute; left: 60px; bottom: -5px; margin-left: -4px; border: 5px solid transparent; border-top-color: #fff; border-bottom: none; }
.rw-bubble.show { opacity: 1; transform: scale(1); }
.rw-bubble.hot { color: #fff; background: #ff3d3d; box-shadow: 0 0 12px rgba(255, 90, 90, 0.85); }
.rw-bubble.hot::after { border-top-color: #ff3d3d; }
/* 文字色予告（#621・#639）: 黒地に色文字。青＜緑＜赤の3色 */
.rw-bubble.cue { background: #120e18; border: 1px solid rgba(255, 255, 255, 0.28); font-size: max(21px, 12px / var(--k, 1)); font-weight: 800; letter-spacing: 0.04em; }
.rw-bubble.cue::after { border-top-color: #120e18; }
.rw-bubble.cue-blue { color: #5cb2ff; text-shadow: 0 0 6px rgba(70, 150, 255, 0.7); }
.rw-bubble.cue-green { color: #4fe07a; text-shadow: 0 0 6px rgba(60, 220, 110, 0.7); }
.rw-bubble.cue-red { color: #ff4040; text-shadow: 0 0 8px rgba(255, 50, 50, 0.85); animation: rw-cue-pulse 0.5s ease-in-out infinite alternate; }
@keyframes rw-cue-pulse { to { transform: scale(1.06); } }
/* 予告の次ゲーム: 枠がその色でうっすら光る（保留の色のような余韻） */
.reel-widget.cued .rw-machine { transition: border-color 0.2s, box-shadow 0.2s; }
.reel-widget.cued-blue .rw-machine { border-color: #5cb2ff; box-shadow: 0 0 10px 2px rgba(92, 178, 255, 0.6); }
.reel-widget.cued-green .rw-machine { border-color: #4fe07a; box-shadow: 0 0 10px 2px rgba(79, 224, 122, 0.6); }
.reel-widget.cued-red .rw-machine { border-color: #ff4040; box-shadow: 0 0 12px 3px rgba(255, 64, 64, 0.7); }
/* 設定変更（観音堂のあと）: 白く光って一筋の光が走る。虹は当たり専用なので使わない */
.rw-bubble.setting { color: #1b2a3a; background: #e9f7ff; box-shadow: 0 0 12px rgba(160, 225, 255, 0.9); }
.rw-bubble.setting::after { border-top-color: #e9f7ff; }
.reel-widget.setting-change .rw-machine { border-color: #bfeaff; box-shadow: 0 0 14px 4px rgba(170, 230, 255, 0.8); animation: rw-setting-glow 0.6s ease-in-out 3 alternate; overflow: hidden; }
.reel-widget.setting-change .rw-machine::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: linear-gradient(110deg, transparent 30%, rgba(255, 255, 255, 0.85) 48%, transparent 66%) -150% 0 / 200% 100% no-repeat;
  animation: rw-setting-sweep 1.1s ease-out 2;
}
.reel-widget.setting-change .rw-lamp { border-color: #bfeaff; box-shadow: 0 0 14px 4px rgba(170, 230, 255, 0.8); }
@keyframes rw-setting-glow { to { box-shadow: 0 0 24px 8px rgba(200, 240, 255, 1); } }
@keyframes rw-setting-sweep { to { background-position: 250% 0; } }
@media (prefers-reduced-motion: reduce) {
  .rw-bubble.cue-red,
  .reel-widget.setting-change .rw-machine, .reel-widget.setting-change .rw-machine::before { animation: none; }
}

/* ---- カットイン（ボーナス揃え／フリーズ）。操作を邪魔しない自走演出 ---- */
.reel-cutin { position: absolute; inset: 0; pointer-events: none; animation: rc-fade 0.25s; }
.reel-cutin.bonus { background: rgba(8, 4, 12, 0.5); }
.reel-cutin.freeze { background: rgba(2, 2, 6, 0.92); }
@keyframes rc-fade { from { opacity: 0; } }
.reel-cutin.out { opacity: 0; transition: opacity 0.25s; }
.rc-board {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}
.rc-machine { position: relative; width: calc(136px * var(--slot-scale)); filter: drop-shadow(0 8px 20px rgba(0, 0, 0, 0.65)); }
.rc-lamp { pointer-events: none; cursor: default; }
.rc-aim { min-height: 32px; margin-bottom: 48px; font-size: max(22px, 11.5px / var(--k, 1)); line-height: 1.5; font-weight: 700; letter-spacing: 0.06em; color: #ffd95e; }
/* 揃え用の大きなリール（窓は3コマ・中段にライン） */
.rc-reels { transition: box-shadow 0.3s, border-color 0.3s; }
.rc-strip { will-change: transform; }
.rc-strip.spinning { animation: rw-spin 0.32s linear infinite; filter: blur(1.6px); }
.rc-strip.land { transition: transform 0.14s cubic-bezier(0.2, 1.6, 0.4, 1); }
/* 7・7 と止まって、最後の1リールを待つ間 */
.rc-board.reach .rc-reels { border-color: #ffe27a; animation: rc-reach 0.5s ease-in-out infinite alternate; }
@keyframes rc-reach { from { box-shadow: 0 10px 40px rgba(0, 0, 0, 0.7), 0 0 10px rgba(255, 210, 90, 0.35); } to { box-shadow: 0 10px 40px rgba(0, 0, 0, 0.7), 0 0 34px rgba(255, 210, 90, 0.85); } }
.rc-label { margin-top: 12px; font-size: 30px; font-weight: 900; letter-spacing: 0.14em; color: rgba(255, 255, 255, 0.22); transition: color 0.2s, text-shadow 0.2s; }
.rc-board.done.big .rc-reels { border-color: #ffe27a; box-shadow: 0 10px 40px rgba(0, 0, 0, 0.7), 0 0 50px rgba(255, 200, 80, 0.8); }
.rc-board.done.big .rc-label { color: #ffd95e; text-shadow: 0 0 18px rgba(255, 170, 60, 0.9); animation: rc-title 0.35s cubic-bezier(0.2, 1.6, 0.4, 1); }
.rc-board.done.reg .rc-reels { border-color: #9fd8ff; box-shadow: 0 10px 40px rgba(0, 0, 0, 0.7), 0 0 36px rgba(110, 190, 255, 0.6); }
.rc-board.done.reg .rc-label { color: #bfe6ff; text-shadow: 0 0 14px rgba(110, 190, 255, 0.8); animation: rc-title 0.35s cubic-bezier(0.2, 1.6, 0.4, 1); }
.rc-board.done.reg .rc-aim { color: #bfe6ff; }
.rc-freeze { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; overflow: hidden; }
.rc-glitch {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, transparent 0 7px, rgba(90, 220, 255, 0.16) 7px 9px, transparent 9px 13px, rgba(255, 80, 200, 0.12) 13px 14px);
  mix-blend-mode: screen;
  animation: rc-glitch 0.18s steps(2) infinite;
}
@keyframes rc-glitch { 50% { transform: translate(3px, -6px); filter: hue-rotate(80deg); } 100% { transform: translate(-2px, 4px); } }
.rc-freeze-text { text-align: center; font-family: var(--font); color: #7de8ff; animation: rc-flicker 0.6s steps(3) infinite; }
.rc-freeze-text b { display: block; font-size: 54px; letter-spacing: 0.3em; text-shadow: 0 0 18px rgba(80, 210, 255, 0.9); }
.rc-freeze-text span { display: block; margin-top: 8px; font-size: max(15px, 11.5px / var(--k, 1)); letter-spacing: 0.04em; color: #b9f3ff; }
@keyframes rc-flicker { 45% { opacity: 0.45; } 55% { opacity: 0.9; } }
.rc-freeze.boom { animation: rc-shake 0.5s; }
@keyframes rc-shake { 20% { transform: translate(-7px, 4px); } 40% { transform: translate(6px, -5px); } 60% { transform: translate(-4px, -3px); } 80% { transform: translate(3px, 5px); } }
.rc-freeze-label { font-family: var(--font); font-size: 72px; letter-spacing: 0.1em; color: #fff; text-shadow: 0 0 26px rgba(255, 210, 90, 1), 0 0 70px rgba(255, 120, 40, 0.8); animation: rc-title 0.35s cubic-bezier(0.2, 1.6, 0.4, 1); }
@keyframes rc-title { from { transform: scale(2.4); opacity: 0; } }
.rc-dance { display: flex; gap: 18px; }
.rc-dance .rw-face.big { width: 64px; height: 64px; animation: rc-dance 0.45s infinite alternate; }
.rc-dance .rw-face.big:nth-child(2) { animation-delay: 0.15s; }
.rc-dance .rw-face.big:nth-child(3) { animation-delay: 0.3s; }
@keyframes rc-dance { from { transform: translateY(0) rotate(-8deg); } to { transform: translateY(-16px) rotate(8deg); } }
.rc-freeze-sub { font-size: 22px; font-weight: 700; letter-spacing: 0.15em; color: #ffd95e; }

/* ---- 初回のみ: パッキーのアプリ説明 ---- */
.reel-intro { position: absolute; inset: 0; background: rgba(6, 4, 10, 0.72); cursor: pointer; animation: rc-fade 0.25s; }
.ri-panel {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 760px;
  padding: 30px 36px 24px;
  background: linear-gradient(180deg, rgba(42, 32, 56, 0.97), rgba(20, 15, 30, 0.97));
  border: 2px solid rgba(244, 210, 122, 0.6);
  border-radius: 14px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.7);
}
.ri-head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.ri-head .rw-face.big { width: 46px; height: 46px; }
.ri-app { font-size: 24px; font-weight: 700; letter-spacing: 0.1em; color: var(--gold); }
.ri-text { min-height: 130px; margin: 0; font-size: 26px; line-height: 1.65; color: #f2ecdf; }
.ri-next { display: block; text-align: right; font-size: 20px; color: #cdb8e6; animation: rc-flicker 1.4s infinite; }

/* ---- 夜の行動のあと: その場でスロットを見せる（翌朝に持ち越さない） ---- */
.reel-night {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(4, 3, 10, 0.72), rgba(4, 3, 10, 0.2) 55%, transparent);
  opacity: 0;
  transition: opacity 0.3s;
}
.reel-night.show { opacity: 1; }
.rn-label {
  position: absolute;
  left: 176px;
  bottom: 30px;
  padding: 7px 16px;
  font-size: max(16px, 11.5px / var(--k, 1));
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #cdb8e6;
  background: linear-gradient(160deg, rgba(16, 10, 24, 0.95), rgba(28, 18, 38, 0.95));
  border: 1px solid rgba(205, 184, 230, 0.45);
  border-radius: 4px;
}

/* ---- パッキースロットノート（ランプをタップ） ---- */
.reel-note .rn-panel {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(860px, calc(100% - 32px));
  max-height: calc(100% - 32px);
  overflow-y: auto;
  padding: 24px 30px 18px;
  background: linear-gradient(180deg, rgba(42, 32, 56, 0.97), rgba(20, 15, 30, 0.97));
  border: 2px solid rgba(244, 210, 122, 0.6);
  border-radius: 14px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.7);
  color: #f2ecdf;
}
/* 記録は1段（縦スクロール）。2段に詰めない（#2840） */
.rn-cols { display: grid; grid-template-columns: 1fr; gap: 4px; }
.rn-cols h3, .rn-setting-box h3 { margin: 10px 0 6px; font-size: max(18px, 11.5px / var(--k, 1)); letter-spacing: 0.12em; color: #cdb8e6; }
.rn-table { width: 100%; border-collapse: collapse; font-size: max(20px, 11.5px / var(--k, 1)); }
.rn-table th { text-align: left; font-weight: 700; color: #e7dccb; padding: 4px 0; }
.rn-table td { text-align: right; padding: 4px 0 4px 10px; font-variant-numeric: tabular-nums; }
.rn-table td:last-child { color: var(--gold); }
.rn-table tr + tr { border-top: 1px solid rgba(255, 255, 255, 0.08); }
.rn-history { margin: 0; padding: 0; list-style: none; font-size: max(18px, 11.5px / var(--k, 1)); }
.rn-history li { display: grid; grid-template-columns: minmax(10em, max-content) 4.5em 1fr; align-items: baseline; padding: 2px 0; }
.rn-history b { letter-spacing: 0.06em; }
.rn-history .k-big b, .rn-history .k-premium b { color: #ff6464; }
.rn-history .k-reg b { color: #6cc0ff; }
.rn-history .k-freeze b { color: #ffd75e; }
.rn-history span { text-align: right; padding-right: 12px; font-variant-numeric: tabular-nums; }
.rn-history .rn-ren { display: inline-block; margin-left: 6px; font-size: 1em; font-weight: 900; letter-spacing: 0; }
.rn-history small { color: #a99cbc; }
.rn-hall { margin: 0; padding: 0; list-style: none; font-size: max(18px, 11.5px / var(--k, 1)); color: #ffd75e; }
.rn-empty, .rn-setting { margin: 0; font-size: max(18px, 11.5px / var(--k, 1)); line-height: 1.6; color: #cfc3dd; }
.rn-secret { letter-spacing: 0.04em; color: #a79cc0; }
.rn-guide-list { margin: 6px 0 10px; padding: 0; list-style: none; display: grid; gap: 10px; }
.rn-guide-list li { display: grid; grid-template-columns: 130px 1fr; gap: 12px; font-size: 16px; line-height: 1.6; color: #f2ecdf; }
.rn-guide-list b { color: var(--gold); letter-spacing: 0.06em; }
.ri-panel.sys { border-color: rgba(191, 230, 255, 0.6); }
.ri-panel.sys .ri-app { color: #bfe6ff; }
.rn-hint-head { margin: 8px 0 2px; font-size: max(17px, 11.5px / var(--k, 1)); font-weight: 700; color: #bfe6ff; letter-spacing: .02em; }
.rn-hint-head.past, .rn-hints.past { color: #8f86a0; }
.rn-hints { margin: 4px 0 0; padding: 0; list-style: none; font-size: max(18px, 11.5px / var(--k, 1)); line-height: 1.6; color: #bfe6ff; }
.rn-setting-box { margin-top: 6px; }
@media (max-width: 640px) {
  .reel-note .rn-panel { padding: 16px 16px 12px; }
}

/* ---- 遊び方カード（店に置いてあるラミネートの遊技説明のイメージ・#639） ---- */
.rn-card {
  --slot-scale: 1.25;
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin: 4px 0 8px;
  padding: 10px;
  border-radius: 12px;
  color: #2a2030;
  background: linear-gradient(180deg, #fffaf0, #f2e8d2);
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.85), 0 3px 10px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}
.rn-card::after { /* ラミネートの光沢 */
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(115deg, transparent 40%, rgba(255, 255, 255, 0.18) 46%, transparent 52%);
}
.rn-tile {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas: "head head" "body body";
  align-items: center;
  gap: 2px 8px;
  padding: 6px 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(120, 90, 50, 0.25);
}
.rn-tile.has-art { grid-template-areas: "head head" "art body"; }
.rn-tile-head { grid-area: head; font-size: 15px; font-weight: 900; letter-spacing: 0.04em; color: #b8202a; }
.rn-tile-body { grid-area: body; font-size: 14px; font-weight: 700; line-height: 1.35; color: #2a2030; }
.rn-art { grid-area: art; display: flex; align-items: center; gap: 2px; }
.rn-art.lamp .rw-face { width: 34px; height: 34px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff3c0, #e8a93e 75%); box-shadow: 0 0 10px 3px rgba(255, 200, 80, 0.8); }
.rn-art.syms { padding: 2px 4px; border-radius: 6px; background: #fbf8f2; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.15); }
.rn-sym { display: grid; place-items: center; width: calc(26px * var(--slot-scale)); height: calc(26px * var(--slot-scale)); }
.cue-chip { display: inline-grid; place-items: center; width: 26px; height: 26px; border-radius: 6px; font-style: normal; font-size: 14px; font-weight: 900; background: #120e18; }
.cue-chip.cue-blue { color: #5cb2ff; }
.cue-chip.cue-green { color: #4fe07a; }
.cue-chip.cue-red { color: #ff4040; }
/* ノートの中の遊び方カードは1段にして、スマホ横持ちでも実寸 11.5px を下回らない（#2840）。初回説明のカードは変えない */
.reel-note .ri-app { font-size: max(24px, 12px / var(--k, 1)); }
.reel-note .ri-next { margin-top: 8px; font-size: max(20px, 11.5px / var(--k, 1)); }
.reel-note .rn-card { grid-template-columns: 1fr; }
.reel-note .rn-tile-head { font-size: max(18px, 12px / var(--k, 1)); }
.reel-note .rn-tile-body { font-size: max(17px, 11.5px / var(--k, 1)); }
.reel-note .cue-chip { width: max(26px, 14px / var(--k, 1)); height: max(26px, 14px / var(--k, 1)); font-size: max(14px, 11.5px / var(--k, 1)); }
.ri-panel.sys .ri-text { min-height: 0; }

/* ワイドステージ（#2861）と見やすさ（#2729）:
   - 説明・ノートの暗幕はステージの左右の余白まで覆う（端に出した MENU・LIME を開いている間に押させない）。
   - ワイドではノートを横に広げ、記録（データ｜当たり履歴・フリーズ殿堂入り）を2列にして、スクロールなしで一度に見せる。
     16:9 では #2840 のとおり1列（縦スクロール）のまま。
   - スマホではマップ左下の筐体を一回り大きく（1.2倍・左下を起点に）。押せるランプと吹き出しも同じ倍率で大きくなる。 */
.reel-intro { inset: 0 calc(-1 * var(--stage-gutter, 0px)); }
#stage[data-wide] .reel-note .rn-panel { width: min(1240px, calc(100% - 32px)); }
#stage[data-wide] .reel-note .rn-cols { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: auto 1fr; column-gap: 40px; }
#stage[data-wide] .reel-note .rn-cols > section:first-child { grid-row: 1 / span 2; }
html:root[data-density="phone"] .reel-widget { scale: 1.2; transform-origin: left bottom; }

/* どのページからでも閉じる札（#3555。3回タップしないと閉じられなかった） */
.reel-note .rn-close {
  position: absolute; top: 12px; right: 14px; z-index: 1;
  min-height: 44px; padding: 0 18px;
  border: 1px solid rgba(244, 210, 122, 0.6); border-radius: 999px;
  background: rgba(20, 15, 30, 0.92); color: #f4d27a;
  font: 700 16px/1 var(--font); letter-spacing: 0.08em; cursor: pointer;
}
html:root[data-density="phone"] body:not(:root) .reel-note .rn-close { min-height: var(--phone-tap); font-size: var(--phone-sub); }

/* ===== css/extras.css ===== */
/* ============================================================
   恋人（ステータスの行）・シーシャくじ・ギャラリー
   日常パートの墨×金の語彙に合わせる
   ============================================================ */

/* ---- ステータス: 恋人の行 ---- */
.pp-row.lover { background: linear-gradient(90deg, rgba(244, 143, 177, 0.16), rgba(255, 255, 255, 0.03) 70%); border-left: 3px solid #f48fb1; }
.pp-row.lover .pp-hearts { color: #ff8fb0; }

/* ---- シーシャくじ ---- */
.kuji-note { margin: 0 0 6px; padding: 8px 12px; font-size: 14px; color: var(--gold-hi); background: rgba(244, 210, 122, 0.08); border-left: 3px solid var(--gold); border-radius: 4px; }
.kuji-cat { border-color: #ff9ec4 !important; color: #ffc2da !important; }
/* くじの暗幕・賞の札・連続の結果は css/motions/garagara.css（2026-11-11 にガチャ風の演出へ作り直し） */

/* ---- ギャラリー ---- */
.gal-overlay { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(5, 4, 10, 0.78); backdrop-filter: blur(3px); }
.gal {
  width: 1040px;
  max-height: 640px;
  display: flex;
  flex-direction: column;
  padding: 22px 28px;
  background: linear-gradient(160deg, rgba(16, 10, 24, 0.97), rgba(28, 18, 38, 0.97));
  border: 1px solid rgba(244, 210, 122, 0.55);
  border-radius: 8px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.7);
}
.gal-head { display: flex; flex-wrap: wrap; flex-shrink: 0; align-items: baseline; gap: 8px 16px; margin-bottom: 14px; }
.gal-head h2 { margin: 0; font-family: var(--font); font-size: 28px; letter-spacing: 0.3em; color: var(--gold-hi); }
.gal-count { font-size: 14px; color: var(--text-dim); }
.gal-collection { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; }
.gal-rate, .gal-complete { color: var(--gold-hi); }
.gal-photos { color: var(--text-dim); font-size: 12px; }
.gal-characters { display: flex; flex-wrap: wrap; flex-shrink: 0; gap: 4px 16px; margin-bottom: 12px; font-size: 12px; color: var(--text-dim); }
.gal-close { margin-left: auto; padding: 6px 18px; color: var(--text); background: transparent; border: 1px solid rgba(244, 210, 122, 0.5); border-radius: 4px; cursor: pointer; }
.gal-close:hover { color: var(--gold-hi); border-color: var(--gold); }
.gal-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; overflow-y: auto; padding-right: 6px; }
.gal-cell {
  position: relative;
  aspect-ratio: 16 / 9;
  padding: 0;
  overflow: hidden;
  background: #0b0812;
  border: 1px solid rgba(244, 210, 122, 0.35);
  border-radius: 4px;
  cursor: pointer;
}
.gal-cell img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.3s; }
.gal-cell:hover img { transform: scale(1.05); }
.gal-cell[data-cg="cg_minto_first_cheki"] img { object-fit: contain; padding: 4px; }
.gal-cell[data-cg="cg_minto_first_cheki"]:hover img { transform: none; }
.gal-cell.locked { display: grid; place-items: center; cursor: default; background: repeating-linear-gradient(45deg, #120d1a 0 10px, #17111f 10px 20px); }
.gal-cell.locked span { font-size: 18px; letter-spacing: 0.3em; color: rgba(244, 210, 122, 0.4); }
.gal-empty, .gal-note { margin: 12px 0 0; font-size: 14px; color: var(--text-dim); }
.gal-viewer { position: absolute; inset: 0; display: none; background: #000 center / contain no-repeat; cursor: zoom-out; }
.gal-viewer.show { display: block; animation: kj-fade 0.25s; }
.gal-tabs { display: flex; gap: 6px; flex-shrink: 0; overflow-x: auto; padding: 0 0 12px; }
.gal-tab { flex-shrink: 0; padding: 8px 14px; border: 1px solid #6b536b; border-radius: 5px; background: #191020; color: var(--text-dim); cursor: pointer; }
.gal-tab[aria-selected="true"] { color: var(--gold-hi); border-color: var(--gold-hi); background: #38243e; }
.gal-tab:focus-visible, .gal-viewer button:focus-visible { outline: 2px solid var(--gold-hi); outline-offset: 2px; }
.gal-grid { flex: 1 1 auto; min-height: 0; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: max-content; align-content: start; }
.gal-cell { min-width: 0; width: 100%; align-self: start; }
.gal-empty { grid-column: 1 / -1; padding: 32px 12px; text-align: center; }
.gal-caption { position: absolute; inset: auto 0 0; background: rgba(8, 5, 14, .88); color: #fff4df; font-size: 14px; padding: 6px; }
.gal-cell.locked { align-content: center; gap: 8px; text-align: center; }
.gal-cell.locked small { color: var(--text-dim); font-size: 14px; }
.gal-media-symbol { display: grid; height: 100%; place-items: center; font-size: 26px; color: var(--gold-hi); }
.gal-cell[data-kind="comic"], .gal-cell[data-kind="cheki"], .gal-cell[data-kind="purikura"] { aspect-ratio: 3 / 4; }
.gal-cell[data-kind="comic"] img, .gal-cell[data-kind="cheki"] img, .gal-cell[data-kind="purikura"] img { object-fit: contain; }
.gal-viewer { z-index: 2; background-color: #09070f; cursor: default; }
.gal-viewer.show { display: flex; flex-direction: column; }
/* fx内の遅延通知を、不透明なギャラリービューアより前へ出す。 */
#stage:has(.gal-viewer.show) > #fx:has(> .vn-loading[data-test="module-loading"]) { z-index: 91; }
.gal-viewer-tools { flex-shrink: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px; background: rgba(12, 8, 20, .97); }
.gal-viewer-tools strong { margin-right: auto; color: var(--gold-hi); }
.gal-viewer-tools .btn { min-width: 0; min-height: 38px; padding: 7px 12px; font-size: 14px; }
.gal-viewer-content { flex: 1; min-height: 0; overflow: auto; display: grid; place-items: center; }
.gal-media-image, .gal-movie { display: block; width: 100%; height: 100%; min-height: 0; object-fit: contain; }
.gal-viewer-content > .gal-media-image { max-height: 100%; }
.gal-comic-scroll { width: 100%; height: 100%; overflow: auto; overscroll-behavior: contain; touch-action: pan-x pan-y pinch-zoom; }
.gal-comic-scroll .gal-media-image { width: auto; height: auto; min-width: 0; max-width: 100%; max-height: 100%; margin: auto; object-fit: contain; }
.gal-comic-scroll.zoomed .gal-media-image { width: max(100%, 1086px); max-width: none; max-height: none; }
.gal-media-error { padding: 20px; color: #fff1d9; }
.gal-viewer .purikura-photo { flex-shrink: 0; }
.gal-cell .gal-photo-thumb { width: 100%; height: 100%; margin: 0; border-width: 4px; pointer-events: none; }
.gal-photo-thumb .purikura-person img { width: 190%; top: -6%; }
.gal-photo-thumb .purikura-doodle { font-size: 12px; }
.gal-photo-thumb .purikura-caption { display: none; }
@media (max-width: 600px) {
  .gal-viewer-tools strong { flex-basis: 100%; }
}

/* ===== css/ui-art.css ===== */
/* 生成画像の共通スキン。文字・入力・ゲージ・ハートは従来のDOMのまま。
   パネルは9スライスで角を保ち、会話枠も短いHUDも同じ質感に揃える。 */
:root {
  --art-panel: url("../img/ui/lounge/panel.webp");
  --art-button: url("../img/ui/lounge/button.webp");
  --art-pin: url("../img/ui/lounge/map-pin.webp");
  --art-heart: url("../img/ui/lounge/heart.webp");
  --art-reward: url("../img/ui/lounge/reward-clean.webp");
  --art-gauge-frame: url("../img/ui/lounge/gauge-frame.webp");
  --art-gauge-fill: url("../img/ui/lounge/gauge-fill.webp");
}

.vn-box, .vn-log, .panel, .modal-box,
.ink-panel, .map-info, .map-notice, .map-time,
.hud-card, .hud-level, .hud-menu, .hud-stamina,
.gain-card {
  /* 拡縮時の9スライスの隙間から明るい背景が透けないよう、内側に墨色を敷く。 */
  background: linear-gradient(#0e0913, #0e0913) center / calc(100% - 8px) calc(100% - 8px) no-repeat;
  border: 0 solid transparent;
  border-radius: 0;
  border-image: var(--art-panel) 110 fill / 24px / 0 stretch;
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.3);
  backdrop-filter: none;
}

.vn-box {
  /* 枠の位置と本文幅は固定。既存の改行とタップ範囲を変えない。 */
  padding: 31px 61px 21px;
  border-image-width: 32px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.36);
}
.vn-box::before, .map-info::before, .map-info::after,
.hud-card::before, .hud-card::after, .hud-level::before, .hud-level::after {
  content: none;
}

/* タイトルのメニューには付けない（文字だけの方が広く見える・GUI23） */
.btn, .vn-choice, .vn-ctl, .vn-name, .mi-go, .mi-banner,
.spot-pin .sub-label, .dc-row, .st-tab {
  background: none;
  border: 0 solid transparent;
  border-radius: 0;
  border-image: var(--art-button) 52 110 fill / 9px 22px / 0 stretch;
  color: var(--text);
  box-shadow: none;
  clip-path: none;
}

.btn { padding: 13px 21px; }
.btn.small { padding: 8px 15px; border-image-width: 7px 16px; }
.btn.ghost { background: none; }
.btn.primary, .btn.primary:hover:not(:disabled), .vn-ctl.on, .mi-go, .st-tab.on {
  background: none;
  color: var(--gold-hi);
  filter: brightness(1.3);
}
.btn.primary .btn-desc { color: var(--text-dim); }
.btn:hover:not(:disabled), .btn:focus-visible,
.vn-choice:hover, .vn-choice:focus-visible,
.vn-ctl:hover, .vn-ctl:focus-visible {
  background: none;
  color: var(--gold-hi);
  filter: brightness(1.3);
  box-shadow: none;
}
:is(.btn, .vn-choice, .vn-ctl, .mi-go):focus-visible {
  outline: 2px solid var(--gold-hi);
  outline-offset: 3px;
}
.vn-choice { padding: 17px 31px; border-image-width: 12px 30px; }
.vn-name {
  padding: 8px 28px 9px 24px;
  color: var(--gold-hi);
  border-image-width: 9px 20px;
}
.vn-ctl { padding: 10px 17px; border-image-width: 8px 15px; }
.mi-banner { padding: 5px 15px; color: var(--gold-hi); border-image-width: 6px 12px; }
.mi-go { padding: 10px 1px; }
.mi-go:hover { filter: brightness(1.45); }

.hud-card { width: 300px; flex: none; padding: 10px 15px; border-image-width: 20px; }
.dc-main { flex: 0 0 74px; min-width: 74px; }
.dc-meta { flex: 1; min-width: 0; }
.dc-row { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 8px; width: 100%; min-width: 0; }
.dc-day b, .dc-row b { font-variant-numeric: tabular-nums; }
.dc-row b { text-align: right; white-space: nowrap; }
.dc-row { font-size: 16px; }
.dc-row span { font-size: 13px; letter-spacing: .02em; }
.dc-row.money b { font-size: 20px; line-height: 1.2; }
.hud-stamina { width: max-content; flex: none; }
.hud-stamina > span, .hud-stamina .hud-bar { flex: none; }
.hud-stamina, .hud-menu, .hud-level { border-image-width: 14px; }
.dc-row { padding: 4px 10px; border-image-width: 5px 12px; }
.st-tab { padding: 7px 18px; border-image-width: 7px 14px; }
.status-modal { display: flex; flex-direction: column; overflow: hidden; }
.status-modal > h3, .status-modal .modal-actions { flex: none; }
.status-modal .modal-body { min-height: 0; overflow: auto; }
.status-modal .modal-actions { margin-top: 14px; }
.map-info { padding: 14px 17px 16px; }
.map-time, .map-notice { border-image-width: 12px; }

/* 看板の縁・面・しっぽは生成画像。共通の墨色面に役割別の低彩度アクセントを重ねる。 */
.spot-pin { --pin-from: #343840; --pin-accent: #a7a5ad; }
.pin-rival { --pin-accent: #bfc4cb; }
.pin-baito, .pin-rest { --pin-accent: #d6d0c7; }
.pin-cafe, .pin-park, .pin-gym { --pin-accent: #8d939b; }
.pin-shop { --pin-accent: #b6a393; }
.pin-stadium { --pin-accent: #e5e0da; }
.spot-pin .label { color: var(--pin-accent); }
.spot-pin .shield {
  padding: 10px 16px 12px;
  isolation: isolate;
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.spot-pin .shield::before {
  content: "";
  position: absolute;
  inset: -2px -2px -9px;
  z-index: -1;
  pointer-events: none;
  background-color: var(--pin-from, #b04a8a);
  background-image: var(--art-pin);
  background-size: 100% 100%;
  background-blend-mode: luminosity;
  -webkit-mask: var(--art-pin) center / 100% 100% no-repeat;
  mask: var(--art-pin) center / 100% 100% no-repeat;
}
.spot-pin .shield::after {
  content: "";
  left: 14%;
  right: 14%;
  top: auto;
  bottom: 2px;
  width: auto;
  height: 4px;
  border: 0;
  border-radius: 0;
  transform: none;
  background-color: var(--pin-accent);
  background-image: var(--art-gauge-fill);
  background-size: 100% 100%;
  background-blend-mode: luminosity;
  -webkit-mask: var(--art-gauge-fill) center / 100% 100% no-repeat;
  mask: var(--art-gauge-fill) center / 100% 100% no-repeat;
}
.spot-pin:hover .shield, .spot-pin.sel .shield { box-shadow: none; }
.spot-pin.sel .shield::before { filter: brightness(1.28) drop-shadow(0 0 4px var(--pin-accent)); }
.spot-pin .sub-label { padding: 4px 10px; border-image-width: 5px 12px; }
.spot-pin .sub-label:not(.closed-tag) { color: #fff7e8; background: rgba(28, 17, 43, .94); border: 1px solid rgba(255, 255, 255, .8); border-image: none; border-radius: 8px; font-weight: 700; }
.spot-pin .sub-label.closed-tag { background: none; border: 0; color: #f0b9b9; }

/* ウィンドウ全体を従来の --gc で着色。生成した無彩色素材の明暗・質感を合成し、
   技術=黄 / センス=水色 / 根性=赤橙 / 魅力=紫 / 洞察=青緑を枠と面にも残す。 */
.gain-card {
  isolation: isolate;
  border-image: none;
  padding: 14px 22px 14px 16px;
  box-shadow: none;
}
.gain-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-color: var(--gc);
  background-image: var(--art-reward);
  background-size: 100% 100%;
  background-blend-mode: luminosity;
  -webkit-mask: var(--art-reward) center / 100% 100% no-repeat;
  mask: var(--art-reward) center / 100% 100% no-repeat;
}
/* 元の縁・質感を保ち、煙だけ除いた reward-clean を全通知で使う。 */
.gc-badge { font-family: var(--font); font-weight: 700; box-shadow: none; }
.gc-badge:not(.face), .st-badge {
  background: none;
  border: 0 solid transparent;
  border-radius: 0;
  border-image: var(--art-panel) 110 fill / 7px / 0 stretch;
  color: var(--text);
  font-family: var(--font);
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1;
  padding-bottom: 2px; /* 日本語の字面が枠中央より1px下に見える分を補正 */
  box-shadow: none;
}
.gc-badge:not(.face) { font-size: 21px; }
.st-badge { border-image-width: 5px; font-size: 17px; }
.gc-title { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; }
.gc-points { color: var(--gc); font-size: 22px; font-weight: 700; font-variant-numeric: tabular-nums; white-space: nowrap; }
/* 原素材に近い4:1の比率で金属縁をつぶさず、通常68pxに収める。
   上下10.5pxの余白と47.2pxの文字列（見出し14px×1.2＋間隔1px＋本文21px×1.4）で高さを決める。
   字形が収まる行高を維持し、銘板は44px（PF25）。 */
.gain-card.stat {
  width: 272px;
  min-width: 272px;
  height: 68px;
  box-sizing: border-box;
  gap: 12px;
  padding: 10.5px 20px 10.5px 14px;
  filter: drop-shadow(0 5px 7px rgba(0, 0, 0, 0.55));
}
.gain-card.stat .gc-badge { width: 44px; height: 44px; font-size: 22px; }
.gain-card.stat .gc-meta { flex: 1; min-width: 0; gap: 1px; }
.gain-card.stat .gc-title { gap: 7px; flex-wrap: nowrap; }
.gain-card.stat .gc-main { font-size: 21px; line-height: 1.4; letter-spacing: 0.06em; }
.gain-card.stat .gc-top { font-size: 14px; line-height: 1.2; letter-spacing: 0.04em; opacity: 0.9; }
.gain-card.stat .gc-points { display: flex; align-items: baseline; gap: 1px; line-height: 1; }
.gain-card.stat .gc-earned { font-size: 14px; white-space: nowrap; color: var(--text-dim); }
.gain-card.stat :is(.gc-count, .gc-unit) { font-size: 19px; font-weight: 800; letter-spacing: -0.02em; text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6); }
.gain-card.stat.evolved { width: 272px; min-width: 272px; max-width: 272px; }
.gain-card.stat.evolved .gc-main { font-size: 15px; white-space: nowrap; letter-spacing: 0; }
.gain-card.stat .gc-next { position: absolute; left: 6px; right: 6px; bottom: 3px; display: flex; align-items: center; gap: 6px; color: var(--gc); font-size: 12px; font-weight: 700; line-height: 1; }
.gain-card.stat .gc-next.capped { color: #aaa; }
.gain-card.stat .gc-next i { display: block; flex: 1; height: 2px; background: #ffffff33; }
.gain-card.stat .gc-next b { display: block; height: 100%; background: var(--gc); }
.gain-card.stat .gc-next.capped b { background: #999; }
.gain-card.stat .gc-evolution { font-size: 18px; line-height: 1.4; }
/* スロットの当たりだけ、元の金属枠を一度明るくする。サイズ・出現位置は共通。 */
.gain-card.stat.slot-bonus.show::after { animation: slot-bonus-glow 0.85s ease-out 0.45s; }
@keyframes slot-bonus-glow {
  0%, 100% { filter: brightness(1); }
  35% { filter: brightness(1.65); }
}
@media (prefers-reduced-motion: reduce) {
  .gain-card.stat.slot-bonus::before, .gain-card.stat.slot-bonus.show::after { animation: none; }
}
.stat-flight {
  position: absolute;
  left: -7px;
  top: -7px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff 0 17%, var(--gain-color) 32%, transparent 72%);
  filter: drop-shadow(0 0 5px var(--gain-color));
  pointer-events: none;
}

/* 字形の♥を使わず、同じ生成絵の空・部分・満タンを重ねる。 */
.gc-hearts { gap: 4px; margin-top: 4px; }
.gc-hearts i, .ui-heart { position: relative; display: inline-block; flex: none; width: 18px; height: 18px; }
.gc-hearts i::before, .gc-hearts i::after, .ui-heart::before, .ui-heart::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--art-heart) center / contain no-repeat;
  text-shadow: none;
}
.gc-hearts i::before, .ui-heart::before { filter: grayscale(1) brightness(0.5); opacity: 0.8; }
.gc-hearts i::after, .ui-heart::after {
  clip-path: inset(calc(100% - var(--fill, 0%)) 0 0 0);
  transition: clip-path 0.9s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.bond .ui-heart::after { filter: hue-rotate(70deg) saturate(0.85); }
.heart-row { display: inline-flex; align-items: center; gap: 4px; }
.heart-row .ui-heart { width: 22px; height: 22px; }
.pp-hearts { display: inline-flex; align-items: center; gap: 8px; }
.pp-relation { font-size: 16px; font-weight: 700; letter-spacing: 0.03em; }
.pp-face { flex: none; }
.pp-detail { flex: 1; min-width: 0; }
.pp-heading { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 16px; }
.pp-hearts { flex-wrap: wrap; }
.pp-guide { margin: 0 0 2px; font-size: 16px; line-height: 1.5; color: var(--text-dim); }
/* 直近の思い出（内心）。導線より前に、やわらかい色で前面に出す */
.pp-memory { margin: 2px 0 0; font-size: 15px; line-height: 1.5; color: rgba(255, 255, 255, 0.72); font-style: italic; }
.pp-next { margin: 2px 0 0; font-size: 16px; line-height: 1.5; letter-spacing: 0.02em; color: var(--text-dim); }
.pp-row[data-relation="romance"] .pp-relation { color: #ff9dbd; }
.pp-row[data-relation="friend"] .pp-relation { color: #9fd9ec; }
.pp-row[data-relation="choice"] .pp-relation { color: var(--gold-hi); }

.dodge-heart { background: var(--art-heart) center / contain no-repeat; text-shadow: none; }

/* 枠も中身も生成画像。体力の割合は枠の内側のtrackで正確に表す。 */
.hud-bar, .gc-meter {
  position: relative;
  height: 14px;
  border: 0;
  border-radius: 0;
  background: var(--art-gauge-frame) center / 100% 100% no-repeat;
  overflow: hidden;
}
.gauge-track { position: absolute; inset: 3px 4px; overflow: hidden; }
.hud-bar b, .gc-meter i {
  height: 100%;
  border-radius: 0;
  background: var(--art-gauge-fill) left center / 100% 100% no-repeat;
}
:is(.hud-stamina, .gain-card.stamina, .sleep-recovery) { --stamina-fill: #8ee6a8; }
:is(.hud-stamina, .gain-card.stamina, .sleep-recovery)[data-health="yellow"] { --stamina-fill: #ffd45c; }
:is(.hud-stamina, .gain-card.stamina, .sleep-recovery)[data-health="red"] { --stamina-fill: #ff6969; }
.hud-stamina .hud-bar b, .hud-stamina.low .hud-bar b, .gain-card.stamina .gc-meter i {
  background-color: var(--stamina-fill);
  background-image: var(--art-gauge-fill);
  background-size: 100% 100%;
  background-blend-mode: luminosity;
  -webkit-mask: var(--art-gauge-fill) left center / 100% 100% no-repeat;
  mask: var(--art-gauge-fill) left center / 100% 100% no-repeat;
  filter: none;
}
@media (prefers-reduced-motion: reduce) { .ui-heart::after { transition: none; } }

/* ===== css/ui-inner.css ===== */
/* 外側はラウンジの金縁、内側は墨色と細い真鍮色の線（GUI29〜31）。 */
:root {
  --inner-edge: rgba(232, 194, 122, 0.25);
  --inner-face: rgba(255, 255, 255, 0.035);
  --inner-hover: rgba(232, 194, 122, 0.08);
  --inner-active: rgba(232, 194, 122, 0.13);
}

/* 短い操作は中央へ。説明を添えた行動は見出しと説明の左端を揃える。 */
.btn { align-items: center; justify-content: center; text-align: center; }
.btn:has(.btn-desc) { align-items: flex-start; text-align: left; }
/* 長い一覧は本文をスクロールし、閉じる操作を窓の中に保つ。 */
.modal-box:has(> .modal-body) { display: flex; flex-direction: column; overflow: hidden; }
.modal-box > h3, .modal-box .modal-actions { flex: none; }
.modal-box .modal-body { min-height: 0; overflow: auto; }
.modal-actions { gap: 8px; margin-top: 16px; }
.modal-actions > .btn { min-width: 128px; min-height: 44px; padding: 10px 20px; }

/* 金縁の窓の中で同じ装飾を繰り返さない。外側の窓と単独の選択肢は ui-art.css。 */
:is(.modal-box, .panel, .ink-panel, .vn-log) .btn,
.st-tab, .shop-tab, .gl-tab, .map-info .mi-go {
  background: var(--inner-face);
  border: 1px solid var(--inner-edge);
  border-image: none;
  border-radius: 4px;
  box-shadow: none;
  filter: none;
  color: var(--text);
}
:is(.modal-box, .panel, .ink-panel, .vn-log) .btn.primary,
.st-tab.on, .shop-tab.on, .gl-tab.on, .map-info .mi-go {
  background: var(--inner-active);
  border-color: rgba(232, 194, 122, 0.55);
  color: var(--gold-hi);
  filter: none;
}
:is(.modal-box, .panel, .ink-panel, .vn-log) .btn:hover:not(:disabled),
:is(.modal-box, .panel, .ink-panel, .vn-log) .btn:focus-visible,
:is(.st-tab, .shop-tab, .gl-tab):is(:hover, :focus-visible),
.map-info .mi-go:hover {
  background: var(--inner-hover);
  border-color: var(--gold);
  color: var(--gold-hi);
  box-shadow: none;
  filter: none;
}
:is(.st-tab, .shop-tab, .gl-tab) { min-height: 40px; padding: 7px 16px; color: var(--text-dim); font-size: 15px; font-weight: 500; }
:is(.st-tab, .shop-tab, .gl-tab).on { font-weight: 700; box-shadow: inset 0 -2px var(--gold); }
:is(.st-tab, .shop-tab, .gl-tab):focus-visible { outline: 2px solid var(--gold-hi); outline-offset: 2px; }

:is(.modal-box, .panel, .ink-panel) :is(.panel, .ink-panel) {
  background: var(--inner-face);
  border: 1px solid var(--inner-edge);
  border-image: none;
  border-radius: 6px;
  box-shadow: none;
}

/* 小さな札も角飾りを外す。能力の色と漢字は残す。 */
.hud-card .dc-row {
  background: var(--inner-face);
  border-image: none;
  border-radius: 3px;
  box-shadow: inset 0 -1px var(--inner-edge);
}
.map-info .mi-banner {
  background: var(--inner-active);
  border-image: none;
  border-radius: 3px;
  color: var(--gold-hi);
}
.st-badge {
  background: color-mix(in srgb, var(--sc, var(--gc)) 12%, var(--ink-2));
  border: 1px solid color-mix(in srgb, var(--sc, var(--gc)) 55%, transparent);
  border-image: none;
  border-radius: 3px;
}
.vn-box .vn-name {
  min-width: 0;
  padding: 8px 18px 9px;
  background: var(--ink-2);
  border: 1px solid var(--inner-edge);
  border-image: none;
  border-radius: 4px;
  text-align: center;
}

/* グラフ・5項目の下を横断する情報欄にして、説明を窓の下へ押し出さない。 */
.status-modal { width: 940px; max-width: 940px; padding: 24px 28px; }
.status-modal > h3 { margin-bottom: 12px; }
.status-modal .modal-actions { margin-top: 12px; }
.st-tabs { gap: 8px; margin-bottom: 12px; }
.st-me { display: grid; grid-template-columns: 320px minmax(0, 1fr); column-gap: 24px; row-gap: 6px; }
.st-radar { grid-column: 1; grid-row: 2 / span 5; align-self: center; }
.status-modal .radar { display: block; width: 320px; height: 320px; }
/* DOMの親子関係は維持し、項目選択と説明の更新は今までのまま動かす。 */
.st-side { display: contents; }
.st-row { grid-column: 2; padding: 5px 10px; align-self: stretch; }
.st-info { gap: 2px; }
.st-line { line-height: 1.35; }
.st-fx { line-height: 1.45; }
.st-misc, .st-note { grid-column: 1 / -1; }
.st-misc { flex-wrap: wrap; gap: 4px 24px; margin-top: 6px; line-height: 1.5; }
.st-note { margin: 0; line-height: 1.5; }
/* 選んだ説明を先頭に置き、項目をスクロールしても本文内で読み続けられる。 */
.st-me .st-note { grid-row: 1; position: sticky; top: 0; z-index: 1; padding: 8px 0; background: var(--panel); }

/* MENUの4項目を2列で揃え、「閉じる」も窓の中央に置く。 */
.menu-modal { width: 620px; padding: 24px 28px; }
.menu-modal .modal-actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.menu-modal .modal-actions > .btn:last-child { grid-column: 1 / -1; justify-self: center; }

/* DAYカードの下に窓を置き、金縁同士が重なる箇所をなくす。 */
.shop { top: 110px; height: 584px; }
.shop-empty { margin-top: 20px; }

/* ===== css/shop.css ===== */
/* Dr.fookah: 白い紙と紫。ゲームの1280×720座標内でHUDと操作欄を常時残す。 */
.shop-paper, .modal-box.shop-dialog {
  --shop-ink: #38283f; --shop-purple: #69497e; --shop-line: #d5c8dc; --shop-muted: #76667e;
  color: var(--shop-ink); background: #f7f3ed;
  background-image: repeating-linear-gradient(35deg, #72547d03 0 1px, transparent 1px 4px);
  border: 1px solid #ded3dc; border-image: none; border-radius: 4px;
  box-shadow: 0 16px 54px #110a2255; text-shadow: none;
}
.shop.shop-paper { top: 72px; width: 1200px; height: 624px; padding: 0; }
/* 店の入口と1Fショップでは左上の HUD の札を隠し、空いた分だけ店のパネルを中央で広げる（所持金は店のヘッダーに出す。#2958）。
   右上の LIME・MENU も店の中では出さず、その分パネルを上まで広げる（上下左右 24px の余白。MENU と同じ枠）。
   店を出ると LIME・MENU は元どおり出る。PC・スマホ共通（オーナー指示 2026-11-11・SUI01）。
   DS風（body.game-ds）は LIME・MENU が下画面の帯にあるので、従来のまま */
body[data-screen="shop"] #hud .hud-card, body[data-screen="shop-entry"] #hud .hud-card { visibility: hidden; }
body:not(.game-ds)[data-screen="shop"] #hud .hud-right, body:not(.game-ds)[data-screen="shop-entry"] #hud .hud-right { visibility: hidden; }
body:not(.game-ds) .shop.shop-paper, body:not(.game-ds) .shop-entry { top: 24px; width: 1232px; height: 672px; }
.shop-paper button { font: inherit; cursor: pointer; touch-action: manipulation; }
.shop-paper button:disabled { cursor: default; }
.shop-paper button:focus-visible { outline: 3px solid #9470ad; outline-offset: 2px; }
.shop-paper .shop-head { flex: none; height: 70px; padding: 12px 26px; align-items: center; gap: 20px; border-bottom: 1px solid var(--shop-line); }
.shop-paper .shop-head h2 { color: var(--shop-ink); font: 36px var(--font); letter-spacing: -.035em; white-space: nowrap; }
.shop-paper .shop-sub { color: var(--shop-muted); border-left: 1px solid var(--shop-line); padding-left: 20px; font-size: 16px; }
.shop-paper .shop-money { color: var(--shop-ink); display: flex; align-items: baseline; gap: 14px; font: 32px var(--font); white-space: nowrap; font-variant-numeric: tabular-nums; }
.shop-paper .shop-money small { font: 14px var(--font); color: var(--shop-muted); }
.shop-paper .shop-tabs { flex: none; gap: 8px; height: 64px; margin: 10px 26px 0; }
.shop-paper .shop-tab { min-width: 164px; padding: 0 18px; white-space: nowrap; border-radius: 4px 4px 0 0; border: 1px solid var(--shop-line); border-image: none; background: #eee8f033; color: var(--shop-ink); font-size: 22px; box-shadow: none; }
.shop-paper .shop-tab.on { color: #fff; background: var(--shop-purple); border-color: var(--shop-purple); }
.shop-paper .shop-tab:hover:not(.on) { background: #e9e0ee; color: var(--shop-ink); }
.shop-filters { flex: none; display: flex; align-items: center; gap: 8px; height: 48px; margin: 0 26px; }
.shop-filters[hidden] { display: none; }
.shop-filter { border: 0; border-radius: 24px; padding: 7px 17px; min-height: 36px; color: var(--shop-muted); background: transparent; font-size: 15px !important; }
.shop-filter.on { background: #e5d9eb; color: #553563; font-weight: 700; }
.shop-filter:hover { background: #ebe2ef; }
.shop-filters > span { margin-left: auto; color: var(--shop-muted); font-size: 14px; }
.shop-paper .shop-body { min-height: 0; padding: 0 6px 0 0; margin: 0 20px 0 26px; gap: 0; scrollbar-color: #af96bc #ece5ec; scrollbar-width: thin; }
.shop-paper .shop-row { flex: none; min-height: 68px; padding: 0 8px; border-radius: 0; border-bottom: 1px solid var(--shop-line); gap: 16px; background: transparent; }
.shop-paper .shop-row:first-child { border-top: 1px solid var(--shop-line); }
.shop-paper .shop-row.selected { background: #e9dfef99; box-shadow: inset 3px 0 #ad8cbe; }
.shop-paper .shop-row.errand { outline: none; background: #eee3f2; box-shadow: inset 4px 0 var(--shop-purple); animation: none; }
.shop-product { display: flex; gap: 14px; align-items: center; flex: 1; min-width: 0; padding: 0; border: 0; text-align: left; background: transparent; color: var(--shop-ink); }
.shop-product:hover b { text-decoration: underline; text-underline-offset: 5px; }
.shop-product-art { display: flex; flex: none; width: 76px; height: 66px; align-items: center; justify-content: center; }
.shop-product-art.botanical { background-size: 600% 300%; background-repeat: no-repeat; width: 66px; margin: 0 5px; }
.shop-type-mark { display: grid; place-items: center; width: 58px; height: 44px; color: #795c8c; border: 1px solid #baa5c3; border-radius: 8px; font: 17px var(--font); letter-spacing: .04em; }
.shop-product-art .art { max-height: 64px; }
.shop-paper .shop-main { min-width: 0; }
.shop-paper .shop-main b { font-size: 19px; font-weight: 500; }
.shop-paper .shop-main small { color: var(--shop-muted); font-size: 14px; }
.shop-paper .shop-stock { color: var(--shop-ink); display: flex; gap: 10px; align-items: baseline; width: 115px; flex: none; font-size: 17px; letter-spacing: 0; }
.shop-paper .shop-stock small { color: var(--shop-muted); font-size: 14px; }
.shop-price { width: 126px; flex: none; text-align: right; font: 25px var(--font); white-space: nowrap; }
.shop-price.expense { font: 16px var(--font); color: var(--shop-purple); }
.shop-quantity { display: flex; align-items: center; justify-content: flex-end; gap: 7px; width: 142px; flex: none; }
.shop-step { display: grid; place-items: center; width: 44px; height: 44px; padding: 0; border: 1px solid #bda9c8; border-radius: 3px; background: #fffaf5; color: var(--shop-ink); font-size: 25px !important; line-height: 1; }
.shop-step.plus { background: var(--shop-purple); color: #fff; border-color: var(--shop-purple); }
.shop-step:disabled { opacity: .35; }
.shop-step:not(:disabled):hover { box-shadow: inset 0 0 0 2px #ac8ebc; }
.shop-quantity output { min-width: 28px; text-align: center; font-size: 20px; font-variant-numeric: tabular-nums; }
.shop-paper .shop-owned { width: 142px; flex: none; color: var(--shop-purple); font-size: 16px; }
.shop-paper .shop-foot { height: 92px; flex: none; margin: 0; padding: 10px 26px; gap: 16px; border-top: 1px solid var(--shop-line); background: #ece5ee99; }
.shop-back { min-width: 164px; min-height: 72px; padding: 10px 22px; font-weight: 700 !important; font-size: 22px !important; color: #58386c; border: 2px solid #9676a8; border-radius: 4px; background: #fffcf8; }
.shop-back:hover { background: #ebe0f0; }
.shop-summary { margin-left: auto; display: flex; align-items: baseline; gap: 10px; border: 0; background: transparent; padding: 7px; color: var(--shop-ink); font-variant-numeric: tabular-nums; }
.shop-summary small { font-size: 14px; }
.shop-summary strong { font: 30px var(--font); }
.shop-summary span { color: var(--shop-muted); font-size: 14px; margin-left: 7px; }
.shop-summary:enabled:hover strong { text-decoration: underline; text-underline-offset: 5px; }
.shop-summary[hidden], .shop-checkout[hidden] { display: none; }
.shop-checkout { flex: none; min-width: 250px; min-height: 52px; padding: 12px 20px; border: 1px solid var(--shop-purple); background: var(--shop-purple); border-radius: 4px; color: #fff; font-size: 18px !important; font-weight: 700 !important; }
.shop-checkout:disabled { background: #e3dbe7; border-color: #cfc1d6; color: #796981; }
.shop-checkout:enabled:hover { background: #533761; }
.shop-paper .shop-errand { flex: none; margin: 8px 26px 0; padding: 6px 12px; background: #eadfec; color: #593c69; border-left: 3px solid #9676a8; font-size: 15px; }
.shop-paper .shop-errand::before { display: none; }
.shop-paper .shop-errand.done { background: #f0eaf2; border-color: #9676a8; color: #593c69; }
.shop-paper .shop-errand.done, .shop-paper .shop-row.done { pointer-events: auto !important; }
.shop-paper .shop-empty, .shop-paper .kuji-note { color: var(--shop-muted); }
.shop-paper .shop-cat { color: var(--shop-muted); border-color: var(--shop-line); }
.shop-paper .btn, .modal-box.shop-dialog .btn { border: 1px solid #b8a1c4; border-image: none; border-radius: 4px; color: #58376a; background: #f5eef7; box-shadow: none; filter: none; text-shadow: none; }
.shop-paper .btn:hover, .modal-box.shop-dialog .btn:hover { color: #38283f; background: #e9deef; }
.shop-paper .kuji-row { padding-top: 14px; padding-bottom: 14px; }
.shop-paper .kuji-row .shop-main { gap: 6px; }
.shop-paper .kuji-row .btn { flex: none; min-width: 150px; min-height: 64px; font-size: 22px; }
.shop-paper .kuji-row .shop-main small { font-size: 18px; }
/* くじ券（KJ05）: 限定台くじの行の下の1行。行そのものは押せない */
.shop-paper .kuji-ticket-row { padding-top: 10px; padding-bottom: 10px; background: #f1eaf3; }
.shop-paper .kuji-ticket-row .shop-main { gap: 4px; }
.shop-paper .kuji-ticket-row .btn { flex: none; min-width: 150px; min-height: 64px; font-size: 22px; }
.shop-paper .kuji-ticket-row .shop-main small { font-size: 18px; }
.shop-paper .kuji-actions { display: flex; flex-direction: row; flex: none; gap: 16px; }
.shop-paper .kuji-title { display: flex; align-items: center; gap: 12px; min-width: 0; }
/* くじの「?」: 見た目は文字ほどの小さな丸。押せる範囲は透明な ::before で 72px 四方に広げる（#2958・オーナー指示） */
.shop-paper .kuji-help { --help-size: 30px; --help-hit: 72px; position: relative; flex: none; width: var(--help-size); height: var(--help-size); padding: 0; border-radius: 50%; border: 1.5px solid #9676a8; background: #fffcf8; color: #58386c; font-size: 18px !important; font-weight: 700; line-height: 1; }
.shop-paper .kuji-help::before { content: ""; position: absolute; left: 50%; top: 50%; width: var(--help-hit); height: var(--help-hit); transform: translate(-50%, -50%); border-radius: 50%; }
.shop-paper .kuji-row { cursor: pointer; }
.shop-paper .kuji-cat { font-size: 26px; border: 0; }
/* 景品の一覧（棚の案内・GCH13）: くじは店ごとに1種類なので、行の下の空いた所にその箱の景品とのこり枚数を並べる。
   左の帯と賞の字の色は、ガラガラの玉と同じ賞の色（S＝金・A＝赤・B＝青・C＝白・ラストワン＝黒） */
.shop-paper .kuji-lineup { flex: none; padding: 16px 8px 20px; }
.kuji-lineup-head { display: flex; align-items: baseline; gap: 16px; margin: 0 0 12px; color: var(--shop-ink); font-size: 20px; font-weight: 500; letter-spacing: .06em; }
.kuji-lineup-head small { color: var(--shop-muted); font-size: 15px; letter-spacing: 0; }
.kuji-lineup-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 14px; margin: 0; padding: 0; list-style: none; }
.kuji-lineup-item { --lineup-color: #b9b0a2; --lineup-ink: #5e554c; display: flex; align-items: center; gap: 12px; min-height: 68px; padding: 6px 14px 6px 8px; border: 1px solid var(--shop-line); border-left: 6px solid var(--lineup-color); border-radius: 4px; background: #fffcf8; }
.kuji-lineup-item[data-rank="S"] { --lineup-color: #e9b233; --lineup-ink: #8a5a06; background: #fff7df; }
.kuji-lineup-item[data-rank="A"] { --lineup-color: #e2443c; --lineup-ink: #b3261c; }
.kuji-lineup-item[data-rank="B"] { --lineup-color: #3f82ea; --lineup-ink: #1f55b0; }
.kuji-lineup-item[data-rank="LAST"] { --lineup-color: #2a2648; --lineup-ink: #2a2648; background: #efedf5; }
.kuji-lineup-item[data-out] { opacity: .45; }
.kuji-lineup-art { flex: none; display: flex; align-items: center; justify-content: center; width: 56px; height: 56px; }
.kuji-lineup-art > * { position: relative; }
.kuji-lineup-art .kj-art-leaf { display: flex; align-items: center; justify-content: center; flex: none; margin: 0; background: none; }
.kuji-lineup-art .kj-gift { --u: 5.6px; }
.kuji-lineup-art .kj-art-fan .kj-gift { --u: 3.4px; }
/* 詰め合わせ（パッケージを扇に重ねた絵）は、枠（56px）からはみ出して賞の字に重ならないよう縮める */
.kuji-lineup-art .kj-art-fan { flex: none; width: 56px; transform: scale(.58); }
.kuji-lineup-secret { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; background: #2a2648; color: #e6e7f0; font-size: 24px; font-weight: 700; box-shadow: inset 0 0 0 3px #b9b4d8; }
.kuji-lineup-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.kuji-lineup-rank { color: var(--lineup-ink); font-size: 15px; font-weight: 700; letter-spacing: .06em; }
.kuji-lineup-name { color: var(--shop-ink); font-size: 18px; line-height: 1.3; }
.kuji-lineup-left { flex: none; color: var(--shop-muted); font-size: 15px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.shop-badge { align-self: flex-start; padding: 2px 12px; border: 1px solid currentColor; border-radius: 14px; font-size: 20px !important; }
.shop-entry { position: absolute; left: 50%; top: 72px; transform: translateX(-50%); width: 1200px; height: 624px; padding: 24px 30px; display: flex; flex-direction: column; }
.shop-entry .shop-head { padding: 0 0 18px; height: 60px; }
.shop-entry > h3 { font-size: 24px; font-weight: 500; letter-spacing: .08em; margin: 18px 0; }
.shop-floors { display: flex; gap: 22px; flex: 1; min-height: 0; }
.shop-floor { position: relative; width: 50%; min-width: 0; padding: 0; border: 1px solid #c7b6d1; border-radius: 5px; overflow: hidden; text-align: left; display: flex; flex-direction: column; background: #f3edf4; color: var(--shop-ink); }
.shop-floor-picture { display: block; position: relative; flex: 1 1 auto; min-height: 128px; width: 100%; overflow: hidden; }
.shop-floor-picture img { display: block; width: 100%; height: 100%; object-fit: cover; }
/* 写真が届くまでの下地（#3203）。通信が遅く上限で入口を出したときも枠を空白にしない。デコードできたら外す（shop.js） */
.shop-floor-picture[data-loading] { background: linear-gradient(150deg, rgba(171, 141, 188, .34), rgba(90, 60, 107, .52)); }
.shop-floor-number { position: absolute; top: 12px; left: 12px; padding: 8px 12px; background: #fbf4f4ec; color: #5a3c6b; border: 1px solid #c6b1d1; border-radius: 3px; font: 28px var(--font); }
.shop-floor-caption { position: relative; display: flex; flex-direction: column; flex: none; justify-content: center; gap: 8px; width: 100%; padding: 14px 24px 16px; }
.shop-floor-caption b { font-size: 23px; font-weight: 500; letter-spacing: .06em; }
.shop-floor-caption small { font-size: 16px; color: #72557f; }
.shop-floor-arrow { position: absolute; bottom: 22px; right: 22px; font-size: 27px; color: #9976ab; }
.shop-floor.showroom { background: #493353; color: #fff; border-color: #493353; }
.shop-floor.showroom small, .shop-floor.showroom .shop-floor-arrow { color: #e0d2e7; }
.shop-floor:enabled:hover { box-shadow: 0 0 0 3px #ab8dbc; }
.shop-floor:disabled img { filter: saturate(.45); opacity: .65; }
.shop-floor:disabled .shop-floor-arrow { display: none; }
.shop-entry-foot { flex: none; margin-top: 20px; }
.shop-entry .shop-back { min-height: 72px; font-size: 22px !important; }
.modal-box.shop-dialog { padding: 28px; max-width: 700px; }
.modal-box.shop-dialog h3 { color: #51325f; }
.modal-box.shop-dialog .btn.primary { color: #fff; background: #69497e; }
.shop-dialog .modal-body { color: #38283f; }
.shop-detail { font-size: 19px; line-height: 1.8; }
.shop-detail .shop-product-art { float: left; margin: 0 20px 8px 0; width: 112px; height: 112px; }
.shop-detail-category { color: #80628f; font-size: 16px; }
.shop-detail p { margin: 8px 0; }
.shop-current { clear: both; padding-top: 14px; border-top: 1px solid #d5c8dc; color: #765780; font-size: 17px; }
.shop-order p { display: flex; justify-content: space-between; gap: 25px; padding: 8px 0; border-bottom: 1px solid #d5c8dc; }
/* スマホ横持ち: stage が縮むぶん（--k）を戻し、実寸で文字 11px 以上・押せる所 38px 以上にする（#2858）。縦持ちは扱わない */
@media (orientation: landscape) and (max-width: 1024px) and (max-height: 520px) and (pointer: coarse) and (hover: none) {
  .shop-paper { --shop-text: max(18px, calc(11.5px / var(--k, 1))); --shop-tap: max(64px, calc(40px / var(--k, 1))); --shop-label: max(22px, calc(12px / var(--k, 1))); }
  .shop-paper .shop-head { height: auto; min-height: 70px; }
  .shop-paper .shop-sub, .shop-paper .shop-money small, .shop-paper .shop-stock small, .shop-paper .shop-summary small, .shop-paper .shop-summary span, .shop-paper .shop-owned, .shop-price.expense, .shop-filters > span,
  .shop-paper .shop-main small, .shop-paper .shop-main .shop-feature-tags.shop-feature-tags, .shop-paper .kuji-row .shop-main small, .shop-paper .kuji-ticket-row .shop-main small, .shop-paper .shop-stock, .shop-paper .shop-stock span, .shop-type-mark, .shop-quantity output { font-size: var(--shop-text); }
  .shop-paper .shop-tabs { height: var(--shop-tap); margin-top: 8px; }
  .shop-paper .shop-tab, .shop-paper .shop-main b { font-size: var(--shop-label); }
  .shop-paper .shop-row { min-height: var(--shop-tap); }
  .shop-paper .shop-product { min-height: var(--shop-tap); }
  .shop-paper .shop-filter { min-height: max(48px, calc(40px / var(--k, 1))); font-size: var(--shop-text) !important; }
  /* 絞り込みの段は 48px 固定のままだと、大きくしたチップがはみ出して上の売り場タブに 6〜9px 重なっていた（#3555）。段をチップの高さに合わせる */
  .shop-paper .shop-filters { height: auto; min-height: max(48px, calc(40px / var(--k, 1))); margin-top: 6px; }
  /* 数量の欄は、大きくした − ＋ の分だけ広げる（固定幅のままだと − が価格に重なる） */
  .shop-paper .shop-quantity { width: auto; }
  .shop-paper .shop-step { flex: none; min-width: max(52px, calc(40px / var(--k, 1))); width: max(52px, calc(40px / var(--k, 1))); height: var(--shop-tap); font-size: var(--shop-label) !important; }
  .shop-paper .shop-row .btn, .shop-paper .shop-checkout { min-height: var(--shop-tap); font-size: var(--shop-label) !important; }
  .shop-paper .kuji-row, .shop-paper .kuji-actions { gap: 16px; }
  .shop-paper .kuji-row .btn, .shop-paper .kuji-ticket-row .btn { min-width: 150px; }
  .kuji-lineup-head { font-size: var(--shop-label); }
  .kuji-lineup-head small, .kuji-lineup-rank, .kuji-lineup-left { font-size: var(--shop-text); }
  .kuji-lineup-name { font-size: var(--shop-label); }
  .kuji-lineup-item { min-height: var(--shop-tap); }
  .shop-paper .kuji-help { --help-size: max(30px, calc(16px / var(--k, 1))); --help-hit: max(72px, calc(40px / var(--k, 1))); font-size: max(18px, calc(11px / var(--k, 1))) !important; }
  .shop-paper .shop-foot { height: auto; min-height: 92px; }
  .shop-paper .shop-summary { min-height: var(--shop-tap); }
  .shop-paper .shop-back, .shop-entry .shop-back { min-height: max(72px, calc(40px / var(--k, 1))); font-size: var(--shop-label) !important; }
  .shop-paper .shop-badge { font-size: max(20px, calc(11.5px / var(--k, 1))) !important; }
  .shop-paper .shop-floor-caption b { font-size: var(--shop-label); }
  .shop-entry > h3 { font-size: max(24px, calc(12px / var(--k, 1))); margin: 6px 0 8px; }
  /* 店の入口: 写真をカード全体に広げ、文字は下端の細い帯（名前＋小さなバッジ）に重ねる。帯が2行になっても写真の上端・カードの下端は左右でそろう（#2858 の追加・オーナー指示） */
  .shop-entry .shop-head { min-height: 0; padding-bottom: 8px; }
  .shop-entry-foot { margin-top: 12px; }
  .shop-floor-picture { position: absolute; inset: 0; height: auto; }
  .shop-floor-number { top: 8px; left: 8px; padding: 4px 10px; font-size: 24px; }
  .shop-floor-caption { position: absolute; left: 0; right: 0; bottom: 0; flex: none; flex-flow: row wrap; align-items: center; justify-content: flex-start; gap: 4px 12px; padding: 8px 52px 8px 18px; background: #f3edf4eb; }
  .shop-floor.showroom .shop-floor-caption { background: #493353eb; }
  .shop-floor-caption b { white-space: nowrap; }
  .shop-paper .shop-floor .shop-badge { max-width: 100%; align-self: center; padding: 0 8px; border-radius: 10px; line-height: 1.35; font-size: max(16px, calc(11px / var(--k, 1))) !important; }
  .shop-floor-arrow { top: 50%; bottom: auto; right: 18px; transform: translateY(-50%); font-size: 24px; }
}

/* ===== css/steam.css ===== */
/* 蒸らしも吸い出しと同じ紫・金の面と左の温度計を使う。 */
.bench[data-step="steam"] :is(.bench-left, .bench-right) { bottom: 12px; }
.bench[data-step="steam"] .bench-right { padding-bottom: 12px; background: radial-gradient(ellipse at 90% 100%, #45304726, transparent 60%), linear-gradient(145deg, #191121, #100b18); }
.bench[data-step="steam"] .bench-heading { padding-left: 12px; }
.bench[data-step="steam"] .bench-title { font-family: "Craft Mincho", var(--font); font-size: 40px; font-weight: 700; letter-spacing: .1em; color: #f6e4c8; text-shadow: 0 1px 2px #8f492744; }
.bench[data-step="steam"] .bench-hint { margin-top: 14px; font-size: 15px; color: #c9bca8; }
.bench[data-step="steam"] .bench-head { position: relative; min-height: 89px; margin-bottom: 0; padding-bottom: 7px; border-bottom: 0; }
.bench[data-step="steam"] .bench-head::after { content: ""; position: absolute; left: 12px; right: 0; top: 56px; height: 1px; background: linear-gradient(90deg, #c8b39238, #c8b3920d); }
.bench[data-step="steam"] .bench-guide { align-self: flex-start; margin-top: 10px; }
/* モード欄の縮小率に依存させず、操作盤面から離れた左の人物欄上部へ。 */
.bench[data-step="steam"] .bench-right .bench-head { left: -238px; right: auto; top: 8px; }
.bench[data-step="steam"] .bench-guide { margin-top: 0; }
.bench[data-step="steam"] .bench-guide summary { width: calc(44px / var(--k, 1)); height: calc(44px / var(--k, 1)); }
.bench[data-step="steam"] .bench-guide-tip { left: 0; right: auto; }

/* タイマー設定・弾幕・吸い出しは同じ位置、同じ64×360pxの温度計。 */
.bench[data-step="steam"] .steam-temperature { position: absolute; left: -128px; top: -48px; height: 360px; z-index: 3; }
.steam-temperature::before { content: "温度"; position: absolute; left: 0; right: 0; top: -19px; font-size: 14px; letter-spacing: .02em; text-align: center; color: #ead7b5; }
.steam-temperature-read { position: absolute; top: calc(100% + 12px); left: -3px; right: -3px; display: flex; justify-content: center; min-height: 32px; border: 1px solid #c1aa7438; border-radius: 6px; background: #100c17ef; }
.steam-temperature-read .pull-state { font-size: 14px; white-space: nowrap; letter-spacing: .02em; }
.thermo-range { position: absolute; left: 0; right: 0; z-index: 7; border: 1px dashed #fff1c8; background: repeating-linear-gradient(-45deg, #fff1c824 0 3px, transparent 3px 7px); box-shadow: inset 0 0 8px #fff1c82b; }
.thermo-range-note { position: absolute; left: -33px; width: 32px; padding: 2px 0; font-size: 12px; text-align: center; font-weight: 700; color: #f4deb2; border-bottom: 1px dashed #edc99799; background: #100b15df; border-radius: 3px; }
.thermo-range[hidden], .thermo-range-note[hidden] { display: none; }
.thermo[data-forecast] .thermo-mark { z-index: 9; }
.steam-timer { gap: 22px; padding-bottom: 0; }
.steam-forecast { width: 520px; display: flex; flex-direction: column; gap: 6px; padding: 11px 16px; border: 1px solid #b59d7152; border-radius: 8px; background: linear-gradient(145deg, #261c2b, #171221); box-shadow: inset 0 1px 0 #f4d9a90c; }
.steam-forecast-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; font-size: 13px; color: #c6b8b0; }
.steam-forecast-value { font-family: "Craft Mincho", var(--font); color: #f0d9ad; font-size: 16px; font-weight: 700; letter-spacing: .04em; }
.steam-weather { display: flex; gap: 13px; align-items: center; color: #b3b4c4; font-size: 12px; font-variant-numeric: tabular-nums; }
.steam-weather i { width: 18px; height: 18px; margin-right: -6px; color: #d2c3a9; }
.steam-weather svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.3; stroke-linecap: round; stroke-linejoin: round; }
.steam-forecast-note { color: #c6b8b0; font-size: 12px; }

/* 左は店内で待つはじめ。息に合わせて、肩がごくわずかに上下する。 */
.bench[data-step="steam"] .bench-worker { position: relative; }
.bench[data-step="steam"] .worker-equipment { right: 92px; bottom: 7%; }
.bench[data-step="steam"] .worker-actor { height: calc(100% + 150px); left: -114px; bottom: -135px; }
.bench[data-step="steam"] .worker-counter { top: 68%; }
.bench[data-step="steam"] .thermal-label { display: none; }
.bench[data-step="steam"] .bench-worker-name { display: none; }
.bench-worker[data-waiting="true"] .worker-actor { animation: worker-wait-settle 5.2s ease-in-out infinite; transform-origin: 55% 40%; }
@keyframes worker-wait-settle { 0%, 100% { transform: translateY(0); } 45% { transform: translateY(-2px) scale(1.004); } }

/* 奥の霧・細い軌道・反射面は淡く、動く雑念と心の芯はくっきり。 */
.steam { height: 100%; justify-content: space-between; gap: 12px; padding-top: 0; }
.steam .dodge-controls { align-self: center; margin-right: 0; }
.dodge-controls { width: 752px; }
/* フィールドの左右も、ウインドウ上側と同じ17pxの余白に揃える。 */
.steam-play { width: 784px; flex: 1; display: grid; justify-items: center; align-items: start; }
/* 上に少し余裕を取り、操作欄との間隔も残す。 */
.steam-play > .dodge { top: 4px; }
/* 残り時間は視線を弾幕から離さず読める、奥の薄い7セグ。 */
.dodge .dodge-timer { position: absolute; left: 50%; top: 50%; width: 448px; height: 158px; transform: translate(-50%, -50%); color: var(--mental-ink); opacity: .16; z-index: 1; pointer-events: none; user-select: none; transition: color .25s ease; }
.dodge { --mental-ink: #86d6c5; }
.dodge[data-mental="clear"] { --mental-ink: #a8e6ff; }
.dodge[data-mental="unsteady"] { --mental-ink: #e4bc77; }
.dodge[data-mental="shaken"] { --mental-ink: #ef8795; }
.bench[data-art-skin] .dodge { border-image: none; border: 1px solid #c5ae815c; border-radius: 10px; background: #131123; box-shadow: inset 0 0 0 3px #a9946614, 0 4px 16px #0007; }
.dodge::before { content: ""; position: absolute; inset: 4px; border: 1px solid #d3b98116; border-radius: 6px; z-index: 3; pointer-events: none; }
.dodge-world-layers { position: absolute; inset: 0; pointer-events: none; z-index: 0; }
.dodge-world-art { position: absolute; inset: 0; background: center / cover no-repeat; opacity: .92; }
.dodge-world { position: absolute; inset: 0; width: 100%; height: 100%; }
.dodge-mist { position: absolute; width: 500px; height: 330px; opacity: .22; background: var(--mist) center / 100% 100% no-repeat; transform-origin: 50% 50%; pointer-events: none; }
.dodge-mist.left { left: -180px; bottom: -120px; transform: rotate(65deg); animation: dodge-mist-left 16s ease-in-out infinite alternate; }
.dodge-mist.right { right: -180px; top: -120px; transform: rotate(-110deg); animation: dodge-mist-right 18s ease-in-out infinite alternate; }
@keyframes dodge-mist-left { to { transform: translate(40px, -12px) rotate(73deg) scale(1.08); } }
@keyframes dodge-mist-right { to { transform: translate(-45px, 12px) rotate(-100deg) scale(1.1); } }
.dodge-mental { z-index: 1; }
.dodge-beat-line { opacity: .18; stroke-width: 1.3; }
.dodge-mental-caption { display: none; }
.dodge-mental[data-level="shaken"] .dodge-beat-line { opacity: .28; stroke-width: 2; }
.dodge[data-mental="shaken"] { border-color: #d48a915c; }
/* #2519 心の状態は文字で出さず、視界の縁と雑念のにじみで見せる。判定は言葉の実寸のまま変えない。 */
.dodge-mental[data-level="clear"] { --mental-ink: #a8e6ff; }
.dodge-mental[data-level="clear"] .dodge-beat-line { opacity: .14; }
.dodge-vignette { position: absolute; inset: 0; z-index: 1; pointer-events: none; opacity: 0; transition: opacity .45s ease, background .45s ease; }
.dodge[data-mental="clear"] .dodge-vignette { opacity: 1; background: radial-gradient(ellipse at 50% 55%, #a8e6ff12, transparent 62%); }
.dodge[data-mental="unsteady"] .dodge-vignette { opacity: 1; background: radial-gradient(ellipse at 50% 50%, transparent 58%, #e4bc771c 82%, #2a1a0c66); }
.dodge[data-mental="shaken"] .dodge-vignette { opacity: 1; background: radial-gradient(ellipse at 50% 50%, transparent 46%, #ef87952e 76%, #3a0f1a99); animation: mind-throb .82s ease-in-out infinite; }
@keyframes mind-throb { 0%, 100% { opacity: .75; } 18% { opacity: 1; } 34% { opacity: .82; } 48% { opacity: .95; } }
.dodge[data-mental="clear"] .dodge-word { color: #e3eef5; text-shadow: 0 0 6px #a8e6ff40, 0 2px 2px #000; }
.dodge[data-mental="unsteady"] .dodge-word { text-shadow: 0 0 8px #e4bc7766, 0 2px 2px #000; }
.dodge[data-mental="shaken"] .dodge-word { color: #ffe9ee; text-shadow: 2px 0 4px #ef8795a6, -2px 0 4px #86d6c540, 0 0 10px #ef879566, 0 2px 2px #000; animation: mind-blur .5s steps(2) infinite; }
@keyframes mind-blur { 50% { text-shadow: -2px 0 4px #ef8795a6, 2px 0 4px #86d6c540, 0 0 12px #ef879577, 0 2px 2px #000; } }
.bench[data-art-skin] .dodge.warning[data-side="left"] { border-left-color: #e3c788; box-shadow: inset 28px 0 30px -22px #e3c78899, 0 4px 16px #0007; }
.bench[data-art-skin] .dodge.warning[data-side="right"] { border-right-color: #e3c788; box-shadow: inset -28px 0 30px -22px #e3c78899, 0 4px 16px #0007; }
.bench[data-art-skin] .dodge.warning[data-side="both"] { border-left-color: #e3c788; border-right-color: #e3c788; box-shadow: inset 28px 0 30px -22px #e3c78899, inset -28px 0 30px -22px #e3c78899, 0 4px 16px #0007; }
.bench[data-art-skin] .dodge.warning[data-side="top"] { border-top-color: #e3c788; box-shadow: inset 0 28px 30px -22px #e3c78899, 0 4px 16px #0007; }
.dodge-word, .dodge-thought-echo, .dodge-cut-half { padding: 5px 12px; color: #f5e8ee; background: linear-gradient(90deg, #20182d00, #302039aa 16% 84%, #20182d00); border: 0; border-radius: 0; font-family: "Craft Mincho", var(--font); font-size: 15px; letter-spacing: .07em; box-shadow: none; text-shadow: 0 0 7px #d7a6d25c, 0 2px 2px #000; white-space: nowrap; }
.dodge-word { z-index: 2; }
.dodge-word::after { content: ""; position: absolute; left: 10%; right: 10%; bottom: 2px; height: 1px; background: linear-gradient(90deg, transparent, #d6b8dc66, transparent); }
.dodge-thought-echo { position: absolute; z-index: 2; pointer-events: none; animation: thought-dissolve .85s ease-out forwards; }
@keyframes thought-dissolve { from { opacity: .7; filter: blur(0); } to { opacity: 0; filter: blur(5px); transform: translateY(-15px) scale(1.08); } }
.dodge-object { z-index: 2; }
.dodge-object svg { display: block; width: 100%; height: 100%; overflow: visible; }
.dodge-object.coal, .dodge-object.clock, .dodge-object.spark, .dodge-object.smoke, .dodge-object.orb { border: 0; border-radius: 0; background: none; box-shadow: none; clip-path: none; opacity: 1; }
.dodge-object.orb { width: 16px; height: 16px; filter: drop-shadow(0 0 5px #d3c2ff88); }
.dodge-object.coal { filter: drop-shadow(0 0 4px #ed904450); }
.dodge-object.clock { filter: drop-shadow(0 0 3px #acbdd044); }
.dodge-object.clock::after { content: none; }
.dodge-object.spark { filter: drop-shadow(0 0 4px #f6ce8555); }
.dodge-object.smoke { filter: drop-shadow(0 0 5px #bc9feb44); }
.bench[data-step="steam"] .dodge-heart { --heart-ink: #70d7ed; --heart-hit: #ef8795; color: var(--heart-ink); background: none; text-shadow: none; filter: drop-shadow(0 0 3px #79e1f055); }
.bench[data-step="steam"] .dodge-heart.shield { color: var(--heart-hit); filter: drop-shadow(0 0 3px #ef879566); }
.dodge-heart > span { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); }
.dodge-heart > span, .dodge-heart svg { display: block; width: var(--heart-size, 20px); height: var(--heart-size, 20px); }
.dodge-core { width: var(--hit-diameter, 8px); height: var(--hit-diameter, 8px); left: 50%; top: 50%; transform: translate(-50%, -50%); background: #fff; box-shadow: none; }
.dodge-core::after, .dodge-heart.shield::after { content: none; }

/* 操作を近くにまとめる。精密モードはボタンの灯りで示す。 */
.dodge-controls { justify-content: flex-end; align-items: flex-start; gap: 12px; height: 180px; flex: none; padding-right: 12px; }
.bench[data-art-skin] .dodge-pad { --stick-lift: 10px; width: 176px; height: 176px; border: 0; background: none; box-shadow: none; }
/* 太い四方向矢印・灰色の大きな可動ノブで、照準ボタンと区別する。 */
.bench[data-art-skin] .dodge-pad > span { display: block; color: #ebdbbfc9; pointer-events: none; }
.dodge-pad > span img { width: calc(100% + 20px); height: calc(100% + 20px); margin: -10px; object-fit: contain; }
.dodge-pad > span svg { width: 100%; height: 100%; fill: none; stroke-width: 1; }
.bench[data-art-skin] .dodge-knob { left: calc(50% - 44px); top: calc(50% - 44px - var(--stick-lift)); width: 88px; height: 88px; border: 2px solid #a6acb7; background: linear-gradient(155deg, #c4cad3, #798491 42%, #424957); box-shadow: inset 0 1px 2px #fff7, inset 0 0 0 3px #171a2544, 0 7px 0 -1px #4c515e, 0 10px 0 -1px #11131e, 0 15px 12px #000a; }
.dodge-knob::before { content: ""; position: absolute; inset: 17px; z-index: 1; border-radius: 50%; background: repeating-linear-gradient(0deg, transparent 0 7px, #c5ced325 7px 8px); mask-image: radial-gradient(ellipse, #000 35%, transparent 72%); }
.dodge-knob::after { content: ""; position: absolute; inset: 7px; border: 1px solid #d2dae047; border-radius: 50%; background: radial-gradient(ellipse at 35% 25%, #c4cbd4, #737d8a 45%, #414957); box-shadow: inset 0 2px 4px #fff2, 0 1px 0 #d5dfe529; }
.bench[data-art-skin] .dodge-pad.held { box-shadow: 0 0 16px #e2cf9d35; }
.bench[data-art-skin] .dodge-pad.held > span { filter: brightness(1.12); }
.bench[data-art-skin] .dodge-pad.held .dodge-knob { border-color: #edf4fc; }
.dodge-pad:focus-visible { outline: 2px solid #d6c49a; outline-offset: 4px; }
.bench[data-art-skin] .btn.dodge-action, .bench[data-art-skin] .btn.dodge-action:hover:not(:disabled) { display: flex; flex-direction: column; justify-content: flex-start; gap: 1px; align-items: center; width: 176px; min-width: 0; height: 180px; min-height: 180px; padding: 0; border: 0; border-image: none; border-radius: 50%; background: none; color: #eee3c9; box-shadow: none; touch-action: none; }
.bench[data-art-skin] .dodge-action:hover:not(:disabled) { filter: brightness(1.12); }
.refresh-emblem { position: relative; width: 152px; height: 152px; flex: none; color: #d4dfc6; pointer-events: none; }
.refresh-emblem img { position: absolute; left: -12px; top: -12px; display: block; width: 176px; height: 176px; object-fit: contain; }
.dodge-refresh:enabled .refresh-emblem::after { content: ""; position: absolute; inset: 12px; border: 2px solid transparent; border-top-color: #d2f4ff99; border-bottom-color: #80cfff55; border-radius: 50%; filter: drop-shadow(0 0 3px #70ccff); animation: refresh-energy-orbit 4.5s linear infinite; }
@keyframes refresh-energy-orbit { to { transform: rotate(360deg); } }
.refresh-emblem svg { width: 100%; height: 100%; }
.refresh-emblem > span:first-child { display: block; width: 100%; height: 100%; }
.recharge-ring { display: none; position: absolute; inset: 12px; border-radius: 50%; background: conic-gradient(#d7edff calc(var(--recharge) * 1turn), #77728a44 0); mask-image: radial-gradient(circle, transparent 65%, #000 66% 70%, transparent 71%); }
.action-recharge { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); font-family: var(--font); font-size: 25px; font-weight: 700; line-height: 1.2; color: #f4f5ff; text-shadow: 0 1px 4px #080512, 0 0 9px #080512; white-space: nowrap; }
.dodge-action[data-cooling="true"] .recharge-ring { display: block; }
.dodge-action[data-cooling="true"] .refresh-emblem :is(img, svg) { opacity: .3; }
.bench[data-art-skin] .btn.dodge-action[data-cooling="true"]:disabled { opacity: 1; filter: none; }
.dodge-slash:enabled .refresh-emblem { filter: drop-shadow(0 0 5px #d4c6f044); }
.dodge-slash-fx { position: absolute; pointer-events: none; z-index: 4; transform: translate(-50%, -50%) rotate(var(--angle)); filter: drop-shadow(0 0 5px #9edfff); animation: steam-slash .32s ease-out forwards; }
.dodge-slash-fx svg { display: block; width: 100%; height: 100%; }
.dodge-slash-fx[data-hit="false"] { filter: none; }
.dodge-slash-fx[data-hit="false"] svg { opacity: .5; }
.slash-control { position: relative; width: 176px; height: 180px; flex: none; }
.slash-growth { position: absolute; right: -10px; bottom: 8px; z-index: 1; display: flex; align-items: center; gap: 9px; padding: 0 5px; border: 1px solid #9a829a; border-radius: 999px; background: #1a1322; box-shadow: 0 2px 5px #000a; color: #e1d4ba; white-space: nowrap; font-family: var(--font); font-size: 14px; font-weight: 700; line-height: 1.2; font-variant-numeric: tabular-nums; }
.dodge-slash[data-tier="1"] .refresh-emblem { color: #d8d7ff; }
.dodge-slash:enabled .recharge-ring { display: block; opacity: .65; }
.dodge-slash[data-tier="1"] .recharge-ring { background: conic-gradient(#d5abff calc(var(--recharge) * 1turn), #77728a44 0); }
.dodge-slash[data-tier="2"] .recharge-ring { background: conic-gradient(#ffe0a3 calc(var(--recharge) * 1turn), #77728a44 0); }
/* 結果の文章は読み上げ専用。画面は刃の色・火花・数字で伝える。 */
.slash-feedback { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.dodge-slash-fx[data-tier="1"] { filter: drop-shadow(0 0 6px #d5abff); }
.dodge-slash-fx[data-tier="2"] { filter: drop-shadow(0 0 7px #ffd58a); }
.dodge-slash.striking .refresh-emblem > span:first-child { animation: slash-press .2s ease-out; }
.dodge-slash-impact { position: absolute; width: 26px; height: 26px; transform: translate(-50%, -50%); z-index: 4; pointer-events: none; background: #fff0b9; clip-path: polygon(48% 0, 56% 38%, 100% 46%, 63% 55%, 53% 100%, 43% 64%, 0 54%, 36% 43%); animation: slash-impact .32s ease-out forwards; }
@keyframes slash-press { 50% { transform: scale(.93); } }
@keyframes slash-impact { from { opacity: 1; } to { opacity: 0; transform: translate(-50%, -50%) scale(.35) rotate(35deg); } }
.dodge-word-cut { position: absolute; z-index: 4; pointer-events: none; }
.dodge-cut-half { position: absolute; inset: 0; }
.dodge-cut-half { animation: word-cut-half .5s ease-out forwards; }
.dodge-word-cut::after { content: ""; position: absolute; inset: 0; background: linear-gradient(var(--cut-gradient-angle), transparent calc(50% - .5px), #fff2c7 50%, transparent calc(50% + .5px)); animation: word-cut-edge .18s ease-out forwards; }
@keyframes word-cut-half { from { opacity: 1; } to { opacity: 0; transform: translate(var(--cut-x), var(--cut-y)) rotate(var(--cut-turn)); } }
@keyframes word-cut-edge { to { opacity: 0; } }
@keyframes steam-slash { 0% { opacity: .8; } 25% { opacity: 1; } 100% { opacity: 0; } }
.refresh-copy { font-family: "Craft Mincho", var(--font); font-weight: 700; font-size: 18px; line-height: 1.2; white-space: nowrap; letter-spacing: .03em; padding: 2px 0; border: 0; background: none; text-shadow: 0 1px 3px #000; }
.precision-copy { display: flex; align-items: center; gap: 8px; }
.precision-state { display: grid; place-items: center; width: 44px; height: 20px; border: 1px solid #8b94884d; border-radius: 10px; font-family: var(--font); font-size: 12px; line-height: 1; font-weight: 700; letter-spacing: .02em; color: #b8bab1; background: #171a18; }
.dodge-precision[aria-pressed="false"] .refresh-emblem { filter: brightness(.72) saturate(.75); }
.bench[data-art-skin] .dodge-action:disabled { opacity: .4; filter: saturate(.5); }
.bench[data-art-skin] .btn.dodge-precision[aria-pressed="true"], .bench[data-art-skin] .btn.dodge-precision[aria-pressed="true"]:hover:not(:disabled) { color: #edf4df; background: none; box-shadow: none; }
.dodge-precision[aria-pressed="true"] .refresh-emblem { filter: brightness(1.2) drop-shadow(0 0 9px #6ee3a575); }
.dodge-precision[aria-pressed="true"] .precision-state { color: #e8ffe7; border-color: #a9e7b2; background: #347d51; box-shadow: 0 0 7px #79e29c66; }
.dodge-precision[aria-pressed="true"] .refresh-emblem { color: #e1f2d0; }

/* 波は実際の消去範囲で止まり、消した弾だけが粒になる。 */
.dr-flash { background: radial-gradient(circle at var(--x) var(--y), #edffe43d, #b5debc20 35%, transparent 72%); }
.dr-ring { border-width: 1px; border-color: #e0edcb; box-shadow: 0 0 8px #c7ddb57a, inset 0 0 15px #b8ceb32b; }
.dr-ring.second { border-color: #dbc7a199; box-shadow: none; }
.dr-ray { width: 32px; height: 1px; background: linear-gradient(90deg, transparent, #fff3d7, transparent); }
@media (prefers-reduced-motion: reduce) {
  .dodge-cut-half.upper, .dodge-cut-half.lower { animation: none; opacity: .5; }
  .dodge-cut-half { transform: translate(var(--cut-still-x), var(--cut-still-y)); }
  .dodge-word-cut::after { display: none; }
  .dodge-slash.striking .refresh-emblem > span:first-child, .dodge-slash-impact { animation: none; }
  .dodge-slash-fx, .dodge-slash-fx[data-tier] { animation: none; opacity: .8; filter: none; }
  .dodge-refresh:enabled .refresh-emblem::after { animation: none; }
  .dodge-mist, .bench-worker[data-waiting="true"] .worker-actor { animation: none; }
  .dodge-mist { opacity: .12; }
  .dodge-thought-echo { animation: none; opacity: .2; }
  .dodge[data-mental="shaken"] .dodge-vignette, .dodge[data-mental="shaken"] .dodge-word { animation: none; }
}

.dodge-slash[data-locked="true"] .refresh-emblem { background: #211e27; }
.dodge-slash[data-locked="true"] .refresh-emblem > span:first-child { opacity: .2; filter: grayscale(1); }
.dodge-slash .refresh-emblem > .slash-lock { position: absolute; inset: 0; display: grid; place-items: center; font-size: 56px; line-height: 1; color: #f4dba5; filter: none; pointer-events: none; }
.dodge-slash .refresh-emblem > .slash-lock[hidden] { display: none; }

/* ===== css/worker-scenes.css ===== */
/* #402: 工程の前景。既存背景・弾幕・操作パネルには触れない。 */
.worker-actions { position: absolute; inset: 32px 0 0; pointer-events: none; }
.worker-action { width: 100%; height: 100%; object-fit: contain; object-position: center 75%; pointer-events: none; }
.worker-action[hidden] { display: none; }
.bench-worker[data-scene="holes"] .worker-action { object-position: center; }
.worker-punch, .worker-punch-hands { position: absolute; inset: 0; pointer-events: none; }
.worker-punch[hidden], .worker-punch-hand[hidden] { display: none; }
.worker-punch-hand, .worker-punch-dots { position: absolute; width: 100%; height: 100%; object-fit: contain; object-position: center; }
.worker-punch-dots ellipse { fill: #171520; stroke: #b7b0b9; stroke-width: 1.3px; }
.bench-worker[data-scene]:not([data-scene="fallback"]):not([data-scene="focus"]) .worker-actor { visibility: hidden; }
.bench-worker:is([data-scene="mix"], [data-scene="pack"], [data-scene="holes"], [data-scene="heat"]) .worker-equipment { visibility: hidden; }
.bench-worker:is([data-scene="pack"], [data-scene="holes"]) .worker-actions { inset: 20px 0 0; }
/* 背景を含む一枚絵は窓全体を覆う。上の余白から別背景の帯を露出させない。 */
.bench-worker[data-scene="heat"] .worker-actions { inset: 0; }
.bench-worker[data-scene="heat"] .worker-action { object-fit: cover; object-position: center; }
/* 一口の間だけ吸う姿へ切り替える。泡の長さは既存 setDraw の期間を使う。 */
.bench-worker:is([data-scene="pull"], [data-scene="inhale"]) .worker-actions { right: 72px; }
.bench-worker:is([data-scene="pull"], [data-scene="inhale"]) .worker-equipment {
  right: 104px; bottom: 140px; width: 102px; height: 260px; overflow: visible;
  z-index: 1;
}
.bench-worker:is([data-scene="pull"], [data-scene="inhale"]) .worker-water i {
  width: 6px; height: 7px; border-color: #f0f6ff; background: #c4e9ff66; box-shadow: 0 0 4px #b8dcff99;
}
/* 本体・ステム・受け皿・ボウルを既存部品のまま全体表示。炭は描き足さない。 */
.bench-worker[data-scene="focus"] .worker-actor {
  width: 320%; height: auto; left: -145%; top: -45%; bottom: auto;
}
.bench-worker[data-scene="focus"] :is(.worker-equipment, .worker-counter) { visibility: hidden; }
.bench-worker[data-scene="focus"] .worker-sweat { left: 66%; top: 44%; }
.bench-worker[data-scene="focus"] .worker-breath { left: 48%; top: 65%; }
.bench-worker.flinch .worker-actions { animation: worker-flinch .45s ease-out; }
.bench-worker[data-draw] .worker-actions { animation: worker-inhale var(--draw-duration) ease-in-out; transform-origin: 45% 50%; }
.bench-worker[data-art-fallback="true"] .bench-worker-caption { display: inline; font-size: 12px; }
@media (prefers-reduced-motion: reduce) {
  .bench-worker.flinch .worker-actions, .bench-worker[data-draw] .worker-actions { animation: none; }
}

/* ===== css/craft-header.css ===== */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
/* 工程名は上の帯へまとめ、右パネルは遊ぶための面積にする。 */
.bench-top { height: 64px; gap: 18px; }
.bench-top .bench-mode { width: 220px; letter-spacing: .14em; }
.bench-progress-count { display: none; }
.bench-progress-track { justify-content: center; gap: 15px; }
.bench .bench-progress-track > .bench-phase { position: relative; display: flex; align-items: center; justify-content: center; gap: 8px; flex: 1; height: 49px; max-width: 140px; padding: 4px 7px; border: 1px solid #dac29718; border-radius: 7px; color: #a79b93; background: #100b1833; }
.bench-phase:not(:last-child)::after { content: "›"; position: absolute; right: -12px; top: 10px; color: #b69967; font-size: 20px; }
.bench-phase-icon { width: 30px; height: 34px; flex: none; }
.bench-phase-icon svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; }
.bench-phase-copy { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.bench .bench-phase .bench-phase-copy { height: auto; flex: none; border-radius: 0; background: none; box-shadow: none; }
.bench[data-art-skin] .bench-phase-copy { box-shadow: none; }
.bench-phase-copy small { font-size: 12px; font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: .02em; }
.bench-phase-copy b { font-size: 14px; letter-spacing: .025em; white-space: nowrap; }
.bench-progress-track > .bench-phase.seen { color: #bba57e; background: #19132144; }
.bench-phase.seen small::after { content: " ✓"; color: #b4d4a4; }
.bench[data-art-skin] .bench-progress-track > .bench-phase.now { color: #f4deb3; border-color: #d4a46a9c; background: linear-gradient(135deg, #6a3a2029, #28152699); box-shadow: inset 0 0 12px #cf89381c, 0 0 8px #e6a25324; }
.bench-phase.now .bench-phase-icon { filter: drop-shadow(0 0 5px #edb66d88); }
.bench-phase.now[data-step="steam"] svg { fill: currentColor; stroke-width: .7; }
.bench-left, .bench-right { top: 70px; }
/* スマホ規格（#2851）: 帯の中のボタン（外観を選ぶ・大会の MENU）は帯の高さ（64px）いっぱいにする。
   規格の高さ（--phone-tap: 72px、ワイドでは 80px）のままだと帯より高く、中央そろえで画面の上端から欠け、下は作業板に隠れる。
   文字の大きさは規格のまま（帯そのものを高くすると作業台全体が下がるので、ここでは変えない）。 */
html:root[data-density="phone"] body:not(:root) .bench .bench-top > .btn { align-self: stretch; min-height: 0; }
.bench[data-step] .bench-right { padding-top: 12px; }
.bench[data-step] .bench-head { position: absolute; right: 12px; top: 8px; z-index: 8; display: block; min-height: 0; margin: 0; padding: 0; border: 0; }
.bench[data-step] .bench-heading, .bench[data-step] .bench-head::after { display: none; }
.bench[data-step] :is(.pull, .steam, .steam-timer) > .thermo { top: 31px; }

/* ===== css/tournament.css ===== */
/* body:not(:root)／.title:not(:root) は、DS風の廃止（横画面一本化）で外した :not(.game-ds)／:not([data-layout="ds"]) と同じ詳細度を保つための置き換え。 */
/* 制作画面と同じ暗い紫・真鍮・銀の面で、大会の記録を一つの放送画面に揃える。 */
.tournament-heading { position: relative; width: 100%; color: #f4efe5; }
.tournament-eyebrow { display: block; color: #c9b78e; font-size: 13px; font-weight: 700; letter-spacing: 0.02em; }
.tournament-heading h1 { margin: 8px 0 0; font-size: 52px; font-weight: 900; letter-spacing: .04em; line-height: 1.18; }
.tournament-heading p { margin: 10px 0 0; font-size: 17px; color: #b7afb9; }
.tournament-face { position: relative; display: grid; place-items: center; flex: none; width: 56px; height: 56px; border-radius: 12px; overflow: hidden; background: #30283c; border: 1px solid #a997762e; image-rendering: auto; }
.tournament-face img { display: block; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity .15s; }
.tournament-face.loaded img { opacity: 1; }
.face-fallback { position: absolute; font-size: 22px; font-weight: 700; color: #dfcfaf; }
.tournament-face.loaded .face-fallback { visibility: hidden; }
/* ===== 大会の中継グラフィック（中間投票・千須の一括投入・結果発表）=====
   ゲーム内1280×720基準。色: 金=主役/はじめ、審査員は --c（上園=桃・博士=青緑・千須=金）。 */
.tournament-live { display: inline-block; margin-right: 10px; padding: 2px 8px 2px 18px; position: relative; border-radius: 3px; background: #d8304f; color: #fff; font-size: 12px; font-weight: 700; font-style: normal; letter-spacing: .02em; vertical-align: 2px; }
.tournament-live::before { content: ""; position: absolute; left: 7px; top: 50%; width: 6px; height: 6px; margin-top: -3px; border-radius: 50%; background: #fff; animation: live-blink 1.2s steps(2) infinite; }
@keyframes live-blink { 50% { opacity: .2; } }

/* 順位のメダル（1=金・2=銀・3=銅・ほか=無地） */
.rank-medal { display: grid; place-items: center; flex: none; width: 40px; height: 40px; clip-path: polygon(25% 0, 75% 0, 100% 50%, 75% 100%, 25% 100%, 0 50%); background: linear-gradient(160deg, #4b4057, #2a2233); color: #e9e1ef; font-size: 20px; font-weight: 900; font-style: italic; font-variant-numeric: tabular-nums; text-shadow: 0 1px 0 #0008; }
[data-rank="1"] > .rank-medal, .rank-medal.gold { background: linear-gradient(160deg, #fff1c4, #e7b450 45%, #9b6a1c); color: #3b2405; text-shadow: 0 1px 0 #fff6; }
[data-rank="2"] > .rank-medal { background: linear-gradient(160deg, #ffffff, #b9c0cc 45%, #6b7280); color: #1f2430; text-shadow: 0 1px 0 #fff8; }
[data-rank="3"] > .rank-medal { background: linear-gradient(160deg, #ffd9b8, #c47a45 45%, #6e3a17); color: #2c1405; text-shadow: 0 1px 0 #fff5; }

/* 審査員ごとに色分けした票の帯 */
.vote-stack { position: relative; display: flex; height: 14px; min-width: 0; overflow: hidden; border-radius: 3px; background: repeating-linear-gradient(90deg, #ffffff10 0 calc(5% - 1px), transparent calc(5% - 1px) 5%), #08060d; box-shadow: inset 0 0 0 1px #ffffff14, inset 0 2px 4px #0009; transform: skewX(-12deg); }
.vote-stack > b { display: block; flex: none; height: 100%; background: linear-gradient(180deg, color-mix(in srgb, var(--c) 70%, #fff), var(--c) 55%, color-mix(in srgb, var(--c) 70%, #000)); box-shadow: inset -1px 0 0 #0006; transition: width 1s cubic-bezier(.2, .8, .2, 1); }
.judge-legend { display: flex; gap: 14px; font-size: 14px; color: #b9b0c3; letter-spacing: 0.04em; }
.judge-legend span { display: flex; align-items: center; gap: 5px; }
.judge-legend i { width: 14px; height: 8px; transform: skewX(-12deg); background: var(--c); border-radius: 1px; }

/* 審査員の持ち点（10粒） */
.judge-panel { display: flex; flex-direction: column; gap: 10px; }
.judge-chip { position: relative; display: grid; grid-template-columns: 46px 1fr; grid-template-rows: auto auto auto; column-gap: 12px; row-gap: 4px; padding: 10px 12px 10px 14px; border-radius: 10px; background: linear-gradient(110deg, color-mix(in srgb, var(--c) 16%, #1a1325), #120d1b 70%); border: 1px solid color-mix(in srgb, var(--c) 40%, transparent); }
.judge-chip::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--c); }
.judge-chip .judge-face { grid-row: 1 / 4; width: 46px; height: 46px; border-radius: 50%; border: 2px solid var(--c); }
.judge-name { font-family: "Suien Name", serif; font-size: 15px; font-weight: 700; color: #f4ede0; }
.judge-pips { display: grid; grid-template-columns: repeat(10, 1fr); gap: 3px; }
.judge-pips b { height: 9px; border-radius: 2px; background: #ffffff14; box-shadow: inset 0 0 0 1px #ffffff12; }
.judge-pips b.on { background: var(--c); box-shadow: 0 0 6px color-mix(in srgb, var(--c) 70%, transparent); }
.judge-left { font-size: 14px; color: #b8afc2; }
.judge-chip:has(.judge-deduction):not(:has(.judge-face)) { grid-template-columns: minmax(0, 1fr); }
/* 顔の無い札（第4章の途中順位）は、46px の顔の列へ文字を入れない（「ダ・／シル／ヴァ」「投入／3」と細かく折れていた。TXW07）。
   1段目に名前と「投入 N ／ 残り N」、2段目に粒。減点の理由が付く最終の札は上の1列のまま */
.judge-chip:not(:has(.judge-face, .judge-deduction)) { grid-template-columns: minmax(0, 1fr) auto; grid-auto-flow: row dense; }
.judge-chip:not(:has(.judge-face, .judge-deduction)) > :is(.judge-pips, .judge-focus, .judge-pick) { grid-column: 1 / -1; }
.judge-chip:not(:has(.judge-face, .judge-deduction)) > .judge-left { align-self: baseline; text-align: right; }
.judge-deduction { grid-column: 1 / -1; min-width: 0; font-size: 12px; line-height: 1.5; color: #cfc4d8; white-space: normal; overflow-wrap: anywhere; }
/* 桜井式の審査（第1章・SKR04）: 審査員ごとの見る所と、この回の入れ先 */
.judge-focus, .judge-pick { grid-column: 2 / -1; min-width: 0; font-size: 13px; font-weight: 700; line-height: 1.35; overflow-wrap: anywhere; }
.judge-focus { color: color-mix(in srgb, var(--c) 70%, #fff); }
.judge-pick { color: #f6d68e; }
.judge-chip.held { background: linear-gradient(110deg, #3a2a0c, #140f19 75%); }
.judge-chip.held .judge-pips b { background: repeating-linear-gradient(135deg, #f6c95e33 0 3px, #f6c95e12 3px 6px); }
.judge-chip.held .judge-left { color: #f6d68e; font-weight: 700; }
.judge-chip.held::after { content: "🔒"; position: absolute; right: 10px; top: 8px; font-size: 13px; filter: grayscale(.2); }

/* ---- 中間投票 */
.standings.tournament-board { width: 1040px; padding: 22px 30px 18px; overflow: hidden; border: 1px solid #e8c27a55; border-radius: 14px; background: linear-gradient(135deg, #1b1228f5, #0d0a15f7 60%), #0d0a15; box-shadow: 0 24px 80px #000c, inset 0 1px 0 #ffe7b322; }
.standings.tournament-board::before { content: ""; position: absolute; inset: 0 0 auto; height: 4px; background: linear-gradient(90deg, #ff8db4, #f6c95e 50%, #5fe2cf); }
.standings .tournament-heading { display: grid; grid-template-columns: auto 1fr; align-items: end; column-gap: 22px; padding-bottom: 14px; border-bottom: 1px solid #e8c27a2e; }
.standings .tournament-eyebrow { grid-column: 1 / -1; }
.standings .tournament-heading h1 { margin-top: 6px; font-size: 40px; font-style: italic; letter-spacing: .06em; background: linear-gradient(180deg, #fff6dc, #e8c27a); -webkit-background-clip: text; background-clip: text; color: transparent; }
.standings .tournament-heading p { margin: 0 0 6px; font-size: 16px; color: #cfc6d8; }
.sd-main { display: grid; grid-template-columns: 1fr 300px; gap: 22px; margin-top: 14px; }
.sd-board { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.standings .sd-rows { margin: 0; gap: 8px; }
.standings .sd-row { display: grid; grid-template-columns: 40px 48px 120px 1fr 72px; align-items: center; gap: 12px; min-height: 60px; padding: 6px 14px 6px 10px; border-radius: 8px; background: linear-gradient(90deg, #ffffff0d, #ffffff04); border: 1px solid #ffffff12; clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%); }
.standings .sd-row.me { background: linear-gradient(90deg, #e8c27a33, #e8c27a0a); border-color: #e8c27a88; box-shadow: inset 4px 0 0 #f6c95e; }
.standings .sd-rank { width: 40px; font-size: 20px; }
.standings .sd-face { width: 48px; height: 48px; border-radius: 10px; }
.standings .sd-name { width: auto; font-family: "Suien Name", serif; font-size: 18px; font-weight: 700; }
.standings .sd-row.me .sd-name { color: #ffe2a6; }
.standings .sd-bar { flex: none; height: 16px; }
.sd-points { width: auto; text-align: right; font-size: 32px; font-weight: 900; font-style: italic; color: #fff; text-shadow: 0 2px 0 #0008; font-variant-numeric: tabular-nums; }
.sd-points small { margin-left: 3px; font-size: 13px; font-style: normal; font-weight: 700; color: #b8afc2; }
.standings .sd-row.me .sd-points { color: #ffe2a6; }
.sd-status { display: flex; align-items: center; gap: 14px; margin-top: 12px; padding: 8px 14px; border-radius: 8px; background: #5fe2cf0d; border: 1px solid #5fe2cf26; font-size: 14px; color: #c4bfc9; }
.sd-status > :last-child { margin-left: auto; color: #9fe7d9; }
.standings .sd-feed { display: flex; flex-direction: row; align-items: stretch; gap: 0; margin-top: 10px; overflow: hidden; border-radius: 6px; background: #000a; font-size: 15px; color: #f2ead9; line-height: 1.45; }
.sd-feed-tag { display: grid; place-items: center; padding: 0 14px; background: #d8304f; color: #fff; font-size: 13px; letter-spacing: 0.02em; }
.sd-feed-lines { display: flex; flex-direction: column; justify-content: center; padding: 6px 14px; }
.sd-feed-lines > div { animation: feed-in .5s ease-out backwards; }
.sd-feed-lines > div + div { animation-delay: .5s; color: #f6d68e; }
@keyframes feed-in { from { opacity: 0; transform: translateX(24px); } }
.sd-recognition { margin: 8px 0 0; padding: 7px 14px; color: #dfc595; border-left: 3px solid #e8c27a; background: #e8c27a0f; font-size: 15px; line-height: 1.5; }

/* ---- 結果発表のカウント（共通の背景は下） */
.count-screen, .sui-cut, .result-table { background: radial-gradient(ellipse 70% 55% at 50% 0%, #6a3f8a55, transparent 70%), linear-gradient(115deg, #100b1df7, #171124e8), url('../img/ui/continue/backdrop_stage.webp') center / cover; }
.count-screen .tournament-heading { position: absolute; left: 52px; top: 34px; width: calc(100% - 104px); }
.count-screen .tournament-heading h1 { font-size: 40px; font-style: italic; }
.count-screen::before { content: ""; position: absolute; left: 50%; top: -10%; width: 760px; height: 120%; transform: translateX(-50%); background: conic-gradient(from 180deg at 50% 0%, transparent 160deg, #fff3d61a 175deg, #fff3d626 180deg, #fff3d61a 185deg, transparent 200deg); pointer-events: none; animation: spot-sway 3.2s ease-in-out infinite alternate; }
@keyframes spot-sway { from { transform: translateX(-50%) rotate(-7deg); } to { transform: translateX(-50%) rotate(7deg); } }
.count-screen .rc-num { top: 47%; font-size: 168px; font-style: italic; font-weight: 900; color: #fff6dc; text-shadow: 0 4px 0 #8a6a3a, 0 0 60px #f6c95e55; font-variant-numeric: tabular-nums; }
.rc-ring { position: absolute; left: 50%; top: 47%; width: 300px; height: 300px; transform: translate(-50%, -50%); }
.rc-ring::before { content: ""; position: absolute; inset: 0; border-radius: 50%; background: repeating-conic-gradient(#f6c95e66 0 1.2deg, transparent 1.2deg 36deg); -webkit-mask: radial-gradient(circle, transparent 58%, #000 59% 63%, transparent 64%); mask: radial-gradient(circle, transparent 58%, #000 59% 63%, transparent 64%); }
.rc-ring svg { display: block; width: 100%; height: 100%; transform: rotate(-90deg); fill: none; stroke-width: 5; }
.rc-ring-track { stroke: #ffffff14; }
.rc-ring-progress { stroke: #f6c95e; stroke-linecap: round; stroke-dasharray: 691.15; stroke-dashoffset: calc(691.15 * (1 - var(--count, 1))); transition: stroke-dashoffset .5s linear; filter: drop-shadow(0 0 8px #f6c95e99); }
.count-screen .rc-pray { bottom: 40px; gap: 16px; }
.count-screen .rc-card { width: 200px; padding: 12px 14px; display: grid; grid-template-columns: 52px 1fr; align-items: center; border: 1px solid #ffffff1c; border-radius: 12px; background: linear-gradient(160deg, #2a1d3ccc, #150f20cc); gap: 6px 12px; font-size: 17px; font-weight: 700; box-shadow: 0 8px 24px #0008; }
.count-screen .rc-face { grid-row: 1 / 3; width: 52px; height: 52px; border-radius: 50%; }
.count-screen .rc-shisha { width: 100%; height: 4px; border-radius: 2px; opacity: .9; box-shadow: 0 0 8px currentColor; order: 3; }
.count-screen .rc-card.me { border-color: #f6c95e; color: #ffe2a6; box-shadow: 0 0 0 1px #f6c95e55, 0 0 26px #f6c95e33; animation: me-pulse 1.2s ease-in-out infinite; }
@keyframes me-pulse { 50% { transform: translateY(-4px); } }
.count-screen .rc-cut { padding: 8px 16px; background: #1c142de8; border-left: 3px solid #f6c95e; font-size: 19px; color: #e7dcf0; box-shadow: 0 6px 18px #0009; }
.count-screen .rc-crt { opacity: .3; }

/* ---- 千須の一括投入 */
.sui-cut { align-items: stretch; justify-content: flex-start; padding: 40px 470px 40px 60px; gap: 18px; overflow: hidden; }
.nc-rays { position: absolute; inset: 0; background: repeating-conic-gradient(from 0deg at 72% 60%, #f6c95e14 0 4deg, transparent 4deg 12deg); opacity: 0; transition: opacity .3s; pointer-events: none; }
.sui-cut.cutting .nc-rays { opacity: 1; animation: rays-flicker .18s steps(2) infinite; }
@keyframes rays-flicker { 50% { opacity: .55; } }
.sui-cut .tournament-heading { position: relative; padding-bottom: 14px; border-bottom: 1px solid #f6c95e33; }
.sui-cut .tournament-heading h1 { font-size: 44px; font-style: italic; background: linear-gradient(180deg, #fff6dc, #f6c95e); -webkit-background-clip: text; background-clip: text; color: transparent; }
.sui-cut .nc-bars { position: relative; width: 100%; gap: 10px; }
.sui-cut .nc-row { display: grid; grid-template-columns: 40px 50px 130px 1fr 64px; align-items: center; gap: 12px; min-height: 64px; padding: 6px 18px 6px 10px; background: linear-gradient(90deg, #ffffff0e, #ffffff04); border: 1px solid #ffffff14; border-radius: 9px; clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%); }
.sui-cut .nc-row.me { border-color: #f6c95e99; background: linear-gradient(90deg, #f6c95e2e, #f6c95e08); box-shadow: inset 4px 0 0 #f6c95e; }
.sui-cut .nc-row.hit { animation: nc-hit .6s ease-out; }
.sui-cut .nc-row.lead { box-shadow: inset 4px 0 0 #f6c95e, 0 0 30px #f6c95e44; }
@keyframes nc-hit { 0% { filter: brightness(2.2); } 100% { filter: none; } }
.sui-cut .nc-name { width: auto; font-family: "Suien Name", serif; font-size: 19px; font-weight: 700; }
.sui-cut .nc-row.me .nc-name, .sui-cut .nc-row.me .nc-pt { color: #ffe2a6; }
.sui-cut .nc-face { width: 50px; height: 50px; border-radius: 10px; }
.sui-cut .nc-bar { flex: none; height: 18px; border-radius: 3px; overflow: hidden; background: repeating-linear-gradient(90deg, #ffffff10 0 calc(5% - 1px), transparent calc(5% - 1px) 5%), #08060d; }
.sui-cut .nc-bar b { transition: width 1s cubic-bezier(.2, .8, .2, 1); }
.sui-cut .nc-pt { width: auto; text-align: right; font-size: 36px; font-weight: 900; font-style: italic; font-variant-numeric: tabular-nums; }
.sui-cut .nc-cut { position: absolute; right: 0; bottom: 0; top: 96px; width: 440px; min-width: 0; margin: 0; padding: 0; display: block; background: none; clip-path: none; transform: translateX(110%); transition: transform .5s cubic-bezier(.2, .9, .2, 1.05); color: #1d1206; }
.sui-cut .nc-cut.show { transform: none; }
.nc-cut-art { position: absolute; inset: 0 0 0 40px; overflow: hidden; background: linear-gradient(160deg, #fff1c4, #e7b450 55%, #8f5f1a); clip-path: polygon(22% 0, 100% 0, 100% 100%, 0 100%); }
.nc-cut-art::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(-62deg, #ffffff22 0 2px, transparent 2px 14px); mix-blend-mode: overlay; }
.nc-cut-art img { position: absolute; left: 12%; bottom: -6%; width: 104%; height: auto; filter: drop-shadow(-8px 0 0 #3b2405aa); }
.nc-cut-art .nc-cut-face { position: absolute; left: 30%; top: 20%; width: 160px; height: 160px; border-radius: 50%; }
.nc-cut-text { position: absolute; left: 0; bottom: 36px; padding: 10px 26px 12px 34px; background: #120c1aee; color: #f4ede0; clip-path: polygon(0 0, 100% 0, calc(100% - 18px) 100%, 0 100%); box-shadow: 0 10px 30px #000a; }
.nc-cut-text small { font-size: 13px; letter-spacing: 0.02em; color: #f6d68e; }
.nc-cut-text b { display: block; font-size: 30px; letter-spacing: .1em; }
.nc-cut-pt { display: flex; align-items: baseline; gap: 10px; margin-top: 2px; font-size: 15px; font-weight: 700; color: #f6d68e; }
.nc-cut-pt strong { font-size: 64px; line-height: .9; font-style: italic; font-weight: 900; background: linear-gradient(180deg, #fff6dc, #f6c95e 55%, #b07a20); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 3px 0 #000a); }
.nc-stamp { position: absolute; left: 30%; top: 15%; z-index: 5; padding: 6px 30px; border: 5px solid #ff4d6d; border-radius: 10px; color: #ff4d6d; font-size: 72px; font-weight: 900; letter-spacing: .14em; transform: translate(-50%, -50%) rotate(-10deg); background: #12081099; text-shadow: 0 0 20px #ff4d6d88; animation: nc-stamp-in .4s cubic-bezier(.2, 1.4, .3, 1) backwards; pointer-events: none; }
@keyframes nc-stamp-in { from { opacity: 0; transform: translate(-50%, -50%) rotate(-10deg) scale(2.4); } }

/* ---- 最終結果 */
.result-table { padding: 26px 44px 24px; display: grid; grid-template-rows: 128px minmax(0, 1fr) 54px; gap: 16px; align-items: stretch; justify-content: stretch; overflow: hidden; }
.rt-rays { position: absolute; inset: 0; background: repeating-conic-gradient(from 0deg at 50% 0%, #f6c95e12 0 6deg, transparent 6deg 18deg); -webkit-mask: radial-gradient(ellipse 70% 80% at 50% 0%, #000 20%, transparent 70%); mask: radial-gradient(ellipse 70% 80% at 50% 0%, #000 20%, transparent 70%); animation: rays-breathe 3s ease-in-out infinite alternate; pointer-events: none; }
.rt-confetti { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 2; }
@keyframes rays-breathe { from { opacity: .6; } to { opacity: 1; } }
.result-table:not([data-rank='1']) .rt-rays { opacity: .35; }
.rt-hero { position: relative; display: flex; align-items: center; gap: 24px; border-bottom: 1px solid #e8c27a33; }
.rt-emblem { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; flex: none; width: 112px; height: 112px; clip-path: polygon(50% 0, 93% 25%, 93% 75%, 50% 100%, 7% 75%, 7% 25%); background: linear-gradient(160deg, #4b4057, #241c2e); color: #e9e1ef; animation: emblem-in .7s cubic-bezier(.2, 1.3, .3, 1) backwards; }
.rt-emblem[data-rank='1'] { background: linear-gradient(160deg, #fff1c4, #e7b450 45%, #8f5f1a); color: #3b2405; }
.rt-emblem[data-rank='2'] { background: linear-gradient(160deg, #ffffff, #b9c0cc 45%, #5b6270); color: #1f2430; }
.rt-emblem[data-rank='3'] { background: linear-gradient(160deg, #ffd9b8, #c47a45 45%, #5e3014); color: #2c1405; }
.rt-emblem b { font-size: 52px; font-weight: 900; font-style: italic; line-height: 1; }
.rt-emblem small { font-size: 12px; font-weight: 900; letter-spacing: 0.02em; }
@keyframes emblem-in { from { opacity: 0; transform: scale(.3) rotate(-30deg); } }
.result-table .tournament-heading { padding-bottom: 0; border: 0; }
.result-table .tournament-heading h1 { margin-top: 4px; color: #e6d0a2; font-size: 64px; font-style: italic; letter-spacing: .08em; line-height: 1.05; }
.result-table[data-rank='1'] .tournament-heading h1 { background: linear-gradient(180deg, #fffaf0, #f6d68e 45%, #c08a2e); background-clip: text; -webkit-background-clip: text; color: transparent; filter: drop-shadow(0 3px 0 #3b2405); }
.rt-layout { display: grid; grid-template-columns: 1.2fr 1fr; gap: 22px; min-height: 0; }
.rt-ranking { min-width: 0; padding: 16px 18px; border: 1px solid #e8c27a2e; border-radius: 12px; background: linear-gradient(160deg, #1a1226d9, #0d0a15d9); }
.rt-ranking-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.rt-ranking h2 { margin: 0; font-size: 14px; font-weight: 700; color: #cfc4d8; letter-spacing: .08em; }
.result-table .rt-rows { width: 100%; gap: 8px; }
.result-table .rt-row { position: relative; display: grid; grid-template-columns: 56px 48px 1fr 74px; grid-template-areas: "rank face name pt" "rank face bar pt"; align-items: center; column-gap: 12px; row-gap: 5px; min-height: 70px; padding: 8px 14px 8px 8px; border-radius: 9px; border: 1px solid #ffffff12; background: linear-gradient(90deg, #ffffff0d, #ffffff03); animation-delay: calc(var(--i) * .14s); }
.result-table .rt-row.me { border-color: #f6c95e; background: linear-gradient(90deg, #f6c95e30, #f6c95e08); box-shadow: inset 4px 0 0 #f6c95e, 0 0 26px #f6c95e22; }
.result-table .rt-rank { grid-area: rank; width: 52px; height: 52px; font-size: 17px; }
.result-table .rt-face { grid-area: face; width: 48px; height: 48px; border-radius: 10px; }
.result-table .rt-name { grid-area: name; width: auto; font-family: "Suien Name", serif; font-size: 18px; font-weight: 700; display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.result-table .rt-row.me .rt-name, .result-table .rt-row.me .rt-pt { color: #ffe2a6; }
.rt-votes { display: inline; margin: 0; font-family: var(--font); font-size: 14px; font-weight: 500; color: #a79dae; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.result-table .rt-bar { grid-area: bar; display: flex; height: 12px; }
.result-table .rt-pt { grid-area: pt; width: auto; text-align: right; font-size: 26px; font-weight: 900; font-style: italic; color: #eee6d4; font-variant-numeric: tabular-nums; white-space: nowrap; }
.result-table .rt-detail { width: auto; display: block; gap: 8px 12px; padding: 16px 18px; border: 1px solid #e8c27a2e; border-radius: 12px; background: linear-gradient(160deg, #1a1226d9, #0d0a15d9); }
.result-table .rt-detail h4 { grid-column: 1 / -1; margin: 0 0 4px; font-size: 14px; letter-spacing: .08em; color: #cfc4d8; }
.result-table .rt-part { position: relative; display: grid; grid-template-columns: 1fr 40px; align-items: center; gap: 2px 8px; padding: 7px 12px 9px; border-radius: 8px; background: #ffffff07; border: 1px solid #ffffff0f; font-size: 14px; font-weight: 700; }
.result-table .rt-part b { grid-column: 2; grid-row: 1 / 3; font-size: 28px; text-align: center; }
.result-table .rt-part small { width: auto; font-size: 14px; color: #a39cae; font-weight: 500; }
/* 総合タイルは <b> が2つ（評価マークとランク文字）。同じセルに重ねず、右列に並べる（#3515）。 */
.result-table .rt-part.total { grid-template-columns: 1fr auto auto; }
.result-table .rt-part.total b { grid-row: 1 / 3; }
.result-table .rt-part.total b.craft-evaluation { grid-column: 2; }
.result-table .rt-part.total b[data-test='craft-final-rank'] { grid-column: 3; min-width: 28px; }
.result-table .rt-part.total { margin: 0; background: linear-gradient(110deg, #f6c95e22, #f6c95e08); border-color: #f6c95e55; }
.result-table .rt-detail-scroll > small { grid-column: 1 / -1; font-size: 12px; line-height: 1.5; color: #a39baa; }
.result-table .rt-judge-comment { color: #f6d68e !important; }
.result-table .rt-deductions { grid-column: 1 / -1; display: grid; gap: 1px; }
.result-table .rt-detail:has(.rt-deductions) { gap: 6px 12px; padding-top: 12px; padding-bottom: 12px; }
.result-table .rt-deductions > small { font-size: 12px; line-height: 1.35; color: #a39baa; }
.result-table .rt-next-tip { color: #9fe7d9 !important; }
.result-table .flavor-actual { grid-column: 1 / -1; }
/* Keep the card within its screen; only its evaluation content scrolls. */
.result-table .rt-detail { min-height: 0; overflow: hidden; }
.result-table .rt-detail-scroll { height: 100%; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-content: start; align-items: start; gap: inherit; overflow: auto; overscroll-behavior: contain;
  /* 続きがあることが分かるよう、下端に影の手がかり（スクロール位置に応じて消える。#3554） */
  background: linear-gradient(#0d0a15d9 30%, #0d0a1500) top / 100% 24px no-repeat local, linear-gradient(#0d0a1500, #0d0a15d9 70%) bottom / 100% 24px no-repeat local,
    radial-gradient(farthest-side at 50% 0, #f6c95e40, #0000) top / 100% 10px no-repeat scroll, radial-gradient(farthest-side at 50% 100%, #f6c95e40, #0000) bottom / 100% 10px no-repeat scroll; scrollbar-width: thin; scrollbar-color: #f6c95e88 transparent; }
.result-table .rt-good-point { color: #e9d6a1; }
.result-table > .btn { justify-self: end; min-width: 320px; border: 1px solid #f6c95e99; border-radius: 8px; background: linear-gradient(135deg, #6a4e2c, #2f2536); box-shadow: inset 0 1px 0 #ffe8b526, 0 6px 20px #0008; color: #fff1d0; font-size: 18px; font-weight: 800; }
.result-table > :is(.rt-hero, .rt-layout, .btn) { position: relative; }
/* スマホ規格（#2851・#2977）では「表彰のあとへ」が規格の高さ（--phone-tap: 72px、ワイドでは 80px）になり、
   下の段（54px）からはみ出して画面の下で欠けていた。スマホでは下の段をボタンの高さに合わせ、
   その分だけ順位と評価の段を縮める（評価は今までどおり枠の中でスクロールする）。 */
html:root[data-density="phone"] body:not(:root) .result-table { grid-template-rows: 128px minmax(0, 1fr) auto; }
.craft-loading { position: absolute; inset: 64px 0 0; z-index: 30; display: grid; place-content: center; gap: 18px; text-align: center; background: #100c1aee; color: #e4d4b4; font-size: 18px; }
.craft-loading::before { content: ''; width: 36px; height: 36px; margin: 0 auto; border: 2px solid #a58b522b; border-top-color: #dfc58e; border-radius: 50%; animation: craft-load 1s linear infinite; }
.bench[data-thermal-band='optimal'] .thermal-label { color: #ebd4ff; }
.bench[data-thermal-band='ready'] .thermal-label { color: #a8eed3; background: none; animation: none; }
.bench-progress-track:has(> .bench-phase:nth-child(6)) { gap: 10px; }
.bench-progress-track:has(> .bench-phase:nth-child(6)) > .bench-phase { gap: 5px; padding: 4px 5px; }
.bench-progress-track:has(> .bench-phase:nth-child(6)) .bench-phase-icon { width: 23px; height: 30px; }
.bench-progress-track:has(> .bench-phase:nth-child(6)) .bench-phase-copy b { font-size: 14px; }
@keyframes craft-load { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
  .tournament-board *, .result-table *, .sui-cut *, .count-screen .rc-card, .count-screen::before, .nc-rays, .rt-rays, .craft-loading::before, .tournament-live::before { animation: none !important; transition: none !important; }
  .rc-ring-progress { transition: none; }
  .nico { animation: none; left: 25%; transform: none; font-size: 19px; opacity: .6; }
}

/* #2359 CUI08: 大会の中継面を制作と同じ夜紫へ。配置・得点表示は維持。 */
.tournament-heading { color: #f6f1fa; }
.tournament-eyebrow, .tournament-heading p, .judge-legend, .judge-left { color: #c9a7e6; }
.tournament-face { background: #2e1d45; border-color: #5a4475; }
.standings.tournament-board, .result-table, .count-screen, .sui-cut {
  background: #150d22 url('../img/ui/craft-night/backdrop.webp') center / cover no-repeat;
  color: #f6f1fa;
}
.standings.tournament-board { border-color: #5a4475; box-shadow: 0 24px 80px #090512b8, inset 0 1px 0 #c9a7e633; }
.standings.tournament-board::before { height: 2px; background: #e3bd6e; }
.standings .sd-board, .result-table .rt-ranking, .result-table .rt-detail {
  background: #221534 url('../img/ui/craft-night/board.webp') center / 100% 100% no-repeat;
  border: 1px solid #5a4475;
  color: #f6f1fa;
}
.judge-chip, .judge-chip.held { background: #2e1d45; border-color: color-mix(in srgb, var(--c) 55%, #5a4475); }
.judge-name { color: #f6f1fa; }
.vote-stack { background: #221534; box-shadow: inset 0 0 0 1px #5a4475, inset 0 2px 4px #09051299; }
.standings .sd-row, .result-table .rt-row {
  clip-path: none; border: 1px solid #5a4475;
  background: #2e1d45 url('../img/ui/craft-night/rank-strip.webp') center / 100% 100% no-repeat;
}
.standings .sd-row.me, .result-table .rt-row.me {
  border-color: #e3bd6e; background: #2e1d45 url('../img/ui/craft-night/rank-strip.webp') center / 100% 100% no-repeat;
  box-shadow: inset 4px 0 0 #e3bd6e;
}
.rank-medal { clip-path: none; background: url('../img/ui/craft-night/medal-plain.webp') center / contain no-repeat; color: #f6f1fa; }
[data-rank="1"] > .rank-medal, .rank-medal.gold { background: url('../img/ui/craft-night/medal-gold.webp') center / contain no-repeat; color: #221534; }
[data-rank="2"] > .rank-medal { background: url('../img/ui/craft-night/medal-silver.webp') center / contain no-repeat; color: #221534; }
[data-rank="3"] > .rank-medal { background: url('../img/ui/craft-night/medal-bronze.webp') center / contain no-repeat; color: #221534; }
.nc-rays, .rt-rays { background: repeating-conic-gradient(from 0deg at 72% 60%, #c9a7e60e 0 4deg, transparent 4deg 16deg); }
.nc-cut-art { clip-path: none; background: url('../img/ui/craft-night/cutin-band.webp') center / 100% 100% no-repeat; }
.nc-cut-art::after { display: none; }
.result-table .rt-part { background: #2e1d45; border-color: #5a4475; }
.result-table .rt-part.total, .count-screen .rc-card.me { border-color: #e3bd6e; background: #2e1d45; }
.count-screen .rc-card, .count-screen .rc-cut, .standings .sd-feed { background: #2e1d45; border-color: #5a4475; color: #f6f1fa; }
.count-screen .rc-num, .result-table .tournament-heading h1 { color: #f6f1fa; text-shadow: 0 2px 0 #221534; }
.standings .sd-feed-lines > div + div, .result-table .rt-judge-comment, .result-table .rt-good-point { color: #e3bd6e !important; }
.result-table > .btn { border-color: #e3bd6e; background: #e3bd6e; color: #221534; }

/* 順位帯自身の罫・内影を使う。旧CSSの枠・影を重ねず、凡例は板枠の上に置かない。 */
.standings .sd-board { background: none; border-color: transparent; box-shadow: none; }
.standings .sd-row, .standings .sd-row.me,
.result-table .rt-row, .result-table .rt-row.me {
  border-color: transparent; box-shadow: none; background-color: transparent;
}
.rank-medal, [data-rank] > .rank-medal, .rank-medal.gold {
  clip-path: none; background-position: center; background-size: contain; background-repeat: no-repeat;
}

.result-table .rt-save { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.result-table .rt-save .btn { min-height: 44px; max-width: 100%; }

/* ================================================================ スマホ規格の大会画面（#2851・#2729 B班）
   ワイドで左右まで広げる・文字の下限を上げるのは wide-craft.css（#2983）。ここは欄の並びと押す所だけを足す。 */
/* 最終結果: 「あなたの一台」の欄の下の補足（効いたもの・良かった点・次の練習）を規格の文字に。
   下段の行の高さ（「……結果を受け止める」が --phone-tap になる分）は phone-density.css（#2976）で決める。 */
html:root[data-density="phone"] body:not(:root) .result-table .rt-detail-scroll > small { font-size: var(--phone-sub); }
/* 中間投票: 審査員の欄と名前の列を広げる（文字を大きくしても持ち点の行・名前が詰まらないように） */
html:root[data-density="phone"] body:not(:root) .standings .sd-main { grid-template-columns: 1fr 380px; }
html:root[data-density="phone"] body:not(:root) .standings .sd-row { grid-template-columns: 40px 48px 150px 1fr 72px; }
html:root[data-density="phone"] body:not(:root) .standings .sd-recognition { font-size: var(--phone-sub); }
/* 入場の紹介カード: 少し広げて、スミさんのひと言を文節で2行までにそろえる */
html:root[data-density="phone"] body:not(:root) .ent-card { width: 960px; }
html:root[data-density="phone"] body:not(:root) .ent-note { line-height: 1.45; word-break: auto-phrase; text-wrap: balance; }
/* GAME OVER: ワイドでは左右の余白を地の色で塗る（会場の絵が覗いていた）。「初回は時間制限なし」の注記を規格の文字に */
body:not(:root) #stage[data-wide] .end-screen.gameover { box-shadow: 0 0 0 var(--stage-gutter) #120a1c; }
/* 注記は横持ちスマホでも実寸12px以上（#2190 P24 の下限）。補助文の規格（実寸11.5px）だけだと下回るため、大きい方を取る */
html:root[data-density="phone"] body:not(:root) .gameover .go-limit-note { font-size: max(var(--phone-sub), calc(12.5px / var(--k, 1))); }

/* ===== css/motions.css ===== */
/* ============================================================
   場面ごとの一度きりのモーショングラフィックス（core/scene-motions.js・CI107〜CI109）の共通部分。
   場面ごとの見た目は css/motions/<場面>.css
   平らな色面・線を描いて引っ込める放射線・広がる輪。色は scene-motions.js の配色（紫1色／場面ごとの色）から渡す
   ============================================================ */
@property --mo-hole { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.mo { position: absolute; inset: 0; overflow: hidden; z-index: 100; pointer-events: auto; font-family: var(--font); }
.mo-defs { position: absolute; width: 0; height: 0; }
.mo-back { position: absolute; inset: 0; }
.mg-kinetic { display: inline-flex; overflow: hidden; padding-block: 0.08em; }
.mg-char { display: inline-block; transform: translateY(110%); opacity: 0; }
